KlipioAutomationJob? startupAutomationJob;

Future<void> main(List<String> args) async {
  startupAutomationJob = KlipioAutomationJob.fromCommandLine(args);
  await bootstrapKlipio(
    app: const KlipioApp(),
    initialize: () async {
      try {
        await (await _klipioDraftsRoot()).create(recursive: true);
      } catch (_) {
        // The editor can still start and report a concrete save error later.
      }
    },
  );
}

const _klipioProjectFileName = 'project.klipio.json';
const _klipioProjectMetaFileName = 'project-meta.json';

String normalizeVideoTitle(String value) {
  var title = value.trim();
  final slash = math.max(title.lastIndexOf('/'), title.lastIndexOf('\\'));
  if (slash >= 0) title = title.substring(slash + 1);
  title = title.replaceFirst(RegExp(r'\.[a-zA-Z0-9]{2,5}$'), '');
  title = title.replaceFirst(RegExp(r'^\s*\d+\s*[.\-_)]\s*'), '');
  return title
      .toLowerCase()
      .replaceAll(RegExp(r'''[‘’'`“”"]'''), '')
      .replaceAll('&', 'and')
      .replaceAll(RegExp(r'[^a-z0-9]+'), ' ')
      .trim()
      .replaceAll(RegExp(r'\s+'), ' ');
}

String numberedExportBaseName(
  String base, {
  required int number,
  required bool enabled,
  bool patternIncludesNumber = false,
}) {
  if (!enabled || patternIncludesNumber) return base;
  return '$number.$base';
}

String _safeProjectDirectoryName(String value) {
  var safe = value
      .trim()
      .replaceAll(RegExp(r'[<>:"/\\|?*\x00-\x1f]'), ' ')
      .replaceAll(RegExp(r'\s+'), ' ')
      .replaceAll(RegExp(r'[. ]+$'), '');
  if (safe.isEmpty) safe = 'Klipio Project';
  if (safe.length > 80) safe = safe.substring(0, 80).trimRight();
  return safe;
}

bool _isKlipioProjectBundlePath(String path) =>
    platform.basename(path).toLowerCase() == _klipioProjectFileName;

bool _sameWindowsPath(String left, String right) =>
    Directory(left).absolute.uri.normalizePath().toFilePath().toLowerCase() ==
    Directory(right).absolute.uri.normalizePath().toFilePath().toLowerCase();

Future<Directory> _klipioDraftsRoot() async {
  final userProfile = Platform.environment['USERPROFILE']?.trim();
  if (Platform.isWindows && userProfile != null && userProfile.isNotEmpty) {
    return Directory(
      '$userProfile${Platform.pathSeparator}Klipio Drafts',
    );
  }
  final documents = await getApplicationDocumentsDirectory();
  return Directory(
    '${documents.parent.path}${Platform.pathSeparator}Klipio Drafts',
  );
}

Future<bool> _isManagedKlipioProjectPath(String projectPath) async {
  if (!_isKlipioProjectBundlePath(projectPath)) return false;
  final draftsRoot = await _klipioDraftsRoot();
  final projectDirectory = File(projectPath).parent;
  return _sameWindowsPath(projectDirectory.parent.path, draftsRoot.path);
}

Future<String?> _projectFileFromSelectedFolder(String selectedFolder) async {
  final projectPath =
      '$selectedFolder${Platform.pathSeparator}$_klipioProjectFileName';
  if (!await _isManagedKlipioProjectPath(projectPath) ||
      !await File(projectPath).exists()) {
    return null;
  }
  return projectPath;
}

Future<List<String>> _discoverKlipioProjectPaths() async {
  final root = await _klipioDraftsRoot();
  await root.create(recursive: true);
  final projects = <(String, DateTime)>[];
  await for (final entity in root.list(followLinks: false)) {
    if (entity is! Directory) continue;
    final path =
        '${entity.path}${Platform.pathSeparator}$_klipioProjectFileName';
    final file = File(path);
    if (!await file.exists()) continue;
    final stat = await file.stat();
    projects.add((path, stat.modified));
  }
  projects.sort((a, b) => b.$2.compareTo(a.$2));
  return [for (final project in projects) project.$1];
}

Future<void> _ensureKlipioProjectStructure(String projectPath) async {
  if (!_isKlipioProjectBundlePath(projectPath)) return;
  final root = File(projectPath).parent;
  await root.create(recursive: true);
  for (final relativePath in [
    'Resources',
    'Resources${Platform.pathSeparator}Media',
    'Resources${Platform.pathSeparator}Audio',
    'Resources${Platform.pathSeparator}Images',
    'Timelines',
    'Cache',
    'Cache${Platform.pathSeparator}Thumbnails',
    'Cache${Platform.pathSeparator}Proxies',
    'Backups',
  ]) {
    await Directory(
      '${root.path}${Platform.pathSeparator}$relativePath',
    ).create(recursive: true);
  }
}

Future<Directory> _uniqueKlipioProjectDirectory(
  Directory parent,
  String preferredName, {
  String? currentPath,
}) async {
  await parent.create(recursive: true);
  final safeName = _safeProjectDirectoryName(preferredName);
  for (var index = 0; index < 10000; index++) {
    final suffix = index == 0 ? '' : ' ($index)';
    final candidate = Directory(
      '${parent.path}${Platform.pathSeparator}$safeName$suffix',
    );
    if (currentPath != null &&
        candidate.path.toLowerCase() == currentPath.toLowerCase()) {
      return candidate;
    }
    if (!await candidate.exists()) return candidate;
  }
  return Directory(
    '${parent.path}${Platform.pathSeparator}$safeName ${DateTime.now().millisecondsSinceEpoch}',
  );
}

Future<void> _copyKlipioProjectDirectory(
  Directory source,
  Directory target,
) async {
  await target.create(recursive: true);
  await for (final entity in source.list(followLinks: false)) {
    final targetPath =
        '${target.path}${Platform.pathSeparator}${platform.basename(entity.path)}';
    if (entity is Directory) {
      await _copyKlipioProjectDirectory(entity, Directory(targetPath));
    } else if (entity is File) {
      await entity.copy(targetPath);
    }
  }
}

Future<void> _writeKlipioProjectBundleFiles(
  String projectPath,
  Map<String, Object?> projectData, {
  bool createBackup = true,
}) async {
  final projectFile = File(projectPath);
  if (!_isKlipioProjectBundlePath(projectPath)) {
    await projectFile.writeAsString(jsonEncode(projectData), flush: true);
    return;
  }
  await _ensureKlipioProjectStructure(projectPath);
  final root = projectFile.parent;
  if (createBackup && await projectFile.exists()) {
    final backupPath =
        '${root.path}${Platform.pathSeparator}Backups${Platform.pathSeparator}project.previous.klipio.json';
    await projectFile.copy(backupPath);
  }
  await projectFile.writeAsString(jsonEncode(projectData), flush: true);
  final videos = projectData['videos'] as List? ?? const [];
  final coverSourcePath = videos.isEmpty || videos.first is! Map
      ? ''
      : '${(videos.first as Map)['path'] ?? ''}';
  final metadataFile = File(
    '${root.path}${Platform.pathSeparator}$_klipioProjectMetaFileName',
  );
  String previousCoverSourcePath = '';
  if (await metadataFile.exists()) {
    try {
      final previous = jsonDecode(await metadataFile.readAsString());
      if (previous is Map) {
        previousCoverSourcePath = '${previous['coverSourcePath'] ?? ''}';
      }
    } catch (_) {
      // Invalid metadata should never keep a stale project cover alive.
    }
  }
  if (previousCoverSourcePath.toLowerCase() != coverSourcePath.toLowerCase()) {
    final cover = File(
      '${root.path}${Platform.pathSeparator}cover.jpg',
    );
    if (await cover.exists()) await cover.delete();
  }
  final metadata = <String, Object?>{
    'name': '${projectData['outputName'] ?? ''}',
    'formatVersion': projectData['version'] ?? 1,
    'savedAt': projectData['savedAt'] ?? DateTime.now().toIso8601String(),
    'videoCount': videos.length,
    'projectFile': _klipioProjectFileName,
    'coverSourcePath': coverSourcePath,
  };
  await metadataFile.writeAsString(jsonEncode(metadata), flush: true);
  await File(
    '${root.path}${Platform.pathSeparator}Timelines${Platform.pathSeparator}timeline.json',
  ).writeAsString(
    jsonEncode({
      'selectedComposition': projectData['selectedComposition'],
      'timelines': projectData['timelines'] ?? const <String, Object?>{},
      'timeline': projectData['timeline'],
    }),
    flush: true,
  );
}

