  Widget _folderRow({
    required String title,
    required String value,
    required String fallback,
    required ValueChanged<String> onChanged,
  }) {
    final phone = MediaQuery.sizeOf(context).shortestSide <= 600;
    final field = Row(
      children: [
        Expanded(
          child: Container(
            height: 44,
            alignment: Alignment.centerLeft,
            padding: const EdgeInsets.symmetric(horizontal: 12),
            decoration: BoxDecoration(
              color: Theme.of(context).colorScheme.surface,
              borderRadius: BorderRadius.circular(8),
              border: Border.all(color: Theme.of(context).dividerColor),
            ),
            child: KText(
              value.trim().isEmpty ? fallback : value,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: value.trim().isEmpty
                    ? Theme.of(context).colorScheme.onSurfaceVariant
                    : null,
              ),
            ),
          ),
        ),
        const SizedBox(width: 8),
        IconButton.filledTonal(
          tooltip: 'Choose folder',
          onPressed: () => _pickFolder(value, onChanged),
          icon: const Icon(Icons.folder_open_outlined),
        ),
      ],
    );
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 7),
      child: phone
          ? Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                KText(title),
                const SizedBox(height: 7),
                field,
              ],
            )
          : Row(children: [
              SizedBox(width: 155, child: KText(title)),
              Expanded(child: field)
            ]),
    );
  }

  Widget _selectRow<T>({
    required String title,
    required T value,
    required List<DropdownMenuItem<T>> items,
    required ValueChanged<T> onChanged,
    String? helper,
  }) {
    final phone = MediaQuery.sizeOf(context).shortestSide <= 600;
    final field = Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        DropdownButtonFormField<T>(
          value: value,
          isExpanded: true,
          items: items,
          onChanged: (next) {
            if (next != null) onChanged(next);
          },
        ),
        if (helper != null) ...[
          const SizedBox(height: 5),
          KText(helper, style: Theme.of(context).textTheme.bodySmall),
        ],
      ],
    );
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8),
      child: phone
          ? Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [KText(title), const SizedBox(height: 7), field],
            )
          : Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                SizedBox(
                    width: 155,
                    child: Padding(
                        padding: const EdgeInsets.only(top: 12),
                        child: KText(title))),
                Expanded(child: field),
              ],
            ),
    );
  }

