                                          KText(
                                            project.missing
                                                ? 'Project file is missing'
                                                : '${project.videoCount} video${project.videoCount == 1 ? '' : 's'} • ${_modifiedLabel(project.modified)}',
                                            style: TextStyle(
                                              color: project.missing
                                                  ? const Color(0xffef4444)
                                                  : Theme.of(context)
                                                      .colorScheme
                                                      .onSurfaceVariant,
                                            ),
                                          ),
                                          const Spacer(),
                                          KText(
                                            _isKlipioProjectBundlePath(
                                                    project.path)
                                                ? File(project.path).parent.path
                                                : project.path,
                                            maxLines: 1,
                                            overflow: TextOverflow.ellipsis,
                                            style: const TextStyle(
                                              color: Color(0xff64748b),
                                              fontSize: 11,
                                            ),
                                          ),
                                        ],
                                      ),
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          );
                        },
                      ),
                    ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _homeProjectThumbnail(_HomeProject project) {
    final thumbnailPath = project.thumbnailPath;
    Widget fallback() => ColoredBox(
          color: Colors.black,
          child: Center(
            child: Icon(
              project.missing ? Icons.link_off : Icons.movie_outlined,
              color: project.missing
                  ? const Color(0xffef4444)
                  : const Color(0xff60a5fa),
              size: 48,
            ),
          ),
        );
    if (thumbnailPath == null || !File(thumbnailPath).existsSync()) {
      return fallback();
    }
    return ColoredBox(
      color: Colors.black,
      child: Image.file(
        File(thumbnailPath),
        fit: BoxFit.cover,
        cacheWidth: 480,
        filterQuality: FilterQuality.medium,
        errorBuilder: (_, __, ___) => fallback(),
      ),
    );
  }
}

class _HomeProject {
  const _HomeProject({
    required this.path,
    this.name = 'Missing project',
    this.modified,
    this.videoCount = 0,
    this.missing = false,
    this.sourceVideoPath,
    this.thumbnailPath,
  });

  final String path;
  final String name;
  final DateTime? modified;
  final int videoCount;
  final bool missing;
  final String? sourceVideoPath;
  final String? thumbnailPath;

  _HomeProject copyWith({String? thumbnailPath}) => _HomeProject(
        path: path,
        name: name,
        modified: modified,
        videoCount: videoCount,
        missing: missing,
        sourceVideoPath: sourceVideoPath,
        thumbnailPath: thumbnailPath ?? this.thumbnailPath,
      );
}

class PickedVideo {
  const PickedVideo({
    required this.name,
    required this.path,
    this.thumbnailPath,
    this.timelineThumbnailPaths = const [],
    this.durationSeconds,
    this.hasAudio = true,
    this.width = 0,
    this.height = 0,
    this.frameRate = 0,
    this.videoCodec = 'unknown',
    this.bitrate = 0,
    this.proxyPath,
  });

  final String name;
  final String path;
  final String? thumbnailPath;
  final List<String> timelineThumbnailPaths;
  final double? durationSeconds;
  final bool hasAudio;
  final int width;
  final int height;
  final double frameRate;
  final String videoCodec;
  final int bitrate;
  final String? proxyPath;

  PickedVideo copyWith({
    String? name,
    String? path,
    String? thumbnailPath,
    List<String>? timelineThumbnailPaths,
    double? durationSeconds,
    bool? hasAudio,
    int? width,
    int? height,
    double? frameRate,
    String? videoCodec,
    int? bitrate,
    String? proxyPath,
  }) {
    return PickedVideo(
      name: name ?? this.name,
      path: path ?? this.path,
      thumbnailPath: thumbnailPath ?? this.thumbnailPath,
      timelineThumbnailPaths:
          timelineThumbnailPaths ?? this.timelineThumbnailPaths,
      durationSeconds: durationSeconds ?? this.durationSeconds,
      hasAudio: hasAudio ?? this.hasAudio,
      width: width ?? this.width,
      height: height ?? this.height,
      frameRate: frameRate ?? this.frameRate,
      videoCodec: videoCodec ?? this.videoCodec,
      bitrate: bitrate ?? this.bitrate,
      proxyPath: proxyPath ?? this.proxyPath,
    );
  }
}

