  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _projectArrangeLayers = widget.settings.arrangeLayers;
    _projectFrameRate = widget.settings.defaultFrameRate;
    _projectProxyEnabled = widget.settings.proxyEnabled;
    final imageCache = PaintingBinding.instance.imageCache;
    imageCache.maximumSize = math.min(imageCache.maximumSize, 256);
    imageCache.maximumSizeBytes =
        math.min(imageCache.maximumSizeBytes, 128 * 1024 * 1024);
    if (widget.settings.defaultExportFolder.trim().isNotEmpty) {
      _outputFolder = widget.settings.defaultExportFolder.trim();
    }
    _textAnimationController = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 1),
    );
    if (widget.active) _textAnimationController.repeat();
    _textAnimationStartedAt = DateTime.now();
    _timelineScrollController.addListener(_handleTimelineScroll);
    unawaited(_musicPreviewPlayer.setReleaseMode(ReleaseMode.loop));
    unawaited(_musicPreviewPlayer.setVolume(_previewAudioVolume(_musicVolume)));
    unawaited(_loadWorkspaceMemory());
    unawaited(_loadInstalledWindowsFonts());
    _autosaveTimer = Timer.periodic(
      const Duration(seconds: 20),
      (_) {
        if (widget.active) unawaited(_autosaveProject());
      },
    );
    if (widget.checkExportAvailable) {
      _loadExportAvailability();
    }
    if (widget.settings.mcpEnabled) {
      unawaited(_syncMcpBridge(enabled: true, port: widget.settings.mcpPort));
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      unawaited(_runStartupAutomationJob());
    });
  }

  @override
  void didUpdateWidget(covariant EditorScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.active != widget.active) {
      if (widget.active) {
        if (!_textAnimationController.isAnimating) {
          _textAnimationController.repeat();
        }
      } else {
        _textAnimationController.stop();
        _filmstripLoadGeneration++;
        unawaited(platform.cancelBackgroundMediaTasks());
        unawaited(_sourceController?.pause());
        unawaited(_previewController?.pause());
        unawaited(_pauseMusicPreview());
      }
    }
    if (!oldWidget.checkExportAvailable && widget.checkExportAvailable) {
      _loadExportAvailability();
    }
    final oldDefault = oldWidget.settings.defaultExportFolder.trim();
    final newDefault = widget.settings.defaultExportFolder.trim();
    if (newDefault.isNotEmpty &&
        newDefault != oldDefault &&
        (_outputFolder == null || _outputFolder == oldDefault)) {
      _outputFolder = newDefault;
    }
    if (oldWidget.settings.mcpEnabled != widget.settings.mcpEnabled ||
        oldWidget.settings.mcpPort != widget.settings.mcpPort) {
      unawaited(
        _syncMcpBridge(
          enabled: widget.settings.mcpEnabled,
          port: widget.settings.mcpPort,
        ),
      );
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state != AppLifecycleState.detached) return;
    _exportCancelToken?.cancel();
    _filmstripLoadGeneration++;
    unawaited(platform.cancelBackgroundMediaTasks());
  }

  Future<void> _syncMcpBridge(
      {required bool enabled, required int port}) async {
    final generation = ++_mcpBridgeGeneration;
    await _mcpBridge?.stop();
    _mcpBridge = null;
    if (!enabled || !mounted) return;
    final bridge = MCPBridge(
      onTimelineChanged: (timeline) {
        if (!mounted) return;
        setState(() {
          _applyTimelineModelUpdate(timeline);
          _status = 'Timeline updated by MCP';
        });
        unawaited(_autosaveProject());
      },
      onSeek: _requestMultiTrackTimelineSeek,
      onPlayPause: () => unawaited(_togglePreview()),
      getCurrentTimeline: () => _multiTrackTimeline,
      getCurrentSelection: () => {
        'clip_id': _selectedTimelineClipId,
        'clip_ids': _effectiveSelectedTimelineClipIds.toList(),
        'caption_ids': _effectiveSelectedCaptionIds.toList(),
      },
      getProjectInfo: () => {
        'project_name': _nameController.text.trim().isEmpty
            ? 'Klipio'
            : _nameController.text.trim(),
        'duration': _multiTrackTimeline.duration,
        'path': _currentProjectPath,
      },
      getMediaLibrary: () => [
        for (final video in _videos)
          {
            'name': video.name,
            'path': video.path,
            'duration': video.durationSeconds,
            'has_audio': video.hasAudio,
          },
      ],
      onOpenProject: (path) => unawaited(_openProjectFromMcp(path)),
    );
    _mcpBridge = bridge;
    try {
      await bridge.start(port: port);
      if (!mounted || generation != _mcpBridgeGeneration) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('MCP connected at ws://127.0.0.1:$port'),
          backgroundColor: Colors.green,
        ),
      );
    } catch (error) {
      if (!mounted || generation != _mcpBridgeGeneration) return;
      _mcpBridge = null;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('MCP could not start: $error')),
      );
    }
  }

  Future<void> _openProjectFromMcp(String path) async {
    var projectPath = path.trim();
    if (Directory(projectPath).existsSync()) {
      projectPath = await _projectFileFromSelectedFolder(projectPath) ?? '';
    }
    if (projectPath.isEmpty || !File(projectPath).existsSync()) {
      if (mounted) setState(() => _status = 'MCP project not found: $path');
      return;
    }
    widget.onShowEditor?.call();
    await _loadProject(projectPath);
  }

  Future<void> _loadInstalledWindowsFonts() async {
    if (!Platform.isWindows || Platform.environment['FLUTTER_TEST'] == 'true') {
      return;
    }
    final discovered = <String>{..._defaultFontChoices};
    const registryKeys = [
      r'HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts',
      r'HKCU\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts',
    ];
    for (final key in registryKeys) {
      try {
        final result = await Process.run('reg.exe', ['query', key]);
        if (result.exitCode != 0) continue;
        for (final line in '${result.stdout}'.split(RegExp(r'[\r\n]+'))) {
          final match = RegExp(
            r'^\s*(.*?)\s+REG_(?:SZ|EXPAND_SZ)\s+',
            caseSensitive: false,
          ).firstMatch(line);
          var name = match?.group(1)?.trim() ?? '';
          name = name
              .replaceFirst(
                RegExp(r'\s+\((?:TrueType|OpenType|All Res)\)$',
                    caseSensitive: false),
                '',
              )
              .trim();
          name = _normalizedFontFamily(name);
          if (_isReadableFontFamily(name)) discovered.add(name);
        }
      } catch (_) {
        // The built-in font list remains available if Registry access fails.
      }
    }
    final unique = <String, String>{};
    for (final name in discovered) {
      unique.putIfAbsent(name.toLowerCase(), () => name);
    }
    final sorted = unique.values.toList()
      ..sort((a, b) => a.toLowerCase().compareTo(b.toLowerCase()));
    if (!mounted) return;
    setState(() {
      _fontChoices
        ..clear()
        ..addAll(sorted);
    });
  }

  String _normalizedFontFamily(String value) {
    var name = value.trim().replaceFirst(RegExp(r'^@+'), '');
    for (final builtIn in _defaultFontChoices) {
      if (builtIn.toLowerCase() == name.toLowerCase()) return builtIn;
    }
    name = name.replaceFirst(
      RegExp(
        r'\s+(?:regular|roman|book|medium|semi[- ]?bold|demi[- ]?bold|extra[- ]?bold|ultra[- ]?bold|bold|extra[- ]?light|ultra[- ]?light|light|thin|black|italic|oblique)(?:\s+(?:italic|oblique))?$',
        caseSensitive: false,
      ),
      '',
    );
    return name.trim();
  }

  bool _isReadableFontFamily(String name) {
    if (name.length < 2 || name.length > 80) return false;
    final lower = name.toLowerCase();
    if (RegExp(
      r'barcode|bar code|symbol|wingdings|webdings|marlett|dingbat|ornament|icon|emoji|music|demo|trial|personal use',
    ).hasMatch(lower)) {
      return false;
    }
    return RegExp(r'[a-zA-Z\u1780-\u17ff]').hasMatch(name);
  }

  String _safeCaptionFont(String value) {
    final normalized = _normalizedFontFamily(value);
    if (!_isReadableFontFamily(normalized)) return 'Arial';
    for (final font in _fontChoices) {
      if (font.toLowerCase() == normalized.toLowerCase()) return font;
    }
    return _defaultFontChoices.contains(normalized) ? normalized : 'Arial';
  }

  double _captionUiFontSize(double value) {
    final normalized = value > 40 ? value / 4.5 : value;
    return normalized.clamp(6.0, 36.0).toDouble();
  }

  double _captionAssFontSize(double value) {
    final normalized = value <= 40 ? value * 4.5 : value;
    return normalized.clamp(27.0, 162.0).toDouble();
  }

  double _captionPreviewFontSize({
    required double scale,
    required double previewHeight,
  }) {
    return (_captionAssFontSize(_captionFontSize) * scale)
        .clamp(1.0, previewHeight * 0.8)
        .toDouble();
  }

  Future<void> _runStartupAutomationJob() async {
    final job = startupAutomationJob;
    if (job == null || _startupAutomationStarted) return;
    _startupAutomationStarted = true;
    try {
      await job.writeResult('loading', message: 'Loading videos into Klipio.');
      final sourcePath = job.sourcePath;
      final paths = job.sourceMode == 'folder'
          ? await platform.videoFilesInFolder(sourcePath)
          : [sourcePath];
      final validPaths =
          paths.where((path) => File(path).existsSync()).toList();
      if (validPaths.isEmpty) {
        throw FileSystemException('No video files were found.', sourcePath);
      }
      await _setPickedVideos([
        for (final path in validPaths)
          PickedVideo(name: platform.basename(path), path: path),
      ]);
      if (!mounted) return;
      setState(() {
        _outputFolder = job.outputFolder.isEmpty ? null : job.outputFolder;
        _outputRatio = job.outputRatio;
        _originalVolume = job.originalVolume.clamp(0.0, _maxAudioBoost);
        _musicVolume = job.musicVolume.clamp(0.0, _maxAudioBoost);
        _musicPath = job.musicPath;
        _hookDurationController.text =
            job.hookLength.isEmpty ? 'auto' : job.hookLength;
        _hookEditMode = job.hookMode == 'bestMoments'
            ? _HookEditMode.bestMoments
            : _HookEditMode.hookWithVideo;
        _capCutRenderEdits = job.renderEdits;
        _capCutOneFolder = job.capCutOneFolder;
        _exportTimelineTogether = true;
        _status = 'Automation job loaded.';
      });
      await job.writeResult('editing', message: 'Applying Klipio settings.');
      if (job.hookMode != 'none') {
        await _applyHookVideoEdit(allVideos: true);
      }
      if (!job.createCapCutDraft) {
        await job.writeResult(
          'ready_for_review',
          message: 'Klipio is ready for review.',
        );
        return;
      }
      await job.writeResult('creating_capcut_draft');
      final automationExportAvailable = await isExportAvailable();
      if (mounted) {
        setState(() => _exportAvailable = automationExportAvailable);
      }
      await _createCapCutDraft();
      await job.writeResult(
        _lastCapCutDraftSuccess ? 'capcut_draft_ready' : 'failed',
        message: _lastCapCutDraftSuccess
            ? 'CapCut draft created by Klipio.'
            : (_lastCapCutDraftMessage.isEmpty
                ? 'Klipio could not create the CapCut draft.'
                : _lastCapCutDraftMessage),
        draftFolder: _lastCapCutDraftFolder,
      );
    } catch (error) {
      if (mounted) setState(() => _status = 'Automation failed: $error');
      await job.writeResult('failed', message: '$error');
    }
  }

