  Future<void> _loadExportAvailability() async {
    final available = await isExportAvailable();
    if (!mounted) return;
    setState(() => _exportAvailable = available);
  }

  Future<void> _loadWorkspaceMemory() async {
    try {
      final prefs = await loadSharedPreferencesRecovering();
      final presetJson = prefs.getStringList(_exportPresetsKey) ?? const [];
      final presets = <_ExportPreset>[];
      for (final raw in presetJson) {
        final data = jsonDecode(raw);
        if (data is Map<String, Object?>) {
          presets.add(_ExportPreset.fromJson(data));
        }
      }
      if (!mounted) return;
      setState(() {
        _recentProjectPaths
          ..clear()
          ..addAll(prefs.getStringList(_recentProjectsKey) ?? const []);
        _recentFolders
          ..clear()
          ..addAll(prefs.getStringList(_recentFoldersKey) ?? const []);
        _exportPresets
          ..clear()
          ..addAll(presets);
        final savedOrder = prefs.getStringList(_workspaceDockOrderKey);
        if (savedOrder != null &&
            savedOrder.toSet().containsAll(_workspaceDockOrder)) {
          _workspaceDockOrder
            ..clear()
            ..addAll(savedOrder.where(_workspaceDockWidths.containsKey));
        }
        final savedWidths = prefs.getString(_workspaceDockWidthsKey);
        if (savedWidths != null) {
          final decoded = jsonDecode(savedWidths);
          if (decoded is Map) {
            for (final entry in decoded.entries) {
              final width = double.tryParse('${entry.value}');
              if (_workspaceDockWidths.containsKey('${entry.key}') &&
                  width != null) {
                _workspaceDockWidths['${entry.key}'] = width;
              }
            }
          }
        }
        final visible = prefs.getStringList(_workspaceVisiblePanelsKey);
        if (visible != null && visible.isNotEmpty) {
          _visibleWorkspacePanels
            ..clear()
            ..addAll(visible);
        }
        _timelineWorkspaceHeight =
            prefs.getDouble(_workspaceTimelineHeightKey) ??
                _timelineWorkspaceHeight;
        final savedTrackHeights = prefs.getString(_workspaceTrackHeightsKey);
        if (savedTrackHeights != null) {
          final decoded = jsonDecode(savedTrackHeights);
          if (decoded is Map) {
            _timelineTrackHeights
              ..clear()
              ..addEntries(decoded.entries.map((entry) => MapEntry(
                    '${entry.key}',
                    (double.tryParse('${entry.value}') ?? 64)
                        .clamp(34, 150)
                        .toDouble(),
                  )));
          }
        }
      });
    } catch (_) {
      // Recent lists are convenience state only.
    }
  }

  Future<void> _saveWorkspaceMemory() async {
    try {
      final prefs = await loadSharedPreferencesRecovering();
      await prefs.setStringList(_recentProjectsKey, _recentProjectPaths);
      await prefs.setStringList(_recentFoldersKey, _recentFolders);
      await prefs.setStringList(
        _exportPresetsKey,
        [for (final preset in _exportPresets) jsonEncode(preset.toJson())],
      );
      await prefs.setStringList(_workspaceDockOrderKey, _workspaceDockOrder);
      await prefs.setString(
        _workspaceDockWidthsKey,
        jsonEncode(_workspaceDockWidths),
      );
      await prefs.setStringList(
        _workspaceVisiblePanelsKey,
        _visibleWorkspacePanels.toList(),
      );
      await prefs.setDouble(
        _workspaceTimelineHeightKey,
        _timelineWorkspaceHeight,
      );
      await prefs.setString(
        _workspaceTrackHeightsKey,
        jsonEncode(_timelineTrackHeights),
      );
    } catch (_) {
      // Recent lists are convenience state only.
    }
  }

  void _scheduleWorkspaceMemorySave() {
    _workspaceMemorySaveTimer?.cancel();
    _workspaceMemorySaveTimer = Timer(
      const Duration(milliseconds: 400),
      () => unawaited(_saveWorkspaceMemory()),
    );
  }

  void _rememberProject(String path) {
    _recentProjectPaths
      ..remove(path)
      ..insert(0, path);
    if (_recentProjectPaths.length > _maxRecentProjects) {
      _recentProjectPaths.removeRange(
        _maxRecentProjects,
        _recentProjectPaths.length,
      );
    }
    unawaited(_saveWorkspaceMemory());
  }

  void _syncRecentProjectPaths(List<String> paths) {
    if (!mounted) return;
    setState(() {
      _recentProjectPaths
        ..clear()
        ..addAll(paths.take(_maxRecentProjects));
    });
  }

  void _syncExternalProjectName(
    String oldPath,
    String newPath,
    String name,
  ) {
    final current = _currentProjectPath;
    if (current == null || current.toLowerCase() != oldPath.toLowerCase()) {
      return;
    }
    setState(() {
      _currentProjectPath = newPath;
      _nameController.text = name;
      _status = 'Project renamed to $name';
    });
  }

  Future<void> _closeExternallyDeletedProject(String path) async {
    final current = _currentProjectPath;
    if (current == null || current.toLowerCase() != path.toLowerCase()) return;
    await _clearProject(confirm: false, createProjectFile: false);
  }

  void _rememberFolder(String path) {
    if (path.trim().isEmpty) return;
    _recentFolders
      ..remove(path)
      ..insert(0, path);
    if (_recentFolders.length > 8) {
      _recentFolders.removeRange(8, _recentFolders.length);
    }
    unawaited(_saveWorkspaceMemory());
  }

  Future<void> _saveCurrentExportPreset() async {
    final controller = TextEditingController(
      text: 'Preset ${_exportPresets.length + 1}',
    );
    final name = await showDialog<String>(
      context: context,
      builder: (context) => AlertDialog(
        title: const KText('Save Export Preset'),
        content: TextField(
          controller: controller,
          autofocus: true,
          decoration: const InputDecoration(labelText: 'Preset name'),
          onSubmitted: (value) => Navigator.of(context).pop(value),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(),
            child: const KText('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(context).pop(controller.text),
            child: const KText('Save'),
          ),
        ],
      ),
    );
    controller.dispose();
    final trimmed = name?.trim();
    if (trimmed == null || trimmed.isEmpty) return;
    final preset = _ExportPreset(
      name: trimmed,
      outputName: _nameController.text,
      batchRenamePattern: _batchRenamePattern,
      qualityPreset: _qualityPreset,
      customBitrateKbps: _customBitrateKbps,
      exportTimelineTogether: _exportTimelineTogether,
      useNumberRange: _useNumberRange,
      rangeStart: _numberStartController.text,
      rangeEnd: _numberEndController.text,
    );
    setState(() {
      _exportPresets.removeWhere((item) => item.name == trimmed);
      _exportPresets.insert(0, preset);
      if (_exportPresets.length > 12) {
        _exportPresets.removeRange(12, _exportPresets.length);
      }
      _status = 'Saved export preset: $trimmed';
    });
    unawaited(_saveWorkspaceMemory());
  }

  void _applyExportPreset(_ExportPreset preset) {
    setState(() {
      _nameController.text = preset.outputName;
      _batchRenamePattern = preset.batchRenamePattern;
      _qualityPreset = preset.qualityPreset;
      _customBitrateKbps = preset.customBitrateKbps;
      _batchRenameController.text = preset.batchRenamePattern;
      _exportTimelineTogether = preset.exportTimelineTogether;
      _useNumberRange = preset.useNumberRange;
      _numberStartController.text = preset.rangeStart;
      _numberEndController.text = preset.rangeEnd;
      _status = 'Applied export preset: ${preset.name}';
    });
  }

  Future<String> _autosavePath() async {
    final draftsRoot = await _klipioDraftsRoot();
    final now = DateTime.now();
    final stamp = '${now.year.toString().padLeft(4, '0')}-'
        '${now.month.toString().padLeft(2, '0')}-'
        '${now.day.toString().padLeft(2, '0')}_'
        '${now.hour.toString().padLeft(2, '0')}-'
        '${now.minute.toString().padLeft(2, '0')}-'
        '${now.second.toString().padLeft(2, '0')}-'
        '${now.millisecond.toString().padLeft(3, '0')}';
    final requestedName = _nameController.text.trim();
    final projectDirectory = await _uniqueKlipioProjectDirectory(
      draftsRoot,
      requestedName.isEmpty ? 'Klipio Project $stamp' : requestedName,
    );
    final path =
        '${projectDirectory.path}${Platform.pathSeparator}$_klipioProjectFileName';
    await _ensureKlipioProjectStructure(path);
    return path;
  }

  Future<void> _autosaveProject({bool includeEmptyProject = false}) async {
    if (_videos.isEmpty && !includeEmptyProject) return;
    try {
      _saveSelectedClipTimelineEdit();
      final path = _currentProjectPath ?? await _autosavePath();
      await _writeKlipioProjectBundleFiles(path, _projectJson());
      _currentProjectPath ??= path;
      _rememberProject(path);
    } catch (_) {
      // Autosave must never interrupt editing.
    }
  }

  Future<void> _saveProjectAs() async {
    if (_videos.isEmpty) {
      _showMessage('Import videos before saving a project.');
      return;
    }
    _saveSelectedClipTimelineEdit();
    var target = _currentProjectPath;
    if (target == null || !await _isManagedKlipioProjectPath(target)) {
      final draftsRoot = await _klipioDraftsRoot();
      final projectDirectory = await _uniqueKlipioProjectDirectory(
        draftsRoot,
        _nameController.text.trim().isEmpty
            ? 'Klipio Project'
            : _nameController.text,
      );
      target =
          '${projectDirectory.path}${Platform.pathSeparator}$_klipioProjectFileName';
    }
    final saveTarget = target;
    await _writeKlipioProjectBundleFiles(saveTarget, _projectJson());
    final projectDirectory = File(saveTarget).parent;
    setState(() {
      _currentProjectPath = saveTarget;
      _status = 'Project saved: ${platform.basename(projectDirectory.path)}';
      _rememberProject(saveTarget);
    });
  }

  Future<void> _openProjectDialog() async {
    final draftsRoot = await _klipioDraftsRoot();
    await draftsRoot.create(recursive: true);
    final selectedFolder = await FilePicker.platform.getDirectoryPath(
      dialogTitle: 'Open Klipio project folder',
      initialDirectory: draftsRoot.path,
    );
    if (selectedFolder == null) return;
    final path = await _projectFileFromSelectedFolder(selectedFolder);
    if (path == null) {
      _showMessage(
        'Choose one project folder directly inside Klipio Drafts. The internal project file is opened automatically.',
      );
      return;
    }
    await _loadProject(path);
  }

  Future<void> _loadProject(String path) async {
    try {
      final data = jsonDecode(await File(path).readAsString());
      if (data is! Map<String, Object?>) {
        throw const FormatException('Project file is not an object.');
      }
      final videos = (data['videos'] as List? ?? const [])
          .whereType<Map>()
          .map((item) => PickedVideo(
                name: '${item['name'] ?? platform.basename('${item['path']}')}',
                path: '${item['path'] ?? ''}',
                durationSeconds:
                    double.tryParse('${item['durationSeconds'] ?? ''}'),
                hasAudio: item['hasAudio'] as bool? ?? true,
                width: int.tryParse('${item['width'] ?? ''}') ?? 0,
                height: int.tryParse('${item['height'] ?? ''}') ?? 0,
                frameRate: double.tryParse('${item['frameRate'] ?? ''}') ?? 0,
                videoCodec: '${item['videoCodec'] ?? 'unknown'}',
                bitrate: int.tryParse('${item['bitrate'] ?? ''}') ?? 0,
                proxyPath: '${item['proxyPath'] ?? ''}'.trim().isEmpty
                    ? null
                    : '${item['proxyPath']}',
              ))
          .where(
              (video) => video.path.isNotEmpty && File(video.path).existsSync())
          .toList();
      if (videos.isEmpty) {
        await _clearProject(
          confirm: false,
          createProjectFile: false,
        );
      } else {
        _applyProjectSettings(data['projectSettings']);
        _multiTrackTimeline = TimelineModel.empty();
        _selectedTimelineClipId = null;
        _selectedTimelineClipIds.clear();
        _selectedCaptionIds.clear();
        _musicTimelineSelected = false;
        _programTimelineClipId = null;
        _compositionPaths.clear();
        _projectMediaPathsByComposition.clear();
        _timelinesByComposition.clear();
        _selectedCompositionPath = null;
        await _setPickedVideos(videos, resetEdits: false);
      }
      if (!mounted) return;
      setState(() {
        _currentProjectPath = path;
        _outputFolder = data['outputFolder'] as String?;
        _nameController.text = '${data['outputName'] ?? ''}';
        _qualityPreset = '${data['qualityPreset'] ?? _qualityPreset}';
        _exportCodec = _safeExportCodec(
          '${data['exportCodec'] ?? _exportCodec}',
        );
        _exportFrameRate = _safeExportFrameRate(
          double.tryParse('${data['exportFrameRate'] ?? _exportFrameRate}') ??
              _exportFrameRate,
        );
        _outputRatio = '${data['outputRatio'] ?? _outputRatio}';
        _batchRenamePattern = '${data['batchRenamePattern'] ?? ''}';
        _batchRenameController.text = _batchRenamePattern;
        _exportTimelineTogether =
            data['exportTimelineTogether'] as bool? ?? _exportTimelineTogether;
        _applyProjectSettings(data['projectSettings']);
        _applyProjectAdvanced(data['advanced']);
        _applyProjectTransform(data['transform']);
        _applyProjectColor(data['color']);
        _applyProjectAudio(data['audio']);
        _applyProjectCaptions(data['captions']);
        _captionCuesByVideo
          ..clear()
          ..addAll(
            _captionCuesMapFromJson(data['captionCues'])
              ..removeWhere(
                (captionPath, _) =>
                    !_videos.any((video) => video.path == captionPath),
              ),
          );
        _selectedCaptionCueIndex = 0;
        _textOverlays
          ..clear()
          ..addAll(_textOverlaysFromJson(data['textOverlays']));
        if (_textOverlays.isEmpty) _textOverlays.add(const _TextOverlayDraft());
        _selectedTextOverlayIndex = 0;
        _loadTextOverlay(_textOverlays.first);
        _clipTimelineEdits
          ..clear()
          ..addAll(_clipEditsFromJson(data['clipEdits']));
        _clipTransformOverrides
          ..clear()
          ..addAll(
            _clipTransformOverridesFromJson(
              data['clipTransformOverrides'],
              _clipTimelineEdits,
            ),
          );
        final savedCompositions = [
          for (final item in data['compositions'] as List? ?? const [])
            if (_videos.any((video) => video.path == '$item')) '$item',
        ];
        if (savedCompositions.isNotEmpty) {
          _compositionPaths
            ..clear()
            ..addAll(savedCompositions);
        }
        final savedProjectMedia = data['projectMedia'];
        if (savedProjectMedia is Map) {
          _projectMediaPathsByComposition.clear();
          for (final entry in savedProjectMedia.entries) {
            final composition = '${entry.key}';
            if (!_compositionPaths.contains(composition)) continue;
            _projectMediaPathsByComposition[composition] = [
              for (final item in entry.value as List? ?? const [])
                if (_videos.any((video) => video.path == '$item')) '$item',
            ];
          }
        }
        for (final composition in _compositionPaths) {
          _projectMediaPathsByComposition.putIfAbsent(
            composition,
            () => [composition],
          );
        }
        final savedTimelines = data['timelines'];
        if (savedTimelines is Map) {
          _timelinesByComposition.clear();
          for (final entry in savedTimelines.entries) {
            final composition = '${entry.key}';
            if (_compositionPaths.contains(composition)) {
              _timelinesByComposition[composition] =
                  TimelineModel.fromJson(entry.value);
            }
          }
        }
        final requestedComposition = '${data['selectedComposition'] ?? ''}';
        _selectedCompositionPath =
            _compositionPaths.contains(requestedComposition)
                ? requestedComposition
                : (_compositionPaths.isEmpty ? null : _compositionPaths.first);
        if (savedTimelines is Map && _selectedCompositionPath != null) {
          _multiTrackTimeline =
              _timelinesByComposition[_selectedCompositionPath!] ??
                  TimelineModel.empty();
        } else {
          _multiTrackTimeline = data['timeline'] == null
              ? _buildLegacyMultiTrackTimeline()
              : TimelineModel.fromJson(data['timeline']);
          if (_selectedCompositionPath != null) {
            _timelinesByComposition[_selectedCompositionPath!] =
                _multiTrackTimeline;
          }
        }
        // Older project bundles could save split parts with every part at
        // timeline time zero. Repair that data once when opening the project
        // so video and linked audio play as a continuous sequence again.
        _multiTrackTimeline = _repairLoadedTimeline(_multiTrackTimeline);
        if (_selectedCompositionPath != null) {
          _timelinesByComposition[_selectedCompositionPath!] =
              _multiTrackTimeline;
        }
        _ensureTextTimelineTracks();
        _timelineMarkers
          ..clear()
          ..addAll([
            for (final item in data['timelineMarkers'] as List? ?? const [])
              if (double.tryParse('$item') != null) double.parse('$item'),
          ]);
        _selectedTimelineClipId = null;
        _selectedTimelineClipIds.clear();
        _selectedCaptionIds.clear();
        _musicTimelineSelected = false;
        _programTimelineClipId = _multiTrackTimeline.videoTracks
                .expand((track) => track.clips)
                .isEmpty
            ? null
            : _multiTrackTimeline.videoTracks
                .expand((track) => track.clips)
                .first
                .id;
        _rememberProject(path);
        if (_outputFolder != null) _rememberFolder(_outputFolder!);
        _status = _isKlipioProjectBundlePath(path)
            ? 'Project loaded: ${platform.basename(File(path).parent.path)}'
            : 'Project loaded: ${platform.basename(path)}';
      });
      final selectedComposition = _selectedCompositionPath;
      if (selectedComposition != null) {
        await _selectComposition(selectedComposition);
      } else {
        _loadClipTimelineEdit(_selectedVideoIndex);
      }
    } catch (error) {
      _showMessage('Could not open project: $error');
    }
  }

  TimelineModel _repairLoadedTimeline(TimelineModel model) {
    final repairedTracks = <TrackModel>[];
    var changed = false;
    for (final track in model.tracks) {
      final clips = [...track.clips];
      final sameMedia = clips.length > 1 &&
          clips.map((clip) => clip.mediaPath).toSet().length == 1;
      final allAtZero = clips.length > 1 &&
          clips.every((clip) => clip.timelineStart.abs() < 0.001);
      final hasSourceOffset = clips.any((clip) => clip.sourceStart > 0.001);
      if (sameMedia && allAtZero && hasSourceOffset) {
        clips.sort((a, b) {
          final source = a.sourceStart.compareTo(b.sourceStart);
          return source != 0 ? source : a.id.compareTo(b.id);
        });
        var cursor = 0.0;
        for (var index = 0; index < clips.length; index++) {
          final clip = clips[index];
          if ((clip.timelineStart - cursor).abs() > 0.001) changed = true;
          clips[index] = clip.copyWith(timelineStart: cursor);
          cursor += math.max(0.001, clip.duration);
        }
      }
      repairedTracks.add(track.copyWith(clips: clips));
    }
    if (!changed) return model;
    return TimelineModel(
      tracks: repairedTracks,
      duration: TimelineModel.calculateDuration(repairedTracks),
    ).normalized();
  }

  void _applyProjectTransform(Object? value) {
    final data = value is Map ? value : const {};
    double number(String key, double fallback) =>
        double.tryParse('${data[key] ?? fallback}') ?? fallback;
    _speed = number('speed', _speed);
    _flip = '${data['flip'] ?? _flip}';
    _scaleX = number('scaleX', _scaleX);
    _scaleY = number('scaleY', _scaleY);
    _zoom = number('zoom', _zoom);
    _panX = number('panX', _panX);
    _panY = number('panY', _panY);
    final canvasMode = '${data['canvasMode'] ?? _canvasMode}'.toLowerCase();
    _canvasMode =
        const {'none', 'blur', 'color', 'pattern'}.contains(canvasMode)
            ? canvasMode
            : 'none';
    final canvasPattern =
        '${data['canvasPattern'] ?? _canvasPattern}'.toLowerCase();
    _canvasPattern =
        const {'grid', 'stripes', 'checker', 'dots'}.contains(canvasPattern)
            ? canvasPattern
            : 'grid';
    _canvasColor =
        _parseHexColor('${data['canvasColor'] ?? ''}') ?? _canvasColor;
    _canvasBlur = number('canvasBlur', _canvasBlur).clamp(4, 80).toDouble();
  }

  void _applyProjectSettings(Object? value) {
    final data = value is Map ? value : const {};
    _projectColorSpace = '${data['colorSpace'] ?? _projectColorSpace}';
    _projectResolution = '${data['resolution'] ?? _projectResolution}';
    _projectProxyResolution =
        '${data['proxyResolution'] ?? _projectProxyResolution}';
    _projectProxyEnabled =
        data['proxyEnabled'] as bool? ?? _projectProxyEnabled;
    _projectCopyMedia = data['copyMedia'] as bool? ?? _projectCopyMedia;
    _projectArrangeLayers =
        data['arrangeLayers'] as bool? ?? _projectArrangeLayers;
    _projectFrameRate =
        double.tryParse('${data['frameRate'] ?? _projectFrameRate}') ??
            _projectFrameRate;
  }

  _ClipTimelineEdit _clipEditWithCurrentTransform(_ClipTimelineEdit edit) {
    return edit.copyWith(
      speed: _speed,
      flip: _flip,
      scaleX: _scaleX,
      scaleY: _scaleY,
      zoom: _zoom,
      panX: _panX,
      panY: _panY,
      originalVolume: _originalVolume,
    );
  }

  void _saveSelectedTransformEdit() {
    if (_videos.isEmpty ||
        _selectedVideoIndex < 0 ||
        _selectedVideoIndex >= _videos.length) {
      return;
    }
    final path = _videos[_selectedVideoIndex].path;
    _clipTimelineEdits[path] =
        _clipEditWithCurrentTransform(_clipTimelineEditFor(path));
  }

  bool _updateSelectedTimelineClipTransform(_ClipTimelineEdit edit) {
    if (_videos.isEmpty ||
        _selectedVideoIndex < 0 ||
        _selectedVideoIndex >= _videos.length) {
      return false;
    }
    final path = _videos[_selectedVideoIndex].path;
    final hasVideo = _multiTrackTimeline.videoTracks.any(
      (track) => track.clips.any((clip) => clip.mediaPath == path),
    );
    if (!hasVideo) return false;
    _applyTimelineModelUpdate(
      _timelineWithAppliedVideoSettings(
        _multiTrackTimeline,
        path,
        edit,
        copyFrame: true,
        copyAudio: true,
      ),
    );
    _storeActiveCompositionTimeline();
    return true;
  }

  TimelineModel _timelineWithAppliedVideoSettings(
    TimelineModel model,
    String videoPath,
    _ClipTimelineEdit edit, {
    required bool copyFrame,
    required bool copyAudio,
    bool copyCanvas = false,
    String? canvasMode,
    String? canvasColor,
    String? canvasPattern,
    double? canvasBlur,
  }) {
    return model.copyWith(
      tracks: [
        for (final track in model.tracks)
          track.copyWith(
            clips: [
              for (final clip in track.clips)
                if (clip.mediaPath != videoPath)
                  clip
                else if (track.type == TrackType.video)
                  clip.copyWith(
                    transform: clip.transform.copyWith(
                      scaleX: copyFrame
                          ? edit.scaleX * edit.zoom
                          : clip.transform.scaleX,
                      scaleY: copyFrame
                          ? edit.scaleY * edit.zoom
                          : clip.transform.scaleY,
                      positionX: copyFrame
                          ? (0.5 + edit.panX * 0.5).clamp(0, 1).toDouble()
                          : clip.transform.positionX,
                      positionY: copyFrame
                          ? (0.5 + edit.panY * 0.5).clamp(0, 1).toDouble()
                          : clip.transform.positionY,
                      canvasMode: copyCanvas
                          ? (canvasMode ?? 'none')
                          : clip.transform.canvasMode,
                      canvasColor: copyCanvas
                          ? (canvasColor ?? '#F4C70F')
                          : clip.transform.canvasColor,
                      canvasPattern: copyCanvas
                          ? (canvasPattern ?? 'grid')
                          : clip.transform.canvasPattern,
                      canvasBlur: copyCanvas
                          ? (canvasBlur ?? 24)
                          : clip.transform.canvasBlur,
                    ),
                  )
                else if (track.type == TrackType.audio && copyAudio)
                  clip.copyWith(volume: edit.originalVolume)
                else
                  clip,
            ],
          ),
      ],
    );
  }

  void _loadTimelineClipTransformIntoInspector(ClipModel clip) {
    _scaleX = clip.transform.scaleX;
    _scaleY = clip.transform.scaleY;
    _zoom = 1;
    _panX = ((clip.transform.positionX - 0.5) * 2).clamp(-1, 1);
    _panY = ((clip.transform.positionY - 0.5) * 2).clamp(-1, 1);
    _canvasMode = clip.transform.canvasMode;
    _canvasPattern = clip.transform.canvasPattern;
    _canvasColor =
        _parseHexColor(clip.transform.canvasColor) ?? const Color(0xfff4c70f);
    _canvasBlur = clip.transform.canvasBlur;
  }

  void _updateCanvasSettings({
    String? mode,
    Color? color,
    String? pattern,
    double? blur,
    bool applyToAll = false,
  }) {
    final selectedIds = _effectiveSelectedTimelineClipIds;
    final editableIds = <String>{};
    for (final track in _multiTrackTimeline.videoTracks) {
      if (track.isLocked) continue;
      for (final clip in track.clips) {
        if (applyToAll || selectedIds.contains(clip.id)) {
          editableIds.add(clip.id);
        }
      }
    }
    if (editableIds.isEmpty) {
      _showMessage('Select an unlocked video clip first.');
      return;
    }
    _recordEditorHistory('video-canvas');
    setState(() {
      _canvasMode = mode ?? _canvasMode;
      _canvasColor = color ?? _canvasColor;
      _canvasPattern = pattern ?? _canvasPattern;
      _canvasBlur = (blur ?? _canvasBlur).clamp(4, 80).toDouble();
      var next = _multiTrackTimeline;
      for (final clipId in editableIds) {
        final result = next.clipById(clipId);
        if (result == null || result.track.type != TrackType.video) continue;
        next = _timelineEditor.updateClipTransform(
          next,
          clipId,
          result.clip.transform.copyWith(
            canvasMode: _canvasMode,
            canvasColor: _colorToHex(_canvasColor),
            canvasPattern: _canvasPattern,
            canvasBlur: _canvasBlur,
          ),
        );
      }
      _applyTimelineModelUpdate(next);
      _storeActiveCompositionTimeline();
      _status = applyToAll
          ? 'Canvas applied to all video clips'
          : 'Canvas updated for ${editableIds.length} clip${editableIds.length == 1 ? '' : 's'}';
    });
    unawaited(_autosaveProject());
  }

  void _setSelectedTransformEdit(
      _ClipTimelineEdit Function(_ClipTimelineEdit) update) {
    if (_videos.isEmpty) {
      setState(() {});
      return;
    }
    final path = _videos[_selectedVideoIndex].path;
    final current = _clipTimelineEditFor(path);
    final next = update(_clipEditWithCurrentTransform(current));
    if (current.sameAs(next)) return;
    _recordEditorHistory('video-transform');
    setState(() {
      _clipTimelineUndoStacks.putIfAbsent(path, () => []).add(current);
      _clipTimelineRedoStacks[path]?.clear();
      if (_selectedVideoIndex > 0) {
        _clipTransformOverrides.add(path);
      }
      _clipTimelineEdits[path] = next;
      _applyClipTimelineEdit(next);
      _updateSelectedTimelineClipTransform(next);
    });
    unawaited(_autosaveProject());
  }

  void _applyCurrentTransformToAllVideos() {
    if (_videos.isEmpty) return;
    unawaited(_showApplySelectedVideoSettingsDialog());
  }

  ({List<int> indexes, String? error}) _parseVideoTargetExpression(
    String expression,
  ) {
    final text = expression
        .trim()
        .toLowerCase()
        .replaceAll('\u2013', '-')
        .replaceAll('\u2014', '-');
    if (_videos.isEmpty) {
      return (indexes: const <int>[], error: 'Import videos first.');
    }
    if (text == 'all') {
      return (
        indexes: List.generate(_videos.length, (index) => index),
        error: null,
      );
    }
    if (text.isEmpty) {
      return (
        indexes: const <int>[],
        error: 'Enter video numbers, for example 1,2,4 to 7.',
      );
    }
    final selected = <int>{};
    for (final rawPart in text.split(',')) {
      final part = rawPart.trim();
      if (part.isEmpty) {
        return (indexes: const <int>[], error: 'Remove empty commas.');
      }
      final range = RegExp(r'^(\d+)\s*(?:-|to)\s*(\d+)$').firstMatch(part);
      if (range != null) {
        final start = int.parse(range.group(1)!);
        final end = int.parse(range.group(2)!);
        if (start < 1 ||
            end < 1 ||
            start > _videos.length ||
            end > _videos.length) {
          return (
            indexes: const <int>[],
            error: 'Video numbers must be between 1 and ${_videos.length}.',
          );
        }
        if (end < start) {
          return (
            indexes: const <int>[],
            error: 'A range must go from a smaller number to a larger number.',
          );
        }
        for (var number = start; number <= end; number++) {
          selected.add(number - 1);
        }
        continue;
      }
      final number = int.tryParse(part);
      if (number == null) {
        return (
          indexes: const <int>[],
          error: 'Use commas and ranges such as 1,2,4 to 7,9.',
        );
      }
      if (number < 1 || number > _videos.length) {
        return (
          indexes: const <int>[],
          error: 'Video numbers must be between 1 and ${_videos.length}.',
        );
      }
      selected.add(number - 1);
    }
    final indexes = selected.toList()..sort();
    return (indexes: indexes, error: null);
  }

  String _videoTargetSummary(List<int> indexes) {
    if (indexes.isEmpty) return 'No videos selected';
    return '${indexes.length} selected: ${indexes.map((index) => index + 1).join(', ')}';
  }

  Future<List<int>?> _showVideoTargetSelectionDialog({
    required String title,
    required String actionLabel,
    required String description,
  }) async {
    final controller = TextEditingController(
      text: _videos.length == 1 ? '1' : '1 to ${_videos.length}',
    );
    var expression = controller.text;
    final result = await showDialog<List<int>>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) {
          final parsed = _parseVideoTargetExpression(expression);
          return AlertDialog(
            icon: const Icon(Icons.playlist_add_check_circle_outlined),
            title: KText(title),
            content: SizedBox(
              width: 450,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  KText(description),
                  const SizedBox(height: 14),
                  TextField(
                    controller: controller,
                    autofocus: true,
                    decoration: InputDecoration(
                      labelText: 'Video numbers',
                      hintText: '1,2,4 to 7,9,10',
                      helperText:
                          parsed.error ?? _videoTargetSummary(parsed.indexes),
                      errorText: parsed.error,
                    ),
                    onChanged: (value) =>
                        setDialogState(() => expression = value),
                    onSubmitted: (_) {
                      if (parsed.error == null && parsed.indexes.isNotEmpty) {
                        Navigator.pop(dialogContext, parsed.indexes);
                      }
                    },
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const KText('Cancel'),
              ),
              FilledButton(
                onPressed: parsed.error == null && parsed.indexes.isNotEmpty
                    ? () => Navigator.pop(dialogContext, parsed.indexes)
                    : null,
                child: KText(actionLabel),
              ),
            ],
          );
        },
      ),
    );
    controller.dispose();
    return result;
  }

  Future<void> _showApplySelectedVideoSettingsDialog() async {
    _saveSelectedClipTimelineEdit();
    _storeActiveCompositionTimeline();
    final source = _clipTimelineEditFor(_videos[_selectedVideoIndex].path);
    final sourceCanvasMode = _canvasMode;
    final sourceCanvasColor = _colorToHex(_canvasColor);
    final sourceCanvasPattern = _canvasPattern;
    final sourceCanvasBlur = _canvasBlur;
    var copySpeed = true;
    var copyFrame = true;
    var copyAudio = true;
    var copyCanvas = true;
    final targetController = TextEditingController(
      text: _videos.length == 1 ? '1' : '1 to ${_videos.length}',
    );
    var targetExpression = targetController.text;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) {
          final targets = _parseVideoTargetExpression(targetExpression);
          return AlertDialog(
            icon: const Icon(Icons.copy_all_outlined),
            title: const KText('Apply selected video settings'),
            content: SingleChildScrollView(
              child: SizedBox(
                width: 450,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    KText(
                      'Copy the latest settings from ${_videos[_selectedVideoIndex].name}. Every target remains independently editable afterward.',
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      controller: targetController,
                      decoration: InputDecoration(
                        labelText: 'Apply to video numbers',
                        hintText: '1,2,4 to 7,9,10',
                        helperText: targets.error == null
                            ? _videoTargetSummary(targets.indexes)
                            : null,
                        errorText: targets.error,
                      ),
                      onChanged: (value) =>
                          setDialogState(() => targetExpression = value),
                    ),
                    CheckboxListTile(
                      contentPadding: EdgeInsets.zero,
                      value: copySpeed,
                      onChanged: (value) => setDialogState(
                        () => copySpeed = value ?? false,
                      ),
                      title: const KText('Speed'),
                    ),
                    CheckboxListTile(
                      contentPadding: EdgeInsets.zero,
                      value: copyFrame,
                      onChanged: (value) => setDialogState(
                        () => copyFrame = value ?? false,
                      ),
                      title:
                          const KText('Frame, flip, scale, zoom and position'),
                    ),
                    CheckboxListTile(
                      contentPadding: EdgeInsets.zero,
                      value: copyAudio,
                      onChanged: (value) => setDialogState(
                        () => copyAudio = value ?? false,
                      ),
                      title: const KText('Source audio level'),
                    ),
                    CheckboxListTile(
                      contentPadding: EdgeInsets.zero,
                      value: copyCanvas,
                      onChanged: (value) => setDialogState(
                        () => copyCanvas = value ?? false,
                      ),
                      title: const KText('Canvas background and blur'),
                    ),
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext, false),
                child: const KText('Cancel'),
              ),
              FilledButton(
                onPressed: targets.error == null &&
                        targets.indexes.isNotEmpty &&
                        (copySpeed || copyFrame || copyAudio || copyCanvas)
                    ? () => Navigator.pop(dialogContext, true)
                    : null,
                child: const KText('Apply to selected videos'),
              ),
            ],
          );
        },
      ),
    );
    final targetResult = _parseVideoTargetExpression(targetExpression);
    targetController.dispose();
    if (confirmed != true || !mounted) return;
    if (targetResult.error != null || targetResult.indexes.isEmpty) return;
    _recordEditorHistory('apply-video-settings-all');
    setState(() {
      for (final index in targetResult.indexes) {
        final video = _videos[index];
        final current = _clipTimelineEditFor(video.path);
        final applied = current.copyWith(
          speed: copySpeed ? source.speed : current.speed,
          flip: copyFrame ? source.flip : current.flip,
          scaleX: copyFrame ? source.scaleX : current.scaleX,
          scaleY: copyFrame ? source.scaleY : current.scaleY,
          zoom: copyFrame ? source.zoom : current.zoom,
          panX: copyFrame ? source.panX : current.panX,
          panY: copyFrame ? source.panY : current.panY,
          originalVolume:
              copyAudio ? source.originalVolume : current.originalVolume,
        );
        _clipTimelineEdits[video.path] = applied;
        for (final entry in _timelinesByComposition.entries.toList()) {
          _timelinesByComposition[entry.key] =
              _timelineWithAppliedVideoSettings(
            entry.value,
            video.path,
            applied,
            copyFrame: copyFrame,
            copyAudio: copyAudio,
            copyCanvas: copyCanvas,
            canvasMode: sourceCanvasMode,
            canvasColor: sourceCanvasColor,
            canvasPattern: sourceCanvasPattern,
            canvasBlur: sourceCanvasBlur,
          );
        }
      }
      _clipTransformOverrides.addAll(
        targetResult.indexes.map((index) => _videos[index].path),
      );
      final activeComposition = _selectedCompositionPath;
      if (activeComposition != null) {
        final activeTimeline = _timelinesByComposition[activeComposition];
        if (activeTimeline != null) _applyTimelineModelUpdate(activeTimeline);
      }
      _applyClipTimelineEdit(
        _clipTimelineEditFor(_videos[_selectedVideoIndex].path),
      );
      _status =
          'Latest settings applied to ${targetResult.indexes.length} video${targetResult.indexes.length == 1 ? '' : 's'}';
    });
    unawaited(_autosaveProject());
  }

  void _applyProjectColor(Object? value) {
    final data = value is Map ? value : const {};
    double number(String key, double fallback) =>
        double.tryParse('${data[key] ?? fallback}') ?? fallback;
    _brightness = number('brightness', _brightness);
    _contrast = number('contrast', _contrast);
    _saturation = number('saturation', _saturation);
    _gamma = number('gamma', _gamma);
  }

  void _applyProjectAudio(Object? value) {
    final data = value is Map ? value : const {};
    _musicPath = data['musicPath'] as String?;
    _originalVolume =
        double.tryParse('${data['originalVolume'] ?? _originalVolume}') ??
            _originalVolume;
    _musicVolume = double.tryParse('${data['musicVolume'] ?? _musicVolume}') ??
        _musicVolume;
  }

  void _applyProjectCaptions(Object? value) {
    final data = value is Map ? value : const {};
    _automaticCaptions = data['enabled'] as bool? ?? _automaticCaptions;
    _captionModel = '${data['model'] ?? _captionModel}';
    _captionLanguage = '${data['language'] ?? _captionLanguage}';
    _captionDevice = '${data['device'] ?? _captionDevice}';
    final savedCaptionStyle = '${data['style'] ?? _captionStyle}';
    _captionStyle = _captionPresets.any(
      (preset) => preset.id == savedCaptionStyle,
    )
        ? savedCaptionStyle
        : 'capcut';
    _captionFont = _safeCaptionFont('${data['font'] ?? _captionFont}');
    _captionFontSize = _captionUiFontSize(
      double.tryParse('${data['fontSize'] ?? _captionFontSize}') ??
          _captionFontSize,
    );
    _captionWordsPerLine =
        int.tryParse('${data['wordsPerLine'] ?? _captionWordsPerLine}') ??
            _captionWordsPerLine;
    _captionBold = data['bold'] as bool? ?? _captionBold;
    _captionUnderline = data['underline'] as bool? ?? _captionUnderline;
    _captionItalic = data['italic'] as bool? ?? _captionItalic;
    _captionCase = '${data['case'] ?? _captionCase}';
    _captionColor = _parseHexColor('${data['color'] ?? ''}') ?? _captionColor;
    _captionCharacterSpacing =
        double.tryParse('${data['characterSpacing'] ?? 0}') ?? 0;
    _captionWordSpacing = double.tryParse('${data['wordSpacing'] ?? 4}') ?? 4;
    _captionLineSpacing = double.tryParse('${data['lineSpacing'] ?? 0}') ?? 0;
    _captionOpacity =
        (double.tryParse('${data['opacity'] ?? 1}') ?? 1).clamp(0.0, 1.0);
    _captionStrokeEnabled =
        data['strokeEnabled'] as bool? ?? _captionStrokeEnabled;
    _captionStrokeColor =
        _parseHexColor('${data['strokeColor'] ?? ''}') ?? _captionStrokeColor;
    _captionStrokeWidth = double.tryParse('${data['strokeWidth'] ?? 6}') ?? 6;
    _captionBackgroundEnabled =
        data['backgroundEnabled'] as bool? ?? _captionBackgroundEnabled;
    _captionBackgroundColor =
        _parseHexColor('${data['backgroundColor'] ?? ''}') ??
            _captionBackgroundColor;
    _captionBackgroundOpacity =
        double.tryParse('${data['backgroundOpacity'] ?? 0.75}') ?? 0.75;
    _captionBackgroundPadding =
        double.tryParse('${data['backgroundPadding'] ?? 10}') ?? 10;
    _captionGlowEnabled = data['glowEnabled'] as bool? ?? _captionGlowEnabled;
    _captionGlowColor =
        _parseHexColor('${data['glowColor'] ?? ''}') ?? _captionGlowColor;
    _captionGlowStrength = double.tryParse('${data['glowStrength'] ?? 8}') ?? 8;
    _captionShadowEnabled =
        data['shadowEnabled'] as bool? ?? _captionShadowEnabled;
    _captionShadowColor =
        _parseHexColor('${data['shadowColor'] ?? ''}') ?? _captionShadowColor;
    _captionShadowStrength =
        double.tryParse('${data['shadowStrength'] ?? 3}') ?? 3;
    _captionCurve = double.tryParse('${data['curve'] ?? 0}') ?? 0;
  }

  List<_TextOverlayDraft> _textOverlaysFromJson(Object? value) {
    final items = value as List? ?? const [];
    return [
      for (final item in items)
        if (item is Map) _textOverlayFromJson(item),
    ];
