  Map<String, Object?> _captionCueToJson(_CaptionCue cue) => {
        'start': cue.start,
        'end': cue.end,
        'text': cue.text,
        'x': cue.x,
        'y': cue.y,
        'words': [
          for (final word in cue.words)
            {'start': word.start, 'end': word.end, 'text': word.text},
        ],
      };

  Map<String, List<_CaptionCue>> _captionCuesMapFromJson(Object? value) {
    final source = value is Map ? value : const {};
    final result = <String, List<_CaptionCue>>{};
    for (final entry in source.entries) {
      final cues = <_CaptionCue>[];
      for (final item in (entry.value as List? ?? const [])) {
        if (item is! Map) continue;
        final start = double.tryParse('${item['start'] ?? ''}');
        final end = double.tryParse('${item['end'] ?? ''}');
        final text = normalizeAssDisplayText('${item['text'] ?? ''}');
        if (start == null || end == null || end <= start || text.isEmpty) {
          continue;
        }
        cues.add(
          _CaptionCue(
            start: start,
            end: end,
            text: text,
            x: (double.tryParse('${item['x'] ?? 0.5}') ?? 0.5)
                .clamp(0.0, 1.0)
                .toDouble(),
            y: (double.tryParse('${item['y'] ?? 0.78}') ?? 0.78)
                .clamp(0.0, 1.0)
                .toDouble(),
            words: [
              for (final word in item['words'] as List? ?? const [])
                if (word is Map &&
                    double.tryParse('${word['start'] ?? ''}') != null &&
                    double.tryParse('${word['end'] ?? ''}') != null)
                  _CaptionWord(
                    start: double.parse('${word['start']}'),
                    end: double.parse('${word['end']}'),
                    text: normalizeAssDisplayText('${word['text'] ?? ''}'),
                  ),
            ],
          ),
        );
      }
      cues.sort((a, b) => a.start.compareTo(b.start));
      if (cues.isNotEmpty) result['${entry.key}'] = cues;
    }
    return result;
  }

  TimelineModel _buildLegacyMultiTrackTimeline({
    TimelineModel? previousTimeline,
    Iterable<PickedVideo>? videos,
  }) {
    final previousModel = previousTimeline ?? _multiTrackTimeline;
    final requestedVideos = videos?.toList();
    final activeMedia = _activeProjectMedia;
    final timelineVideos = requestedVideos != null && requestedVideos.isNotEmpty
        ? requestedVideos
        : activeMedia.isNotEmpty
            ? activeMedia
            : _videos;
    final previousClips = <String, ClipModel>{
      for (final track in previousModel.tracks)
        for (final clip in track.clips) clip.id: clip,
    };
    final preservedTracks = [
      for (final track in previousModel.tracks)
        if (track.type == TrackType.text || track.index > 1) track,
    ];
    final movedVideoIds = {
      for (final track in preservedTracks)
        if (track.type == TrackType.video)
          for (final clip in track.clips) clip.replacesClipId ?? clip.id,
    };
    final movedAudioIds = {
      for (final track in preservedTracks)
        if (track.type == TrackType.audio)
          for (final clip in track.clips) clip.replacesClipId ?? clip.id,
    };
    final videoClips = <ClipModel>[];
    final audioClips = <ClipModel>[];
    var timelineCursor = 0.0;
    for (final video in timelineVideos) {
      final edit = _clipTimelineEditFor(video.path);
      final parts = edit.timelineParts(video.durationSeconds);
      for (final part in parts) {
        final duration = math.max(0.001, part.end - part.start).toDouble();
        final baseId = _stableTimelineClipId(video.path, part.start, part.end);
        final previous = previousClips[baseId];
        final clipTimelineStart = previous?.transitionIn != null
            ? math
                .max(
                  0,
                  timelineCursor - previous!.transitionIn!.duration,
                )
                .toDouble()
            : previous?.hasProfessionalEdits == true
                ? previous!.timelineStart
                : timelineCursor;
        final transform = previous?.transform ??
            ClipTransform(
              scaleX: edit.scaleX * edit.zoom,
              scaleY: edit.scaleY * edit.zoom,
              positionX: (0.5 + edit.panX * 0.5).clamp(0, 1).toDouble(),
              positionY: (0.5 + edit.panY * 0.5).clamp(0, 1).toDouble(),
            );
        if (!movedVideoIds.contains(baseId)) {
          videoClips.add(
            ClipModel(
              id: baseId,
              mediaPath: video.path,
              timelineStart: clipTimelineStart,
              duration: duration,
              sourceStart: part.start,
              zIndex: 0,
              transform: transform,
              effects: previous?.effects ?? const [],
              transitionIn: previous?.transitionIn,
              keyframes: previous?.keyframes ?? const [],
            ),
          );
        }
        final audioId = 'audio-$baseId';
        final previousAudio = previousClips[audioId];
        if (video.hasAudio && !movedAudioIds.contains(audioId)) {
          audioClips.add(
            ClipModel(
              id: audioId,
              mediaPath: video.path,
              timelineStart: previousAudio?.transitionIn != null
                  ? clipTimelineStart
                  : previousAudio?.hasProfessionalEdits == true
                      ? previousAudio!.timelineStart
                      : clipTimelineStart,
              duration: duration,
              sourceStart: part.start,
              zIndex: 0,
              volume: edit.originalVolume,
              isLinkedAudio: previousAudio?.isLinkedAudio ?? true,
              linkedClipId: previousAudio?.linkedClipId ?? baseId,
              transitionIn: previousAudio?.transitionIn,
            ),
          );
        }
        timelineCursor = clipTimelineStart + duration;
      }
    }
    final tracks = <TrackModel>[
      TrackModel(
        id: 'video-1',
        type: TrackType.video,
        index: 1,
        isMuted: _videoTrackHidden,
        clips: videoClips,
      ),
      ...preservedTracks.where((track) => track.type == TrackType.video),
      TrackModel(
        id: 'audio-1',
        type: TrackType.audio,
        index: 1,
        isMuted: _originalAudioMuted,
        clips: audioClips,
      ),
      ...preservedTracks.where((track) => track.type == TrackType.audio),
      ...preservedTracks.where((track) => track.type == TrackType.text),
    ];
    return TimelineModel(
      tracks: tracks,
      duration: TimelineModel.calculateDuration(tracks),
    ).normalized();
  }

  double _videoTimelineEnd([TimelineModel? model]) {
    final timeline = model ?? _multiTrackTimeline;
    var end = 0.0;
    for (final track in timeline.videoTracks) {
      for (final clip in track.clips) {
        end = math.max(end, clip.timelineEnd);
      }
    }
    return end;
  }

  TimelineModel _timelineWithFirstVideo(PickedVideo video) {
    final duration = math.max(0.001, video.durationSeconds ?? 0.001).toDouble();
    final edit = _clipTimelineEditFor(video.path);
    final clipId =
        'clip-${DateTime.now().microsecondsSinceEpoch}-${video.path.hashCode.abs()}';
    final videoClip = ClipModel(
      id: clipId,
      mediaPath: video.path,
      timelineStart: 0,
      duration: duration,
      sourceStart: 0,
      zIndex: 0,
    );
    final tracks = <TrackModel>[
      TrackModel(
        id: 'video-1',
        type: TrackType.video,
        index: 1,
        clips: [videoClip],
      ),
      TrackModel(
        id: 'audio-1',
        type: TrackType.audio,
        index: 1,
        clips: [
          if (video.hasAudio)
            videoClip.copyWith(
              id: 'audio-$clipId',
              volume: edit.originalVolume,
              isLinkedAudio: true,
              linkedClipId: clipId,
            ),
        ],
      ),
    ];
    return TimelineModel(
      tracks: tracks,
      duration: TimelineModel.calculateDuration(tracks),
    ).normalized();
  }

  List<PickedVideo> get _compositionVideos => [
        for (final path in _compositionPaths)
          for (final video in _videos)
            if (video.path == path) video,
      ];

  List<PickedVideo> get _activeProjectMedia {
    final composition = _selectedCompositionPath;
    if (composition == null) return const [];
    final paths = _projectMediaPathsByComposition[composition] ?? [composition];
    return [
      for (final path in paths)
        for (final video in _videos)
          if (video.path == path) video,
    ];
  }

  void _storeActiveCompositionTimeline() {
    final composition = _selectedCompositionPath;
    if (composition == null) return;
    _timelinesByComposition[composition] = _multiTrackTimeline;
  }

  void _ensureComposition(PickedVideo video) {
    if (!_compositionPaths.contains(video.path)) {
      _compositionPaths.add(video.path);
    }
    _projectMediaPathsByComposition.putIfAbsent(
      video.path,
      () => [video.path],
    );
    _timelinesByComposition.putIfAbsent(
      video.path,
      () => _timelineWithFirstVideo(video),
    );
  }

  Future<void> _selectComposition(String path) async {
    final index = _videos.indexWhere((video) => video.path == path);
    if (index < 0) return;
    _storeActiveCompositionTimeline();
    final timeline = _timelinesByComposition[path] ??
        _timelineWithFirstVideo(_videos[index]);
    final clips = timeline.videoTracks.expand((track) => track.clips).toList();
    final firstClip = clips.isEmpty ? null : clips.first;
    setState(() {
      _selectedCompositionPath = path;
      _multiTrackTimeline = timeline;
      _selectedTimelineClipId = firstClip?.id;
      _programTimelineClipId = firstClip?.id;
      _timelineMarkers.clear();
      _status = 'Opened ${_videos[index].name} timeline';
    });
    await _selectVideo(index, saveCurrentEdit: false);
    if (firstClip != null) {
      await _seekProgramPreview(firstClip.timelineStart);
    }
  }

  Future<void> _addImportedVideoToTimeline(int index) async {
    await _insertProjectMediaOnTimeline(index);
  }

  Future<void> _insertProjectMediaOnTimeline(
    int index, {
    String? trackId,
    double? timelineStart,
  }) async {
    if (index < 0 || index >= _videos.length) return;
    _recordEditorHistory('timeline-media-add');
    final video = _videos[index];
    final duration = math.max(0.001, video.durationSeconds ?? 0.001).toDouble();
    var timeline = _multiTrackTimeline;
    if (timeline.videoTracks.isEmpty) {
      timeline = _timelineWithFirstVideo(video);
    } else {
      final clipId =
          'clip-${DateTime.now().microsecondsSinceEpoch}-${video.path.hashCode.abs()}';
      final start = timelineStart ?? _videoTimelineEnd(timeline);
      final videoClip = ClipModel(
        id: clipId,
        mediaPath: video.path,
        timelineStart: start,
        duration: duration,
        sourceStart: 0,
        zIndex: 0,
      );
      final videoTrack = trackId == null
          ? timeline.videoTracks.first
          : (timeline.trackById(trackId) ?? timeline.videoTracks.first);
      timeline = _timelineEditor.insertClip(
        timeline,
        trackId: videoTrack.id,
        clip: videoClip,
      );
      if (video.hasAudio) {
        var audioTrack =
            timeline.audioTracks.isEmpty ? null : timeline.audioTracks.first;
        if (audioTrack == null) {
          timeline = _timelineEditor.addTrack(timeline, TrackType.audio);
          audioTrack = timeline.audioTracks.first;
        }
        timeline = _timelineEditor.insertClip(
          timeline,
          trackId: audioTrack.id,
          clip: videoClip.copyWith(
            id: 'audio-$clipId',
            volume: _originalVolume,
            isLinkedAudio: true,
            linkedClipId: clipId,
          ),
        );
      }
    }
    final added = timeline.videoTracks
        .expand((track) => track.clips)
        .where((clip) => clip.mediaPath == video.path)
        .reduce((a, b) => a.timelineStart >= b.timelineStart ? a : b);
    setState(() {
      _multiTrackTimeline = timeline;
      final composition = _selectedCompositionPath;
      if (composition != null) {
        _timelinesByComposition[composition] = timeline;
      }
      _selectedTimelineClipId = added.id;
      _programTimelineClipId = added.id;
      _status = '${video.name} added as a separate timeline clip';
    });
    if (index != _selectedVideoIndex) {
      await _selectVideo(index, saveCurrentEdit: false);
    }
    await _seekProgramPreview(added.timelineStart);
    unawaited(_autosaveProject());
  }

  void _dropProjectMediaOnTimeline(
    TimelineMediaDragData media,
    String trackId,
    double timelineStart,
  ) {
    final index = _videos.indexWhere((video) => video.path == media.mediaPath);
    if (index < 0) return;
    unawaited(
      _insertProjectMediaOnTimeline(
        index,
        trackId: trackId,
        timelineStart: timelineStart,
      ),
    );
  }

  void _syncMultiTrackFromLegacy({
    String? preferredMediaPath,
    bool allCompositions = false,
  }) {
    if (_videos.isEmpty) {
      _multiTrackTimeline = TimelineModel.empty();
      _selectedTimelineClipId = null;
      _programTimelineClipId = null;
      _selectedTimelineClipIds.clear();
      return;
    }

    if (allCompositions) {
      for (final composition in _compositionPaths) {
        final mediaPaths = _projectMediaPathsByComposition[composition] ??
            <String>[composition];
        final compositionVideos = [
          for (final path in mediaPaths)
            for (final video in _videos)
              if (video.path == path) video,
        ];
        if (compositionVideos.isEmpty) continue;
        final previous = composition == _selectedCompositionPath
            ? _multiTrackTimeline
            : _timelinesByComposition[composition];
        _timelinesByComposition[composition] = _buildLegacyMultiTrackTimeline(
          previousTimeline: previous,
          videos: compositionVideos,
        );
      }
      final active = _selectedCompositionPath;
      if (active != null && _timelinesByComposition[active] != null) {
        _multiTrackTimeline = _timelinesByComposition[active]!;
      } else {
        _multiTrackTimeline = _buildLegacyMultiTrackTimeline();
      }
    } else {
      _multiTrackTimeline = _buildLegacyMultiTrackTimeline();
    }
    _ensureTextTimelineTracks();

    ClipModel? preferredClip;
    if (preferredMediaPath != null) {
      for (final track in _multiTrackTimeline.videoTracks) {
        for (final clip in track.clips) {
          if (clip.mediaPath == preferredMediaPath) {
            preferredClip = clip;
            break;
          }
        }
        if (preferredClip != null) break;
      }
    }
    preferredClip ??= _multiTrackTimeline.videoTracks
        .expand((track) => track.clips)
        .cast<ClipModel?>()
        .firstWhere((clip) => clip != null, orElse: () => null);

    final selectedIsValid = _selectedTimelineClipId != null &&
        _multiTrackTimeline.clipById(_selectedTimelineClipId!) != null;
    if (!selectedIsValid) {
      _selectedTimelineClipId = preferredClip?.id;
    }
    final programIsValid = _programTimelineClipId != null &&
        _multiTrackTimeline.clipById(_programTimelineClipId!) != null;
    if (!programIsValid) {
      _programTimelineClipId = preferredClip?.id;
    }
    _selectedTimelineClipIds.removeWhere(
      (id) => _multiTrackTimeline.clipById(id) == null,
    );
    _storeActiveCompositionTimeline();
  }

  String _stableTimelineClipId(String path, double start, double end) {
    var hash = 2166136261;
    for (final unit in path.toLowerCase().codeUnits) {
      hash = ((hash ^ unit) * 16777619) & 0x7fffffff;
    }
    return 'clip-$hash-${(start * 1000).round()}-${(end * 1000).round()}';
  }

  Map<String, Object?> _clipEditToJson(_ClipTimelineEdit edit) => {
        'trimStartSeconds': edit.trimStartSeconds,
        'trimEndSeconds': edit.trimEndSeconds,
        'splitEverySeconds': edit.splitEverySeconds,
        'speed': edit.speed,
        'flip': edit.flip,
        'scaleX': edit.scaleX,
        'scaleY': edit.scaleY,
        'zoom': edit.zoom,
        'panX': edit.panX,
        'panY': edit.panY,
        'originalVolume': edit.originalVolume,
        'splitPoints': edit.splitPoints,
        'deletedRanges': [
          for (final range in edit.deletedRanges)
            {'start': range.start, 'end': range.end},
        ],
        'partOrder': edit.partOrder,
      };

  Map<String, _ClipTimelineEdit> _clipEditsFromJson(Object? value) {
    final source = value is Map ? value : const {};
    return {
      for (final entry in source.entries)
        '${entry.key}': _clipEditFromJson(entry.value),
    };
  }

  Set<String> _clipTransformOverridesFromJson(
    Object? value,
    Map<String, _ClipTimelineEdit> edits,
  ) {
    if (value is List) {
      final masterPath = _videos.isEmpty ? null : _videos.first.path;
      return {
        for (final item in value)
          if ('$item'.isNotEmpty && '$item' != masterPath) '$item',
      };
    }
    if (_videos.isEmpty) return {};
    final masterPath = _videos.first.path;
    final master = edits[masterPath] ?? const _ClipTimelineEdit();
    return {
      for (final entry in edits.entries)
        if (entry.key != masterPath && !_sameTransform(entry.value, master))
          entry.key,
    };
  }

  _ClipTimelineEdit _clipEditFromJson(Object? value) {
    final data = value is Map ? value : const {};
    double number(String key) =>
        double.tryParse('${data[key] ?? 0}')?.toDouble() ?? 0;
    return _ClipTimelineEdit(
      trimStartSeconds: number('trimStartSeconds'),
      trimEndSeconds: number('trimEndSeconds'),
      splitEverySeconds: number('splitEverySeconds'),
      speed: double.tryParse('${data['speed'] ?? _speed}') ?? _speed,
      flip: '${data['flip'] ?? _flip}',
      scaleX: double.tryParse('${data['scaleX'] ?? _scaleX}') ?? _scaleX,
      scaleY: double.tryParse('${data['scaleY'] ?? _scaleY}') ?? _scaleY,
      zoom: double.tryParse('${data['zoom'] ?? _zoom}') ?? _zoom,
      panX: double.tryParse('${data['panX'] ?? _panX}') ?? _panX,
      panY: double.tryParse('${data['panY'] ?? _panY}') ?? _panY,
      originalVolume:
          double.tryParse('${data['originalVolume'] ?? _originalVolume}') ??
              _originalVolume,
      splitPoints: [
        for (final item in data['splitPoints'] as List? ?? const [])
          if (double.tryParse('$item') != null) double.parse('$item'),
      ],
      deletedRanges: [
        for (final item in data['deletedRanges'] as List? ?? const [])
          if (item is Map)
            (
              start: double.tryParse('${item['start'] ?? 0}') ?? 0,
              end: double.tryParse('${item['end'] ?? 0}') ?? 0,
            ),
      ],
      partOrder: [
        for (final item in data['partOrder'] as List? ?? const [])
          if (double.tryParse('$item') != null) double.parse('$item'),
      ],
    );
  }

  void _handleTimelineScroll() {
    if (!_timelineScrollController.hasClients) return;
    final nextOffset = _timelineScrollController.offset;
    if ((nextOffset - _timelineScrollOffset).abs() < 24) return;
    _timelineScrollOffset = nextOffset;
    _timelineScrollOffsetListenable.value = nextOffset;
    _timelineMediaLoadDebounce?.cancel();
    _timelineMediaLoadDebounce = Timer(
      const Duration(milliseconds: 180),
      () => unawaited(_loadVisibleTimelineMedia()),
    );
  }

  Future<void> _pickVideos() async {
    final result = await FilePicker.platform.pickFiles(
      allowMultiple: true,
      type: FileType.video,
    );
    if (result == null) return;

    final picked = result.files
        .where((file) => file.path != null)
        .map((file) => PickedVideo(name: file.name, path: file.path!))
        .toList();
    if (picked.isEmpty) return;

    final existingPaths =
        _videos.map((video) => video.path.toLowerCase()).toSet();
    final newVideos = picked
        .where((video) => !existingPaths.contains(video.path.toLowerCase()))
        .toList();
    if (newVideos.isEmpty) {
      _showMessage('Those video files are already in the project.');
      return;
    }

    await _setPickedVideos(
      [..._videos, ...newVideos],
      resetEdits: false,
      selectedIndex: _videos.length,
      compositionPathsToAdd: [for (final video in newVideos) video.path],
    );
  }

  Future<void> _pickProjectVideos() async {
    if (_selectedCompositionPath == null) {
      _showMessage('Select a video project in Import first.');
      return;
    }
    final result = await FilePicker.platform.pickFiles(
      allowMultiple: true,
      type: FileType.video,
    );
    if (result == null) return;
    await _addProjectMedia([
      for (final file in result.files)
        if (file.path != null) PickedVideo(name: file.name, path: file.path!),
    ]);
  }

  Future<void> _pickProjectVideoFolder() async {
    if (_selectedCompositionPath == null) {
      _showMessage('Select a video project in Import first.');
      return;
    }
    final folder = await FilePicker.platform.getDirectoryPath();
    if (folder == null) return;
    final paths = await platform.videoFilesInFolder(folder);
    if (paths.isEmpty) {
      _showMessage('No video files found in this folder.');
      return;
    }
    _rememberFolder(folder);
    await _addProjectMedia([
      for (final path in paths)
        PickedVideo(name: platform.basename(path), path: path),
    ]);
  }

  Future<PickedVideo> _enrichVideoMetadata(PickedVideo video) async {
    final info = await platform.probeMedia(video.path);
    final savedProxy = video.proxyPath;
    return video.copyWith(
      durationSeconds: info.durationSeconds ?? video.durationSeconds,
      hasAudio: info.hasAudio,
      width: info.width,
      height: info.height,
      frameRate: info.frameRate,
      videoCodec: info.videoCodec,
      bitrate: info.bitrate,
      proxyPath: savedProxy != null && File(savedProxy).existsSync()
          ? savedProxy
          : null,
    );
  }

  platform.MediaProbeInfo _probeInfoForVideo(PickedVideo video) => (
        durationSeconds: video.durationSeconds,
        width: video.width,
        height: video.height,
        frameRate: video.frameRate,
        videoCodec: video.videoCodec,
        bitrate: video.bitrate,
        hasAudio: video.hasAudio,
      );

  bool _shouldUseProxy(PickedVideo video) {
    final explicitlyEnabled =
        _projectProxyEnabled || widget.settings.proxyEnabled;
    final smartEnabled = widget.settings.autoOptimization == 'smart';
    return explicitlyEnabled ||
        (smartEnabled && platform.mediaNeedsProxy(_probeInfoForVideo(video)));
  }

  String? _availablePreviewPath(PickedVideo video) {
    final proxy = video.proxyPath;
    if (proxy != null && File(proxy).existsSync()) return proxy;
    if (_proxyUnavailableSources.contains(video.path)) return video.path;
    return _shouldUseProxy(video) ? null : video.path;
  }

  Future<String> _proxyCacheFolder() async {
    final configured = widget.settings.proxyFolder.trim();
    if (configured.isNotEmpty) return configured;
    final cacheConfigured = widget.settings.cacheFolder.trim();
    final root = cacheConfigured.isNotEmpty
        ? Directory(cacheConfigured)
        : Directory(
            '${(await getTemporaryDirectory()).path}${Platform.pathSeparator}KlipioCache',
          );
    return '${root.path}${Platform.pathSeparator}proxies';
  }

  Future<String?> _ensureProxyForVideo(PickedVideo video) {
    final existing = video.proxyPath;
    if (existing != null && File(existing).existsSync()) {
      return Future<String?>.value(existing);
    }
    if (!_shouldUseProxy(video)) return Future<String?>.value(null);
    final active = _proxyJobsBySource[video.path];
    if (active != null) return active;
    late final Future<String?> job;
    job = () async {
      final cacheFolder = await _proxyCacheFolder();
      final proxy = await platform.generateProxyMedia(
        video.path,
        cacheFolder,
        resolution: _projectProxyResolution,
      );
      if (proxy == null || !File(proxy).existsSync()) {
        _proxyUnavailableSources.add(video.path);
        if (mounted) {
          final index = _videos.indexWhere((item) => item.path == video.path);
          final shouldReload = index == _selectedVideoIndex;
          setState(() {
            _status =
                'Proxy unavailable for ${video.name}; using source preview';
          });
          if (shouldReload) {
            await _selectVideo(index, saveCurrentEdit: false);
          }
        }
        return null;
      }
      _proxyUnavailableSources.remove(video.path);
      if (!mounted) return proxy;
      final index = _videos.indexWhere((item) => item.path == video.path);
      if (index < 0) return proxy;
      final shouldReload = index == _selectedVideoIndex;
      setState(() {
        _videos[index] = _videos[index].copyWith(proxyPath: proxy);
        _status = 'Lightweight preview ready for ${video.name}';
      });
      unawaited(_autosaveProject());
      if (shouldReload && mounted) {
        await _selectVideo(index, saveCurrentEdit: false);
      }
      return proxy;
    }();
    _proxyJobsBySource[video.path] = job;
    unawaited(job.whenComplete(() {
      if (identical(_proxyJobsBySource[video.path], job)) {
        _proxyJobsBySource.remove(video.path);
      }
    }));
    return job;
  }

  void _scheduleNeededProxies(Iterable<PickedVideo> videos) {
    for (final video in videos) {
      if (_shouldUseProxy(video)) unawaited(_ensureProxyForVideo(video));
    }
  }

  Future<void> _addProjectMedia(List<PickedVideo> picked) async {
    final composition = _selectedCompositionPath;
    if (composition == null || picked.isEmpty) return;
    final paths = _projectMediaPathsByComposition.putIfAbsent(
      composition,
      () => [composition],
    );
    final knownByPath = {
      for (final video in _videos) video.path.toLowerCase(): video,
    };
    final cacheDirectory = await getTemporaryDirectory();
    final thumbnailCache =
        '${cacheDirectory.path}${platform.pathSeparator}klipio_thumbnails';
    final added = <PickedVideo>[];
    for (final item in picked) {
      final key = item.path.toLowerCase();
      var video = knownByPath[key];
      if (video == null) {
        video = await _enrichVideoMetadata(item);
        knownByPath[key] = video;
        added.add(video);
      }
      if (!paths.any((path) => path.toLowerCase() == key)) {
        paths.add(video.path);
      }
    }
    if (!mounted) return;
    setState(() {
      _videos.addAll(added);
      for (final video in added) {
        _clipTimelineEdits.putIfAbsent(
          video.path,
          () => const _ClipTimelineEdit(),
        );
      }
      _status =
          '${picked.length} media file${picked.length == 1 ? '' : 's'} added inside ${platform.basename(composition)}';
    });
    final generation = ++_filmstripLoadGeneration;
    unawaited(_loadTimelineFilmstrips(generation, thumbnailCache));
    _scheduleNeededProxies(added);
    unawaited(_autosaveProject());
  }

  bool _isSupportedVideoPath(String path) {
    const extensions = {
      '.mp4',
      '.mov',
      '.mkv',
      '.avi',
      '.webm',
      '.m4v',
      '.wmv',
      '.flv',
      '.mpeg',
      '.mpg',
      '.mts',
      '.m2ts',
      '.3gp',
    };
    final lower = path.toLowerCase();
    return extensions.any(lower.endsWith);
  }

  Future<void> _importDroppedMedia(List<DropItem> items) async {
    if (items.isEmpty || _importingDroppedMedia) return;
    setState(() {
      _draggingMediaFiles = false;
      _importingDroppedMedia = true;
      _status = 'Scanning dropped files and folders...';
    });
    try {
      final paths = <String>[];
      for (final item in items) {
        final path = item.path;
        if (path.trim().isEmpty) continue;
        if (await Directory(path).exists()) {
          paths.addAll(await platform.videoFilesInFolder(path));
          _rememberFolder(path);
        } else if (await File(path).exists() && _isSupportedVideoPath(path)) {
          paths.add(path);
        }
      }

      final existing = _videos.map((v) => v.path.toLowerCase()).toSet();
      final uniquePaths = <String>[];
      final seen = <String>{...existing};
      for (final path in paths) {
        if (seen.add(path.toLowerCase())) uniquePaths.add(path);
      }
      if (uniquePaths.isEmpty) {
        if (mounted) {
          setState(() => _status = paths.isEmpty
              ? 'No supported video files found in the drop.'
              : 'All dropped videos are already imported.');
        }
        return;
      }
      final startIndex = _videos.length;
      await _setPickedVideos(
        [
          ..._videos,
          for (final path in uniquePaths)
            PickedVideo(name: platform.basename(path), path: path),
        ],
        resetEdits: false,
        selectedIndex: startIndex,
        compositionPathsToAdd: uniquePaths,
      );
      if (mounted) {
        setState(() => _status =
            'Imported ${uniquePaths.length} video${uniquePaths.length == 1 ? '' : 's'} into Media. Double-click one to add it to the timeline.');
      }
    } catch (error) {
      if (mounted) setState(() => _status = 'Drop import failed: $error');
    } finally {
      if (mounted) setState(() => _importingDroppedMedia = false);
    }
  }

  Widget _mediaFileDropTarget({required Widget child}) {
    return DropTarget(
      onDragEntered: (_) => setState(() => _draggingMediaFiles = true),
      onDragExited: (_) => setState(() => _draggingMediaFiles = false),
      onDragDone: (details) => unawaited(_importDroppedMedia(details.files)),
      child: Stack(
        fit: StackFit.expand,
        children: [
          child,
          if (_draggingMediaFiles)
            IgnorePointer(
              child: Container(
                margin: const EdgeInsets.all(5),
                decoration: BoxDecoration(
                  color: const Color(0xdd111827),
                  borderRadius: BorderRadius.circular(9),
                  border: Border.all(color: const Color(0xff22d3ee), width: 2),
                ),
                child: const Center(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(Icons.file_download_outlined,
                          color: Color(0xff22d3ee), size: 42),
                      SizedBox(height: 10),
                      KText('Drop video files or folders',
                          style: TextStyle(
                              color: Colors.white,
                              fontSize: 16,
                              fontWeight: FontWeight.w900)),
                      SizedBox(height: 4),
                      KText(
                        'All supported videos will be added',
                        style: TextStyle(color: Color(0xffcbd5e1)),
                      ),
                    ],
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }

  Future<void> _pickVideoFolder() async {
    final folder = await FilePicker.platform.getDirectoryPath();
    if (folder == null) return;

    final paths = await platform.videoFilesInFolder(folder);
    if (!mounted) return;

    if (paths.isEmpty) {
      _showMessage('No video files found in this folder.');
      return;
    }

    final picked = paths
        .map((path) => PickedVideo(name: platform.basename(path), path: path))
        .toList();
    _rememberFolder(folder);
    await _setPickedVideos(picked);
  }

  Future<void> _openAutosaveProject() async {
    final projects = await _discoverKlipioProjectPaths();
    if (projects.isEmpty) {
      _showMessage('No autosave project found yet.');
      return;
    }
    await _loadProject(projects.first);
  }

  Future<void> _openVideoFolderPath(String folder) async {
    if (!Directory(folder).existsSync()) {
      _showMessage('Folder no longer exists: $folder');
      return;
    }
    final paths = await platform.videoFilesInFolder(folder);
    if (paths.isEmpty) {
      _showMessage('No video files found in this folder.');
      return;
    }
    _rememberFolder(folder);
    await _setPickedVideos(
      paths
          .map((path) => PickedVideo(name: platform.basename(path), path: path))
          .toList(),
    );
  }

  Future<void> _setPickedVideos(
    List<PickedVideo> picked, {
    bool resetEdits = true,
    int selectedIndex = 0,
    List<String>? compositionPathsToAdd,
  }) async {
    await platform.cancelBackgroundMediaTasks();
    _storeActiveCompositionTimeline();
    final loadGeneration = ++_controllerLoadGeneration;
    final filmstripGeneration = ++_filmstripLoadGeneration;
    setState(() => _status = 'Reading media metadata...');
    final cacheDirectory = await getTemporaryDirectory();
    final thumbnailCache =
        '${cacheDirectory.path}${platform.pathSeparator}klipio_thumbnails';
    final enriched = await Future.wait<PickedVideo>([
      for (final video in picked) _enrichVideoMetadata(video),
    ]);

    await _stopMusicPreview();
    final oldSourceController = _sourceController;
    final oldPreviewController = _previewController;
    oldSourceController?.removeListener(_handleSourceTick);
    oldPreviewController?.removeListener(_handlePreviewTick);
    if (mounted) {
      setState(() {
        _sourceController = null;
        _previewController = null;
        _sourceError = null;
        _previewError = null;
      });
    }
    await oldSourceController?.dispose();
    await oldPreviewController?.dispose();
    VideoPlayerController? sourceController;
    VideoPlayerController? controller;
    String? sourceError;
    String? previewError;
    final initialPreviewPath = _availablePreviewPath(enriched.first);
    if (initialPreviewPath == null) {
      sourceError = 'Preparing lightweight preview...';
      previewError = 'Preparing lightweight preview...';
    } else {
      try {
        sourceController = await createPreviewController(initialPreviewPath);
        await sourceController.setVolume(_previewAudioVolume(_sourceVolume));
      } catch (error) {
        sourceController = null;
        sourceError = 'Cannot play source: $error';
      }
      try {
        controller = await createPreviewController(initialPreviewPath);
      } catch (error) {
        controller = null;
        previewError = 'Cannot play preview: $error';
      }
    }

    if (!mounted || loadGeneration != _controllerLoadGeneration) {
      await sourceController?.dispose();
      await controller?.dispose();
      return;
    }
    _applyClipTimelineEdit(const _ClipTimelineEdit());
    setState(() {
      final hadCompositions = _compositionPaths.isNotEmpty;
      _videos
        ..clear()
        ..addAll(enriched);
      if (resetEdits) {
        _compositionPaths.clear();
        _projectMediaPathsByComposition.clear();
        _timelinesByComposition.clear();
        _selectedCompositionPath = null;
      }
      final rootsToAdd = compositionPathsToAdd ??
          ((resetEdits || !hadCompositions)
              ? enriched.map((video) => video.path).toList()
              : const <String>[]);
      for (final path in rootsToAdd) {
        final videoIndex = enriched.indexWhere((video) => video.path == path);
        if (videoIndex >= 0) _ensureComposition(enriched[videoIndex]);
      }
      _numberStartController.text = '1';
      _numberEndController.text = '${enriched.length}';
      if (resetEdits) {
        _clipTimelineEdits
          ..clear()
          ..addEntries(
            enriched.map(
              (video) => MapEntry(video.path, const _ClipTimelineEdit()),
            ),
          );
      } else {
        for (final video in enriched) {
          _clipTimelineEdits.putIfAbsent(
            video.path,
            () => const _ClipTimelineEdit(),
          );
        }
      }
      _clipTimelineUndoStacks.clear();
      _clipTimelineRedoStacks.clear();
      _editorUndoHistory.clear();
      _editorRedoHistory.clear();
      _clipTransformOverrides.removeWhere(
        (path) => !enriched.any((video) => video.path == path),
      );
      _captionCuesByVideo.removeWhere(
        (path, _) => !enriched.any((video) => video.path == path),
      );
      _audioWaveformPeaks.removeWhere(
        (path, _) => !enriched.any((video) => video.path == path),
      );
      if (resetEdits) {
        _clipTransformOverrides.clear();
      }
      _selectedVideoIndex = selectedIndex.clamp(0, enriched.length - 1);
      _sourceController = sourceController;
      _previewController = controller;
      _sourceError = sourceError;
      _previewError = previewError;
      final selectedPath = enriched[_selectedVideoIndex].path;
      if (_compositionPaths.contains(selectedPath)) {
        _selectedCompositionPath = selectedPath;
      } else if (_selectedCompositionPath == null ||
          !_compositionPaths.contains(_selectedCompositionPath)) {
        _selectedCompositionPath =
            _compositionPaths.isEmpty ? selectedPath : _compositionPaths.first;
      }
      _multiTrackTimeline =
          _timelinesByComposition[_selectedCompositionPath!] ??
              _timelineWithFirstVideo(enriched[_selectedVideoIndex]);
      _timelinesByComposition[_selectedCompositionPath!] = _multiTrackTimeline;
      final clips = _multiTrackTimeline.videoTracks
          .expand((track) => track.clips)
          .toList();
      final firstClip = clips.isEmpty ? null : clips.first;
      _selectedTimelineClipId = firstClip?.id;
      _programTimelineClipId = firstClip?.id;
      _status = controller == null
          ? '${enriched.length} selected. Preview is unavailable on this platform.'
          : '${_compositionPaths.length} separate video project${_compositionPaths.length == 1 ? '' : 's'} ready';
    });
    _attachSourceListener(sourceController);
    _attachPreviewListener(controller);
    if (_selectedVideoIndex != 0) {
      await _selectVideo(_selectedVideoIndex, saveCurrentEdit: false);
    } else {
      _scheduleLoadedMonitorFramePrime(sourceController, controller);
    }
    unawaited(
      _loadTimelineFilmstrips(
        filmstripGeneration,
        thumbnailCache,
      ),
    );
    _scheduleNeededProxies(enriched);
  }

  Future<void> _loadTimelineFilmstrips(
    int generation,
    String thumbnailCache,
  ) async {
    final cacheDirectory = await getTemporaryDirectory();
    final waveformCache =
        '${cacheDirectory.path}${platform.pathSeparator}klipio_waveforms';
    final activePaths = <String>{
      if (_videos.isNotEmpty)
        _videos[_selectedVideoIndex.clamp(0, _videos.length - 1)].path,
      for (final track in _multiTrackTimeline.tracks)
        for (final clip in track.clips) clip.mediaPath,
    };
    final pendingPaths = [
      for (final video in _videos)
        if (activePaths.contains(video.path) &&
            (video.thumbnailPath == null ||
                video.timelineThumbnailPaths.isEmpty ||
                (video.hasAudio &&
                    !_audioWaveformPeaks.containsKey(video.path))))
          video.path,
    ];
    for (var itemIndex = 0; itemIndex < pendingPaths.length; itemIndex++) {
      if (!mounted || generation != _filmstripLoadGeneration) return;
      final path = pendingPaths[itemIndex];
      final currentIndex = _videos.indexWhere((video) => video.path == path);
      if (currentIndex < 0) continue;
      final video = _videos[currentIndex];
      final mediaVisuals = await Future.wait<Object?>([
        if (video.thumbnailPath == null)
          platform.thumbnailForVideo(video.path, thumbnailCache)
        else
          Future.value(video.thumbnailPath),
        if (video.timelineThumbnailPaths.isEmpty)
          platform.timelineThumbnailsForVideo(
            video.path,
            thumbnailCache,
            video.durationSeconds,
          )
        else
          Future.value(video.timelineThumbnailPaths),
        if (video.hasAudio)
          platform.audioWaveformLod(
            video.path,
            waveformCache,
            durationSeconds: video.durationSeconds,
          )
        else
          Future.value(
            const (peaks: <double>[], peaksPerSecond: 20.0),
          ),
      ]);
      final cover = mediaVisuals[0] as String?;
      final frames = mediaVisuals[1] as List<String>;
      final waveform = mediaVisuals[2] as platform.AudioWaveformLod;
      if (!mounted || generation != _filmstripLoadGeneration) return;
      final nextIndex = _videos.indexWhere((item) => item.path == path);
      if (nextIndex < 0) continue;
      setState(() {
        _videos[nextIndex] = _videos[nextIndex].copyWith(
          thumbnailPath: cover,
          timelineThumbnailPaths: frames,
        );
        if (waveform.peaks.isNotEmpty) {
          _cacheWaveform(path, waveform);
        }
        _status = frames.isEmpty
            ? 'Loading audio waveform for ${video.name}'
            : 'Loading timeline media ${itemIndex + 1} of ${pendingPaths.length}';
      });
    }
    if (mounted && generation == _filmstripLoadGeneration) {
      setState(() => _status = 'Timeline thumbnails and waveforms ready');
      unawaited(_loadVisibleTimelineMedia());
    }
  }

  void _cacheWaveform(String path, platform.AudioWaveformLod waveform) {
    _audioWaveformPeaks.remove(path);
    _audioWaveformPeakRates.remove(path);
    _audioWaveformPeaks[path] = waveform.peaks;
    _audioWaveformPeakRates[path] = waveform.peaksPerSecond;
    while (_audioWaveformPeaks.length > 8) {
      final oldest = _audioWaveformPeaks.keys.first;
      _audioWaveformPeaks.remove(oldest);
      _audioWaveformPeakRates.remove(oldest);
    }
  }

  Future<void> _loadVisibleTimelineMedia() async {
    if (!mounted || _videos.isEmpty || _multiTrackTimeline.tracks.isEmpty) {
      return;
    }
    if (_timelineMediaLoadRunning) {
      _timelineMediaLoadAgain = true;
      return;
    }
    _timelineMediaLoadRunning = true;
    final generation = _filmstripLoadGeneration;
    try {
      final pixelsPerSecond = _timelinePixelsPerSecond();
      final labelWidth =
          MediaQuery.sizeOf(context).shortestSide <= 600 ? 124.0 : 132.0;
      final visibleStart = math.max(
        0.0,
        (_timelineScrollOffset - labelWidth) / pixelsPerSecond,
      );
      final visibleEnd = visibleStart +
          math.max(1.0, _timelineViewportWidth) / pixelsPerSecond;
      final sourceWindows = <String, ({double start, double end})>{};
      for (final track in _multiTrackTimeline.tracks) {
        if (track.type != TrackType.video || track.isMuted) continue;
        for (final clip in track.clips) {
          final start = math.max(visibleStart, clip.timelineStart);
          final end = math.min(visibleEnd, clip.timelineEnd);
          if (end <= start) continue;
          final sourceStart = clip.sourceStart + start - clip.timelineStart;
          final sourceEnd = clip.sourceStart + end - clip.timelineStart;
          final previous = sourceWindows[clip.mediaPath];
          sourceWindows[clip.mediaPath] = (
            start: previous == null
                ? sourceStart
                : math.min(previous.start, sourceStart),
            end: previous == null
                ? sourceEnd
                : math.max(previous.end, sourceEnd),
          );
        }
      }
      if (sourceWindows.isEmpty) return;
      final cacheDirectory = await getTemporaryDirectory();
      final thumbnailCache =
          '${cacheDirectory.path}${platform.pathSeparator}klipio_thumbnails';
      for (final entry in sourceWindows.entries) {
        if (!mounted || generation != _filmstripLoadGeneration) return;
        final index = _videos.indexWhere((video) => video.path == entry.key);
        if (index < 0) continue;
        final video = _videos[index];
        final paths = await platform.timelineThumbnailsForVideo(
          video.path,
          thumbnailCache,
          video.durationSeconds,
          visibleSourceStart: entry.value.start,
          visibleSourceEnd: entry.value.end,
        );
        if (!mounted || generation != _filmstripLoadGeneration) return;
        final currentIndex =
            _videos.indexWhere((video) => video.path == entry.key);
        if (currentIndex < 0 || paths.isEmpty) continue;
        setState(() {
          _videos[currentIndex] = _videos[currentIndex].copyWith(
            timelineThumbnailPaths: paths,
          );
        });
      }
    } finally {
      _timelineMediaLoadRunning = false;
      if (_timelineMediaLoadAgain && mounted) {
        _timelineMediaLoadAgain = false;
        unawaited(_loadVisibleTimelineMedia());
      }
    }
  }

  Future<void> _replaceVideoAt(int index) async {
    if (index < 0 || index > _videos.length) return;
    final isAdding = index == _videos.length;
    final result = await FilePicker.platform.pickFiles(type: FileType.video);
    final file =
        result == null || result.files.isEmpty ? null : result.files.first;
    if (file?.path == null) return;

    final replacement = PickedVideo(name: file!.name, path: file.path!);
    final updated = [..._videos];
    if (index == updated.length) {
      updated.add(replacement);
    } else {
      updated[index] = replacement;
    }
    await _setPickedVideos(
      updated,
      resetEdits: false,
      selectedIndex: index,
    );
    _showMessage(
        'Video ${index + 1} ${isAdding ? 'added' : 'replaced'}: ${file.name}.');
  }

  Future<void> _clearProject({
    bool confirm = true,
    bool createProjectFile = true,
  }) async {
    if (confirm && _videos.isNotEmpty) {
      final confirmed = await showDialog<bool>(
        context: context,
        builder: (context) => AlertDialog(
          title: const KText('Start a new project?'),
          content: KText(
            'Close the current project with ${_videos.length} loaded video${_videos.length == 1 ? '' : 's'} and start a new one? Your source files and saved projects will not be deleted.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(context).pop(false),
              child: const KText('Cancel'),
            ),
            FilledButton.icon(
              onPressed: () => Navigator.of(context).pop(true),
              icon: const Icon(Icons.add_box_outlined),
              label: const KText('New project'),
            ),
          ],
        ),
      );
      if (confirmed != true || !mounted) return;
    }

    ++_controllerLoadGeneration;
    ++_filmstripLoadGeneration;
    _timelineMediaLoadDebounce?.cancel();
    final exportToken = _exportCancelToken;
    final captionToken = _captionCancelToken;
    try {
      await Future.wait<void>([
        if (exportToken != null)
          exportToken.cancelAndWait(timeout: const Duration(seconds: 8)),
        if (captionToken != null)
          captionToken.cancelAndWait(timeout: const Duration(seconds: 8)),
        platform.cancelBackgroundMediaTasks(),
      ]);
    } catch (_) {
      await terminateAllKlipioWorkers();
    }
    _proxyJobsBySource.clear();
    _proxyUnavailableSources.clear();
    await _stopMusicPreview();
    final source = _sourceController;
    final preview = _previewController;
    source?.removeListener(_handleSourceTick);
    preview?.removeListener(_handlePreviewTick);
    setState(() {
      _videos.clear();
      _editorUndoHistory.clear();
      _editorRedoHistory.clear();
      _compositionPaths.clear();
      _projectMediaPathsByComposition.clear();
      _timelinesByComposition.clear();
      _selectedCompositionPath = null;
      _clipTimelineEdits.clear();
      _clipTimelineUndoStacks.clear();
      _clipTimelineRedoStacks.clear();
      _captionCuesByVideo.clear();
      _audioWaveformPeaks.clear();
      _audioWaveformPeakRates.clear();
      _textOverlays
        ..clear()
        ..add(const _TextOverlayDraft());
      _selectedTextOverlayIndex = 0;
      _loadTextOverlay(_textOverlays.first);
      _clipTransformOverrides.clear();
      _multiTrackTimeline = TimelineModel.empty();
      _timelineMarkers.clear();
      _selectedTimelineClipId = null;
      _selectedTimelineClipIds.clear();
      _selectedCaptionIds.clear();
      _musicTimelineSelected = false;
      _programTimelineClipId = null;
      _sourceController = null;
      _previewController = null;
      _sourceError = null;
      _previewError = null;
      _selectedVideoIndex = 0;
      _currentProjectPath = null;
      _nameController.clear();
      _numberStartController.text = '1';
      _numberEndController.clear();
      _titleCheckController.clear();
      _status = 'New project ready. Open Project media to import files.';
    });
    await source?.dispose();
    await preview?.dispose();
    if (createProjectFile) {
      await _autosaveProject(includeEmptyProject: true);
    }
  }

  List<String> _pastedVideoTitles() => _titleCheckController.text
      .split(RegExp(r'\r?\n'))
      .map((line) => line.trim())
      .where((line) => line.isNotEmpty)
      .toList();

  Future<void> _showTitleCheckDialog() async {
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) {
          final titles = _pastedVideoTitles();
          final masterNumbers = [
            for (final video in _videos)
              titles.indexWhere(
                (title) =>
                    normalizeVideoTitle(title) ==
                    normalizeVideoTitle(video.name),
              ),
          ];
          final matchCount = masterNumbers.where((index) => index >= 0).length;

          return AlertDialog(
            title: const KText('Call Check - Video Order'),
            content: SizedBox(
              width: 820,
              height: 620,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  KText(
                    'Paste your full master title list, one title per line. Each loaded project video is searched anywhere in that list.',
                    style: TextStyle(color: _mutedTextColor),
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: _titleCheckController,
                    minLines: 5,
                    maxLines: 8,
                    decoration: const InputDecoration(
                      labelText: 'Master video title list',
                      hintText:
                          'Paste the complete list here, one title per line',
                      border: OutlineInputBorder(),
                    ),
                    onChanged: (_) => setDialogState(() {}),
                  ),
                  const SizedBox(height: 10),
                  KText(
                    '$matchCount of ${_videos.length} project videos found  |  ${titles.length} master titles pasted',
                    style: const TextStyle(fontWeight: FontWeight.w700),
                  ),
                  const SizedBox(height: 8),
                  Expanded(
                    child: _videos.isEmpty
                        ? const Center(
                            child: KText(
                                'Import project videos first, then paste the master title list.'))
                        : ListView.builder(
                            itemCount: _videos.length,
                            itemBuilder: (context, index) {
                              final actual =
                                  _withoutExtension(_videos[index].name);
                              final masterIndex = masterNumbers[index];
                              final isMatch = masterIndex >= 0;
                              final color = isMatch ? Colors.green : Colors.red;
                              return Card(
                                color: color.withOpacity(0.10),
                                child: ListTile(
                                  leading: CircleAvatar(
                                    backgroundColor: color,
                                    foregroundColor: Colors.white,
                                    child: KText(
                                        isMatch ? '${masterIndex + 1}' : '!'),
                                  ),
                                  title: KText(
                                    actual,
                                    style: TextStyle(
                                      color: color,
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  subtitle: KText(
                                    isMatch
                                        ? 'Found at master number ${masterIndex + 1}  |  Project position ${index + 1}'
                                        : 'Not found in the pasted master list  |  Project position ${index + 1}',
                                  ),
                                  trailing: isMatch
                                      ? const Icon(Icons.check_circle,
                                          color: Colors.green)
                                      : FilledButton.icon(
                                          onPressed: () async {
                                            await _replaceVideoAt(index);
                                            if (dialogContext.mounted) {
                                              setDialogState(() {});
                                            }
                                          },
                                          icon: const Icon(Icons.swap_horiz),
                                          label: const KText('Replace'),
                                        ),
                                ),
                              );
                            },
                          ),
                  ),
                ],
              ),
            ),
            actions: [
              OutlinedButton.icon(
                onPressed: matchCount < 2
                    ? null
                    : () async {
                        final ranked = [
                          for (var index = 0; index < _videos.length; index++)
                            (
                              video: _videos[index],
                              master: masterNumbers[index]
                            ),
                        ]..sort((a, b) {
                            final aRank = a.master < 0 ? 1 << 30 : a.master;
                            final bRank = b.master < 0 ? 1 << 30 : b.master;
                            return aRank.compareTo(bRank);
                          });
                        await _setPickedVideos(
                          ranked.map((item) => item.video).toList(),
                          resetEdits: false,
                        );
                        if (dialogContext.mounted) {
                          setDialogState(() {});
                        }
                      },
                icon: const Icon(Icons.sort_by_alpha),
                label: const KText('Sort by master list'),
              ),
              TextButton(
                onPressed: () {
                  _titleCheckController.clear();
                  setDialogState(() {});
                },
                child: const KText('Clear'),
              ),
              FilledButton(
                onPressed: () => Navigator.of(dialogContext).pop(),
                child: const KText('Done'),
              ),
            ],
          );
        },
      ),
    );
  }

  Future<void> _selectVideo(int index, {bool saveCurrentEdit = true}) async {
    if (index < 0 || index >= _videos.length) return;
    final loadGeneration = ++_controllerLoadGeneration;
    if (saveCurrentEdit) {
      _saveSelectedClipTimelineEdit();
    }
    await _stopMusicPreview();
    final oldSourceController = _sourceController;
    final oldPreviewController = _previewController;
    oldSourceController?.removeListener(_handleSourceTick);
    oldPreviewController?.removeListener(_handlePreviewTick);
    if (mounted) {
      setState(() {
        _selectedVideoIndex = index;
        _selectedCaptionCueIndex = 0;
        _sourceController = null;
        _previewController = null;
        _sourceError = null;
        _previewError = null;
        _clipEditMode = true;
        _status = 'Loading ${_videos[index].name}...';
      });
      _loadClipTimelineEdit(index);
    }
    await oldSourceController?.dispose();
    await oldPreviewController?.dispose();
    VideoPlayerController? sourceController;
    VideoPlayerController? controller;
    String? sourceError;
    String? previewError;
    final selectedVideo = _videos[index];
    final previewPath = _availablePreviewPath(selectedVideo);
    if (previewPath == null) {
      sourceError = 'Preparing lightweight preview...';
      previewError = 'Preparing lightweight preview...';
      unawaited(_ensureProxyForVideo(selectedVideo));
    } else {
      try {
        sourceController = await createPreviewController(previewPath);
        await sourceController.setVolume(_previewAudioVolume(_sourceVolume));
      } catch (error) {
        sourceController = null;
        sourceError = 'Cannot play source: $error';
      }
      try {
        controller = await createPreviewController(previewPath);
      } catch (error) {
        controller = null;
        previewError = 'Cannot play preview: $error';
      }
    }
    if (!mounted || loadGeneration != _controllerLoadGeneration) {
      await sourceController?.dispose();
      await controller?.dispose();
      return;
    }
    setState(() {
      _selectedVideoIndex = index;
      _sourceController = sourceController;
      _previewController = controller;
      _sourceError = sourceError;
      _previewError = previewError;
      _status = 'Selected ${_videos[index].name}';
      _editorSelection = EditorSelection.video(_videos[index].path);
    });
    _attachSourceListener(sourceController);
    _attachPreviewListener(controller);
    _scheduleLoadedMonitorFramePrime(sourceController, controller);
    unawaited(_loadVisibleTimelineMedia());
  }

  Future<void> _removeImportedVideo(int index) async {
    if (index < 0 || index >= _videos.length) return;
    ++_filmstripLoadGeneration;
    await platform.cancelBackgroundMediaTasks();
    _proxyJobsBySource.clear();
    _proxyUnavailableSources.clear();
    final removed = _videos[index];
    final wasActiveComposition = removed.path == _selectedCompositionPath;
    _storeActiveCompositionTimeline();

    _clipTimelineEdits.remove(removed.path);
    _clipTimelineUndoStacks.remove(removed.path);
    _clipTimelineRedoStacks.remove(removed.path);
    _clipTransformOverrides.remove(removed.path);
    _captionCuesByVideo.remove(removed.path);
    _audioWaveformPeaks.remove(removed.path);
    _audioWaveformPeakRates.remove(removed.path);
    _selectedCaptionIds.removeWhere(
      (id) => _captionSelectionTarget(id)?.path == removed.path,
    );

    setState(() {
      _compositionPaths.remove(removed.path);
      _projectMediaPathsByComposition.remove(removed.path);
      _timelinesByComposition.remove(removed.path);
      for (final paths in _projectMediaPathsByComposition.values) {
        paths.remove(removed.path);
      }
      _videos.removeAt(index);
      if (_videos.isEmpty) {
        _selectedVideoIndex = 0;
      } else if (index < _selectedVideoIndex) {
        _selectedVideoIndex--;
      }
      if (wasActiveComposition) {
        _selectedCompositionPath =
            _compositionPaths.isEmpty ? null : _compositionPaths.first;
        _multiTrackTimeline = _selectedCompositionPath == null
            ? TimelineModel.empty()
            : (_timelinesByComposition[_selectedCompositionPath!] ??
                TimelineModel.empty());
        final clips = _multiTrackTimeline.videoTracks
            .expand((track) => track.clips)
            .toList();
        _selectedTimelineClipId = clips.isEmpty ? null : clips.first.id;
        _programTimelineClipId = _selectedTimelineClipId;
      }
      _status = 'Removed ${removed.name} from imports';
    });

    if (_compositionPaths.isEmpty) {
      await _stopMusicPreview();
      final oldSourceController = _sourceController;
      final oldPreviewController = _previewController;
      oldSourceController?.removeListener(_handleSourceTick);
      oldPreviewController?.removeListener(_handlePreviewTick);
      setState(() {
        _sourceController = null;
        _previewController = null;
        _sourceError = null;
        _previewError = null;
        _progress = 0;
      });
      _applyClipTimelineEdit(const _ClipTimelineEdit());
      await oldSourceController?.dispose();
      await oldPreviewController?.dispose();
      return;
    }

    if (wasActiveComposition && _selectedCompositionPath != null) {
      await _selectComposition(_selectedCompositionPath!);
    }
  }

  Future<void> _pickOutputFolder() async {
    final folder = await FilePicker.platform.getDirectoryPath();
    if (!mounted) return;
    setState(() {
      _outputFolder = folder;
      _status = folder == null ? _status : 'Output folder selected';
    });
  }

