    }
  }

  Future<void> _togglePreview() async {
    var controller = _previewController;
    final wasPlaying = controller?.value.isPlaying == true;
    if (wasPlaying) {
      _previewFramePrimeGeneration++;
      await controller!.pause();
      await _pauseMusicPreview();
      MediaJobManager.instance.resumeBackgroundWork();
      if (mounted) setState(() {});
      return;
    }

    var playStart = _requestedTimelinePlayheadSeconds.value ??
        _liveTimelinePlayheadSeconds.value ??
        _currentProgramSeconds();
    playStart = _programPlayStartSeconds(playStart);
    if (_hasAuthoritativeProgramTimeline) {
      var target = _programTargetForTimelineSeconds(playStart);
      if (target?.isGap == true) {
        final next = ProgramTimelineMapper.nextPlayableVideoClip(
          _multiTrackTimeline,
          atOrAfterTimelineSeconds: playStart,
        );
        if (next == null) return;
        playStart = next.timelineStart;
        target = _programTargetForTimelineSeconds(playStart);
      }
      if (target == null || target.isGap) return;
      _requestedTimelinePlayheadSeconds.value = playStart;
      _liveTimelinePlayheadSeconds.value = playStart;
      if (!await _seekProgramPreview(playStart)) return;
    } else {
      if (controller == null || !controller.value.isInitialized) {
        if (!await _seekProgramPreview(playStart)) return;
      }
      await _seekPreviewToPlayablePosition();
    }

    controller = _previewController;
    if (controller == null || !controller.value.isInitialized) return;
    MediaJobManager.instance.pauseBackgroundWork();
    _previewFramePrimeGeneration++;
    await controller.setPlaybackSpeed(_speed);
    await controller.setVolume(_previewAudioVolume(_effectiveOriginalVolume));
    await controller.play();
    await _playMusicPreview();
    if (mounted) setState(() {});
  }

  bool get _hasAuthoritativeProgramTimeline =>
      ProgramTimelineMapper.hasPlayableVideo(_multiTrackTimeline);

  double _programPlaybackDurationSeconds() {
    if (_hasAuthoritativeProgramTimeline) {
      return ProgramTimelineMapper.duration(_multiTrackTimeline)
          .clamp(0.0, double.infinity)
          .toDouble();
    }
    return math
        .max(
          _actualMultiTrackExportDuration(),
          math.max(_multiTrackTimeline.duration, _timelineSequenceDuration()),
        )
        .clamp(0.0, double.infinity)
        .toDouble();
  }

  double _programPlayStartSeconds(double seconds) {
    final duration = _programPlaybackDurationSeconds();
    if (duration <= 0.001) {
      return seconds.clamp(0.0, double.infinity).toDouble();
    }
    if (seconds >= duration - 0.08) return 0.0;
    return seconds.clamp(0.0, duration).toDouble();
  }

  Future<void> _toggleSourcePreview() async {
    final controller = _sourceController;
    if (controller == null || !controller.value.isInitialized) return;
    _sourceFramePrimeGeneration++;
    await controller.setVolume(_previewAudioVolume(_sourceVolume));
    if (controller.value.isPlaying) {
      await controller.pause();
    } else {
      // If the user scrubbed the source slider, start from that position.
      final inPoint = _sourceInPoint;
      if (inPoint != null) {
        await controller.seekTo(
          Duration(milliseconds: (inPoint * 1000).round()),
        );
        _sourceInPoint = null;
      } else {
        // If we're at the end, wrap back to the start.
        final pos = controller.value.position.inMilliseconds;
        final dur = controller.value.duration.inMilliseconds;
        if (dur > 0 && pos >= dur - 80) {
          await controller.seekTo(Duration.zero);
        }
      }
      await controller.play();
    }
    if (mounted) setState(() {});
  }

  Future<bool> _seekProgramPreview(double seconds) async {
    if (_videos.isEmpty) return false;
    final target = _programTargetForTimelineSeconds(seconds);
    if (target == null) return false;
    if (target.isGap) {
      await _previewController?.pause();
      await _pauseMusicPreview();
      _programTimelineClipId = null;
      _requestedTimelinePlayheadSeconds.value = target.timelineSeconds;
      _liveTimelinePlayheadSeconds.value = target.timelineSeconds;
      if (mounted) setState(() {});
      return false;
    }
    final wasPlaying = _previewController?.value.isPlaying == true;
    final switchingVideo = target.videoIndex != _selectedVideoIndex;
    final controllerUnavailable = _previewController == null ||
        _previewController?.value.isInitialized != true;
    if (switchingVideo || controllerUnavailable) {
      await _selectVideo(
        target.videoIndex,
        saveCurrentEdit: switchingVideo,
      );
    }
    final targetClip = target.clipId == null
        ? null
        : _multiTrackTimeline.clipById(target.clipId!)?.clip;
    if (targetClip != null) {
      _loadTimelineClipTransformIntoInspector(targetClip);
    }
    final controller = _previewController;
    if (controller == null || !controller.value.isInitialized) return false;
    _programTimelineClipId = target.clipId;
    await controller.seekTo(
      Duration(milliseconds: (target.sourceSeconds! * 1000).round()),
    );
    if (wasPlaying) {
      await controller.play();
    } else {
      _schedulePausedFramePrime(controller, source: false);
    }
    if (mounted) setState(() {});
    return true;
  }

  Future<void> _seekSourcePreview(double seconds) async {
    final controller = _sourceController;
    if (controller == null || !controller.value.isInitialized) return;
    final wasPlaying = controller.value.isPlaying;
    await controller.seekTo(Duration(milliseconds: (seconds * 1000).round()));
    if (!wasPlaying) _schedulePausedFramePrime(controller, source: true);
    if (mounted) setState(() {});
  }

  void _scheduleLoadedMonitorFramePrime(
    VideoPlayerController? sourceController,
    VideoPlayerController? previewController,
  ) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (sourceController != null) {
        _schedulePausedFramePrime(sourceController, source: true);
      }
      if (previewController != null) {
        _schedulePausedFramePrime(previewController, source: false);
      }
    });
  }

  void _schedulePausedFramePrime(
    VideoPlayerController controller, {
    required bool source,
  }) {
    // An existing warm-up is already decoding the newest seek position.
    // Do not invalidate it or the controller could be left playing silently.
    if (controller.value.isPlaying) return;
    final generation =
        source ? ++_sourceFramePrimeGeneration : ++_previewFramePrimeGeneration;
    unawaited(_primePausedFrame(controller, source, generation));
  }

  Future<void> _primePausedFrame(
    VideoPlayerController controller,
    bool source,
    int generation,
  ) async {
    final activeController = source ? _sourceController : _previewController;
    if (!mounted ||
        controller != activeController ||
        !controller.value.isInitialized ||
        controller.value.isPlaying) {
      return;
    }
    final restoreVolume = source ? _sourceVolume : _effectiveOriginalVolume;
    try {
      await controller.setVolume(0);
      await controller.play();
      await Future<void>.delayed(const Duration(milliseconds: 180));
      final currentGeneration =
          source ? _sourceFramePrimeGeneration : _previewFramePrimeGeneration;
      final currentController = source ? _sourceController : _previewController;
      if (!mounted ||
          generation != currentGeneration ||
          controller != currentController) {
        return;
      }
      await controller.pause();
      await controller.setVolume(_previewAudioVolume(restoreVolume));
      if (mounted) setState(() {});
    } catch (_) {
      // A failed warm-up must not make normal playback unusable.
      if (controller == (source ? _sourceController : _previewController)) {
        try {
          await controller.setVolume(_previewAudioVolume(restoreVolume));
        } catch (_) {}
      }
    }
  }

  Future<void> _seekPreviewToPlayablePosition({
    bool preferNext = false,
  }) async {
    final controller = _previewController;
    if (controller == null ||
        !controller.value.isInitialized ||
        _videos.isEmpty) {
      return;
    }
    final edit = _clipTimelineEditFor(_videos[_selectedVideoIndex].path);
    final parts =
        edit.timelineParts(_videos[_selectedVideoIndex].durationSeconds);
    if (parts.isEmpty) return;

    final seconds = controller.value.position.inMilliseconds / 1000;
    final target = _playableSecondsForPosition(
      seconds,
      parts,
      preferNext: preferNext,
    );
    if ((target - seconds).abs() < 0.01) return;
    await controller.seekTo(Duration(milliseconds: (target * 1000).round()));
  }

  double _playableSecondsForPosition(
    double seconds,
    List<({double start, double end})> parts, {
    required bool preferNext,
  }) {
    for (final part in parts) {
      if (seconds >= part.start - 0.001 && seconds < part.end - 0.001) {
        return seconds;
      }
      if (seconds < part.start) {
        return part.start;
      }
    }
    return preferNext ? parts.last.start : parts.first.start;
  }

  double _currentProgramSeconds() {
    if (_videos.isEmpty ||
        _selectedVideoIndex < 0 ||
        _selectedVideoIndex >= _videos.length) {
      return 0;
    }
    final requestedTimelineSeconds = _requestedTimelinePlayheadSeconds.value;
    if (requestedTimelineSeconds != null) {
      final duration = _programPlaybackDurationSeconds();
      return requestedTimelineSeconds
          .clamp(0.0, math.max(duration, 0.0))
          .toDouble();
    }
    final programClipId = _programTimelineClipId;
    if (programClipId != null) {
      final result = _multiTrackTimeline.clipById(programClipId);
      if (result != null &&
          result.track.type == TrackType.video &&
          result.clip.mediaPath == _videos[_selectedVideoIndex].path) {
        final sourceSeconds = _currentPlayheadSeconds();
        return ProgramTimelineMapper.timelineSecondsForSource(
          clip: result.clip,
          sourceSeconds: sourceSeconds,
        );
      }
    }
    if (_hasAuthoritativeProgramTimeline) {
      return (_liveTimelinePlayheadSeconds.value ?? 0.0)
          .clamp(0.0, _programPlaybackDurationSeconds())
          .toDouble();
    }
    var sequenceSeconds = 0.0;
    for (final item in _visibleTimelineVideos()) {
      final index = item.index;
      final video = item.video;
      final parts = _clipTimelineEditFor(video.path).timelineParts(
        video.durationSeconds,
      );
      if (index < _selectedVideoIndex) {
        sequenceSeconds += parts.fold<double>(
          0,
          (sum, part) => sum + (part.end - part.start).abs(),
        );
        continue;
      }
      if (index == _selectedVideoIndex) {
        final sourceSeconds = _currentPlayheadSeconds();
        for (final part in parts) {
          final partDuration = (part.end - part.start).abs();
          if (sourceSeconds >= part.start - 0.001 &&
              sourceSeconds <= part.end + 0.001) {
            return sequenceSeconds +
                (sourceSeconds - part.start).clamp(0.0, partDuration);
          }
          sequenceSeconds += partDuration;
        }
        return sequenceSeconds.clamp(0.0, _timelineSequenceDuration());
      }
    }
    return sequenceSeconds;
  }

  bool _shouldSkipCurrentPreviewPosition(double seconds) {
    if (_isSkippingPreviewEdit ||
        _videos.isEmpty ||
        _selectedVideoIndex < 0 ||
        _selectedVideoIndex >= _videos.length) {
      return false;
    }
    final edit = _clipTimelineEditFor(_videos[_selectedVideoIndex].path);
    final parts =
        edit.timelineParts(_videos[_selectedVideoIndex].durationSeconds);
    if (parts.isEmpty) return false;
    for (final part in parts) {
      if (seconds >= part.start - 0.001 && seconds < part.end - 0.12) {
        return false;
      }
    }
    return true;
  }

  Future<void> _skipPreviewEditAt(double seconds) async {
    final controller = _previewController;
    if (controller == null ||
        !controller.value.isInitialized ||
        _videos.isEmpty) {
      return;
    }
    _isSkippingPreviewEdit = true;
    try {
      final edit = _clipTimelineEditFor(_videos[_selectedVideoIndex].path);
      final parts =
          edit.timelineParts(_videos[_selectedVideoIndex].durationSeconds);
      for (var index = 0; index < parts.length; index++) {
        final part = parts[index];
        if (seconds >= part.start - 0.001 && seconds < part.end - 0.12) {
          return;
        }
        if (seconds >= part.end - 0.12 && seconds <= part.end + 0.25) {
          if (index < parts.length - 1) {
            await controller.seekTo(
              Duration(milliseconds: (parts[index + 1].start * 1000).round()),
            );
            return;
          }
          break;
        }
      }
      for (final part in parts) {
        if (seconds < part.start - 0.001) {
          await controller.seekTo(
            Duration(milliseconds: (part.start * 1000).round()),
          );
          return;
        }
      }
      if (_exportTimelineTogether && _selectedVideoIndex < _videos.length - 1) {
        await _playNextTimelineClip();
        return;
      }
      await controller.pause();
      await _pauseMusicPreview();
      if (parts.isNotEmpty) {
        await controller.seekTo(
          Duration(milliseconds: (parts.last.end * 1000).round()),
        );
      }
    } finally {
      _isSkippingPreviewEdit = false;
      if (mounted) setState(() {});
    }
  }

  void _attachPreviewListener(VideoPlayerController? controller) {
    controller?.addListener(_handlePreviewTick);
  }

  void _attachSourceListener(VideoPlayerController? controller) {
    controller?.addListener(_handleSourceTick);
  }

  void _handleSourceTick() {
    final controller = _sourceController;
    if (controller == null || !controller.value.isInitialized) return;
  }

  void _handlePreviewTick() {
    final controller = _previewController;
    if (controller == null || !controller.value.isInitialized) return;
    if (widget.active) {
      _liveTimelinePlayheadSeconds.value = _currentProgramSeconds();
    }
    final requested = _requestedTimelinePlayheadSeconds.value;
    if (requested != null &&
        (_currentProgramSeconds() - requested).abs() <= 0.2) {
      _requestedTimelinePlayheadSeconds.value = null;
    }
    final position = controller.value.position;
    if (_hasAuthoritativeProgramTimeline) {
      if (controller.value.isPlaying) {
        final seconds = position.inMilliseconds / 1000;
        final programClipId = _programTimelineClipId;
        final programClip = programClipId == null
            ? null
            : _multiTrackTimeline.clipById(programClipId)?.clip;
        if (programClip != null &&
            seconds >= programClip.sourceEnd - 0.10 &&
            !_autoAdvancingPreview) {
          _autoAdvancingPreview = true;
          unawaited(_playNextProgramTimelineClip(programClip));
        }
      }
      return;
    }
    final duration = controller.value.duration;
    if (controller.value.isPlaying) {
      final seconds = position.inMilliseconds / 1000;
      final programClipId = _programTimelineClipId;
      final programClip = programClipId == null
          ? null
          : _multiTrackTimeline.clipById(programClipId)?.clip;
      if (programClip != null &&
          seconds >= programClip.sourceEnd - 0.10 &&
          !_autoAdvancingPreview) {
        _autoAdvancingPreview = true;
        unawaited(_playNextProgramTimelineClip(programClip));
        return;
      }
      if (_shouldSkipCurrentPreviewPosition(seconds)) {
        unawaited(_skipPreviewEditAt(seconds));
        return;
      }
    }
    if (duration > Duration.zero &&
        position >= duration - const Duration(milliseconds: 250) &&
        !controller.value.isPlaying) {
      if (widget.settings.autoAdvanceTimeline &&
          _exportTimelineTogether &&
          !_autoAdvancingPreview &&
          _selectedVideoIndex < _videos.length - 1) {
        _autoAdvancingPreview = true;
        unawaited(_playNextTimelineClip());
        return;
      }
      unawaited(_pauseMusicPreview());
    }
  }

  Future<void> _playNextProgramTimelineClip(ClipModel current) async {
    try {
      final next = ProgramTimelineMapper.nextPlayableVideoClip(
        _multiTrackTimeline,
        atOrAfterTimelineSeconds: current.timelineEnd,
        excludingClipId: current.id,
      );
      if (next == null) {
        await _previewController?.pause();
        await _pauseMusicPreview();
        _programTimelineClipId = null;
        _requestedTimelinePlayheadSeconds.value = null;
        _liveTimelinePlayheadSeconds.value = _programPlaybackDurationSeconds();
        return;
      }
      await _seekProgramPreview(next.timelineStart + 0.001);
      await _previewController?.play();
      await _playMusicPreview();
    } finally {
      _autoAdvancingPreview = false;
      if (mounted) setState(() {});
    }
  }

  Future<void> _playNextTimelineClip() async {
    if (_hasAuthoritativeProgramTimeline) {
      final currentId = _programTimelineClipId;
      final current = currentId == null
          ? null
          : _multiTrackTimeline.clipById(currentId)?.clip;
      if (current != null) await _playNextProgramTimelineClip(current);
      return;
    }
    await _selectVideo(_selectedVideoIndex + 1);
    final controller = _previewController;
    if (controller != null && controller.value.isInitialized) {
      await _seekPreviewToPlayablePosition();
      await controller.play();
      await _playMusicPreview();
    }
    _autoAdvancingPreview = false;
  }

  Future<void> _playMusicPreview() async {
    final path = _musicPath;
    if (path == null || path.isEmpty) {
      await _stopMusicPreview();
      return;
    }

    try {
      await _musicPreviewPlayer.setReleaseMode(ReleaseMode.loop);
      await _musicPreviewPlayer
          .setVolume(_previewAudioVolume(_effectiveMusicVolume));
      if (_musicPreviewPath != path) {
        await _musicPreviewPlayer.stop();
        await _musicPreviewPlayer.play(DeviceFileSource(path));
        _musicPreviewPath = path;
      } else {
        await _musicPreviewPlayer.resume();
      }
    } catch (error) {
      if (!mounted) return;
      setState(() => _status = 'Cannot preview music: $error');
    }
  }

  Future<void> _pauseMusicPreview() async {
    await _musicPreviewPlayer.pause();
  }

  Future<void> _stopMusicPreview() async {
    await _musicPreviewPlayer.stop();
    _musicPreviewPath = null;
  }

  Future<void> _selectPreviousVideo() async {
    if (_videos.isEmpty) return;
    final previous =
        _selectedVideoIndex <= 0 ? _videos.length - 1 : _selectedVideoIndex - 1;
    await _selectVideo(previous);
  }

  Future<void> _selectNextVideo() async {
    if (_videos.isEmpty) return;
    final next =
        _selectedVideoIndex >= _videos.length - 1 ? 0 : _selectedVideoIndex + 1;
    await _selectVideo(next);
  }

