  Future<void> _exportVideos({
    bool prepareForCapCut = false,
    bool showSettingsDialog = true,
  }) async {
    try {
      await _exportVideosImpl(
        prepareForCapCut: prepareForCapCut,
        showSettingsDialog: showSettingsDialog,
      );
    } catch (error, stackTrace) {
      await _recoverUnexpectedExportFailure(error, stackTrace);
    }
  }

  Future<void> _exportVideosImpl({
    required bool prepareForCapCut,
    required bool showSettingsDialog,
  }) async {
    if (_videos.isEmpty) {
      _showMessage('Select one or more videos first.');
      return;
    }
    await _pausePlaybackForExport();

    final baseFolder = _outputFolder ?? await _defaultOutputFolder();
    final folder = prepareForCapCut && baseFolder != null
        ? _capCutReadyFolder(baseFolder)
        : baseFolder;
    if (folder == null) {
      _showMessage('Select an output folder first.');
      return;
    }

    if (!_exportAvailable) {
      _showMessage(
        platform.isAndroid || platform.isIos
            ? 'This Flutter mobile UI is ready. Add an FFmpeg mobile plugin/backend to enable phone export.'
            : 'Install FFmpeg and add it to PATH to enable export on this PC.',
      );
      return;
    }

    _syncCutFields();
    var jobs = _buildExportJobs(folder, applyNumberRange: false);
    if (prepareForCapCut) {
      jobs = _capCutJobs(
        jobs,
        rootFolder: folder,
        oneFolder: _capCutOneFolder,
        renderEdits: _capCutRenderEdits,
      );
    }
    if (jobs.isEmpty) {
      _showMessage('No export jobs were created. Check cut/split values.');
      return;
    }

    String exportFolder;
    if (showSettingsDialog) {
      final confirmed = await _showExportSettingsDialog(
        folder,
        jobs,
        prepareForCapCut: prepareForCapCut,
      );
      if (!confirmed || !mounted) return;
      exportFolder = _confirmedExportFolder ?? _outputFolder ?? folder;
      _confirmedExportFolder = null;
      jobs = _buildExportJobs(exportFolder);
      if (prepareForCapCut) {
        jobs = _capCutJobs(
          jobs,
          rootFolder: exportFolder,
          oneFolder: _capCutOneFolder,
          renderEdits: _capCutRenderEdits,
        );
      }
    } else {
      exportFolder = _outputFolder ?? folder;
      jobs = _buildExportJobs(exportFolder);
      if (prepareForCapCut) {
        jobs = _capCutJobs(
          jobs,
          rootFolder: exportFolder,
          oneFolder: _capCutOneFolder,
          renderEdits: _capCutRenderEdits,
        );
      }
    }
    if (jobs.isEmpty) {
      _showMessage('No videos are inside the selected number range.');
      return;
    }

    // "One timeline video" is authoritative. A project may remember the
    // separate-parts preference, but that must never silently replace the
    // edited timeline with short source fragments.
    final activeTimelineMediaPaths = <String>{
      for (final track in _multiTrackTimeline.videoTracks)
        if (!track.isMuted)
          for (final clip in track.clips)
            if (!clip.isMuted && clip.duration > 0.001) clip.mediaPath,
    };
    // A single imported source can produce several timeline clips after hook,
    // split, trim, or delete edits. Those clips are one edited movie, not
    // separate export jobs. This also repairs older projects that remembered
    // the obsolete separate-output preference.
    final isSingleSourceEditedTimeline =
        _videos.length == 1 && activeTimelineMediaPaths.length == 1;
    final exportTimelineTogether = !prepareForCapCut &&
        (_exportTimelineTogether || isSingleSourceEditedTimeline);
    final exportDetails = _buildExportDialogDetails(
      exportFolder,
      jobs,
      exportTimelineTogether: exportTimelineTogether,
      titleOverride: prepareForCapCut ? 'Prepare for CapCut' : null,
      nameOverride: prepareForCapCut
          ? '${_groupQueuedExports(jobs).length} CapCut clips'
          : null,
    );
    final useMultiTrackExport = !prepareForCapCut &&
        exportTimelineTogether &&
        _compositionPaths.length <= 1 &&
        activeTimelineMediaPaths.isNotEmpty;
    if (useMultiTrackExport) {
      final timelineDuration = _actualMultiTrackExportDuration();
      final timelineDetails = exportDetails.copyWith(
        durationSeconds: timelineDuration,
        estimatedSize: _estimatedExportSizeLabel(
          timelineDuration,
          _exportBitrateKbps,
          1,
        ),
      );
      await _runMultiTrackExport(exportFolder, timelineDetails);
      return;
    }
    final cancelToken = ExportCancelToken();
    _exportCancelToken = cancelToken;
    _updateExportProgressView(
      details: exportDetails,
      progress: 0,
      elapsed: Duration.zero,
      status: prepareForCapCut
          ? 'Preparing CapCut clips...'
          : 'Preparing export...',
    );
    final exportStartedAt = DateTime.now();
    _showExportProgressDialog();

    setState(() {
      _isExporting = true;
      _renderQueuePaused = false;
      _renderQueueStopRequested = false;
      _progress = 0;
      _status = prepareForCapCut ? 'Preparing CapCut clips...' : 'Exporting...';
    });

    if (exportTimelineTogether) {
      setState(() {
        _progress = 0;
        _status = 'Rendering timeline sequence...';
      });
      var lastProgressUpdate = DateTime.fromMillisecondsSinceEpoch(0);
      final result = await exportVideoSequence(
        SequenceExportJob(
          jobs: [
            for (final item in jobs)
              ExportJob(
                inputPath: item.video.path,
                outputPath: item.outputPath,
                settings: item.settings,
                cancelToken: cancelToken,
              ),
          ],
          outputPath: _timelineOutputPath(exportFolder),
          settings: _settings,
          cancelToken: cancelToken,
          onProgress: (progress, status) {
            final now = DateTime.now();
            if (now.difference(lastProgressUpdate).inMilliseconds < 250 &&
                progress < 1) {
              return;
            }
            lastProgressUpdate = now;
            if (!mounted) return;
            setState(() {
              _progress = progress.clamp(0.0, 1.0).toDouble();
              _status = status;
            });
            _updateExportProgressView(
              details: exportDetails,
              progress: progress,
              elapsed: DateTime.now().difference(exportStartedAt),
              status: 'Rendering timeline sequence...',
            );
          },
        ),
      );
      if (!mounted) return;
      if (result.success) {
        setState(() {
          _isExporting = false;
          _renderQueuePaused = false;
          _renderQueueStopRequested = false;
          _exportCancelToken = null;
          _progress = 1;
          _status = 'Ready';
        });
        MediaJobManager.instance.resumeBackgroundWork();
        _updateExportProgressView(
          details: exportDetails,
          progress: 1,
          elapsed: DateTime.now().difference(exportStartedAt),
          status: 'Export complete',
        );
        _closeExportProgressDialog();
        _playExportCompleteSound();
        _showMessage('Timeline export complete: ${result.outputPath}');
      } else {
        final canceled = result.message == 'Export canceled.';
        setState(() {
          _isExporting = false;
          _renderQueuePaused = false;
          _renderQueueStopRequested = false;
          _exportCancelToken = null;
          _status = canceled ? 'Export canceled' : 'Ready';
        });
        MediaJobManager.instance.resumeBackgroundWork();
        _closeExportProgressDialog();
        _showMessage(canceled
            ? 'Export canceled.'
            : 'Timeline export failed: ${result.message}');
      }
      return;
    }

    final exportGroups = _groupQueuedExports(jobs);
    var success = 0;
    var failed = 0;
    String? lastError;
    var lastProgressUpdate = DateTime.fromMillisecondsSinceEpoch(0);
    for (var index = 0; index < exportGroups.length; index++) {
      final canContinue = await _waitForRenderQueueResume(
        details: exportDetails,
        exportStartedAt: exportStartedAt,
      );
      if (!canContinue) {
        lastError = 'Export canceled.';
        break;
      }
      final group = exportGroups[index];
      final outputName = platform.basename(group.outputPath);
      void onClipProgress(double clipProgress, String status) {
        final now = DateTime.now();
        if (now.difference(lastProgressUpdate).inMilliseconds < 250 &&
            clipProgress < 1) {
          return;
        }
        lastProgressUpdate = now;
        if (!mounted) return;
        final totalProgress =
            ((index + clipProgress.clamp(0.0, 1.0)) / exportGroups.length)
                .clamp(0.0, 1.0)
                .toDouble();
        setState(() {
          _progress = totalProgress;
          _status = prepareForCapCut
              ? 'Preparing CapCut clip ${index + 1} of ${exportGroups.length}: $outputName'
              : 'Exporting ${index + 1} of ${exportGroups.length}: $outputName';
        });
        _updateExportProgressView(
          details: exportDetails.copyWith(
            name: outputName,
            durationSeconds: _queuedExportGroupDuration(group),
            thumbnailPath: group.video.thumbnailPath,
          ),
          progress: totalProgress,
          elapsed: DateTime.now().difference(exportStartedAt),
          status: prepareForCapCut
              ? 'Preparing CapCut clip ${index + 1} of ${exportGroups.length}'
              : 'Exporting ${index + 1} of ${exportGroups.length}',
        );
      }

      final result = await _exportQueuedVideoComposition(
        group,
        cancelToken: cancelToken,
        onProgress: onClipProgress,
      );
      if (!mounted) return;
      if (result.success) {
        success++;
      } else {
        failed++;
        lastError = '$outputName: ${result.message}';
        if (result.message == 'Export canceled.') {
          break;
        }
      }
      setState(() {
        _progress = (index + 1) / exportGroups.length;
        _status = prepareForCapCut
            ? 'Prepared ${index + 1} of ${exportGroups.length}'
            : 'Exported ${index + 1} of ${exportGroups.length}';
      });
    }

    setState(() {
      _isExporting = false;
      _renderQueuePaused = false;
      _renderQueueStopRequested = false;
      _exportCancelToken = null;
      _status = lastError?.contains('Export canceled.') == true
          ? 'Export canceled'
          : 'Ready';
    });
    MediaJobManager.instance.resumeBackgroundWork();
    _updateExportProgressView(
      details: exportDetails,
      progress: 1,
      elapsed: DateTime.now().difference(exportStartedAt),
      status: lastError == null
          ? prepareForCapCut
              ? 'CapCut clips ready'
              : 'Export complete'
          : 'Export finished',
    );
    _closeExportProgressDialog();
    if (lastError?.contains('Export canceled.') == true) {
      _showMessage('Export canceled.');
    } else if (lastError == null) {
      _playExportCompleteSound();
      if (prepareForCapCut) {
        _showMessage(
          'CapCut-ready folder complete. Success: $success, failed: $failed.',
        );
      } else {
        _showMessage('Export complete. Success: $success, failed: $failed.');
      }
    } else {
      _showMessage(
        'Export complete. Success: $success, failed: $failed. Last error: $lastError',
      );
    }
  }

  Future<void> _runMultiTrackExport(
    String exportFolder,
    KlipioExportDialogDetails exportDetails,
  ) async {
    final outputPath = _timelineOutputPath(exportFolder);
    final dimensions = _multiTrackOutputDimensions();
    final sourceTimelineDuration = _actualMultiTrackExportDuration();
    final sourceTimeline =
        _multiTrackTimeline.copyWith(duration: sourceTimelineDuration);
    final compositionPath = _selectedCompositionPath;
    final playbackSpeed = (compositionPath == null
            ? _speed
            : _clipTimelineEditFor(compositionPath).speed)
        .clamp(_minVideoSpeed, _maxVideoSpeed)
        .toDouble();
    final exportTimeline = _retimeTimelineForExport(
      sourceTimeline,
      playbackSpeed,
    );
    final timelineDuration = _actualMultiTrackExportDuration(exportTimeline);
    final timelineCaptionCues = _retimeCaptionCuesForExport(
      _exportTimelineCaptionCues(sourceTimeline),
      playbackSpeed,
    );
    final captionSettings = timelineCaptionCues.isEmpty
        ? null
        : _settings.copyWith(
            automaticCaptions: false,
            captionCues: timelineCaptionCues,
            textOverlays: const [],
            speed: 1,
            trimStartSeconds: 0,
            trimEndSeconds: timelineDuration,
          );
    final cancelToken = ExportCancelToken();
    _exportCancelToken = cancelToken;
    _updateExportProgressView(
      details: exportDetails,
      progress: 0,
      elapsed: Duration.zero,
      status: 'Preparing multi-track filter graph...',
    );
    _showExportProgressDialog();
    final startedAt = DateTime.now();
    setState(() {
      _isExporting = true;
      _renderQueuePaused = false;
      _renderQueueStopRequested = false;
      _progress = 0;
      _status = 'Rendering dynamic multi-track timeline...';
    });
    final result = await exportMultiTrackTimeline(
      MultiTrackExportJob(
        timeline: exportTimeline.copyWith(duration: timelineDuration),
        outputPath: outputPath,
        width: dimensions.width,
        height: dimensions.height,
        frameRate: _exportFrameRate > 0 ? _exportFrameRate : _projectFrameRate,
        videoBitrateKbps: _exportBitrateKbps,
        exportCodec: _exportCodec,
        hardwareEncoding: widget.settings.hardwareEncoding,
        hardwareDecoding: widget.settings.hardwareDecoding,
        playbackSpeedsByMediaPath: _videoPlaybackSpeedsForExport(
          sourceTimeline,
          playbackSpeed,
        ),
        textOverlays: _retimeTextOverlaysForExport(
          _exportManualTextOverlays(),
          playbackSpeed,
        ),
        captionSettings: captionSettings,
        cancelToken: cancelToken,
        onProgress: (progress, status) {
          if (!mounted) return;
          setState(() {
            _progress = progress.clamp(0, 1).toDouble();
            _status = status;
          });
          _updateExportProgressView(
            details: exportDetails,
            progress: progress,
            elapsed: DateTime.now().difference(startedAt),
            status: status,
          );
        },
      ),
    );
    if (!mounted) return;
    setState(() {
      _isExporting = false;
      _renderQueuePaused = false;
      _renderQueueStopRequested = false;
      _progress = result.success ? 1 : 0;
      _status = result.success
          ? 'Multi-track export complete'
          : 'Multi-track export failed';
    });
    MediaJobManager.instance.resumeBackgroundWork();
    _exportCancelToken = null;
    _updateExportProgressView(
      details: exportDetails,
      progress: result.success ? 1 : 0,
      elapsed: DateTime.now().difference(startedAt),
      status: result.success ? 'Multi-track export complete' : result.message,
    );
    _closeExportProgressDialog();
    if (result.success) {
      _playExportCompleteSound();
      _showMessage('Multi-track export complete: $outputPath');
    } else {
      _showMessage(result.message);
    }
  }

  ({int width, int height}) _multiTrackOutputDimensions() {
    final base = switch (_outputRatio) {
      '9:16' => (width: 1080, height: 1920),
      '4:5' => (width: 1080, height: 1350),
      '1:1' => (width: 1080, height: 1080),
      '3:4' => (width: 1080, height: 1440),
      '4:3' => (width: 1440, height: 1080),
      _ => (width: 1920, height: 1080),
    };
    final scale = switch (_projectResolution) {
      '3840x2160' => 2.0,
      '1280x720' => 2 / 3,
      _ => 1.0,
    };
    int even(double value) => math.max(2, (value / 2).round() * 2);
    return (
      width: even(base.width * scale),
      height: even(base.height * scale),
    );
  }

  Future<void> _createCapCutDraft({bool showSettingsDialog = true}) async {
    _lastCapCutDraftSuccess = false;
    _lastCapCutDraftFolder = null;
    _lastCapCutDraftMessage = '';
    if (_videos.isEmpty) {
      _lastCapCutDraftMessage = 'Select one or more videos first.';
      _showMessage('Select one or more videos first.');
      return;
    }
    if (!platform.isDesktop || !Platform.isWindows) {
      _lastCapCutDraftMessage =
          'CapCut draft export is available on Windows desktop only.';
      _showMessage('CapCut draft export is available on Windows desktop only.');
      return;
    }
    if (await isCapCutDesktopRunning()) {
      _lastCapCutDraftMessage =
          'Close CapCut before creating drafts, then try again.';
      _showMessage('Close CapCut before creating drafts, then try again.');
      return;
    }

    _syncCutFields();
    final initialFolder = _outputFolder ?? await _defaultOutputFolder();
    if (initialFolder == null) return;
    final selectedFolder = showSettingsDialog
        ? await _showCapCutDraftSettingsDialog(initialFolder)
        : initialFolder;
    if (selectedFolder == null || selectedFolder.trim().isEmpty) return;
    final scratchFolder = selectedFolder.trim();
    final jobs = _buildExportJobs(
      scratchFolder,
      applyNumberRange: !_capCutRangeNumbersAllVideos,
    );
    if (jobs.isEmpty) {
      _lastCapCutDraftMessage =
          'No videos are inside the selected number range.';
      _showMessage('No videos are inside the selected number range.');
      return;
    }

    final draftGroups = _capCutDraftGroups(jobs);
    final multipleDrafts = draftGroups.length > 1;
    final renderDraftClips = _capCutDraftNeedsRenderedClips(jobs);
    if (renderDraftClips && !_exportAvailable) {
      _lastCapCutDraftMessage = platform.isAndroid || platform.isIos
          ? 'A mobile FFmpeg backend is required to render CapCut draft effects.'
          : 'Install FFmpeg and add it to PATH to render CapCut draft effects.';
      _showMessage(
        platform.isAndroid || platform.isIos
            ? 'This Flutter mobile UI is ready. Add an FFmpeg mobile plugin/backend to render CapCut draft effects.'
            : 'Install FFmpeg and add it to PATH to render CapCut draft effects.',
      );
      return;
    }
    final renderFolder =
        renderDraftClips ? await _capCutDraftRenderFolder(scratchFolder) : null;
    final projectName = multipleDrafts
        ? '${draftGroups.length} CapCut drafts'
        : _capCutDraftProjectName(
            draftGroups.first,
            useTypedName: _exportTimelineTogether,
          );

    setState(() {
      _isExporting = true;
      _renderQueuePaused = false;
      _renderQueueStopRequested = false;
      _progress = 0;
      _status = 'Creating CapCut draft...';
    });
    final exportDetails = _buildExportDialogDetails(
      scratchFolder,
      jobs,
      exportTimelineTogether: true,
      titleOverride: 'Create CapCut Draft',
      nameOverride: projectName,
    );
    _updateExportProgressView(
      details: exportDetails,
      progress: 0,
      elapsed: Duration.zero,
      status: 'Creating CapCut draft...',
    );
    final cancelToken = ExportCancelToken();
    _exportCancelToken = cancelToken;
    _showExportProgressDialog();

    final results = <CapCutDraftResult>[];
    for (var index = 0; index < draftGroups.length; index++) {
      if (cancelToken.isCanceled || _renderQueueStopRequested) {
        results.add(
          const CapCutDraftResult(
            success: false,
            message: 'Export canceled.',
          ),
        );
        break;
      }
      final group = draftGroups[index];
      final groupName = _capCutDraftProjectName(
        group,
        useTypedName: _exportTimelineTogether,
      );
      final status = multipleDrafts
          ? 'Creating CapCut draft ${index + 1} of ${draftGroups.length}: $groupName'
          : 'Creating CapCut draft...';
      if (mounted) {
        setState(() {
          _progress = index / draftGroups.length;
          _status = status;
        });
        _updateExportProgressView(
          details: exportDetails,
          progress: index / draftGroups.length,
          elapsed: _exportProgressView.value.elapsed,
          status: status,
        );
      }

      try {
        final clips = renderDraftClips
            ? await _renderCapCutDraftClips(
                group,
                renderFolder!,
                groupIndex: index,
                groupCount: draftGroups.length,
                details: exportDetails,
                cancelToken: cancelToken,
              )
            : [
                for (final job in group)
                  CapCutDraftClip(
                    inputPath: job.video.path,
                    name: _capCutDraftJobClipName(job),
                    settings: job.settings,
                  ),
              ];
        results.add(
          await createCapCutDraft(
            projectName: groupName,
            outputRoot: scratchFolder,
            clips: clips,
            launchCapCut: false,
            includeCaptionsInDraft: false,
            exportCaptionSrt: true,
          ).timeout(const Duration(hours: 1)),
        );
      } catch (error) {
        final message =
            cancelToken.isCanceled ? 'Export canceled.' : error.toString();
        results.add(
          CapCutDraftResult(
            success: false,
            message: message,
          ),
        );
        if (cancelToken.isCanceled) break;
      }
    }

    if (!mounted) return;
    final successResults = results.where((result) => result.success).toList();
    final failedResults = results.where((result) => !result.success).toList();
    final allSucceeded = failedResults.isEmpty && successResults.isNotEmpty;
    _lastCapCutDraftSuccess = allSucceeded;
    _lastCapCutDraftMessage = allSucceeded
        ? successResults.last.message
        : (failedResults.isEmpty
            ? 'Unknown CapCut draft error.'
            : failedResults.last.message);
    if (successResults.isNotEmpty) {
      _lastCapCutDraftFolder = successResults.first.draftFolder;
    }
    setState(() {
      _isExporting = false;
      _renderQueuePaused = false;
      _renderQueueStopRequested = false;
      _exportCancelToken = null;
      _progress = allSucceeded ? 1 : successResults.length / draftGroups.length;
      _status =
          failedResults.any((result) => result.message == 'Export canceled.')
              ? 'Export canceled'
              : 'Ready';
    });
    MediaJobManager.instance.resumeBackgroundWork();
    _updateExportProgressView(
      details: exportDetails,
      progress: allSucceeded ? 1 : successResults.length / draftGroups.length,
      elapsed: _exportProgressView.value.elapsed,
      status:
          failedResults.any((result) => result.message == 'Export canceled.')
              ? 'CapCut draft canceled'
              : allSucceeded
                  ? 'CapCut draft ready'
                  : 'CapCut draft failed',
    );
    _closeExportProgressDialog();

    if (failedResults.any((result) => result.message == 'Export canceled.')) {
      _showMessage('CapCut draft canceled.');
      return;
    }

    if (successResults.isNotEmpty) {
      if (failedResults.isEmpty) {
        _showMessage(
          multipleDrafts
              ? 'CapCut drafts ready: ${successResults.length} drafts saved with Caption SRT folders.'
              : 'CapCut draft ready: ${successResults.first.projectName ?? projectName}. Caption SRT: ${successResults.first.captionFolder ?? 'no caption cues available'}',
        );
      } else {
        _showMessage(
          'CapCut drafts complete. Success: ${successResults.length}, failed: ${failedResults.length}. Last error: ${failedResults.last.message}',
        );
      }
    } else {
      _showMessage(
        'CapCut draft failed: ${failedResults.isEmpty ? 'Unknown error' : failedResults.last.message}',
      );
    }
  }

  Future<String?> _showCapCutDraftSettingsDialog(String initialFolder) async {
    var draftFolder = initialFolder;
    var name = _nameController.text;
    var oneDraft = _exportTimelineTogether;
    var useNumberRange = _useNumberRange;
    var rangeStart = _numberStartController.text.trim().isEmpty
        ? '1'
        : _numberStartController.text.trim();
    var rangeEnd = _automaticNumberRangeEndText(
      rangeStart,
      _numberEndController.text,
    );
    final confirmed = await showDialog<bool>(
      context: context,
      barrierDismissible: !_isExporting,
      builder: (context) {
        return StatefulBuilder(
          builder: (context, setDialogState) {
            final selectedCount = useNumberRange
                ? _numberRangeVideoCount(rangeStart, rangeEnd)
                : _selectedExportVideoCount();
            return Dialog(
              backgroundColor: _panelColor,
              insetPadding:
                  const EdgeInsets.symmetric(horizontal: 24, vertical: 24),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(8),
                side: BorderSide(color: _panelBorderColor),
              ),
              child: ConstrainedBox(
                constraints: BoxConstraints(
                  maxWidth: 520,
                  maxHeight: MediaQuery.sizeOf(context).height - 48,
                ),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(18, 16, 18, 8),
                      child: Row(
                        children: [
                          const KText(
                            'Create CapCut draft',
                            style: TextStyle(
                              fontSize: 16,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                          const Spacer(),
                          KText(
                            oneDraft ? '1 draft' : '$selectedCount drafts',
                            style: const TextStyle(
                              color: Color(0xffa3a3a3),
                              fontSize: 12,
                            ),
                          ),
                        ],
                      ),
                    ),
                    Divider(height: 1, color: _panelBorderColor),
                    Flexible(
                      child: SingleChildScrollView(
                        padding: const EdgeInsets.all(18),
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            TextFormField(
                              initialValue: name,
                              decoration:
                                  _exportInputDecoration('Name').copyWith(
                                hintText: 'Blank = original video name',
                              ),
                              onChanged: (value) => name = value,
                            ),
                            const SizedBox(height: 12),
                            Row(
                              children: [
                                Expanded(
                                  child: InputDecorator(
                                    decoration:
                                        _exportInputDecoration('Export to'),
                                    child: KText(
                                      draftFolder,
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 8),
                                IconButton.filledTonal(
                                  onPressed: () async {
                                    final picked = await FilePicker.platform
                                        .getDirectoryPath(
                                      dialogTitle:
                                          'Choose where to save CapCut draft',
                                      initialDirectory: draftFolder,
                                    );
                                    if (picked == null ||
                                        picked.trim().isEmpty) {
                                      return;
                                    }
                                    setDialogState(() {
                                      draftFolder = picked;
                                    });
                                  },
                                  icon: const Icon(Icons.folder_open),
                                  tooltip: 'Choose output folder',
                                ),
                              ],
                            ),
                            const SizedBox(height: 18),
                            CheckboxListTile(
                              dense: true,
                              contentPadding: EdgeInsets.zero,
                              value: useNumberRange,
                              onChanged: (value) => setDialogState(() {
                                useNumberRange = value ?? false;
                              }),
                              title: const KText('Output numbering'),
