  void _showExportProgressDialog() {
    if (_exportProgressDialogOpen) return;
    _exportProgressDialogOpen = true;
    unawaited(
      showDialog<void>(
        context: context,
        barrierDismissible: false,
        builder: (context) => ValueListenableBuilder<KlipioExportProgressView>(
          valueListenable: _exportProgressView,
          builder: (context, view, _) => _exportProgressDialog(view),
        ),
      ).whenComplete(() => _exportProgressDialogOpen = false),
    );
  }

  Future<void> _recoverUnexpectedExportFailure(
    Object error,
    StackTrace stackTrace,
  ) async {
    final token = _exportCancelToken;
    try {
      await token?.cancelAndWait(timeout: const Duration(seconds: 5));
    } catch (_) {
      // The emergency worker sweep below is the final cleanup path.
    }
    try {
      await terminateAllKlipioWorkers().timeout(const Duration(seconds: 8));
    } catch (_) {
      // UI recovery must complete even when Windows is releasing a process.
    }
    try {
      final directory = Directory(
        '${Directory.systemTemp.path}${Platform.pathSeparator}KlipioLogs',
      );
      await directory.create(recursive: true);
      final stack = '$stackTrace';
      await File(
        '${directory.path}${Platform.pathSeparator}export-errors.log',
      ).writeAsString(
        '${DateTime.now().toIso8601String()} [export UI recovery]\r\n'
        'Error: $error\r\n'
        '${stack.length > 12000 ? stack.substring(0, 12000) : stack}\r\n\r\n',
        mode: FileMode.append,
        flush: true,
      );
    } catch (_) {
      // Logging is diagnostic only.
    }
    if (!mounted) return;
    final rawMessage = '$error'.replaceFirst('Exception: ', '').trim();
    final message = rawMessage.isEmpty
        ? 'The export pipeline stopped unexpectedly.'
        : rawMessage.length > 360
            ? '${rawMessage.substring(0, 360)}...'
            : rawMessage;
    final details = _exportProgressView.value.details ??
        _buildExportDialogDetails(_outputFolder ?? '', const []);
    setState(() {
      _isExporting = false;
      _renderQueuePaused = false;
      _renderQueueStopRequested = false;
      _exportCancelToken = null;
      _progress = 0;
      _status = 'Export failed';
    });
    MediaJobManager.instance.resumeBackgroundWork();
    _updateExportProgressView(
      details: details,
      progress: 0,
      elapsed: _exportProgressView.value.elapsed,
      status: 'Export failed: $message',
    );
    _closeExportProgressDialog();
    _showMessage('Export failed safely: $message');
  }

  void _closeExportProgressDialog() {
    if (!mounted || !_exportProgressDialogOpen) return;
    _exportProgressDialogOpen = false;
    final navigator = Navigator.of(context, rootNavigator: true);
    if (navigator.canPop()) {
      navigator.pop();
    }
  }

  Future<void> _returnToHome({bool closeDialog = false}) async {
    await _autosaveProject();
    await _sourceController?.pause();
    await _previewController?.pause();
    await _stopMusicPreview();
    if (!mounted) return;
    if (closeDialog) _closeExportProgressDialog();
    widget.onBackHome();
  }

  Future<void> _pausePlaybackForExport() async {
    MediaJobManager.instance.pauseBackgroundWork();
    try {
      await _sourceController?.pause();
    } catch (_) {
      // Export must still open if a preview controller is being replaced.
    }
    try {
      await _previewController?.pause();
    } catch (_) {
      // Export must still open if a preview controller is being replaced.
    }
    try {
      await _stopMusicPreview();
    } catch (_) {
      // A stale music preview must not block the export workflow.
    }
  }

  Future<void> _confirmCancelExport() async {
    if (!_isExporting) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        icon: const Icon(Icons.warning_amber_rounded),
        title: const KText('Stop exporting your video?'),
        content: const KText(
          'The current export will stop. Your project and source media will stay safe.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const KText('Keep exporting'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const KText('Stop export'),
          ),
        ],
      ),
    );
    if (confirmed == true) {
      final stopped = await _cancelExport();
      if (!mounted) return;
      if (stopped) _closeExportProgressDialog();
    }
  }

  Future<bool> _cancelExport() async {
    final token = _exportCancelToken;
    if (token == null) return true;
    _renderQueueStopRequested = true;
    _renderQueuePaused = false;
    if (mounted) setState(() => _status = 'Stopping encoder...');
    _updateExportProgressView(
      details: _exportProgressView.value.details ??
          _buildExportDialogDetails(_outputFolder ?? '', const []),
      progress: _progress,
      elapsed: _exportProgressView.value.elapsed,
      status: 'Stopping encoder...',
    );
    try {
      await token.cancelAndWait();
    } on TimeoutException {
      if (mounted) {
        setState(() => _status = 'Encoder stop timed out');
      }
      _updateExportProgressView(
        details: _exportProgressView.value.details ??
            _buildExportDialogDetails(_outputFolder ?? '', const []),
        progress: _progress,
        elapsed: _exportProgressView.value.elapsed,
        status: 'Still stopping encoder...',
      );
      return false;
    }
    if (!mounted) return true;
    setState(() => _status = 'Export canceled');
    MediaJobManager.instance.resumeBackgroundWork();
    _updateExportProgressView(
      details: _exportProgressView.value.details ??
          _buildExportDialogDetails(_outputFolder ?? '', const []),
      progress: _progress,
      elapsed: _exportProgressView.value.elapsed,
      status: 'Export canceled',
    );
    return true;
  }

  void _pauseRenderQueue() {
    if (!_isExporting || _exportCancelToken?.isCanceled == true) return;
    _exportCancelToken?.pause();
    setState(() {
      _renderQueuePaused = true;
      _status = 'Render queue paused...';
    });
    final view = _exportProgressView.value;
    final details = view.details;
    if (details != null) {
      _updateExportProgressView(
        details: details,
        progress: _progress,
        elapsed: view.elapsed,
        status: 'Render queue paused...',
      );
    }
  }

  void _resumeRenderQueue() {
    if (!_isExporting) return;
    _exportCancelToken?.resume();
    setState(() {
      _renderQueuePaused = false;
      _status = 'Resuming render queue...';
    });
    final view = _exportProgressView.value;
    final details = view.details;
    if (details != null) {
      _updateExportProgressView(
        details: details,
        progress: _progress,
        elapsed: view.elapsed,
        status: 'Resuming render queue...',
      );
    }
  }

  Future<bool> _waitForRenderQueueResume({
    required KlipioExportDialogDetails details,
    required DateTime exportStartedAt,
  }) async {
    while (mounted &&
        _renderQueuePaused &&
        !_renderQueueStopRequested &&
        _exportCancelToken?.isCanceled != true) {
      _updateExportProgressView(
        details: details,
        progress: _progress,
        elapsed: DateTime.now().difference(exportStartedAt),
        status: 'Render queue paused...',
      );
      await Future<void>.delayed(const Duration(milliseconds: 250));
    }
    return mounted &&
        !_renderQueueStopRequested &&
        _exportCancelToken?.isCanceled != true;
  }

  void _runEditorShortcut(_EditorShortcut shortcut) {
    switch (shortcut) {
      case _EditorShortcut.export:
        if (!_isExporting) unawaited(_showExportHub());
      case _EditorShortcut.saveProject:
        unawaited(_saveProjectAs());
      case _EditorShortcut.openProject:
        unawaited(_openProjectDialog());
      case _EditorShortcut.split:
        _splitClipAtPlayhead();
      case _EditorShortcut.cutStart:
        _cutClipStartAtPlayhead();
      case _EditorShortcut.cutEnd:
        _cutClipEndAtPlayhead();
      case _EditorShortcut.undo:
        _undoEditor();
      case _EditorShortcut.redo:
        _redoEditor();
      case _EditorShortcut.playPause:
        unawaited(_togglePreview());
      case _EditorShortcut.deletePart:
        _deleteClipPartAtPlayhead();
      case _EditorShortcut.copy:
        _copySelectedTimelineClip();
      case _EditorShortcut.cut:
        _cutSelectedTimelineClip();
      case _EditorShortcut.paste:
        _pasteTimelineClip();
      case _EditorShortcut.duplicate:
        _duplicateSelectedTimelineClip();
    }
  }

