  KlipioExportDialogDetails _buildExportDialogDetails(
      String folder, List<_QueuedExport> jobs,
      {bool? exportTimelineTogether,
      String? titleOverride,
      String? nameOverride}) {
    final timelineTogether = exportTimelineTogether ?? _exportTimelineTogether;
    final outputCount = timelineTogether ? 1 : _groupQueuedExports(jobs).length;
    final duration = jobs.fold<double>(
      0,
      (sum, job) => sum + _queuedExportDuration(job),
    );
    final selectedVideo = _videos.isEmpty
        ? null
        : _videos[_selectedVideoIndex.clamp(0, _videos.length - 1)];
    final typed = _safeName(_nameController.text);
    final name = nameOverride ??
        (timelineTogether
            ? '${typed.isEmpty ? 'timeline_export' : typed}.mp4'
            : outputCount == 1
                ? '${_exportBaseName(jobs.first.video)}.mp4'
                : '$outputCount videos');
    return KlipioExportDialogDetails(
      title: titleOverride ??
          (timelineTogether ? 'Export timeline' : 'Export videos'),
      name: name,
      outputFolder: folder,
      durationSeconds: duration,
      estimatedSize: _estimatedExportSizeLabel(
        duration,
        _exportBitrateKbps,
        outputCount,
      ),
      thumbnailPath: selectedVideo?.thumbnailPath,
    );
  }

  double _queuedExportDuration(_QueuedExport job) {
    final start = job.settings.trimStartSeconds;
    final end = job.settings.trimEndSeconds;
    final duration = end > start
        ? end - start
        : (job.video.durationSeconds ?? 0).clamp(0.0, double.infinity);
    return duration / job.settings.speed.clamp(_minVideoSpeed, _maxVideoSpeed);
  }

  double _queuedExportGroupDuration(_QueuedExportGroup group) {
    return group.parts.fold<double>(
      0,
      (sum, part) => sum + _queuedExportDuration(part),
    );
  }

  TimelineModel _retimeTimelineForExport(
    TimelineModel timeline,
    double requestedSpeed,
  ) {
    final speed = requestedSpeed.clamp(_minVideoSpeed, _maxVideoSpeed);
    if ((speed - 1).abs() < 0.0001) return timeline;
    final tracks = [
      for (final track in timeline.tracks)
        track.copyWith(
          clips: [
            for (final clip in track.clips)
              clip.copyWith(
                timelineStart: clip.timelineStart / speed,
                duration: clip.duration / speed,
                transitionIn: clip.transitionIn == null
                    ? null
                    : ClipTransition(
                        type: clip.transitionIn!.type,
                        duration: clip.transitionIn!.duration / speed,
                      ),
                keyframes: [
                  for (final keyframe in clip.keyframes)
                    ClipKeyframe(
                      offset: keyframe.offset / speed,
                      transform: keyframe.transform,
                    ),
                ],
              ),
          ],
        ),
    ];
    return TimelineModel(
      tracks: tracks,
      duration: timeline.duration / speed,
    ).normalized();
  }

  Map<String, double> _videoPlaybackSpeedsForExport(
    TimelineModel sourceTimeline,
    double requestedSpeed,
  ) {
    final speed = requestedSpeed.clamp(_minVideoSpeed, _maxVideoSpeed);
    return {
      for (final track in sourceTimeline.videoTracks)
        for (final clip in track.clips) clip.mediaPath: speed,
    };
  }

  List<CaptionCueSettings> _retimeCaptionCuesForExport(
    List<CaptionCueSettings> cues,
    double requestedSpeed,
  ) {
    final speed = requestedSpeed.clamp(_minVideoSpeed, _maxVideoSpeed);
    if ((speed - 1).abs() < 0.0001) return cues;
    return [
      for (final cue in cues)
        CaptionCueSettings(
          start: cue.start / speed,
          end: cue.end / speed,
          text: cue.text,
          x: cue.x,
          y: cue.y,
          words: [
            for (final word in cue.words)
              CaptionWordSettings(
                start: word.start / speed,
                end: word.end / speed,
                text: word.text,
              ),
          ],
        ),
    ];
  }

  List<TextOverlaySettings> _retimeTextOverlaysForExport(
    List<TextOverlaySettings> overlays,
    double requestedSpeed,
  ) {
    final speed = requestedSpeed.clamp(_minVideoSpeed, _maxVideoSpeed);
    if ((speed - 1).abs() < 0.0001) return overlays;
    return [
      for (final overlay in overlays)
        TextOverlaySettings(
          text: overlay.text,
          x: overlay.x,
          y: overlay.y,
          size: overlay.size,
          font: overlay.font,
          color: overlay.color,
          opacity: overlay.opacity,
          stroke: overlay.stroke,
          strokeColor: overlay.strokeColor,
          strokeOpacity: overlay.strokeOpacity,
          shadow: overlay.shadow,
          shadowColor: overlay.shadowColor,
          shadowOpacity: overlay.shadowOpacity,
          animation: overlay.animation,
          animationDuration: overlay.animationDuration,
          startX: overlay.startX,
          startY: overlay.startY,
          timelineStart: overlay.timelineStart / speed,
          timelineEnd:
              overlay.timelineEnd <= 0 ? 0 : overlay.timelineEnd / speed,
          visible: overlay.visible,
          tracking: overlay.tracking,
          curve: overlay.curve,
        ),
    ];
  }

  Future<ExportResult> _exportQueuedVideoComposition(
    _QueuedExportGroup group, {
    required ExportCancelToken cancelToken,
    required void Function(double progress, String status) onProgress,
  }) async {
    final timeline = group.video.path == _selectedCompositionPath
        ? _multiTrackTimeline
        : _timelinesByComposition[group.video.path];
    final hasVideo = timeline != null &&
        timeline.videoTracks.any(
          (track) =>
              !track.isMuted &&
              track.clips.any(
                (clip) => !clip.isMuted && clip.duration > 0.001,
              ),
        );
    if (timeline != null && hasVideo) {
      final dimensions = _multiTrackOutputDimensions();
      final playbackSpeed = _clipTimelineEditFor(group.video.path)
          .speed
          .clamp(_minVideoSpeed, _maxVideoSpeed)
          .toDouble();
      final sourceTimelineDuration = _actualMultiTrackExportDuration(timeline);
      final sourceTimeline = timeline.copyWith(
        duration: sourceTimelineDuration,
      );
      final exportTimeline = _retimeTimelineForExport(
        sourceTimeline,
        playbackSpeed,
      );
      final timelineDuration = _actualMultiTrackExportDuration(exportTimeline);
      final captionCues = _retimeCaptionCuesForExport(
        _exportTimelineCaptionCues(sourceTimeline),
        playbackSpeed,
      );
      final captionSettings = captionCues.isEmpty
          ? null
          : _settings.copyWith(
              automaticCaptions: false,
              speed: 1,
              trimStartSeconds: 0,
              trimEndSeconds: timelineDuration,
              textOverlays: const [],
              captionCues: captionCues,
            );
      return exportMultiTrackTimeline(
        MultiTrackExportJob(
          timeline: exportTimeline.copyWith(duration: timelineDuration),
          outputPath: group.outputPath,
          width: dimensions.width,
          height: dimensions.height,
          frameRate:
              _exportFrameRate > 0 ? _exportFrameRate : _projectFrameRate,
          videoBitrateKbps: _exportBitrateKbps,
          exportCodec: _exportCodec,
          hardwareEncoding: widget.settings.hardwareEncoding,
          hardwareDecoding: widget.settings.hardwareDecoding,
          playbackSpeedsByMediaPath: _videoPlaybackSpeedsForExport(
            sourceTimeline,
            playbackSpeed,
          ),
          textOverlays: _retimeTextOverlaysForExport(
            _exportManualTextOverlays(),
            playbackSpeed,
          ),
          captionSettings: captionSettings,
          cancelToken: cancelToken,
          onProgress: onProgress,
        ),
      );
    }

    if (group.parts.length == 1) {
      return exportVideo(
        ExportJob(
          inputPath: group.video.path,
          outputPath: group.outputPath,
          settings: group.parts.first.settings,
          cancelToken: cancelToken,
          onProgress: onProgress,
        ),
      );
    }
    return exportVideoSequence(
      SequenceExportJob(
        jobs: [
          for (final part in group.parts)
            ExportJob(
              inputPath: group.video.path,
              outputPath: part.outputPath,
              settings: part.settings,
              cancelToken: cancelToken,
            ),
        ],
        outputPath: group.outputPath,
        settings: group.parts.first.settings,
        cancelToken: cancelToken,
        onProgress: onProgress,
      ),
    );
  }

  double _actualMultiTrackExportDuration([TimelineModel? requestedTimeline]) {
    final timeline = requestedTimeline ?? _multiTrackTimeline;
    var videoEnd = 0.0;
    for (final track in timeline.videoTracks) {
      if (track.isMuted) continue;
      for (final clip in track.clips) {
        if (clip.isMuted) continue;
        videoEnd = math.max(videoEnd, clip.timelineEnd);
      }
    }
    if (videoEnd > 0.001) return videoEnd;

    var fallbackEnd = 0.0;
    for (final track in timeline.tracks) {
      if (track.isMuted || track.type == TrackType.video) continue;
      for (final clip in track.clips) {
        if (!clip.isMuted) {
          fallbackEnd = math.max(fallbackEnd, clip.timelineEnd);
        }
      }
    }
    if (fallbackEnd > 0.001) return fallbackEnd;
    return requestedTimeline == null
        ? math.max(timeline.duration, _timelineSequenceDuration())
        : timeline.duration;
  }

  int _bitrateForQuality(String quality) {
    return switch (quality) {
      '4K' => 35000,
      '1080p' => 8000,
      '720p' => 5000,
      '480p' => 2500,
      'Low' => 1200,
      'Custom' => _customBitrateKbps.round(),
      _ => 8000,
    };
  }

  String _estimatedExportSizeLabel(
    double durationSeconds,
    int bitrateKbps,
    int fileCount,
  ) {
    if (durationSeconds <= 0) return 'Calculating...';
    const audioKbps = 192;
    final bytes = durationSeconds * (bitrateKbps + audioKbps) * 1000 / 8;
    final suffix = fileCount > 1 ? ' total estimated' : ' estimated';
    if (bytes >= 1024 * 1024 * 1024) {
      return '${(bytes / (1024 * 1024 * 1024)).toStringAsFixed(2)} GB$suffix';
    }
    return '${(bytes / (1024 * 1024)).round()} MB$suffix';
  }

  String _formatClock(Duration duration) {
    final hours = duration.inHours;
    final minutes = duration.inMinutes.remainder(60);
    final seconds = duration.inSeconds.remainder(60);
    if (hours > 0) {
      return '$hours:${minutes.toString().padLeft(2, '0')}:${seconds.toString().padLeft(2, '0')}';
    }
    return '${minutes.toString().padLeft(2, '0')}:${seconds.toString().padLeft(2, '0')}';
  }

  String _formatTimecode(double seconds) {
    final safe = seconds.isFinite ? math.max(0.0, seconds) : 0.0;
    final wholeSeconds = safe.floor();
    final frameRate = _projectFrameRate.clamp(1.0, 120.0);
    final frames = ((safe - wholeSeconds) * frameRate).floor();
    final hours = wholeSeconds ~/ 3600;
    final minutes = (wholeSeconds ~/ 60) % 60;
    final secs = wholeSeconds % 60;
    return '${hours.toString().padLeft(2, '0')}:'
        '${minutes.toString().padLeft(2, '0')}:'
        '${secs.toString().padLeft(2, '0')}:'
        '${frames.toString().padLeft(2, '0')}';
  }

  CaptionStyle get _resolvedCaptionStyle {
    final preset = _captionPreset(_captionStyle);
    final background = _captionBackgroundEnabled
        ? _captionBackgroundColor
        : preset.backgroundColor;
    final backgroundOpacity = _captionBackgroundEnabled
        ? _captionBackgroundOpacity
        : background.opacity;
    return CaptionStyle(
      id: preset.id,
      name: preset.name,
      fontFamily: _safeCaptionFont(_captionFont),
      fontSize: _captionAssFontSize(_captionFontSize),
      color: _captionColor,
      highlightColor: preset.accentColor,
      backgroundColor: background.withOpacity(1),
      strokeColor: _captionStrokeColor,
      strokeWidth: _captionStrokeEnabled ? _captionStrokeWidth : 0,
      bold: _captionBold,
      italic: _captionItalic,
      underline: _captionUnderline,
      opacity: _captionOpacity,
      shadowColor: _captionShadowColor,
      shadowBlur: _captionShadowEnabled ? _captionShadowStrength : 0,
      shadowOffsetX: _captionShadowEnabled ? _captionShadowStrength * 0.7 : 0,
      shadowOffsetY: _captionShadowEnabled ? _captionShadowStrength * 0.9 : 0,
      backgroundOpacity: backgroundOpacity,
      borderRadius: 8,
      padding: _captionBackgroundEnabled
          ? _captionBackgroundPadding
          : backgroundOpacity > 0
              ? 12
              : 0,
      alignment: TextAlign.center,
      position: const Offset(0.5, 0.78),
      letterSpacing: _captionCharacterSpacing,
      wordSpacing: _captionWordSpacing,
      lineSpacing: _captionLineSpacing,
      animation: preset.motion,
      wordsPerLine: _captionWordsPerLine,
    );
  }

  VideoEditSettings get _settings {
    _saveSelectedTextOverlay();
    final caption = _resolvedCaptionStyle;
    return VideoEditSettings(
      speed: _speed,
      flip: _flip,
      scaleX: _scaleX,
      scaleY: _scaleY,
      zoom: _zoom,
      watermarkPath: _watermarkPath,
      watermarkPosition: 'custom',
      watermarkSize: _watermarkSize,
      musicPath: _musicPath,
      originalVolume: _originalAudioMuted ? 0 : _originalVolume,
      musicVolume: _musicTrackMuted ? 0 : _musicVolume,
      outputRatio: _outputRatio,
      canvasMode: _canvasMode,
      canvasColor: _colorToHex(_canvasColor),
      canvasPattern: _canvasPattern,
      canvasBlur: _canvasBlur,
      panX: _panX,
      panY: _panY,
      overlayText: _overlayTextController.text,
      overlayTextX: _overlayTextX,
      overlayTextY: _overlayTextY,
      overlayTextSize: _overlayTextSize,
      overlayFont: _overlayFont,
      overlayTextColor: _colorToHex(_overlayTextColor),
      overlayTextOpacity: _overlayTextOpacity,
      overlayTextStroke: _overlayTextStroke,
      overlayTextStrokeColor: _colorToHex(_overlayTextStrokeColor),
      overlayTextStrokeOpacity: _overlayTextStrokeOpacity,
      overlayTextShadow: true,
      overlayTextShadowColor: _colorToHex(_overlayTextShadowColor),
