  VideoEditSettings _settingsForClip(_ClipTimelineEdit edit) {
    return _settings.copyWith(
      speed: edit.speed,
      flip: edit.flip,
      scaleX: edit.scaleX,
      scaleY: edit.scaleY,
      zoom: edit.zoom,
      panX: edit.panX,
      panY: edit.panY,
      originalVolume: edit.originalVolume,
    );
  }

  List<CaptionCueSettings> _captionSettingsForVideo(String path) => [
        if (!_captionTrackHidden)
          for (final cue in _captionCuesByVideo[path] ?? const <_CaptionCue>[])
            CaptionCueSettings(
              start: cue.start,
              end: cue.end,
              text: cue.text,
              x: cue.x,
              y: cue.y,
              words: [
                for (final word in cue.words)
                  CaptionWordSettings(
                    start: word.start,
                    end: word.end,
                    text: word.text,
                  ),
              ],
            ),
      ];

  int get _exportBitrateKbps {
    return switch (_qualityPreset) {
      '4K' => 35000,
      '1080p' => 8000,
      '720p' => 5000,
      '480p' => 2500,
      'Low' => 1200,
      'Custom' => _customBitrateKbps.round(),
      _ => 8000,
    };
  }

  String _safeExportCodec(String value) {
    final normalized = value.trim().toLowerCase();
    return switch (normalized) {
      'hevc' || 'h265' || 'h.265' => 'hevc',
      _ => 'h264',
    };
  }

  double _safeExportFrameRate(double value) {
    if (value <= 0) return 0;
    const supported = [23.976, 24.0, 25.0, 29.97, 30.0, 50.0, 59.94, 60.0];
    return supported.reduce(
      (a, b) => (value - a).abs() <= (value - b).abs() ? a : b,
    );
  }

  bool get _exportsSeparatePartFiles => _exportSplitPartsAsFiles;

  double get _batchSplitSeconds {
    return _parseDurationSeconds(
      _batchSplitMinutesController.text,
      plainNumberSeconds: 60,
    );
  }

  double _parseDurationSeconds(
    String input, {
    double plainNumberSeconds = 1,
  }) {
    final raw = input.trim().toLowerCase();
    if (raw.isEmpty) return 0;

    if (raw.contains(':')) {
      final parts = raw.split(':');
      if (parts.length < 2 || parts.length > 3) return 0;
      final values = parts.map((part) => double.tryParse(part.trim())).toList();
      if (values.any((value) => value == null || value < 0)) return 0;
      if (values.length == 2) {
        return values[0]! * 60 + values[1]!;
      }
      return values[0]! * 3600 + values[1]! * 60 + values[2]!;
    }

    final unitPattern = RegExp(
      r'(\d+(?:\.\d+)?)\s*(hours?|hrs?|h|minutes?|mins?|m|seconds?|secs?|s)\b',
    );
    final matches = unitPattern.allMatches(raw).toList();
    if (matches.isNotEmpty) {
      var seconds = 0.0;
      for (final match in matches) {
        final value = double.tryParse(match.group(1) ?? '');
        if (value == null || value < 0) return 0;
        final unit = match.group(2) ?? '';
        if (unit.startsWith('h')) {
          seconds += value * 3600;
        } else if (unit.startsWith('m')) {
          seconds += value * 60;
        } else {
          seconds += value;
        }
      }
      return seconds;
    }

    final plain = double.tryParse(raw);
    if (plain == null || plain <= 0) return 0;
    return plain * plainNumberSeconds;
  }

  List<_QueuedExport> _buildExportJobs(
    String folder, {
    bool applyNumberRange = true,
  }) {
    _saveSelectedClipTimelineEdit();
    if (!_batchSplitLongVideos) {
      final timelineJobs = _buildTimelineClipExportJobs(
        folder,
        applyNumberRange: applyNumberRange,
      );
      if (timelineJobs.isNotEmpty) return timelineJobs;
    }
    final jobs = <_QueuedExport>[];
    final range = _selectedExportRange();
    for (var videoIndex = 0; videoIndex < _videos.length; videoIndex++) {
      if (applyNumberRange &&
          _useNumberRange &&
          (videoIndex < range.startIndex || videoIndex > range.endIndex)) {
        continue;
      }
      final video = _videos[videoIndex];
      final clipEdit = _clipTimelineEditFor(video.path);
      final batchSplitSeconds = _batchSplitSeconds;
      final applyBatchSplit = _batchSplitLongVideos &&
          batchSplitSeconds > 0 &&
          (!_batchSplitSelectedVideoOnly || videoIndex == _selectedVideoIndex);
      final effectiveEdit = applyBatchSplit
          ? clipEdit.copyWith(splitEverySeconds: batchSplitSeconds)
          : clipEdit;
      final clipSettings = _settingsForClip(effectiveEdit).copyWith(
        captionCues: _captionSettingsForVideo(video.path),
      );
      final parts = effectiveEdit.timelineParts(video.durationSeconds);
      final separatePartFiles = _exportsSeparatePartFiles;
      final splitSectionCount = applyBatchSplit
          ? math.max(
              1,
              ((video.durationSeconds ?? 0) / batchSplitSeconds).ceil(),
            )
          : parts.length;
      for (var partIndex = 0; partIndex < parts.length; partIndex++) {
        final part = parts[partIndex];
        final exportPartIndex = separatePartFiles && parts.length > 1
            ? applyBatchSplit
                ? math.max(1, (part.start / batchSplitSeconds).floor() + 1)
                : partIndex + 1
            : null;
        jobs.add(
          _QueuedExport(
            video: video,
            outputPath: _outputPath(
              folder,
              videoIndex,
              video,
              segmentIndex: exportPartIndex,
              segmentCount: splitSectionCount,
            ),
            settings: clipSettings.copyWith(
              trimStartSeconds: part.start,
              trimEndSeconds: part.end,
            ),
            partIndex: exportPartIndex,
            partCount: exportPartIndex == null ? null : splitSectionCount,
          ),
        );
      }
    }
    return jobs;
  }

  List<_QueuedExport> _buildTimelineClipExportJobs(
    String folder, {
    required bool applyNumberRange,
  }) {
    _storeActiveCompositionTimeline();
    final clips = <({int videoIndex, ClipModel clip})>[];
    final range = _selectedExportRange();
    for (var videoIndex = 0; videoIndex < _videos.length; videoIndex++) {
      if (applyNumberRange &&
          _useNumberRange &&
          (videoIndex < range.startIndex || videoIndex > range.endIndex)) {
        continue;
      }
      final video = _videos[videoIndex];
      final timeline = _selectedCompositionPath == video.path
          ? _multiTrackTimeline
          : _timelinesByComposition[video.path];
      if (timeline == null) continue;
      for (final track in timeline.videoTracks) {
        if (track.isMuted) continue;
        for (final clip in track.clips) {
          if (clip.isMuted ||
              clip.duration <= 0.001 ||
              clip.mediaPath != video.path) {
            continue;
          }
          clips.add((videoIndex: videoIndex, clip: clip));
        }
      }
    }
    clips.sort((a, b) {
      final video = a.videoIndex.compareTo(b.videoIndex);
      if (video != 0) return video;
      final start = a.clip.timelineStart.compareTo(b.clip.timelineStart);
      if (start != 0) return start;
      final track = a.clip.zIndex.compareTo(b.clip.zIndex);
      if (track != 0) return track;
      return a.videoIndex.compareTo(b.videoIndex);
    });
    if (clips.isEmpty) return const [];

    final perVideoClipCounts = <String, int>{};
    for (final item in clips) {
      perVideoClipCounts[item.clip.mediaPath] =
          (perVideoClipCounts[item.clip.mediaPath] ?? 0) + 1;
    }
    final perVideoSeen = <String, int>{};
    return [
      for (final item in clips)
        _timelineClipExportJob(
          folder: folder,
          videoIndex: item.videoIndex,
          clip: item.clip,
          occurrence: perVideoSeen[item.clip.mediaPath] =
              (perVideoSeen[item.clip.mediaPath] ?? 0) + 1,
          occurrenceCount: perVideoClipCounts[item.clip.mediaPath] ?? 1,
        ),
    ];
  }

  _QueuedExport _timelineClipExportJob({
    required String folder,
    required int videoIndex,
    required ClipModel clip,
    required int occurrence,
    required int occurrenceCount,
  }) {
    final video = _videos[videoIndex];
    final edit = _clipTimelineEditFor(video.path);
    final transform = clip.transform;
    final segmentIndex = _exportsSeparatePartFiles ? occurrence : null;
    final clipSettings = _settingsForClip(edit).copyWith(
      trimStartSeconds: clip.sourceStart,
      trimEndSeconds: clip.sourceEnd,
      scaleX: transform.scaleX,
      scaleY: transform.scaleY,
      zoom: 1,
      panX: ((transform.positionX - 0.5) * 2).clamp(-1.0, 1.0).toDouble(),
      panY: ((transform.positionY - 0.5) * 2).clamp(-1.0, 1.0).toDouble(),
      canvasMode: transform.canvasMode,
      canvasColor: transform.canvasColor,
      canvasPattern: transform.canvasPattern,
      canvasBlur: transform.canvasBlur,
      captionCues: _captionSettingsForVideo(video.path),
    );
    return _QueuedExport(
      video: video,
      outputPath: _outputPath(
        folder,
        videoIndex,
        video,
        segmentIndex: segmentIndex,
        segmentCount: segmentIndex == null ? null : occurrenceCount,
      ),
      settings: clipSettings,
      partIndex: segmentIndex,
      partCount: segmentIndex == null ? null : occurrenceCount,
    );
  }

  List<_QueuedExportGroup> _groupQueuedExports(List<_QueuedExport> jobs) {
    final groups = <_QueuedExportGroup>[];
    for (final job in jobs) {
      final existingIndex = groups.indexWhere(
        (group) =>
            group.video.path == job.video.path &&
            group.outputPath == job.outputPath,
      );
      if (existingIndex >= 0) {
        final existing = groups[existingIndex];
        groups[existingIndex] = _QueuedExportGroup(
          video: existing.video,
          outputPath: existing.outputPath,
          parts: [...existing.parts, job],
        );
      } else {
        groups.add(
          _QueuedExportGroup(
            video: job.video,
            outputPath: job.outputPath,
            parts: [job],
          ),
        );
      }
    }
    return groups;
  }

  List<_QueuedExport> _capCutJobs(
    List<_QueuedExport> jobs, {
    required String rootFolder,
    required bool oneFolder,
    required bool renderEdits,
  }) {
    final clipCounters = <String, int>{};
    return [
      for (var index = 0; index < jobs.length; index++)
        _QueuedExport(
          video: jobs[index].video,
          outputPath: _capCutClipOutputPath(
            jobs[index],
            rootFolder,
            index,
            (clipCounters[jobs[index].video.path] =
                (clipCounters[jobs[index].video.path] ?? 0) + 1),
            oneFolder: oneFolder,
          ),
          settings: renderEdits
              ? jobs[index].settings
              : _capCutFastSettings(jobs[index].settings),
          partIndex: jobs[index].partIndex,
          partCount: jobs[index].partCount,
        ),
    ];
  }

  String _capCutClipOutputPath(
      _QueuedExport job, String rootFolder, int globalIndex, int clipIndex,
      {required bool oneFolder}) {
    final folder = oneFolder ? rootFolder : _capCutVideoFolder(job, rootFolder);
    final outputBase =
        _safeName(_withoutExtension(platform.basename(job.outputPath)));
    final base = outputBase.isNotEmpty
        ? outputBase
        : _safeName(
            job.video.name.replaceFirst(RegExp(r'\.[^.]+$'), ''),
          );
    final name = base.isEmpty ? 'video' : base;
    return '$folder${Platform.pathSeparator}$name.mp4';
  }

  String _capCutVideoFolder(_QueuedExport job, String rootFolder) {
    final videoIndex =
        _videos.indexWhere((video) => video.path == job.video.path);
    final order =
        (videoIndex < 0 ? 1 : videoIndex + 1).toString().padLeft(3, '0');
    final base = _safeName(
      job.video.name.replaceFirst(RegExp(r'\.[^.]+$'), ''),
    );
    final name = base.isEmpty ? 'video' : base;
    return '$rootFolder${Platform.pathSeparator}${order}_$name';
  }

  VideoEditSettings _capCutFastSettings(VideoEditSettings source) {
    return VideoEditSettings(
      speed: 1,
      flip: 'none',
      scaleX: 1,
      scaleY: 1,
      zoom: 1,
      watermarkPath: null,
      watermarkPosition: 'custom',
      watermarkSize: _watermarkSize,
      musicPath: null,
      originalVolume: 1,
      musicVolume: 0,
      outputRatio: 'original',
      panX: 0,
      panY: 0,
      overlayText: '',
      textOverlays: const [],
      brightness: 0,
      contrast: 1,
      saturation: 1,
      gamma: 1,
      trimStartSeconds: source.trimStartSeconds,
      trimEndSeconds: source.trimEndSeconds,
      videoBitrateKbps: source.videoBitrateKbps,
      exportCodec: source.exportCodec,
      exportFrameRate: source.exportFrameRate,
      hardwareEncoding: source.hardwareEncoding,
      hardwareDecoding: source.hardwareDecoding,
    );
  }

  void _syncCutFields() {
    final start = _parseDurationSeconds(_trimStartController.text);
    final end = _parseDurationSeconds(_trimEndController.text);
    _trimStartSeconds = start < 0 ? 0 : start;
    _trimEndSeconds = end < 0 ? 0 : end;
    _saveSelectedClipTimelineEdit();
  }

  _ClipTimelineEdit _clipTimelineEditFor(String path) {
    return _rawClipTimelineEditFor(path);
  }

  _ClipTimelineEdit _rawClipTimelineEditFor(String path) {
    return _clipTimelineEdits[path] ?? const _ClipTimelineEdit();
  }

  bool _sameTransform(_ClipTimelineEdit a, _ClipTimelineEdit b) {
    return (a.speed - b.speed).abs() < 0.001 &&
        a.flip == b.flip &&
        (a.scaleX - b.scaleX).abs() < 0.001 &&
        (a.scaleY - b.scaleY).abs() < 0.001 &&
        (a.zoom - b.zoom).abs() < 0.001 &&
        (a.panX - b.panX).abs() < 0.001 &&
        (a.panY - b.panY).abs() < 0.001;
  }

  _EditorHistorySnapshot _captureEditorHistory() {
    _saveSelectedTextOverlay();
    _saveSelectedClipTimelineEdit();
    return _EditorHistorySnapshot(
      timeline: _multiTrackTimeline,
      timelinesByComposition: Map.of(_timelinesByComposition),
      projectMediaPathsByComposition: {
        for (final entry in _projectMediaPathsByComposition.entries)
          entry.key: List.of(entry.value),
      },
      textOverlays: List.of(_textOverlays),
      clipTimelineEdits: Map.of(_clipTimelineEdits),
      captionCuesByVideo: {
        for (final entry in _captionCuesByVideo.entries)
          entry.key: List.of(entry.value),
      },
      clipTransformOverrides: Set.of(_clipTransformOverrides),
      timelineMarkers: List.of(_timelineMarkers),
      selectedCompositionPath: _selectedCompositionPath,
      selectedTimelineClipId: _selectedTimelineClipId,
      programTimelineClipId: _programTimelineClipId,
      editorSelection: _editorSelection,
      selectedTextOverlayIndex: _selectedTextOverlayIndex,
      selectedCaptionCueIndex: _selectedCaptionCueIndex,
      selectedVideoIndex: _selectedVideoIndex,
      brightness: _brightness,
      contrast: _contrast,
      saturation: _saturation,
      gamma: _gamma,
      originalVolume: _originalVolume,
      musicVolume: _musicVolume,
      watermarkX: _watermarkX,
      watermarkY: _watermarkY,
      watermarkSize: _watermarkSize,
      watermarkPath: _watermarkPath,
      musicPath: _musicPath,
      outputRatio: _outputRatio,
      projectColorSpace: _projectColorSpace,
      projectResolution: _projectResolution,
      projectProxyResolution: _projectProxyResolution,
      projectProxyEnabled: _projectProxyEnabled,
      projectCopyMedia: _projectCopyMedia,
      projectArrangeLayers: _projectArrangeLayers,
      projectFrameRate: _projectFrameRate,
      automaticCaptions: _automaticCaptions,
    );
  }

  void _recordEditorHistory(String key) {
    if (_restoringEditorHistory) return;
    final now = DateTime.now();
    final coalesced = _lastEditorHistoryKey == key &&
        _lastEditorHistoryAt != null &&
        now.difference(_lastEditorHistoryAt!) <
            const Duration(milliseconds: 650);
    if (coalesced) {
      _lastEditorHistoryAt = now;
      return;
    }
    _editorUndoHistory.add(_captureEditorHistory());
    if (_editorUndoHistory.length > 80) _editorUndoHistory.removeAt(0);
    _editorRedoHistory.clear();
    _lastEditorHistoryKey = key;
    _lastEditorHistoryAt = now;
  }

  bool get _canUndoEditor => _editorUndoHistory.isNotEmpty;
  bool get _canRedoEditor => _editorRedoHistory.isNotEmpty;

  void _undoEditor() {
    if (_editorUndoHistory.isEmpty) return;
    final snapshot = _editorUndoHistory.removeLast();
    _editorRedoHistory.add(_captureEditorHistory());
    _restoreEditorHistory(snapshot, 'Undo');
  }

  void _redoEditor() {
    if (_editorRedoHistory.isEmpty) return;
    final snapshot = _editorRedoHistory.removeLast();
    _editorUndoHistory.add(_captureEditorHistory());
    _restoreEditorHistory(snapshot, 'Redo');
  }

  void _restoreEditorHistory(_EditorHistorySnapshot snapshot, String action) {
    _restoringEditorHistory = true;
    setState(() {
      _multiTrackTimeline = snapshot.timeline;
      _timelinesByComposition
        ..clear()
        ..addAll(snapshot.timelinesByComposition);
      _projectMediaPathsByComposition
        ..clear()
        ..addAll({
          for (final entry in snapshot.projectMediaPathsByComposition.entries)
            entry.key: List.of(entry.value),
        });
      _textOverlays
        ..clear()
        ..addAll(snapshot.textOverlays);
      if (_textOverlays.isEmpty) {
        _textOverlays.add(const _TextOverlayDraft());
      }
      _clipTimelineEdits
        ..clear()
        ..addAll(snapshot.clipTimelineEdits);
      _captionCuesByVideo
        ..clear()
        ..addAll({
          for (final entry in snapshot.captionCuesByVideo.entries)
            entry.key: List.of(entry.value),
        });
      _clipTransformOverrides
        ..clear()
        ..addAll(snapshot.clipTransformOverrides);
      _timelineMarkers
        ..clear()
        ..addAll(snapshot.timelineMarkers);
      _selectedCompositionPath = snapshot.selectedCompositionPath;
      _selectedTimelineClipId = snapshot.selectedTimelineClipId;
      _programTimelineClipId = snapshot.programTimelineClipId;
      _editorSelection = snapshot.editorSelection;
      _selectedTextOverlayIndex =
          snapshot.selectedTextOverlayIndex.clamp(0, _textOverlays.length - 1);
      _selectedCaptionCueIndex = snapshot.selectedCaptionCueIndex;
      _selectedVideoIndex = _videos.isEmpty
          ? 0
          : snapshot.selectedVideoIndex.clamp(0, _videos.length - 1);
      _brightness = snapshot.brightness;
      _contrast = snapshot.contrast;
      _saturation = snapshot.saturation;
      _gamma = snapshot.gamma;
      _originalVolume = snapshot.originalVolume;
      _musicVolume = snapshot.musicVolume;
      _watermarkX = snapshot.watermarkX;
      _watermarkY = snapshot.watermarkY;
      _watermarkSize = snapshot.watermarkSize;
      _watermarkPath = snapshot.watermarkPath;
      _musicPath = snapshot.musicPath;
      _outputRatio = snapshot.outputRatio;
      _projectColorSpace = snapshot.projectColorSpace;
      _projectResolution = snapshot.projectResolution;
      _projectProxyResolution = snapshot.projectProxyResolution;
      _projectProxyEnabled = snapshot.projectProxyEnabled;
      _projectCopyMedia = snapshot.projectCopyMedia;
      _projectArrangeLayers = snapshot.projectArrangeLayers;
      _projectFrameRate = snapshot.projectFrameRate;
      _automaticCaptions = snapshot.automaticCaptions;
      _loadTextOverlay(_textOverlays[_selectedTextOverlayIndex]);
      if (_videos.isNotEmpty) _loadClipTimelineEdit(_selectedVideoIndex);
      final selectedClip = _selectedTimelineClipId == null
          ? null
          : _multiTrackTimeline.clipById(_selectedTimelineClipId!);
      if (selectedClip?.track.type == TrackType.video) {
        _loadTimelineClipTransformIntoInspector(selectedClip!.clip);
      }
      _status = '$action complete';
    });
    _restoringEditorHistory = false;
    _lastEditorHistoryKey = null;
    _lastEditorHistoryAt = null;
    unawaited(_autosaveProject());
  }

  void _saveSelectedClipTimelineEdit() {
    if (_videos.isEmpty ||
        _selectedVideoIndex < 0 ||
        _selectedVideoIndex >= _videos.length) {
      return;
    }
    final path = _videos[_selectedVideoIndex].path;
    final previous = _clipTimelineEditFor(path);
    final start = _parseDurationSeconds(_trimStartController.text);
    final end = _parseDurationSeconds(_trimEndController.text);
    final split = _parseDurationSeconds(_splitEveryController.text);
    final edit = _ClipTimelineEdit(
      trimStartSeconds: start < 0 ? 0 : start,
      trimEndSeconds: end < 0 ? 0 : end,
      splitEverySeconds: split < 0 ? 0 : split,
      speed: _speed,
      flip: _flip,
      scaleX: _scaleX,
      scaleY: _scaleY,
      zoom: _zoom,
      panX: _panX,
      panY: _panY,
      originalVolume: _originalVolume,
      splitPoints:
          _clipTimelineEditFor(_videos[_selectedVideoIndex].path).splitPoints,
      deletedRanges:
          _clipTimelineEditFor(_videos[_selectedVideoIndex].path).deletedRanges,
      partOrder:
          _clipTimelineEditFor(_videos[_selectedVideoIndex].path).partOrder,
    );
    _clipTimelineEdits[path] = edit;
    _trimStartSeconds = edit.trimStartSeconds;
    _trimEndSeconds = edit.trimEndSeconds;
    if (!previous.sameAs(edit) && !_updateSelectedTimelineClipTransform(edit)) {
      _syncMultiTrackFromLegacy();
    }
  }

  void _loadClipTimelineEdit(int index) {
    if (index < 0 || index >= _videos.length) return;
    _applyClipTimelineEdit(_clipTimelineEditFor(_videos[index].path));
  }

  void _applyClipTimelineEdit(_ClipTimelineEdit edit) {
    _trimStartSeconds = edit.trimStartSeconds;
    _trimEndSeconds = edit.trimEndSeconds;
    _speed = edit.speed;
    _flip = edit.flip;
    _scaleX = edit.scaleX;
    _scaleY = edit.scaleY;
    _zoom = edit.zoom;
    _panX = edit.panX;
    _panY = edit.panY;
    _originalVolume = edit.originalVolume;
    _trimStartController.text = _fieldNumber(edit.trimStartSeconds);
    _trimEndController.text =
        edit.trimEndSeconds <= 0 ? '' : _fieldNumber(edit.trimEndSeconds);
    _splitEveryController.text =
        edit.splitEverySeconds <= 0 ? '' : _fieldNumber(edit.splitEverySeconds);
  }

  String _fieldNumber(double value) {
    return value
        .toStringAsFixed(3)
        .replaceAll(RegExp(r'0+$'), '')
        .replaceAll(RegExp(r'\.$'), '');
  }

  Future<String?> _defaultOutputFolder() async {
    final configured = widget.settings.defaultExportFolder.trim();
    if (configured.isNotEmpty) {
      await Directory(configured).create(recursive: true);
      if (mounted) setState(() => _outputFolder = configured);
      return configured;
    }
    final directory = await getApplicationDocumentsDirectory();
    setState(() => _outputFolder = directory.path);
    return directory.path;
  }

  void _playExportCompleteSound() {
    if (!widget.settings.exportCompleteSound) return;
    unawaited(SystemSound.play(SystemSoundType.alert));
  }

  String _capCutReadyFolder(String folder) {
    if (platform.basename(folder).toLowerCase() == 'capcut ready') {
      return folder;
    }
    return '$folder${Platform.pathSeparator}CapCut Ready';
  }

  // ignore: unused_element
  Future<void> _openFolder(String folder) async {
    try {
      if (Platform.isWindows) {
        await Process.start('explorer.exe', [folder]);
      } else if (Platform.isMacOS) {
        await Process.start('open', [folder]);
      } else if (Platform.isLinux) {
        await Process.start('xdg-open', [folder]);
      }
    } catch (_) {
      // Opening the folder is a convenience only; export already completed.
    }
  }

  String _outputPath(
    String folder,
    int index,
    PickedVideo video, {
    int? segmentIndex,
    int? segmentCount,
  }) {
    if (segmentIndex != null && (segmentCount ?? 0) > 1) {
      final base = _partExportBaseName(index, video, segmentIndex);
      return '$folder${platform.pathSeparator}$base.mp4';
    }
    final base = _exportBaseName(video);
    final videoSuffix =
        _useNumberRange ? '' : (_videos.length > 1 ? '_${index + 1}' : '');
    final suffix = videoSuffix;
    return '$folder${platform.pathSeparator}$base$suffix.mp4';
  }

  String _partExportBaseName(int index, PickedVideo video, int partIndex) {
    final number = _useNumberRange ? _exportNumberForVideo(video) : index + 1;
    final label = _safeName(_partLabel.trim()).isEmpty
        ? 'part'
        : _safeName(_partLabel.trim());
    final typed = _safeName(_nameController.text);
    final title = typed.isEmpty ? _videoTitle(video) : typed;
    return _safeName('$number.$label$partIndex.$title');
  }

  String _timelineOutputPath(String folder) {
    final typed = _safeName(_nameController.text);
    final base = typed.isEmpty ? 'timeline_export' : typed;
    return '$folder${platform.pathSeparator}$base.mp4';
  }

  String _exportBaseName(PickedVideo video) {
    final patterned = _patternedExportBaseName(video);
    if (patterned.isNotEmpty) return patterned;
    final typed = _safeName(_nameController.text);
    if (typed.isEmpty) return _videoBaseName(video);
    return numberedExportBaseName(
      typed,
      number: _exportNumberForVideo(video),
      enabled: _useNumberRange,
    );
  }

  String _patternedExportBaseName(PickedVideo video) {
    final pattern = _batchRenamePattern.trim();
    if (pattern.isEmpty) return '';
    final number = _exportNumberForVideo(video);
    final sourceTitle = _withoutExtension(video.name);
    final title = _safeName(sourceTitle);
    final typed = _safeName(_nameController.text);
    final value = pattern
        .replaceAll('{n}', '$number')
        .replaceAll('{index}', '$number')
        .replaceAll('{title}', title)
        .replaceAll('{name}', typed.isEmpty ? title : typed);
    final safeValue = _safeName(value);
    if (safeValue.isEmpty) return '';
    return numberedExportBaseName(
      safeValue,
      number: number,
      enabled: _useNumberRange,
      patternIncludesNumber:
          pattern.contains('{n}') || pattern.contains('{index}'),
    );
  }

  String _videoBaseName(PickedVideo video) {
    final base = _videoTitle(video);
    return numberedExportBaseName(
      base.isEmpty ? 'video' : base,
      number: _exportNumberForVideo(video),
      enabled: _useNumberRange,
    );
  }

  String _videoTitle(PickedVideo video) =>
      _safeName(_withoutExtension(video.name));

  int _exportNumberForVideo(PickedVideo video) {
    final index = _videos.indexWhere((item) => item.path == video.path);
    if (index < 0) return 1;
    return _exportRangeStart() + index - _selectedExportRange().startIndex;
  }

  ({int startIndex, int endIndex}) _selectedExportRange() {
    final count = _videos.length;
    if (count <= 0) return (startIndex: 0, endIndex: -1);
    final selectedCount = _selectedExportVideoCount().clamp(0, count);
    if (selectedCount <= 0) return (startIndex: 0, endIndex: -1);
    return (startIndex: 0, endIndex: selectedCount - 1);
  }

  int _exportRangeStart() {
    return _numberRangeStartValue(_numberStartController.text);
  }

  int _exportRangeEnd() {
    return _numberRangeEndValue(
      _numberStartController.text,
      _numberEndController.text,
    );
  }

  int _selectedExportVideoCount() {
    if (!_useNumberRange) return _videos.length;
    return _numberRangeVideoCount(
      _numberStartController.text,
      _numberEndController.text,
    );
  }

  int _numberRangeStartValue(String startText) {
    final value = int.tryParse(startText.trim()) ?? 1;
    return value < 1 ? 1 : value;
  }

  int _numberRangeEndValue(String startText, String endText) {
    final start = _numberRangeStartValue(startText);
    return int.tryParse(endText.trim()) ??
        (_videos.isEmpty ? start : start + _videos.length - 1);
  }

  String _automaticNumberRangeEndText(String startText, String endText) {
    final trimmed = endText.trim();
    if (trimmed.isNotEmpty) return trimmed;
    final start = _numberRangeStartValue(startText);
    return '${_videos.isEmpty ? start : start + _videos.length - 1}';
  }

  int _numberRangeVideoCount(String startText, String endText) {
    final start = _numberRangeStartValue(startText);
    final end = _numberRangeEndValue(startText, endText);
    if (end < start) return 0;
    return (end - start + 1).clamp(0, _videos.length);
  }

  String _withoutExtension(String name) {
    final dot = name.lastIndexOf('.');
    if (dot <= 0) return name;
    return name.substring(0, dot);
  }

  String _safeName(String input) {
    final cleaned =
        input.trim().replaceAll(RegExp(r'[<>:"/\\|?*\x00-\x1f]+'), '_');
    final normalized = cleaned.replaceAll(RegExp(r'^[ .]+|[ .]+$'), '');
    return normalized;
  }

  Future<void> _chooseHookVideoTargets() async {
    final targets = await _showVideoTargetSelectionDialog(
      title: 'Choose videos for Hook edit',
      actionLabel: 'Create Hook edits',
      description:
          'Enter individual videos or ranges. Example: 1,2,4 to 7,9,10.',
    );
    if (targets == null || targets.isEmpty || !mounted) return;
    await _applyHookVideoEdit(videoIndexes: targets);
  }

  Future<void> _applyHookVideoEdit({
    bool allVideos = false,
    List<int>? videoIndexes,
  }) async {
    try {
      if (_videos.isEmpty) {
        _showMessage('Import a video before creating a hook edit.');
        return;
      }
      _saveSelectedClipTimelineEdit();
      final safeIndex = _selectedVideoIndex.clamp(0, _videos.length - 1);
      final targetIndexes = videoIndexes ??
          (allVideos
              ? List.generate(_videos.length, (index) => index)
              : [safeIndex]);
      final batch = allVideos || videoIndexes != null;
      final plannedEdits = <String, _ClipTimelineEdit>{};
      var skipped = 0;
      for (var queueIndex = 0;
          queueIndex < targetIndexes.length;
          queueIndex++) {
        final videoIndex = targetIndexes[queueIndex];
        final video = _videos[videoIndex];
        final duration = video.durationSeconds ?? 0;
        if (duration < 8) {
          skipped++;
          continue;
        }
        final manualTargetSeconds = _manualHookEditSeconds();
        if (manualTargetSeconds != null && manualTargetSeconds > duration) {
          skipped++;
          if (!batch) {
            _showMessage(
              'Hook length ${_formatDuration(manualTargetSeconds)} is longer than this video (${_formatDuration(duration)}).',
            );
            setState(() {
              _status = 'Hook length is longer than selected video.';
            });
            return;
          }
          continue;
        }
        final targetSeconds = _hookEditTargetSeconds(duration);
        final hookSeconds = math.min(5.0, math.max(2.0, targetSeconds * 0.12));

        setState(() {
          _status = batch
              ? 'Scanning hook ${queueIndex + 1}/${targetIndexes.length}: ${video.name}'
              : 'Scanning for hook moments...';
        });
        final scoredMoments = await _scoreHookMoments(
          video.path,
          duration,
          fast: batch,
        );
        if (!mounted) return;

        final ranges = _hookTimelineRanges(
          scoredMoments,
          duration,
          targetSeconds,
          hookSeconds,
        );
        if (ranges.isEmpty) {
          skipped++;
          continue;
        }
        final current = _clipTimelineEditFor(video.path);
        final edit = _clipTimelineEditWithRanges(current, ranges, duration);
        plannedEdits[video.path] = edit;
      }
      if (plannedEdits.isEmpty) {
        _showMessage('Hook edit could not find valid video ranges.');
        return;
      }

      final selectedPath = _videos[safeIndex].path;
      _recordEditorHistory(batch ? 'hook-edit-selected' : 'hook-edit');
      setState(() {
        for (final entry in plannedEdits.entries) {
          final current = _clipTimelineEditFor(entry.key);
          if (!current.sameAs(entry.value)) {
            _clipTimelineUndoStacks
                .putIfAbsent(entry.key, () => [])
                .add(current);
            _clipTimelineRedoStacks[entry.key]?.clear();
          }
          _clipTimelineEdits[entry.key] = entry.value;
        }
        final selectedEdit = plannedEdits[selectedPath];
        if (selectedEdit != null) {
          _applyClipTimelineEdit(selectedEdit);
        }
        _syncMultiTrackFromLegacy(
          preferredMediaPath: selectedPath,
          allCompositions: batch,
        );
        _exportTimelineTogether = true;
        _status = batch
            ? 'Hook edit applied to ${plannedEdits.length} videos${skipped > 0 ? ', skipped $skipped' : ''}.'
            : 'Hook edit applied to selected video.';
      });

      final selectedClipId = _selectedTimelineClipId;
      final selectedClip = selectedClipId == null
          ? null
          : _multiTrackTimeline.clipById(selectedClipId)?.clip;
      final playStart = batch ? 0.0 : selectedClip?.timelineStart ?? 0.0;
      _timelineSeekDebounce?.cancel();
      _timelineSeekGeneration++;
      _requestedTimelinePlayheadSeconds.value = playStart;
      _liveTimelinePlayheadSeconds.value = playStart;
      await _seekProgramPreview(playStart);
      if (!mounted) return;
      unawaited(_autosaveProject());
      _showMessage(
        batch
            ? 'Hook edit applied to ${plannedEdits.length} videos.'
            : 'Hook video edit applied to selected video.',
      );
    } catch (error) {
      if (!mounted) return;
      setState(() => _status = 'Hook video failed: $error');
      _showMessage('Hook video failed. Try a shorter hook edit length.');
    }
  }

  double _hookEditTargetSeconds(double duration) {
    final raw = _hookDurationController.text.trim().toLowerCase();
    final parsed = raw.isEmpty || raw == 'auto'
        ? _autoHookEditSeconds(duration)
        : _parseDurationSeconds(raw, plainNumberSeconds: 60);
    final fallback = _autoHookEditSeconds(duration);
    final requested = parsed <= 0 ? fallback : parsed;
    return requested.clamp(8.0, duration).toDouble();
  }

  double? _manualHookEditSeconds() {
    final raw = _hookDurationController.text.trim().toLowerCase();
    if (raw.isEmpty || raw == 'auto') return null;
    final parsed = _parseDurationSeconds(raw, plainNumberSeconds: 60);
    return parsed <= 0 ? null : parsed;
  }

  double _autoHookEditSeconds(double duration) {
    if (_hookEditMode == _HookEditMode.bestMoments) {
      return _autoHookBestMomentsSeconds(duration);
    }
    if (duration <= 0) return 0;
    if (duration <= 60) return duration;
    if (duration <= 10 * 60) {
      final target = duration * 0.9;
      return target.clamp(math.min(duration, 45.0), duration).toDouble();
    }
    if (duration <= 20 * 60) {
      final target = duration * 0.8;
      return target.clamp(8 * 60, math.min(duration, 10 * 60)).toDouble();
    }
    if (duration <= 30 * 60) {
      final target = duration * 0.75;
      return target.clamp(8 * 60, math.min(duration, 20 * 60)).toDouble();
    }
    final target = duration * 0.65;
    return target.clamp(10 * 60, math.min(duration, 30 * 60)).toDouble();
  }

  double _autoHookBestMomentsSeconds(double duration) {
    if (duration <= 0) return 0;
    if (duration <= 60) return duration;
    final target = duration * 0.35;
    return target.clamp(45.0, math.min(duration, 15 * 60)).toDouble();
  }

  List<({double start, double end})> _hookTimelineRanges(
    List<({double start, double score})> scoredMoments,
    double duration,
    double targetSeconds,
    double hookSeconds,
  ) {
    if (_batchSplitLongVideos && _batchSplitSeconds > 0) {
      return _splitAwareHookTimelineRanges(
        scoredMoments,
        duration,
        hookSeconds,
      );
    }
    final hook = _hookRangeForSection(scoredMoments, 0, duration, hookSeconds);
    if (_hookEditMode == _HookEditMode.hookWithVideo) {
      return _hookWithVideoTimelineRanges(hook, duration, targetSeconds);
    }
    final mainSegments =
        _bestMainHookSegments(scoredMoments, duration, hook, targetSeconds);
    return _safeHookTimelineRanges([hook, ...mainSegments], duration);
  }

  List<({double start, double end})> _hookWithVideoTimelineRanges(
    ({double start, double end}) hook,
    double duration,
    double targetSeconds,
  ) {
    final ranges = <({double start, double end})>[hook];
    var remaining = math.max(0.0, targetSeconds - (hook.end - hook.start));
    for (final span in _availableHookSpans(duration, hook)) {
      if (remaining <= 0.001) break;
      final keep = math.min(remaining, span.end - span.start);
      if (keep > 0.05) {
        ranges.add((start: span.start, end: span.start + keep));
        remaining -= keep;
      }
    }
    return _safeHookTimelineRanges(ranges, duration);
  }

  List<({double start, double end})> _splitAwareHookTimelineRanges(
    List<({double start, double score})> scoredMoments,
    double duration,
    double hookSeconds,
  ) {
    final splitSeconds = _batchSplitSeconds;
    if (splitSeconds <= 0) return const [];
    final ranges = <({double start, double end})>[];
    var sectionStart = 0.0;
    while (sectionStart < duration - 0.05) {
      final sectionEnd = math.min(duration, sectionStart + splitSeconds);
      if (sectionEnd - sectionStart < 1) break;
      final hook = _hookRangeForSection(
        scoredMoments,
        sectionStart,
        sectionEnd,
        hookSeconds,
      );
      ranges.add(hook);
      if (sectionStart < hook.start - 0.05) {
        ranges.add((start: sectionStart, end: hook.start));
      }
      if (hook.end < sectionEnd - 0.05) {
        ranges.add((start: hook.end, end: sectionEnd));
      }
      sectionStart = sectionEnd;
    }
    return _safeHookTimelineRanges(ranges, duration);
  }

  ({double start, double end}) _hookRangeForSection(
    List<({double start, double score})> scoredMoments,
    double sectionStart,
    double sectionEnd,
    double hookSeconds,
  ) {
    final sectionDuration = sectionEnd - sectionStart;
    final safeHookSeconds =
        math.min(hookSeconds, math.max(1.0, sectionDuration));
    final candidates = scoredMoments
        .where(
          (moment) =>
              moment.start >= sectionStart &&
              moment.start <= sectionEnd - safeHookSeconds,
        )
        .toList()
      ..sort((a, b) => b.score.compareTo(a.score));
    final start = candidates.isNotEmpty
        ? candidates.first.start
        : sectionStart + math.max(0.0, sectionDuration * 0.35);
    final clampedStart = start
        .clamp(
            sectionStart, math.max(sectionStart, sectionEnd - safeHookSeconds))
        .toDouble();
    return (start: clampedStart, end: clampedStart + safeHookSeconds);
  }

  Future<List<({double start, double score})>> _scoreHookMoments(
    String path,
    double duration, {
    bool fast = false,
  }) async {
    if (!(Platform.isWindows || Platform.isMacOS || Platform.isLinux)) {
      return _fallbackHookScores(duration);
    }
    final sampleCount = fast
        ? duration < 1200
            ? 5
            : 7
        : duration < 1200
            ? 12
            : 18;
    final maxStart = math.max(0.0, duration - 5);
    final step = sampleCount <= 1 ? maxStart : maxStart / (sampleCount - 1);
    final moments = <({double start, double score})>[];
    for (var index = 0; index < sampleCount; index++) {
      final start = (step * index).clamp(0.0, maxStart).toDouble();
      final score = await _scoreAudioWindow(path, start);
      if (!mounted) return moments;
      if (score != null) {
        moments.add((start: start, score: score));
      }
      setState(() {
        _status = 'Scanning hook moments ${index + 1}/$sampleCount...';
      });
    }
    return moments.isEmpty ? _fallbackHookScores(duration) : moments;
  }

  Future<double?> _scoreAudioWindow(String path, double start) async {
    return platform.audioWindowLevelScore(path, start);
  }

  List<({double start, double score})> _fallbackHookScores(double duration) {
    final maxStart = math.max(0.0, duration - 5);
    return [
      (start: maxStart * 0.18, score: 1),
      (start: maxStart * 0.38, score: 3),
      (start: maxStart * 0.62, score: 4),
      (start: maxStart * 0.82, score: 2),
    ];
  }

  List<({double start, double end})> _bestMainHookSegments(
    List<({double start, double score})> scoredMoments,
    double duration,
    ({double start, double end}) hook,
    double targetSeconds,
  ) {
    const maxSegmentCount = 3;
    final hookSeconds = hook.end - hook.start;
    final availableMainSeconds = math.max(0.0, duration - hookSeconds);
    final mainSeconds =
        (targetSeconds - hookSeconds).clamp(0.0, availableMainSeconds);
    final segmentCount =
        math.max(1, math.min(maxSegmentCount, mainSeconds ~/ 8));
    final segmentLength = mainSeconds / segmentCount;
    final selected = <({double start, double end})>[];
    if (segmentLength <= 0.001) return selected;
    final spans = _availableHookSpans(duration, hook);
    if (_totalRangeSeconds(spans) <= mainSeconds + 0.001) {
      return spans;
    }
    final candidates = scoredMoments.isEmpty
        ? _fallbackHookScores(duration)
        : ([...scoredMoments]..sort((a, b) => b.score.compareTo(a.score)));
    for (final moment in candidates) {
      if (selected.length >= segmentCount) break;
      final candidate = _segmentNearMoment(
        moment.start,
        segmentLength,
        spans,
        selected,
      );
      if (candidate != null) selected.add(candidate);
    }
    while (selected.length < segmentCount) {
      final remainingSeconds = mainSeconds - _totalRangeSeconds(selected);
      if (remainingSeconds <= 0.001) break;
      final remainingCount = segmentCount - selected.length;
      final nextLength = remainingSeconds / remainingCount;
      final next = _firstAvailableSegment(nextLength, spans, selected);
      if (next == null) break;
      selected.add(next);
    }
    selected.sort((a, b) => a.start.compareTo(b.start));
    return selected;
  }

  List<({double start, double end})> _availableHookSpans(
    double duration,
    ({double start, double end}) hook,
  ) {
    return [
      if (hook.start > 0.05) (start: 0.0, end: hook.start),
      if (hook.end < duration - 0.05) (start: hook.end, end: duration),
    ];
  }

  ({double start, double end})? _segmentNearMoment(
    double moment,
    double length,
    List<({double start, double end})> spans,
    List<({double start, double end})> selected,
  ) {
    final orderedSpans = [...spans]..sort(
        (a, b) => _distanceToRange(moment, a).compareTo(
          _distanceToRange(moment, b),
        ),
      );
    for (final span in orderedSpans) {
      final candidate = _candidateInsideSpan(moment, length, span);
      if (candidate != null &&
          !selected.any((range) => _rangesOverlap(candidate, range))) {
        return candidate;
      }
    }
    return _firstAvailableSegment(length, spans, selected);
  }

  ({double start, double end})? _candidateInsideSpan(
    double moment,
    double length,
    ({double start, double end}) span,
  ) {
    if (span.end - span.start < length - 0.001) return null;
    final start = (moment - length * 0.35)
        .clamp(span.start, span.end - length)
        .toDouble();
    return (start: start, end: start + length);
  }

  ({double start, double end})? _firstAvailableSegment(
    double length,
    List<({double start, double end})> spans,
    List<({double start, double end})> selected,
  ) {
    for (final gap in _availableGaps(spans, selected)) {
      if (gap.end - gap.start >= length - 0.001) {
        return (start: gap.start, end: gap.start + length);
      }
    }
    return null;
  }

  List<({double start, double end})> _availableGaps(
    List<({double start, double end})> spans,
    List<({double start, double end})> selected,
  ) {
    final gaps = <({double start, double end})>[];
    for (final span in spans) {
      var cursor = span.start;
      final blockers = selected
          .where((range) => _rangesOverlap(range, span))
          .toList()
        ..sort((a, b) => a.start.compareTo(b.start));
      for (final blocker in blockers) {
        if (blocker.start > cursor + 0.001) {
          gaps.add((start: cursor, end: blocker.start));
        }
        cursor = math.max(cursor, blocker.end);
      }
      if (span.end > cursor + 0.001) {
        gaps.add((start: cursor, end: span.end));
      }
    }
    return gaps;
  }

  double _distanceToRange(
    double value,
    ({double start, double end}) range,
  ) {
    if (value < range.start) return range.start - value;
    if (value > range.end) return value - range.end;
    return 0;
  }

  double _totalRangeSeconds(List<({double start, double end})> ranges) {
    return ranges.fold<double>(
      0,
      (sum, range) => sum + math.max(0.0, range.end - range.start),
    );
  }

  List<({double start, double end})> _safeHookTimelineRanges(
    List<({double start, double end})> ranges,
    double duration,
  ) {
    final safe = <({double start, double end})>[];
    for (final range in ranges) {
      final start = range.start.clamp(0.0, duration).toDouble();
      final end = range.end.clamp(0.0, duration).toDouble();
      if (end - start < 0.05) continue;
      final candidate = (start: start, end: end);
      if (safe.any((item) => _rangesOverlap(item, candidate))) continue;
      safe.add(candidate);
    }
    return safe;
  }

  bool _rangesOverlap(
    ({double start, double end}) first,
    ({double start, double end}) second,
  ) {
    return first.start < second.end && second.start < first.end;
  }

  _ClipTimelineEdit _clipTimelineEditWithRanges(
    _ClipTimelineEdit current,
    List<({double start, double end})> selectedRanges,
    double duration,
  ) {
    final normalized = selectedRanges
        .map(
          (range) => (
            start: range.start.clamp(0.0, duration).toDouble(),
            end: range.end.clamp(0.0, duration).toDouble(),
          ),
        )
        .where((range) => range.end > range.start)
        .toList();
    final boundaries = <double>{0, duration};
    for (final range in normalized) {
      boundaries
        ..add(range.start)
        ..add(range.end);
    }
    final sortedBoundaries = boundaries.toList()..sort();
    final splitPoints = sortedBoundaries
        .where((value) => value > 0.001 && value < duration - 0.001)
        .toList();
    final keepKeys = {
      for (final range in normalized)
        '${range.start.toStringAsFixed(3)}-${range.end.toStringAsFixed(3)}',
    };
    final deletedRanges = <({double start, double end})>[];
    for (var index = 0; index < sortedBoundaries.length - 1; index++) {
      final part = (
        start: sortedBoundaries[index],
        end: sortedBoundaries[index + 1],
      );
      final key =
          '${part.start.toStringAsFixed(3)}-${part.end.toStringAsFixed(3)}';
      if (!keepKeys.contains(key) && part.end > part.start) {
        deletedRanges.add(part);
      }
    }
    return current.copyWith(
      trimStartSeconds: 0,
      trimEndSeconds: duration,
      splitEverySeconds: 0,
      splitPoints: splitPoints,
      deletedRanges: deletedRanges,
      partOrder: normalized.map((range) => range.start).toList(),
    );
  }

  void _showMessage(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: KText(message)),
    );
  }

  Future<void> _showAppSettingsDialog() async {
    await showKlipioSettingsDialog(
      context,
      settings: widget.settings,
      onSaved: widget.onSettingsChanged,
    );
  }

  @override
  Widget build(BuildContext context) {
    return CallbackShortcuts(
      bindings: _shortcutBindings,
      child: Focus(
        autofocus: true,
        child: LayoutBuilder(
          builder: (context, constraints) {
            final phoneMode = constraints.maxWidth < 720;
