  Widget _windowMenuAction() {
    const labels = {
      'project': 'Project / Media',
      'source': 'Source Monitor',
      'program': 'Program Monitor',
      'inspector': 'Inspector / Effects',
      'timeline': 'Timeline',
    };
    return Padding(
      padding: const EdgeInsets.only(right: 5),
      child: PopupMenuButton<String>(
        tooltip: 'Window • show, hide, or reset panels',
        onSelected: (value) {
          if (value == 'reset') {
            setState(() {
              _workspaceDockOrder
                ..clear()
                ..addAll(['project', 'source', 'program', 'inspector']);
              _workspaceDockWidths
                ..clear()
                ..addAll({
                  'project': 280,
                  'source': 470,
                  'program': 520,
                  'inspector': 340,
                });
              _visibleWorkspacePanels
                ..clear()
                ..addAll([
                  'project',
                  'source',
                  'program',
                  'inspector',
                  'timeline',
                ]);
              _timelineWorkspaceHeight = 330;
            });
          } else {
            setState(() {
              if (!_visibleWorkspacePanels.add(value)) {
                _visibleWorkspacePanels.remove(value);
              }
            });
          }
          unawaited(_saveWorkspaceMemory());
        },
        itemBuilder: (context) => [
          for (final entry in labels.entries)
            CheckedPopupMenuItem<String>(
              value: entry.key,
              checked: _visibleWorkspacePanels.contains(entry.key),
              child: KText(entry.value),
            ),
          const PopupMenuDivider(),
          const PopupMenuItem<String>(
            value: 'reset',
            child: ListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              leading: Icon(Icons.restart_alt),
              title: KText('Reset workspace'),
            ),
          ),
        ],
        child: Container(
          constraints: const BoxConstraints(minWidth: 58),
          padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 1),
          decoration: BoxDecoration(borderRadius: BorderRadius.circular(5)),
          child: const Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(Icons.window_outlined, size: 18),
              SizedBox(height: 1),
              KText(
                'Window',
                style: TextStyle(fontSize: 10, fontWeight: FontWeight.w600),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _desktopWorkspace() {
    return LayoutBuilder(
      builder: (context, constraints) {
        const dividerSize = 4.0;
        final topPanels = _workspaceDockOrder
            .where(_visibleWorkspacePanels.contains)
            .toList();
        final showTimeline = _visibleWorkspacePanels.contains('timeline');
        final timelineHeight = _timelineWorkspaceHeight
            .clamp(190.0, math.max(190.0, constraints.maxHeight - 230))
            .toDouble();
        return Column(
          children: [
            if (topPanels.isNotEmpty)
              Expanded(
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    for (final entry in topPanels.indexed) ...[
                      Expanded(
                        flex: math.max(
                          1,
                          (_workspaceDockWidths[entry.$2] ?? 300).round(),
                        ),
                        child: _dockableWorkspacePanel(entry.$2),
                      ),
                      if (entry.$1 < topPanels.length - 1)
                        _workspaceResizeHandle(
                          axis: Axis.vertical,
                          onDrag: (delta) {
                            final left = entry.$2;
                            final right = topPanels[entry.$1 + 1];
                            setState(() {
                              _workspaceDockWidths[left] =
                                  ((_workspaceDockWidths[left] ?? 300) + delta)
                                      .clamp(140.0, 900.0)
                                      .toDouble();
                              _workspaceDockWidths[right] =
                                  ((_workspaceDockWidths[right] ?? 300) - delta)
                                      .clamp(140.0, 900.0)
                                      .toDouble();
                            });
                          },
                          onDragEnd: () => unawaited(_saveWorkspaceMemory()),
                        ),
                    ],
                  ],
                ),
              ),
            if (topPanels.isNotEmpty && showTimeline)
              _workspaceResizeHandle(
                axis: Axis.horizontal,
                onDrag: (delta) => setState(() {
                  _timelineWorkspaceHeight = (_timelineWorkspaceHeight - delta)
                      .clamp(
                        190.0,
                        math.max(190.0, constraints.maxHeight - 230),
                      )
                      .toDouble();
                }),
                onDragEnd: () => unawaited(_saveWorkspaceMemory()),
              ),
            if (showTimeline)
              SizedBox(
                height: topPanels.isEmpty
                    ? constraints.maxHeight
                    : timelineHeight - dividerSize,
                child: _timelinePanel(compact: false),
              ),
            if (topPanels.isEmpty && !showTimeline)
              Expanded(
                child: _emptyWorkspaceMessage(),
              ),
          ],
        );
      },
    );
  }

