  Widget _phoneNavItem({
    required int index,
    required IconData icon,
    required String label,
  }) {
    final selected = index == _phoneTabIndex;
    final accent = Theme.of(context).colorScheme.primary;
    return InkWell(
      onTap: () => setState(() => _phoneTabIndex = index),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 170),
        curve: Curves.easeOutCubic,
        decoration: BoxDecoration(
          border: Border(
            top: BorderSide(
              color: selected ? accent : Colors.transparent,
              width: 2,
            ),
          ),
        ),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(icon, size: 21, color: selected ? accent : _mutedTextColor),
            const SizedBox(height: 2),
            KText(
              label,
              maxLines: 1,
              style: TextStyle(
                fontSize: 10,
                fontWeight: selected ? FontWeight.w600 : FontWeight.w400,
                color: selected ? accent : _mutedTextColor,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _phoneTabPanel() {
    final child = switch (_phoneTabIndex) {
      0 => _mediaLibraryPanel(),
      1 => _phoneEditPanel(),
      2 => _focusedControlsPanel('Captions', _captionControlSection()),
      3 => _timelinePanel(compact: true),
      4 => _focusedControlsPanel('Audio', _audioControlSection()),
      5 => _focusedControlsPanel('Export', _exportControlSection()),
      _ => _timelinePanel(compact: true),
    };
    return AnimatedSwitcher(
      duration: const Duration(milliseconds: 190),
      switchInCurve: Curves.easeOutCubic,
      switchOutCurve: Curves.easeInCubic,
      transitionBuilder: (child, animation) => FadeTransition(
        opacity: animation,
        child: SlideTransition(
          position: Tween<Offset>(
            begin: const Offset(0.025, 0),
            end: Offset.zero,
          ).animate(animation),
          child: child,
        ),
      ),
      child: KeyedSubtree(key: ValueKey(_phoneTabIndex), child: child),
    );
  }

