  Widget _panelShell({
    required String title,
    Widget? trailing,
    required Widget child,
    String? workspacePanelId,
    bool showHeader = true,
    bool darkChrome = false,
  }) {
    return Card(
      margin: EdgeInsets.zero,
      elevation: 0,
      color: darkChrome ? _monitorCanvasColor : _panelColor,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.zero,
        side: BorderSide(
          color: darkChrome ? _monitorChromeBorderColor : _panelBorderColor,
        ),
      ),
      clipBehavior: Clip.antiAlias,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          if (showHeader)
            Container(
              height: widget.settings.compactWorkspace ? 28 : 30,
              padding: const EdgeInsets.symmetric(horizontal: 9),
              decoration: BoxDecoration(
                color: darkChrome ? _monitorChromeColor : _panelHeaderColor,
                border: Border(
                  bottom: BorderSide(
                    color: darkChrome
                        ? _monitorChromeBorderColor
                        : _panelBorderColor,
                  ),
                ),
              ),
              child: Row(
                children: [
                  if (title.isNotEmpty)
                    Expanded(
                      child: KText(
                        title,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                          letterSpacing: 0.35,
                          color: darkChrome ? _monitorChromeTextColor : null,
                        ),
                      ),
                    ),
                  if (trailing != null)
                    title.isEmpty
                        ? Expanded(
                            child: ClipRect(
                              child: DefaultTextStyle.merge(
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                child: trailing,
                              ),
                            ),
                          )
                        : Flexible(
                            flex: 2,
                            child: ClipRect(
                              child: DefaultTextStyle.merge(
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                child: trailing,
                              ),
                            ),
                          ),
                  const SizedBox(width: 4),
                  if (workspacePanelId == null)
                    Icon(
                      Icons.menu,
                      size: 14,
                      color: darkChrome
                          ? _monitorChromeTextColor
                          : _mutedTextColor,
                    ),
                  if (workspacePanelId != null) ...[
                    const SizedBox(width: 2),
                    IconButton(
                      visualDensity: VisualDensity.compact,
                      padding: EdgeInsets.zero,
                      constraints:
                          const BoxConstraints.tightFor(width: 24, height: 24),
                      onPressed: () {
                        setState(
                          () =>
                              _visibleWorkspacePanels.remove(workspacePanelId),
                        );
                        unawaited(_saveWorkspaceMemory());
                      },
                      icon: Icon(
                        Icons.close,
                        size: 15,
                        color: darkChrome ? _monitorChromeTextColor : null,
                      ),
                      tooltip: 'Close panel',
                    ),
                  ],
                ],
              ),
            ),
          Expanded(child: child),
        ],
      ),
    );
  }

