  void _applyAdjustmentsToAllClips() {
    final target = _professionalTargetClip();
    if (target == null) return;
    final source = target.clip.effects
        .where((effect) => _clipAdjustmentTypes.contains(effect.type))
        .toList();
    if (source.isEmpty) return;
    _recordEditorHistory('adjust-apply-all');
    var serial = DateTime.now().microsecondsSinceEpoch;
    var next = _multiTrackTimeline;
    for (final track in next.videoTracks) {
      if (track.isLocked) continue;
      next = _timelineEditor.updateTrack(
        next,
        track.id,
        (current) => current.copyWith(
          clips: [
            for (final clip in current.clips)
              clip.copyWith(
                effects: [
                  ...clip.effects.where(
                    (effect) => !_clipAdjustmentTypes.contains(effect.type),
                  ),
                  for (final effect in source)
                    ClipEffect(
                      id: 'adjust-all-${serial++}',
                      type: effect.type,
                      amount: effect.amount,
                      enabled: effect.enabled,
                    ),
                ],
              ),
          ],
        ),
      );
    }
    setState(() {
      _multiTrackTimeline = next;
      _status = 'Adjustments applied to all unlocked video clips';
    });
    unawaited(_autosaveProject());
  }

  ({TrackModel track, ClipModel clip})? _professionalTargetClip() {
    final selectedId = _selectedTimelineClipId;
    if (selectedId != null) {
      final selected = _multiTrackTimeline.clipById(selectedId);
      if (selected != null && selected.track.type == TrackType.video) {
        return selected;
      }
    }
    final active = _activeBaseVideoClip(_currentProgramSeconds());
    if (active == null) return null;
    return _multiTrackTimeline.clipById(active.id);
  }

  List<({TrackModel track, ClipModel clip})> _selectedProfessionalTargets() {
    final targets = <({TrackModel track, ClipModel clip})>[];
    for (final id in _effectiveSelectedTimelineClipIds) {
      final result = _multiTrackTimeline.clipById(id);
      if (result != null &&
          result.track.type == TrackType.video &&
          !result.track.isLocked) {
        targets.add(result);
      }
    }
    if (targets.isNotEmpty) return targets;
    final fallback = _professionalTargetClip();
    return fallback == null ? const [] : [fallback];
  }

