  void _applyClipEffectStyle(
    String name,
    List<(ClipEffectType, double)> effects,
  ) {
    final target = _professionalTargetClip();
    if (target == null ||
        !_ensureTimelineClipUnlocked(
          target.clip.id,
          action: 'adding this effect style',
        )) {
      return;
    }
    final targets = _selectedProfessionalTargets();
    _recordEditorHistory('effect-style-${target.clip.id}');
    var next = _multiTrackTimeline;
    var serial = DateTime.now().microsecondsSinceEpoch;
    for (final selected in targets) {
      for (final entry in effects) {
        next = _timelineEditor.addClipEffect(
          next,
          selected.clip.id,
          ClipEffect(
            id: 'style-${serial++}',
            type: entry.$1,
            amount: entry.$2,
          ),
        );
      }
    }
    setState(() {
      _multiTrackTimeline = next;
      _status = targets.length > 1
          ? '$name applied to ${targets.length} clips'
          : '$name applied to ${target.track.label}';
    });
    unawaited(_autosaveProject());
  }

  Widget _activeClipEffectTile(ClipEffect effect) {
    final signedAmount = {
      ClipEffectType.temperature,
      ClipEffectType.tint,
      ClipEffectType.exposure,
      ClipEffectType.brightness,
      ClipEffectType.contrast,
      ClipEffectType.highlights,
      ClipEffectType.shadows,
      ClipEffectType.whites,
      ClipEffectType.blacks,
      ClipEffectType.brilliance,
      ClipEffectType.saturation,
      ClipEffectType.gamma,
    }.contains(effect.type);
    final minimum = signedAmount ? -1.0 : 0.0;
    return Card(
      margin: const EdgeInsets.only(bottom: 6),
      color: _controlSurfaceColor,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(8, 5, 3, 6),
        child: Column(
          children: [
            Row(
              children: [
                Icon(_clipEffectIcon(effect.type), size: 17),
                const SizedBox(width: 7),
                Expanded(
                  child: KText(
                    effect.type.label,
                    style: const TextStyle(fontWeight: FontWeight.w700),
                  ),
                ),
                Switch(
                  value: effect.enabled,
                  onChanged: (enabled) =>
                      _updateClipEffect(effect.id, enabled: enabled),
                ),
                IconButton(
                  visualDensity: VisualDensity.compact,
                  tooltip: 'Remove effect',
                  onPressed: () => _removeClipEffect(effect.id),
                  icon: const Icon(Icons.close, size: 17),
                ),
              ],
            ),
            Row(
              children: [
                const KText('Amount', style: TextStyle(fontSize: 10)),
                Expanded(
                  child: Slider(
                    value: effect.amount.clamp(minimum, 2),
                    min: minimum,
                    max: 2,
                    divisions: signedAmount ? 60 : 40,
                    onChanged: (amount) =>
                        _updateClipEffect(effect.id, amount: amount),
                  ),
                ),
                SizedBox(
                  width: 30,
                  child: KText(
                    effect.amount.toStringAsFixed(1),
                    style: const TextStyle(fontSize: 9),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  void _updateClipEffect(
    String effectId, {
    double? amount,
    bool? enabled,
  }) {
    final target = _professionalTargetClip();
    if (target == null) return;
    if (!_ensureTimelineClipUnlocked(
      target.clip.id,
      action: 'editing this effect',
    )) {
      return;
    }
    _recordEditorHistory('effect-$effectId');
    setState(() {
      _multiTrackTimeline = _timelineEditor.updateClipEffect(
        _multiTrackTimeline,
        target.clip.id,
        effectId,
        (effect) => effect.copyWith(amount: amount, enabled: enabled),
      );
      _status = 'Effect stack updated';
    });
    unawaited(_autosaveProject());
  }

  void _removeClipEffect(String effectId) {
    final target = _professionalTargetClip();
    if (target == null) return;
    if (!_ensureTimelineClipUnlocked(
      target.clip.id,
      action: 'removing this effect',
    )) {
      return;
    }
    _recordEditorHistory('effect-remove');
    setState(() {
      _multiTrackTimeline = _timelineEditor.removeClipEffect(
        _multiTrackTimeline,
        target.clip.id,
        effectId,
      );
      _status = 'Effect removed';
    });
    unawaited(_autosaveProject());
  }

  void _addTransformKeyframe() {
    final target = _professionalTargetClip();
    if (target == null) return;
    if (!_ensureTimelineClipUnlocked(
      target.clip.id,
      action: 'adding a keyframe',
    )) {
      return;
    }
    final offset = (_currentProgramSeconds() - target.clip.timelineStart)
        .clamp(0, target.clip.duration)
        .toDouble();
    setState(() {
      _multiTrackTimeline = _timelineEditor.setClipKeyframe(
        _multiTrackTimeline,
        target.clip.id,
        ClipKeyframe(offset: offset, transform: target.clip.transform),
      );
      _status = 'Motion keyframe added at ${_formatDuration(offset)}';
    });
    unawaited(_autosaveProject());
  }

  void _removeNearestTransformKeyframe() {
    final target = _professionalTargetClip();
    if (target == null || target.clip.keyframes.isEmpty) return;
    if (!_ensureTimelineClipUnlocked(
      target.clip.id,
      action: 'removing a keyframe',
    )) {
      return;
    }
    final offset = (_currentProgramSeconds() - target.clip.timelineStart)
        .clamp(0, target.clip.duration)
        .toDouble();
    final nearest = [...target.clip.keyframes]..sort((a, b) =>
        (a.offset - offset).abs().compareTo((b.offset - offset).abs()));
    setState(() {
      _multiTrackTimeline = _timelineEditor.removeClipKeyframe(
        _multiTrackTimeline,
        target.clip.id,
        nearest.first.offset,
      );
      _status = 'Nearest motion keyframe removed';
    });
    unawaited(_autosaveProject());
  }

  Widget _transitionPresetLibrary() {
    const transitions = <(ClipTransitionType, IconData)>[
      (ClipTransitionType.dissolve, Icons.blur_on),
      (ClipTransitionType.fadeBlack, Icons.gradient),
      (ClipTransitionType.slideLeft, Icons.arrow_back),
      (ClipTransitionType.slideRight, Icons.arrow_forward),
      (ClipTransitionType.slideUp, Icons.arrow_upward),
      (ClipTransitionType.slideDown, Icons.arrow_downward),
    ];
    final target = _professionalTargetClip();
    final current = target?.clip.transitionIn;
    return ListView(
      padding: const EdgeInsets.all(10),
      children: [
        Row(
          children: [
            const Expanded(
              child: KText(
                'TRANSITIONS',
                style: TextStyle(
                  fontSize: 10,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 0.7,
                ),
              ),
            ),
            KText(
              target == null ? 'Select a video clip' : target.track.label,
              style: TextStyle(fontSize: 10, color: _mutedTextColor),
            ),
          ],
        ),
        const SizedBox(height: 8),
        for (final transition in transitions)
          Card(
            margin: const EdgeInsets.only(bottom: 7),
            color: current?.type == transition.$1
                ? Theme.of(context).colorScheme.primary.withOpacity(0.14)
                : _controlSurfaceColor,
            child: ListTile(
              dense: true,
              leading: Icon(transition.$2, size: 20),
              title: KText(
                transition.$1.label,
                style: const TextStyle(fontWeight: FontWeight.w700),
              ),
              trailing: current?.type == transition.$1
                  ? const Icon(Icons.check_circle, size: 18)
                  : const Icon(Icons.add_circle_outline, size: 18),
              onTap: target == null
                  ? null
                  : () => _applyClipTransition(transition.$1),
            ),
          ),
        if (current != null) ...[
          const SizedBox(height: 6),
          _slider(
            'Transition duration',
            current.duration,
            0.1,
            2,
            (value) {
              _transitionDurationSeconds = value;
              _applyClipTransition(current.type);
            },
            divisions: 38,
            valueFormatter: (value) => '${value.toStringAsFixed(2)}s',
          ),
          Align(
            alignment: Alignment.centerRight,
            child: TextButton.icon(
              onPressed: _removeClipTransition,
              icon: const Icon(Icons.link_off, size: 16),
              label: const KText('Remove transition'),
            ),
          ),
        ],
        const SizedBox(height: 8),
        KText(
          'Apply a transition to the incoming clip. Klipio overlaps it with the previous clip on the same track and renders matching audio fades.',
          style: TextStyle(fontSize: 10, color: _mutedTextColor),
        ),
      ],
    );
  }

  void _applyClipTransition(ClipTransitionType type) {
    final target = _professionalTargetClip();
    if (target == null) return;
    if (!_ensureTimelineClipUnlocked(
      target.clip.id,
      action: 'adding a transition',
    )) {
      return;
    }
    _recordEditorHistory('transition');
    final next = _timelineEditor.setClipTransition(
      _multiTrackTimeline,
      target.clip.id,
      ClipTransition(type: type, duration: _transitionDurationSeconds),
    );
    if (identical(next, _multiTrackTimeline)) {
      _showMessage(
          'A transition needs a previous clip on the same video track.');
      return;
    }
    setState(() {
      _multiTrackTimeline = next;
      _status = '${type.label} applied';
    });
    unawaited(_autosaveProject());
  }

  void _removeClipTransition() {
    final target = _professionalTargetClip();
    if (target == null) return;
    if (!_ensureTimelineClipUnlocked(
      target.clip.id,
      action: 'removing this transition',
    )) {
      return;
    }
    _recordEditorHistory('transition-remove');
    final next = _timelineEditor.setClipTransition(
      _multiTrackTimeline,
      target.clip.id,
      null,
    );
    if (identical(next, _multiTrackTimeline)) return;
    setState(() {
      _multiTrackTimeline = next;
      _status = 'Transition removed';
    });
    unawaited(_autosaveProject());
  }

