  List<({PickedVideo video, int index})> _visibleTimelineVideos() {
    if (_videos.isEmpty) return const [];
    if (!_clipEditMode) {
      return [
        for (final entry in _videos.indexed) (video: entry.$2, index: entry.$1),
      ];
    }
    final index = _selectedVideoIndex.clamp(0, _videos.length - 1);
    return [(video: _videos[index], index: index)];
  }

  Widget _timelineTracks({required bool compact}) {
    if (_multiTrackTimeline.tracks.isNotEmpty) {
      final thumbnailPaths = {
        for (final video in _videos)
          video.path: video.timelineThumbnailPaths.isNotEmpty
              ? video.timelineThumbnailPaths
              : [if (video.thumbnailPath != null) video.thumbnailPath!],
      };
      final mediaWithSourceAudio = {
        for (final video in _videos)
          if (video.hasAudio) video.path,
      };
      final clipLabels = {
        for (final overlay in _previewTextOverlays())
          if (overlay.id.isNotEmpty) overlay.id: overlay.text,
      };
      return ValueListenableBuilder<double>(
        valueListenable: _timelineScrollOffsetListenable,
        builder: (context, scrollOffset, _) =>
            ValueListenableBuilder<TimelineModel?>(
          valueListenable: _timelineEditPreviewModel,
          builder: (context, previewModel, _) {
            final displayModel = previewModel ?? _multiTrackTimeline;
            final pixelsPerSecond = _timelinePixelsPerSecond();
            final labelWidth = compact ? 124.0 : 132.0;
            final visibleStart = math.max(
              0.0,
              (scrollOffset - labelWidth) / pixelsPerSecond,
            );
            final visibleEnd = visibleStart +
                math.max(1.0, _timelineViewportWidth) / pixelsPerSecond;
            return DynamicTimelineView(
              model: displayModel,
              pixelsPerSecond: pixelsPerSecond,
              playheadSeconds: _currentProgramSeconds(),
              playheadOverride: _liveTimelinePlayheadSeconds,
              visibleStartSeconds: visibleStart,
              visibleEndSeconds: visibleEnd,
              selectedClipId: _selectedTimelineClipId,
              selectedClipIds: _effectiveSelectedTimelineClipIds,
              markers: _timelineMarkers,
              compact: compact,
              trackHeights: _timelineTrackHeights,
              skimmerSeconds: _timelineSkimmerSeconds,
              thumbnailPaths: thumbnailPaths,
              audioWaveformPeaks: _audioWaveformPeaks,
              waveformPeaksPerSecondByMedia: _audioWaveformPeakRates,
              marqueeController: _timelineMarqueeController,
              onMarqueeSelection: (clipIds, additive) => unawaited(
                _selectTimelineMarquee(clipIds, additive: additive),
              ),
              mediaWithSourceAudio: mediaWithSourceAudio,
              clipLabels: clipLabels,
              captionCues: _dynamicTimelineCaptionCues(displayModel),
              selectedCaptionId:
                  _editorSelection.kind == EditorSelectionKind.captionCue
                      ? _editorSelection.id
                      : null,
              selectedCaptionIds: _effectiveSelectedCaptionIds,
              onCaptionSelected: (id) =>
                  unawaited(_selectDynamicTimelineCaption(id)),
              onCaptionSelectionChanged: (id, toggle, range) => unawaited(
                _selectDynamicTimelineCaption(
                  id,
                  toggle: toggle,
                  range: range,
                ),
              ),
              captionHidden: _captionTrackHidden,
              captionLocked: _captionTrackLocked,
              onCaptionVisibilityChanged: () {
                setState(() => _captionTrackHidden = !_captionTrackHidden);
                unawaited(_autosaveProject());
              },
              onCaptionLockChanged: () {
                setState(() => _captionTrackLocked = !_captionTrackLocked);
                unawaited(_autosaveProject());
              },
              onCaptionDeleteRequested: () =>
                  unawaited(_deleteCaptionTimelineTrack()),
              onTrackDeleteRequested: (trackId) =>
                  unawaited(_deleteTimelineTrack(trackId)),
              musicPath: _musicPath,
              musicMuted: _musicTrackMuted,
              musicLocked: _musicTrackLocked,
              onMusicMuteChanged: () {
                setState(() => _musicTrackMuted = !_musicTrackMuted);
                if (_musicTrackMuted) unawaited(_pauseMusicPreview());
                unawaited(_autosaveProject());
              },
              onMusicLockChanged: () {
                setState(() => _musicTrackLocked = !_musicTrackLocked);
                unawaited(_autosaveProject());
              },
              onMusicDeleteRequested: () =>
                  unawaited(_deleteMusicTimelineTrack()),
              musicSelected: _musicTimelineSelected,
              onMusicSelected: (id, toggle, range) => _selectTimelineMusic(
                toggle: toggle,
              ),
              onSeek: _requestMultiTrackTimelineSeek,
              onClipSelected: (clipId) =>
                  unawaited(_selectMultiTrackClip(clipId)),
              onClipSelectionChanged: (clipId, toggle, range) => unawaited(
                _selectMultiTrackClip(
                  clipId,
                  toggle: toggle,
                  range: range,
                ),
              ),
              onClipContextMenu: (clipId, position) =>
                  unawaited(_showTimelineClipContextMenu(clipId, position)),
              onMediaDropped: _dropProjectMediaOnTimeline,
              onTrackHeightChanged: (trackId, height) {
                setState(() => _timelineTrackHeights[trackId] = height);
                _scheduleWorkspaceMemorySave();
              },
              onModelPreviewChanged: (model) =>
                  _timelineEditPreviewModel.value = model,
              onModelPreviewCommitted: _commitTimelineEditPreview,
              onModelChanged: _commitTimelineModelChange,
            );
          },
        ),
      );
    }
    final hasCaptionTrack =
        _automaticCaptions || _captionCuesByVideo.isNotEmpty;
    final labels = compact
        ? [if (hasCaptionTrack) 'T1', 'V1', 'A1']
        : [
            if (hasCaptionTrack) 'T1',
            'V2',
            'V1',
            'A1',
            if (_showExtractedAudioTrack) 'A2',
          ];
    return LayoutBuilder(
      builder: (context, constraints) {
        final labelWidth = compact ? 52.0 : 72.0;
        final maxHeight = constraints.maxHeight.clamp(1.0, 1000.0).toDouble();
        final rulerHeight =
            (maxHeight * 0.16).clamp(12.0, compact ? 20.0 : 26.0);
        const verticalPadding = 4.0;
        final availableHeight =
            (constraints.maxHeight - rulerHeight - verticalPadding)
                .clamp(1.0, 1000.0);
        final clipHeight = (availableHeight / labels.length).toDouble();
        final labelFontSize = clipHeight < 24 ? 10.0 : 12.0;
        final trackMargin = clipHeight < 22 ? 1.0 : 2.0;
        final playheadX = labelWidth + _timelinePlayheadOffset();
        final timelineWidth = constraints.maxWidth - labelWidth;
        return Padding(
          padding: EdgeInsets.fromLTRB(compact ? 2 : 4, 2, 4, 2),
          child: GestureDetector(
            behavior: HitTestBehavior.translucent,
            onTapDown: (details) => _seekTimelineAt(
              details.localPosition.dx - labelWidth,
            ),
            onHorizontalDragUpdate: (details) => _seekTimelineAt(
              details.localPosition.dx - labelWidth,
            ),
            child: Stack(
              clipBehavior: Clip.hardEdge,
              children: [
                Column(
                  children: [
                    SizedBox(
                      height: rulerHeight,
                      child: Row(
                        children: [
                          SizedBox(width: labelWidth),
                          Expanded(
                            child: MouseRegion(
                              cursor: SystemMouseCursors.click,
                              child: GestureDetector(
                                behavior: HitTestBehavior.opaque,
                                onTapDown: (details) => _seekTimelineAt(
                                  details.localPosition.dx,
                                ),
                                onHorizontalDragStart: (details) =>
                                    _seekTimelineAt(
                                  details.localPosition.dx,
                                ),
                                onHorizontalDragUpdate: (details) =>
                                    _seekTimelineAt(
                                  details.localPosition.dx,
                                ),
                                child: _timelineRuler(
                                  width: timelineWidth,
                                  compact: compact,
                                ),
                              ),
                            ),
                          ),
                        ],
                      ),
                    ),
                    for (final label in labels)
                      SizedBox(
                        height: clipHeight,
                        child: Row(
                          children: [
                            SizedBox(
                              width: labelWidth,
                              child: _timelineTrackLabel(
                                label,
                                fontSize: labelFontSize,
                              ),
                            ),
                            Expanded(
                              child: Container(
                                margin: EdgeInsets.only(bottom: trackMargin),
                                decoration: BoxDecoration(
                                  color: _isLightUi
                                      ? const Color(0xfff7f7f8)
                                      : const Color(0xff171719),
                                  border: Border(
                                    bottom:
                                        BorderSide(color: _panelBorderColor),
                                  ),
                                ),
                                child: label == 'T1'
                                    ? _timelineCaptionClips()
                                    : label == 'V1'
                                        ? _timelineVideoClips()
                                        : label == 'A1'
                                            ? _timelineAudioClips()
                                            : label == 'A2'
                                                ? _timelineAudioClips(
                                                    extracted: true,
                                                  )
                                                : const SizedBox.shrink(),
                              ),
                            ),
                          ],
                        ),
                      ),
                  ],
                ),
                Positioned(
                  left: playheadX - 5,
                  top: rulerHeight,
                  bottom: 0,
                  child: MouseRegion(
                    cursor: SystemMouseCursors.resizeLeftRight,
                    child: GestureDetector(
                      behavior: HitTestBehavior.translucent,
                      onHorizontalDragUpdate: (details) => _seekTimelineAt(
                        details.localPosition.dx + playheadX - labelWidth,
                      ),
                      child: const SizedBox(width: 12),
                    ),
                  ),
                ),
                Positioned(
                  left: playheadX,
                  top: 0,
                  bottom: 0,
                  child: IgnorePointer(
                    child: Container(
                      width: 2,
                      color: const Color(0xff3b82f6),
                    ),
                  ),
                ),
                Positioned(
                  left: playheadX - 5,
                  top: rulerHeight - 2,
                  child: IgnorePointer(
                    child: CustomPaint(
                      size: const Size(12, 9),
                      painter: _PlayheadHandlePainter(),
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  String _captionTimelineId(String path, int index) =>
      'caption:${Uri.encodeComponent(path)}:$index';

  ({String path, int index})? _captionSelectionTarget(String id) {
    final match = RegExp(r'^caption:(.*):(\d+)$').firstMatch(id);
    if (match == null) return null;
    final index = int.tryParse(match.group(2)!);
    if (index == null) return null;
    return (path: Uri.decodeComponent(match.group(1)!), index: index);
  }

  void _selectAllCaptionsForCurrentVideo() {
    if (_videos.isEmpty) return;
    final path = _videos[_selectedVideoIndex].path;
    final cues = _captionCuesByVideo[path] ?? const <_CaptionCue>[];
    if (cues.isEmpty) return;
    setState(() {
      _selectedCaptionIds
        ..clear()
        ..addAll([
          for (var index = 0; index < cues.length; index++)
            _captionTimelineId(path, index),
        ]);
      _selectedCaptionCueIndex = 0;
      _editorSelection = EditorSelection.caption(
        _captionTimelineId(path, 0),
        label: cues.first.text,
      );
    });
  }

  void _setSelectedCaptionPosition({double? x, double? y}) {
    if (_videos.isEmpty || _captionTrackLocked) return;
    final currentPath = _videos[_selectedVideoIndex].path;
    final currentCues =
        _captionCuesByVideo[currentPath] ?? const <_CaptionCue>[];
    if (currentCues.isEmpty) return;
    var ids = _effectiveSelectedCaptionIds;
    if (ids.isEmpty) {
      ids = {
        _captionTimelineId(currentPath,
            _selectedCaptionCueIndex.clamp(0, currentCues.length - 1))
      };
    }
    _recordEditorHistory('caption-position');
    setState(() {
      final updates = <String, List<_CaptionCue>>{};
      for (final id in ids) {
        final target = _captionSelectionTarget(id);
        if (target == null) continue;
        final cues =
            updates[target.path] ?? [...?_captionCuesByVideo[target.path]];
        if (target.index < 0 || target.index >= cues.length) continue;
        final cue = cues[target.index];
        cues[target.index] = cue.copyWith(
          x: (x ?? cue.x).clamp(0.02, 0.98).toDouble(),
          y: (y ?? cue.y).clamp(0.02, 0.98).toDouble(),
        );
        updates[target.path] = cues;
      }
      for (final entry in updates.entries) {
        _captionCuesByVideo[entry.key] = entry.value;
      }
      _status = 'Moved ${ids.length} caption${ids.length == 1 ? '' : 's'}';
    });
  }

  void _dragSelectedCaptions(_CaptionCue active, Offset normalizedDelta) {
    if (_videos.isEmpty || _captionTrackLocked) return;
    String? path;
    var index = -1;
    for (final entry in _captionCuesByVideo.entries) {
      final candidate = entry.value.indexOf(active);
      if (candidate < 0) continue;
      path = entry.key;
      index = candidate;
      break;
    }
    if (path == null || index < 0) return;
    final activeId = _captionTimelineId(path, index);
    if (!_effectiveSelectedCaptionIds.contains(activeId)) {
      _selectedCaptionIds
        ..clear()
        ..add(activeId);
      _selectedCaptionCueIndex = index;
      _editorSelection = EditorSelection.caption(activeId, label: active.text);
    }
    _setSelectedCaptionPosition(
      x: active.x + normalizedDelta.dx,
      y: active.y + normalizedDelta.dy,
    );
  }

  List<TimelineCaptionCueData> _dynamicTimelineCaptionCues([
    TimelineModel? timeline,
  ]) {
    final result = <TimelineCaptionCueData>[];
    for (final track in (timeline ?? _multiTrackTimeline).videoTracks) {
      for (final clip in track.clips) {
        final cues = _captionCuesByVideo[clip.mediaPath];
        if (cues == null || cues.isEmpty) continue;
        for (var index = 0; index < cues.length; index++) {
          final cue = cues[index];
          final visibleStart = math.max(cue.start, clip.sourceStart).toDouble();
          final visibleEnd = math.min(cue.end, clip.sourceEnd).toDouble();
          if (visibleEnd <= visibleStart) continue;
          result.add(
            TimelineCaptionCueData(
              id: _captionTimelineId(clip.mediaPath, index),
              timelineStart:
                  clip.timelineStart + (visibleStart - clip.sourceStart),
              duration: visibleEnd - visibleStart,
              text: cue.text,
            ),
          );
        }
      }
    }
    result.sort((a, b) => a.timelineStart.compareTo(b.timelineStart));
    return result;
  }

  Set<String> get _effectiveSelectedTimelineClipIds {
    final primary = _selectedTimelineClipId;
    if (_selectedTimelineClipIds.isEmpty) {
      return primary == null ? const {} : {primary};
    }
    if (primary == null || _selectedTimelineClipIds.contains(primary)) {
      return Set.unmodifiable(_selectedTimelineClipIds);
    }
    return {primary};
  }

  Set<String> get _effectiveSelectedCaptionIds {
    final primary = _editorSelection.kind == EditorSelectionKind.captionCue
        ? _editorSelection.id
        : null;
    if (_selectedCaptionIds.isEmpty) {
      return primary == null ? const {} : {primary};
    }
    if (primary == null || _selectedCaptionIds.contains(primary)) {
      return Set.unmodifiable(_selectedCaptionIds);
    }
    return {primary};
  }

  int get _timelineSelectionCount =>
      _effectiveSelectedTimelineClipIds.length +
      _effectiveSelectedCaptionIds.length +
      (_musicTimelineSelected ? 1 : 0);

  Set<String> _timelineClipSelectionFor(
    String id, {
    required bool toggle,
    required bool range,
  }) {
    final current = {..._effectiveSelectedTimelineClipIds};
    if (range && _selectedTimelineClipId != null) {
      final clicked = _multiTrackTimeline.clipById(id);
      final anchor = _multiTrackTimeline.clipById(_selectedTimelineClipId!);
      if (clicked != null && anchor?.track.id == clicked.track.id) {
        final ordered = [...clicked.track.clips]
          ..sort((a, b) => a.timelineStart.compareTo(b.timelineStart));
        final first = ordered.indexWhere((clip) => clip.id == anchor!.clip.id);
        final last = ordered.indexWhere((clip) => clip.id == id);
        if (first >= 0 && last >= 0) {
          final low = math.min(first, last);
          final high = math.max(first, last);
          return {
            if (toggle) ...current,
            for (var index = low; index <= high; index++) ordered[index].id,
          };
        }
      }
    }
    if (toggle) {
      if (!current.add(id)) current.remove(id);
      return current;
    }
    return {id};
  }

  Set<String> _captionSelectionFor(
    String id, {
    required bool toggle,
    required bool range,
  }) {
    final current = {..._effectiveSelectedCaptionIds};
    final anchor = _editorSelection.kind == EditorSelectionKind.captionCue
        ? _editorSelection.id
        : null;
    if (range && anchor != null) {
      final ordered = _dynamicTimelineCaptionCues();
      final first = ordered.indexWhere((cue) => cue.id == anchor);
      final last = ordered.indexWhere((cue) => cue.id == id);
      if (first >= 0 && last >= 0) {
        final low = math.min(first, last);
        final high = math.max(first, last);
        return {
          if (toggle) ...current,
          for (var index = low; index <= high; index++) ordered[index].id,
        };
      }
    }
    if (toggle) {
      if (!current.add(id)) current.remove(id);
      return current;
    }
    return {id};
  }

  Future<void> _selectDynamicTimelineCaption(
    String id, {
    bool toggle = false,
    bool range = false,
  }) async {
    if (!id.startsWith('caption:')) return;
    final separator = id.lastIndexOf(':');
    if (separator <= 'caption:'.length) return;
    final path =
        Uri.decodeComponent(id.substring('caption:'.length, separator));
    final index = int.tryParse(id.substring(separator + 1));
    final videoIndex = _videos.indexWhere((video) => video.path == path);
    final cues = _captionCuesByVideo[path] ?? const <_CaptionCue>[];
    if (index == null || videoIndex < 0 || index < 0 || index >= cues.length) {
      return;
    }
    if (videoIndex != _selectedVideoIndex) {
      await _selectVideo(videoIndex, saveCurrentEdit: false);
      if (!mounted) return;
    }
    final nextSelection = _captionSelectionFor(
      id,
      toggle: toggle,
      range: range,
    );
    final primaryCaptionId = nextSelection.contains(id)
        ? id
        : (nextSelection.isEmpty ? null : nextSelection.last);
    final primaryCaption = primaryCaptionId == null
        ? null
        : _dynamicTimelineCaptionCues()
            .where((cue) => cue.id == primaryCaptionId)
            .firstOrNull;
    setState(() {
      _selectedCaptionIds
        ..clear()
        ..addAll(nextSelection);
      if (!toggle && !range) {
        _selectedTimelineClipIds.clear();
        _musicTimelineSelected = false;
      }
      _selectedCaptionCueIndex = index;
      _selectedTimelineClipId = null;
      _editorSelection = nextSelection.isEmpty
          ? const EditorSelection.none()
          : EditorSelection.caption(
              primaryCaptionId!,
              label: primaryCaption?.text ?? cues[index].text,
            );
      _visibleWorkspacePanels.add('inspector');
      _status = nextSelection.length > 1
          ? '${nextSelection.length} caption clips selected'
          : 'Caption selected';
    });
  }

  Future<void> _deleteCaptionTimelineTrack() async {
    if (_captionTrackLocked) {
      _showMessage('Unlock T1 before deleting captions.');
      return;
    }
    final paths = {
      for (final track in _multiTrackTimeline.videoTracks)
        for (final clip in track.clips) clip.mediaPath,
    };
    if (!paths.any((path) => _captionCuesByVideo[path]?.isNotEmpty == true)) {
      return;
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const KText('Delete caption track?'),
        content: const KText(
          'All caption blocks in this timeline will be removed. The source video is not changed.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const KText('Cancel'),
          ),
          FilledButton.icon(
            onPressed: () => Navigator.pop(context, true),
            icon: const Icon(Icons.delete_outline),
            label: const KText('Delete captions'),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;
    _recordEditorHistory('caption-track-delete');
    setState(() {
      for (final path in paths) {
        _captionCuesByVideo.remove(path);
      }
      _selectedCaptionIds.clear();
      _selectedCaptionCueIndex = 0;
      _editorSelection = _videos.isEmpty
          ? const EditorSelection.none()
          : EditorSelection.video(_videos[_selectedVideoIndex].path);
      _status = 'Caption track deleted';
    });
    unawaited(_autosaveProject());
  }

  Future<void> _deleteTimelineTrack(String trackId) async {
    final track = _multiTrackTimeline.trackById(trackId);
    if (track == null) return;
    if (track.isLocked) {
      _showMessage('Unlock ${track.label} before deleting it.');
      return;
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: KText('Delete ${track.label} track?'),
        content: KText(
          track.clips.isEmpty
              ? 'This empty track will be removed.'
              : 'This removes ${track.clips.length} clip${track.clips.length == 1 ? '' : 's'} from the timeline. Original media files are not deleted.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const KText('Cancel'),
          ),
          FilledButton.icon(
            onPressed: () => Navigator.pop(context, true),
            icon: const Icon(Icons.delete_outline),
            label: const KText('Delete track'),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;
    _recordEditorHistory('track-delete');
    final deletedVideoIds = track.type == TrackType.video
        ? track.clips.map((clip) => clip.id).toSet()
        : const <String>{};
    final deletedTextIds = track.type == TrackType.text
        ? track.clips.expand((clip) => [clip.id, clip.mediaPath]).toSet()
        : const <String>{};
    var tracks = <TrackModel>[
      for (final item in _multiTrackTimeline.tracks)
        if (item.id != trackId)
          item.type == TrackType.audio && deletedVideoIds.isNotEmpty
              ? item.copyWith(
                  clips: item.clips
                      .where(
                        (clip) =>
                            !clip.isLinkedAudio ||
                            !deletedVideoIds.contains(clip.linkedClipId),
                      )
                      .toList(),
                )
              : item,
    ];
    if (!tracks.any((item) => item.type == track.type) &&
        track.type != TrackType.text) {
      tracks = [
        ...tracks,
        TrackModel(
          id: '${track.type.name}-1',
          type: track.type,
          index: 1,
        ),
      ];
    }
    setState(() {
      if (deletedTextIds.isNotEmpty) {
        _textOverlays.removeWhere(
          (overlay) => deletedTextIds.contains(overlay.id),
        );
        if (_textOverlays.isEmpty) {
          _textOverlays.add(const _TextOverlayDraft());
        }
      }
      _applyTimelineModelUpdate(
        TimelineModel(
          tracks: tracks,
          duration: TimelineModel.calculateDuration(tracks),
        ).normalized(),
      );
      _selectedTimelineClipIds.removeWhere(
        (id) => _multiTrackTimeline.clipById(id) == null,
      );
      _selectedTimelineClipId = null;
      _editorSelection = _videos.isEmpty
          ? const EditorSelection.none()
          : EditorSelection.video(_videos[_selectedVideoIndex].path);
      _status = '${track.label} track deleted';
    });
    unawaited(_autosaveProject());
  }

  Future<void> _deleteMusicTimelineTrack() async {
    if (_musicPath == null) return;
    if (_musicTrackLocked) {
      _showMessage('Unlock M1 before deleting the music track.');
      return;
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const KText('Delete music track?'),
        content: const KText(
          'The background music is removed from the timeline and export. The original audio file is not deleted.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const KText('Cancel'),
          ),
          FilledButton.icon(
            onPressed: () => Navigator.pop(context, true),
            icon: const Icon(Icons.delete_outline),
            label: const KText('Delete music'),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;
    await _stopMusicPreview();
    if (!mounted) return;
    _recordEditorHistory('music-track-delete');
    setState(() {
      _musicPath = null;
      _musicTrackMuted = false;
      _musicTrackLocked = false;
      _musicTimelineSelected = false;
      if (_editorSelection.id == 'music-track') {
        _editorSelection = const EditorSelection.none();
      }
      _status = 'Music track deleted';
    });
    unawaited(_autosaveProject());
  }

  Widget _timelineTrackLabel(String label, {required double fontSize}) {
    final isVideo = label.startsWith('V');
    final isCaption = label.startsWith('T');
    final isPrimaryVideo = label == 'V1';
    final isVideoAudio = label == 'A1' || label == 'A2';
    return Padding(
      padding: const EdgeInsets.only(right: 6),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.end,
        children: [
          if (isCaption)
            Icon(
              Icons.subtitles_outlined,
              size: fontSize + 3,
              color: const Color(0xfff97316),
            )
          else if (isPrimaryVideo)
            _timelineTrackToggle(
              icon: _videoTrackHidden
                  ? Icons.visibility_off_outlined
                  : Icons.visibility_outlined,
              tooltip:
                  _videoTrackHidden ? 'Show video track' : 'Hide video track',
              active: !_videoTrackHidden,
              onPressed: () => setState(() {
                _videoTrackHidden = !_videoTrackHidden;
              }),
            )
          else if (isVideo)
            Icon(
              Icons.visibility_outlined,
              size: fontSize + 2,
              color: _mutedTextColor,
            )
          else
            _timelineTrackToggle(
              icon: (isVideoAudio ? _originalAudioMuted : _musicTrackMuted)
                  ? Icons.volume_off_outlined
                  : Icons.volume_up_outlined,
              tooltip: (isVideoAudio ? _originalAudioMuted : _musicTrackMuted)
                  ? 'Unmute track'
                  : 'Mute track',
              active: !(isVideoAudio ? _originalAudioMuted : _musicTrackMuted),
              onPressed: () {
                setState(() {
                  if (isVideoAudio) {
                    _originalAudioMuted = !_originalAudioMuted;
                  } else {
                    _musicTrackMuted = !_musicTrackMuted;
                  }
                });
                final controller = _previewController;
                if (controller != null && controller.value.isInitialized) {
                  unawaited(
                    controller.setVolume(
                      _previewAudioVolume(_effectiveOriginalVolume),
                    ),
                  );
                }
                unawaited(
                  _musicPreviewPlayer.setVolume(
                    _previewAudioVolume(_effectiveMusicVolume),
                  ),
                );
              },
            ),
          const SizedBox(width: 5),
          KText(
            label,
            style: TextStyle(
              color: _mutedTextColor,
              fontWeight: FontWeight.w600,
              fontSize: fontSize,
            ),
          ),
        ],
      ),
    );
  }

  Widget _timelineTrackToggle({
    required IconData icon,
    required String tooltip,
    required bool active,
    required VoidCallback onPressed,
  }) {
    return IconButton(
      visualDensity: VisualDensity.compact,
      padding: EdgeInsets.zero,
      constraints: const BoxConstraints.tightFor(width: 24, height: 24),
      iconSize: 15,
      color: active ? const Color(0xff94a3b8) : const Color(0xff64748b),
      onPressed: onPressed,
      icon: Icon(icon),
      tooltip: tooltip,
    );
  }

  Widget _timelineRuler({required double width, required bool compact}) {
    return CustomPaint(
      painter: _TimelineRulerPainter(
        marks: _timelineRulerMarks(width, compact: compact),
        compact: compact,
        axisColor: _panelBorderColor,
        labelColor: _mutedTextColor,
      ),
      child: const SizedBox.expand(),
    );
  }

  List<({double x, double seconds, bool major})> _timelineRulerMarks(
    double width, {
    required bool compact,
  }) {
    if (_videos.isEmpty || width <= 0) {
      return const [];
    }
    final step = _timelineTickStep();
    final majorEvery = _timelineMajorTickEvery(step);
    final marks = <({double x, double seconds, bool major})>[];
    final sequenceDuration = _timelineSequenceDuration();
    final pixelsPerSecond = _timelinePixelsPerSecond();
    final viewportWidth = _timelineScrollController.hasClients
        ? _timelineScrollController.position.viewportDimension
        : width;
    final labelWidth = compact ? 52.0 : 72.0;
    const bufferPx = 240.0;
    final visibleStartPx =
        (_timelineScrollOffset - labelWidth - bufferPx).clamp(0.0, width);
    final visibleEndPx =
        (_timelineScrollOffset + viewportWidth - labelWidth + bufferPx)
            .clamp(0.0, width);
    var second = (visibleStartPx / pixelsPerSecond / step).floor() * step;
    var index = (second / step).round();
    final maxSecond =
        (visibleEndPx / pixelsPerSecond).clamp(0.0, sequenceDuration);
    while (second <= sequenceDuration + 0.001) {
      if (second > maxSecond + step) break;
      marks.add((
        x: (second * pixelsPerSecond).clamp(0.0, width),
        seconds: second,
        major: index % majorEvery == 0,
      ));
      second += step;
      index++;
    }
    if (sequenceDuration * pixelsPerSecond >= visibleStartPx &&
        sequenceDuration * pixelsPerSecond <= visibleEndPx &&
        (marks.isEmpty || marks.last.seconds < sequenceDuration)) {
      marks.add((
        x: (sequenceDuration * pixelsPerSecond).clamp(0.0, width),
        seconds: sequenceDuration,
        major: true,
      ));
    }
    return marks;
  }

  double _timelineTickStep() {
    final px = _timelinePixelsPerSecond();
    if (px >= 140) return 0.1;
    if (px >= 70) return 0.25;
    if (px >= 36) return 0.5;
    if (px >= 16) return 1;
    if (px >= 8) return 2;
    if (px >= 4) return 5;
    return 10;
  }

  int _timelineMajorTickEvery(double step) {
    if (step < 1) return (1 / step).round();
    if (step <= 1) return 5;
    return 2;
  }

  Widget _timelineActionButton({
    required IconData icon,
    required String label,
    required String tooltip,
    required VoidCallback? onPressed,
    bool primary = false,
    bool danger = false,
    bool iconOnly = false,
  }) {
    final foreground = danger ? const Color(0xffef4444) : null;
    final style = primary
        ? FilledButton.styleFrom(
            visualDensity: VisualDensity.compact,
            padding: EdgeInsets.symmetric(horizontal: iconOnly ? 6 : 9),
            minimumSize: const Size(0, 28),
          )
        : OutlinedButton.styleFrom(
            foregroundColor: foreground,
            side: danger ? const BorderSide(color: Color(0xff7f1d1d)) : null,
            visualDensity: VisualDensity.compact,
            padding: EdgeInsets.symmetric(horizontal: iconOnly ? 6 : 8),
            minimumSize: const Size(0, 28),
          );
    final child = Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        Icon(icon, size: 16),
        if (!iconOnly) ...[
          const SizedBox(width: 4),
          KText(label,
              style:
                  const TextStyle(fontSize: 11, fontWeight: FontWeight.w600)),
        ],
      ],
    );
    return Padding(
      padding: const EdgeInsets.only(right: 4, top: 4, bottom: 4),
      child: Tooltip(
        message: tooltip,
        child: primary
            ? FilledButton(onPressed: onPressed, style: style, child: child)
            : OutlinedButton(onPressed: onPressed, style: style, child: child),
      ),
    );
  }

