  void _zoomTimelineIn() {
    _setTimelineZoom((_timelineZoom + 5).clamp(0, 100).toDouble());
  }

  void _zoomTimelineOut() {
    _setTimelineZoom((_timelineZoom - 5).clamp(0, 100).toDouble());
  }

  void _fitTimelineZoom() {
    _setTimelineZoom(0, resetScroll: true);
  }

  void _setTimelineZoom(double value, {bool resetScroll = false}) {
    final nextZoom = value.clamp(0.0, 100.0).toDouble();
    if (!resetScroll && (nextZoom - _timelineZoom).abs() < 0.001) return;

    final oldPixelsPerSecond = _timelinePixelsPerSecond();
    final oldOffset = _timelineScrollController.hasClients
        ? _timelineScrollController.offset
        : _timelineScrollOffset;
    final anchorSeconds =
        (_liveTimelinePlayheadSeconds.value ?? _currentProgramSeconds())
            .clamp(0.0, math.max(0.0, _multiTrackTimeline.duration))
            .toDouble();
    final anchorViewportX = anchorSeconds * oldPixelsPerSecond - oldOffset;
    final generation = ++_timelineZoomGeneration;

    setState(() => _timelineZoom = nextZoom);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted ||
          generation != _timelineZoomGeneration ||
          !_timelineScrollController.hasClients) {
        return;
      }
      final position = _timelineScrollController.position;
      final target = resetScroll
          ? 0.0
          : anchorSeconds * _timelinePixelsPerSecond() - anchorViewportX;
      final clamped = target.clamp(0.0, position.maxScrollExtent).toDouble();
      if ((position.pixels - clamped).abs() > 0.5) {
        _timelineScrollController.jumpTo(clamped);
      }
      _timelineScrollOffset = clamped;
      _timelineScrollOffsetListenable.value = clamped;
    });
  }

  double _timelinePixelsPerSecond() {
    final progress = _timelineZoom.clamp(0, 100) / 100;
    final duration = math.max(0.1, _multiTrackTimeline.duration + 2);
    final viewport = _timelineViewportWidth > 0 ? _timelineViewportWidth : 900;
    // Zero percent is a true wide overview. Short edits remain readable while
    // long projects shrink enough to show their complete duration.
    final fitScale = (viewport * 0.62 / duration).clamp(0.08, 160.0).toDouble();
    return fitScale * math.pow(160 / fitScale, progress).toDouble();
  }

  double _timelinePartWidth(({double start, double end}) part) {
    final duration = (part.end - part.start).abs();
    return (duration * _timelinePixelsPerSecond())
        .clamp(1.0, double.infinity)
        .toDouble();
  }

  double _timelineContentWidth({double minimumWidth = 420}) {
    var width = 0.0;
    for (final item in _visibleTimelineVideos()) {
      final parts = _clipTimelineEditFor(item.video.path).timelineParts(
        item.video.durationSeconds,
      );
      for (final part in parts) {
        width += _timelinePartWidth(part);
      }
    }
    final dynamicWidth =
        (_multiTrackTimeline.duration + 2) * _timelinePixelsPerSecond();
    width = math.max(width, dynamicWidth);
    return width < minimumWidth ? minimumWidth : width;
  }

  void _requestMultiTrackTimelineSeek(double seconds) {
    if (_videos.isEmpty) return;
    final duration = _programPlaybackDurationSeconds();
    final requested = seconds.clamp(0.0, duration).toDouble();
    final generation = ++_timelineSeekGeneration;
    _requestedTimelinePlayheadSeconds.value = requested;
    _liveTimelinePlayheadSeconds.value = requested;
    _timelineSeekDebounce?.cancel();
    _timelineSeekDebounce = Timer(
      const Duration(milliseconds: 35),
      () => unawaited(
        _commitMultiTrackTimelineSeek(requested, generation),
      ),
    );
  }

  Future<void> _commitMultiTrackTimelineSeek(
    double seconds,
    int generation,
  ) async {
    if (_videos.isEmpty) return;
    final target = _programTargetForTimelineSeconds(seconds);
    if (target == null) return;
    final wasPlaying = _previewController?.value.isPlaying == true;
    if (target.isGap) {
      await _previewController?.pause();
      await _pauseMusicPreview();
      _programTimelineClipId = null;
      if (generation == _timelineSeekGeneration) {
        _requestedTimelinePlayheadSeconds.value = target.timelineSeconds;
        _liveTimelinePlayheadSeconds.value = target.timelineSeconds;
      }
      if (mounted) setState(() {});
      return;
    }
    final wasClipEditMode = _clipEditMode;
    final switchingVideo = target.videoIndex != _selectedVideoIndex;
    final controllerUnavailable = _previewController == null ||
        _previewController?.value.isInitialized != true;
    if (switchingVideo || controllerUnavailable) {
      await _selectVideo(
        target.videoIndex,
        saveCurrentEdit: switchingVideo,
      );
      if (mounted && _clipEditMode != wasClipEditMode) {
        setState(() => _clipEditMode = wasClipEditMode);
      }
    }
    final targetClip = target.clipId == null
        ? null
        : _multiTrackTimeline.clipById(target.clipId!)?.clip;
    if (targetClip != null) {
      _loadTimelineClipTransformIntoInspector(targetClip);
    }
    final controller = _previewController;
    if (controller != null && controller.value.isInitialized) {
      _programTimelineClipId = target.clipId;
      await controller.setVolume(
        _previewAudioVolume(_effectiveOriginalVolume),
      );
      await controller.seekTo(
        Duration(milliseconds: (target.sourceSeconds! * 1000).round()),
      );
      if (wasPlaying) {
        await controller.play();
      } else {
        _schedulePausedFramePrime(controller, source: false);
      }
    }
    if (generation == _timelineSeekGeneration) {
      _liveTimelinePlayheadSeconds.value = target.timelineSeconds;
    }
  }

  void _commitTimelineEditPreview() {
    final preview = _timelineEditPreviewModel.value;
    if (preview == null) return;
    _timelineEditPreviewModel.value = null;
    if (identical(preview, _multiTrackTimeline)) return;
    _commitTimelineModelChange(preview);
  }

  void _commitTimelineModelChange(TimelineModel model) {
    if (identical(model, _multiTrackTimeline)) return;
    _recordEditorHistory('timeline-model-change');
    setState(() {
      _applyTimelineModelUpdate(model);
      _status = 'Multi-track timeline updated';
    });
    final controller = _previewController;
    if (controller != null && controller.value.isInitialized) {
      unawaited(
        controller.setVolume(
          _previewAudioVolume(_effectiveOriginalVolume),
        ),
      );
    }
    unawaited(_autosaveProject());
  }

  Future<void> _selectTimelineMarquee(
    Set<String> itemIds, {
    required bool additive,
  }) async {
    final nextClips =
        additive ? <String>{..._effectiveSelectedTimelineClipIds} : <String>{};
    final nextCaptions =
        additive ? <String>{..._effectiveSelectedCaptionIds} : <String>{};
    var nextMusic = additive && _musicTimelineSelected;
    for (final id in itemIds) {
      if (id == 'music-track') {
        nextMusic = true;
      } else if (id.startsWith('caption:')) {
        nextCaptions.add(id);
      } else if (_multiTrackTimeline.clipById(id) != null) {
        nextClips.add(id);
      }
    }
    final total = nextClips.length + nextCaptions.length + (nextMusic ? 1 : 0);
    if (total == 0) {
      setState(() {
        _selectedTimelineClipIds.clear();
        _selectedCaptionIds.clear();
        _selectedTimelineClipId = null;
        _musicTimelineSelected = false;
        _editorSelection = const EditorSelection.none();
        _status = 'Selection cleared';
      });
      return;
    }
    if (nextClips.isNotEmpty) {
      await _selectMultiTrackClip(nextClips.last);
    } else if (nextCaptions.isNotEmpty) {
      await _selectDynamicTimelineCaption(nextCaptions.last);
    } else if (nextMusic) {
      _selectTimelineMusic();
    }
    if (!mounted) return;
    setState(() {
      _selectedTimelineClipIds
        ..clear()
        ..addAll(nextClips);
      _selectedCaptionIds
        ..clear()
        ..addAll(nextCaptions);
      _selectedTimelineClipId = nextClips.isEmpty ? null : nextClips.last;
      _musicTimelineSelected = nextMusic;
      _status = '$total timeline item${total == 1 ? '' : 's'} selected';
    });
  }

  Future<void> _selectMultiTrackClip(
    String clipId, {
    bool toggle = false,
    bool range = false,
  }) async {
    final result = _multiTrackTimeline.clipById(clipId);
    if (result == null) return;
    final nextSelection = _timelineClipSelectionFor(
      clipId,
      toggle: toggle,
      range: range,
    );
    final primaryId = nextSelection.contains(clipId)
        ? clipId
        : (nextSelection.isEmpty ? null : nextSelection.last);
    if (primaryId == null) {
      setState(() {
        _selectedTimelineClipIds.clear();
        _selectedTimelineClipId = null;
        _editorSelection = const EditorSelection.none();
        _status = 'Selection cleared';
      });
      return;
    }
    final primaryResult = _multiTrackTimeline.clipById(primaryId);
    if (primaryResult == null) return;
    if (result.track.type == TrackType.text) {
      final index = _textOverlays.indexWhere(
        (overlay) =>
            overlay.id == result.clip.mediaPath || overlay.id == clipId,
      );
      if (index >= 0) {
        _selectTextOverlay(index);
        if (!mounted) return;
        setState(() {
          _selectedTimelineClipIds
            ..clear()
            ..addAll(nextSelection);
          if (!toggle && !range) {
            _selectedCaptionIds.clear();
            _musicTimelineSelected = false;
          }
          _selectedTimelineClipId = primaryId;
          _status = nextSelection.length > 1
              ? '${nextSelection.length} timeline clips selected'
              : 'Text clip selected';
        });
      }
      return;
    }
    setState(() {
      _selectedTimelineClipIds
        ..clear()
        ..addAll(nextSelection);
      if (!toggle && !range) {
        _selectedCaptionIds.clear();
        _musicTimelineSelected = false;
      }
      _selectedTimelineClipId = primaryId;
      if (primaryResult.track.type == TrackType.video) {
        _programTimelineClipId = primaryId;
      }
      _editorSelection = primaryResult.track.type == TrackType.audio
          ? EditorSelection.audio(primaryId)
          : EditorSelection.video(primaryId);
      _status = nextSelection.length > 1
          ? '${nextSelection.length} timeline clips selected'
          : '${primaryResult.track.label} clip selected';
    });
    final videoIndex = _videos.indexWhere(
      (video) => video.path == primaryResult.clip.mediaPath,
    );
    if (videoIndex >= 0 && videoIndex != _selectedVideoIndex) {
      await _selectVideo(videoIndex, saveCurrentEdit: false);
      if (mounted) setState(() => _selectedTimelineClipId = primaryId);
    }
    if (primaryResult.track.type == TrackType.video) {
      if (mounted) {
        setState(() {
          _loadTimelineClipTransformIntoInspector(primaryResult.clip);
          _selectedTimelineClipId = primaryId;
          _programTimelineClipId = primaryId;
        });
      }
      final timelineStart = primaryResult.clip.timelineStart;
      _timelineSeekDebounce?.cancel();
      _timelineSeekGeneration++;
      _requestedTimelinePlayheadSeconds.value = timelineStart;
      _liveTimelinePlayheadSeconds.value = timelineStart;
      await _seekProgramPreview(timelineStart);
    }
  }

  void _selectTimelineMusic({bool toggle = false}) {
    setState(() {
      _musicTimelineSelected = toggle ? !_musicTimelineSelected : true;
      if (!toggle) {
        _selectedTimelineClipIds.clear();
        _selectedCaptionIds.clear();
        _selectedTimelineClipId = null;
      }
      _editorSelection = _musicTimelineSelected
          ? const EditorSelection.audio('music-track')
          : const EditorSelection.none();
      _visibleWorkspacePanels.add('inspector');
      _status =
          _musicTimelineSelected ? 'Music track selected' : 'Selection cleared';
    });
  }

  bool _ensureTimelineClipUnlocked(
    String? clipId, {
    String action = 'editing',
  }) {
    if (clipId == null) return true;
    final result = _multiTrackTimeline.clipById(clipId);
    if (result?.track.isLocked != true) return true;
    _showMessage('Unlock ${result!.track.label} before $action.');
    return false;
  }

  void _copySelectedTimelineClip() {
    final selectedIds = _effectiveSelectedTimelineClipIds;
    if (selectedIds.length > 1) {
      final copied = <({
        ClipModel clip,
        TrackType type,
        int trackIndex,
        ClipModel? linkedAudio,
      })>[];
      for (final id in selectedIds) {
        final result = _multiTrackTimeline.clipById(id);
        if (result == null || result.track.type == TrackType.text) continue;
        copied.add((
          clip: result.clip,
          type: result.track.type,
          trackIndex: result.track.index,
          linkedAudio: result.track.type == TrackType.video
              ? _multiTrackTimeline.linkedAudioForVideo(result.clip.id)
              : null,
        ));
      }
      if (copied.isNotEmpty) {
        _timelineMultiClipboard = copied;
        _timelineClipboard = null;
        _textOverlayClipboard = null;
        setState(() => _status = '${copied.length} clips copied');
      }
      return;
    }
    final id = _selectedTimelineClipId;
    if (id == null) return;
    final result = _multiTrackTimeline.clipById(id);
    if (result == null) return;
    if (result.track.type == TrackType.text) {
      _saveSelectedTextOverlay();
      final index = _textOverlays.indexWhere(
        (overlay) => overlay.id == result.clip.id,
      );
      if (index >= 0) {
        _textOverlayClipboard = _textOverlays[index];
        _timelineClipboard = null;
        _timelineMultiClipboard = const [];
      }
    } else {
      _timelineClipboard = (clip: result.clip, type: result.track.type);
      _textOverlayClipboard = null;
      _timelineMultiClipboard = const [];
    }
    setState(() => _status = '${result.track.label} clip copied');
  }

  void _cutSelectedTimelineClip() {
    if (_effectiveSelectedTimelineClipIds.length > 1) {
      final unlocked = _effectiveSelectedTimelineClipIds.where((id) {
        return _multiTrackTimeline.clipById(id)?.track.isLocked != true;
      }).toSet();
      if (unlocked.length != _effectiveSelectedTimelineClipIds.length) {
        _showMessage('Unlock the selected tracks before cutting clips.');
        return;
      }
      _copySelectedTimelineClip();
      _deleteSelectedTimelineItems();
      return;
    }
    final id = _selectedTimelineClipId;
    if (id == null) return;
    if (!_ensureTimelineClipUnlocked(id, action: 'cutting this clip')) return;
    _copySelectedTimelineClip();
    final result = _multiTrackTimeline.clipById(id);
    if (result?.track.type == TrackType.text) {
      final index = _textOverlays.indexWhere((overlay) => overlay.id == id);
      if (index >= 0) _deleteTextOverlayAt(index);
      return;
    }
    _recordEditorHistory('timeline-cut');
    setState(() {
      _multiTrackTimeline = _timelineEditor.deleteClip(_multiTrackTimeline, id);
      _selectedTimelineClipIds.clear();
      _selectedTimelineClipId = null;
      _status = 'Clip cut';
    });
    unawaited(_autosaveProject());
  }

  void _pasteTimelineClipGroup() {
    final copied = _timelineMultiClipboard;
    if (copied.isEmpty) return;
    _recordEditorHistory('timeline-group-paste');
    final earliest =
        copied.map((item) => item.clip.timelineStart).reduce(math.min);
    var next = _multiTrackTimeline;
    final insertedIds = <String>{};
    final stamp = DateTime.now().microsecondsSinceEpoch;
    for (var index = 0; index < copied.length; index++) {
      final item = copied[index];
      TrackModel? target;
      for (final track in next.tracks) {
        if (track.type == item.type &&
            track.index == item.trackIndex &&
            !track.isLocked) {
          target = track;
          break;
        }
      }
      if (target == null) {
        for (final track in next.tracks) {
          if (track.type == item.type && !track.isLocked) {
            target = track;
            break;
          }
        }
      }
      if (target == null) {
        next = _timelineEditor.addTrack(next, item.type);
        target = next.tracks.where((track) => track.type == item.type).last;
      }
      final id = 'clip-$stamp-$index';
      final clip = item.clip.copyWith(
        id: id,
        timelineStart:
            _currentProgramSeconds() + (item.clip.timelineStart - earliest),
        clearReplacesClipId: true,
        clearTransitionIn: true,
      );
      next = _timelineEditor.insertClip(next, trackId: target.id, clip: clip);
      insertedIds.add(id);
      final linked = item.linkedAudio;
      if (linked != null) {
        TrackModel? audioTarget;
        for (final track in next.audioTracks) {
          if (!track.isLocked) {
            audioTarget = track;
            break;
          }
        }
        if (audioTarget == null) {
          next = _timelineEditor.addTrack(next, TrackType.audio);
          audioTarget = next.audioTracks.last;
        }
        next = _timelineEditor.insertClip(
          next,
          trackId: audioTarget.id,
          clip: linked.copyWith(
            id: 'audio-$id',
            timelineStart: clip.timelineStart,
            sourceStart: clip.sourceStart,
            duration: clip.duration,
            isLinkedAudio: true,
            linkedClipId: id,
            clearTransitionIn: true,
          ),
        );
      }
    }
    setState(() {
      _multiTrackTimeline = next.normalized();
      _selectedTimelineClipIds
        ..clear()
        ..addAll(insertedIds);
      _selectedTimelineClipId = insertedIds.isEmpty ? null : insertedIds.last;
      _status = '${insertedIds.length} clips pasted at playhead';
    });
    unawaited(_autosaveProject());
  }

  void _pasteTimelineClip() {
    if (_timelineMultiClipboard.isNotEmpty) {
      _pasteTimelineClipGroup();
      return;
    }
    final text = _textOverlayClipboard;
    if (text != null) {
      _recordEditorHistory('timeline-paste');
      final id = 'text-${DateTime.now().microsecondsSinceEpoch}';
      final copy = text.copyWith(
        id: id,
        timelineStart: _currentProgramSeconds(),
        trackIndex: _nextTextTrackIndex(),
        isLocked: false,
      );
      setState(() {
        if (_textOverlays.length == 1 &&
            _textOverlays.first.text.trim().isEmpty) {
          _textOverlays.clear();
        }
        _textOverlays.add(copy);
        _selectedTextOverlayIndex = _textOverlays.length - 1;
        _loadTextOverlay(copy);
        _insertTextTimelineClip(copy);
        _selectedTimelineClipId = id;
        _editorSelection = EditorSelection.text(id, label: copy.text);
        _status = 'Text pasted at playhead';
      });
      unawaited(_autosaveProject());
      return;
    }
    final copied = _timelineClipboard;
    if (copied == null) return;
    final linkedSource = copied.type == TrackType.video
        ? _multiTrackTimeline.linkedAudioForVideo(copied.clip.id)
        : null;
    _recordEditorHistory('timeline-paste');
    var target = _selectedTimelineClipId == null
        ? null
        : _multiTrackTimeline.clipById(_selectedTimelineClipId!)?.track;
    if (target?.type != copied.type || target?.isLocked == true) {
      target = null;
      for (final track in _multiTrackTimeline.tracks) {
        if (track.type == copied.type && !track.isLocked) {
          target = track;
          break;
        }
      }
    }
    if (target == null) {
      _multiTrackTimeline =
          _timelineEditor.addTrack(_multiTrackTimeline, copied.type);
      target = _multiTrackTimeline.tracks
          .where((track) => track.type == copied.type)
          .last;
    }
    final id = 'clip-${DateTime.now().microsecondsSinceEpoch}';
    final clip = copied.clip.copyWith(
      id: id,
      timelineStart: _currentProgramSeconds(),
      clearReplacesClipId: true,
      clearTransitionIn: true,
    );
    var next = _timelineEditor.insertClip(
      _multiTrackTimeline,
      trackId: target.id,
      clip: clip,
    );
    if (linkedSource != null) {
      var audioTrack = next.audioTracks.firstWhere(
        (track) => !track.isLocked,
        orElse: () => const TrackModel(
          id: '',
          type: TrackType.audio,
          index: 0,
        ),
      );
      if (audioTrack.id.isEmpty) {
        next = _timelineEditor.addTrack(next, TrackType.audio);
        audioTrack = next.audioTracks.last;
      }
      next = _timelineEditor.insertClip(
        next,
        trackId: audioTrack.id,
        clip: linkedSource.copyWith(
          id: 'audio-$id',
          timelineStart: clip.timelineStart,
          sourceStart: clip.sourceStart,
          duration: clip.duration,
          isLinkedAudio: true,
          linkedClipId: id,
          clearTransitionIn: true,
        ),
      );
    }
    setState(() {
      _multiTrackTimeline = next;
      _selectedTimelineClipId = id;
      _status = 'Clip pasted at playhead';
    });
    unawaited(_autosaveProject());
  }

  void _duplicateSelectedTimelineClip() {
    final id = _selectedTimelineClipId;
    if (id == null) return;
    if (!_ensureTimelineClipUnlocked(id, action: 'duplicating this clip')) {
      return;
    }
    final result = _multiTrackTimeline.clipById(id);
    if (result?.track.type == TrackType.text) {
      _duplicateTextOverlay();
      return;
    }
    _copySelectedTimelineClip();
    _pasteTimelineClip();
  }

  void _copySelectedClipAttributes() {
    final id = _selectedTimelineClipId;
    if (id == null) return;
    final clip = _multiTrackTimeline.clipById(id)?.clip;
    if (clip == null) return;
    _timelineAttributeClipboard = (
      transform: clip.transform,
      effects: [...clip.effects],
      keyframes: [...clip.keyframes],
    );
    setState(() => _status = 'Clip attributes copied');
  }

  void _pasteSelectedClipAttributes() {
    final id = _selectedTimelineClipId;
    final attributes = _timelineAttributeClipboard;
    if (id == null || attributes == null) return;
    if (!_ensureTimelineClipUnlocked(id, action: 'changing attributes')) {
      return;
    }
    setState(() {
      var next = _timelineEditor.updateClipTransform(
        _multiTrackTimeline,
        id,
        attributes.transform,
      );
      final result = next.clipById(id);
      if (result != null) {
        next = _timelineEditor.updateTrack(
          next,
          result.track.id,
          (track) => track.copyWith(
            clips: [
              for (final clip in track.clips)
                if (clip.id == id)
                  clip.copyWith(
                    effects: [...attributes.effects],
                    keyframes: [...attributes.keyframes],
                  )
                else
                  clip,
            ],
          ),
        );
      }
      _multiTrackTimeline = next;
      _status = 'Clip attributes pasted';
    });
    unawaited(_autosaveProject());
  }

  void _toggleSelectedTimelineClipActive() {
    final id = _selectedTimelineClipId;
    if (id == null) return;
    final result = _multiTrackTimeline.clipById(id);
    if (result == null) return;
    if (!_ensureTimelineClipUnlocked(id, action: 'changing this clip')) return;
    final nextMuted = !result.clip.isMuted;
    final selectedIds = _effectiveSelectedTimelineClipIds.where((clipId) {
      final selected = _multiTrackTimeline.clipById(clipId);
      return selected != null && !selected.track.isLocked;
    }).toSet();
    if (selectedIds.isEmpty) selectedIds.add(id);
    setState(() {
      _multiTrackTimeline = _multiTrackTimeline.copyWith(
        tracks: [
          for (final track in _multiTrackTimeline.tracks)
            !track.isLocked
                ? track.copyWith(
                    clips: [
                      for (final clip in track.clips)
                        if (selectedIds.contains(clip.id))
                          clip.copyWith(isMuted: nextMuted)
                        else
                          clip,
                    ],
                  )
                : track,
        ],
      );
      _status = selectedIds.length > 1
          ? '${selectedIds.length} clips ${nextMuted ? 'deactivated' : 'activated'}'
          : nextMuted
              ? 'Clip deactivated'
              : 'Clip activated';
    });
    unawaited(_autosaveProject());
  }

  void _extractSelectedClipAudio() {
    final id = _selectedTimelineClipId;
    if (id == null) return;
    final result = _multiTrackTimeline.clipById(id);
    if (result == null || result.track.type != TrackType.video) return;
    if (result.track.isLocked) {
      _showMessage('Unlock ${result.track.label} before extracting audio.');
      return;
    }
    var timeline = _multiTrackTimeline;
    final linkedAudio = timeline.linkedAudioForVideo(result.clip.id);
    if (linkedAudio == null) {
      _showMessage('This video audio is already extracted.');
      return;
    }
    final linkedResult = timeline.clipById(linkedAudio.id);
    if (linkedResult == null) return;
    final extractedId =
        'extracted-audio-${DateTime.now().microsecondsSinceEpoch}';
    timeline = _timelineEditor.updateTrack(
      timeline,
      linkedResult.track.id,
      (track) => track.copyWith(
        clips: [
          for (final clip in track.clips)
            if (clip.id == linkedAudio.id)
              clip.copyWith(
                id: extractedId,
                isLinkedAudio: false,
                clearLinkedClipId: true,
              )
            else
              clip,
        ],
      ),
    );
    final audioTrack = timeline.clipById(extractedId)?.track;
    if (audioTrack == null) {
      timeline = _timelineEditor.addTrack(timeline, TrackType.audio);
      final target = timeline.audioTracks.last;
      timeline = _timelineEditor.insertClip(
        timeline,
        trackId: target.id,
        clip: result.clip.copyWith(
          id: extractedId,
          zIndex: 0,
          volume: _originalVolume,
          isLinkedAudio: false,
          clearLinkedClipId: true,
        ),
      );
    }
    final resolvedTrack = timeline.clipById(extractedId)?.track;
    setState(() {
      _multiTrackTimeline = timeline;
      _selectedTimelineClipId = extractedId;
      _editorSelection = EditorSelection.audio(extractedId);
      _status = 'Audio extracted to ${resolvedTrack?.label ?? 'audio track'}';
    });
    unawaited(_autosaveProject());
  }

  Future<void> _showTimelineClipContextMenu(
    String clipId,
    Offset position,
  ) async {
    final result = _multiTrackTimeline.clipById(clipId);
    if (result == null) return;
    _selectedTimelineClipId = clipId;
    final editable = !result.track.isLocked;
    final overlay = Overlay.of(context).context.findRenderObject() as RenderBox;
    final choice = await showMenu<_TimelineClipAction>(
      context: context,
      position: RelativeRect.fromRect(
        Rect.fromLTWH(position.dx, position.dy, 1, 1),
        Offset.zero & overlay.size,
      ),
      items: [
        const PopupMenuItem(
            value: _TimelineClipAction.copy,
            child: Text('Copy                         Ctrl+C')),
        PopupMenuItem(
            value: _TimelineClipAction.cut,
            enabled: editable,
            child: const Text('Cut                              Ctrl+X')),
        PopupMenuItem(
          value: _TimelineClipAction.paste,
          enabled: _timelineClipboard != null ||
              _timelineMultiClipboard.isNotEmpty ||
              _textOverlayClipboard != null,
          child: const Text('Paste                          Ctrl+V'),
        ),
        PopupMenuItem(
            value: _TimelineClipAction.duplicate,
            enabled: editable,
            child: const Text('Duplicate                    Ctrl+D')),
        const PopupMenuDivider(),
        const PopupMenuItem(
            value: _TimelineClipAction.copyAttributes,
            child: Text('Copy attributes')),
        PopupMenuItem(
          value: _TimelineClipAction.pasteAttributes,
          enabled: editable && _timelineAttributeClipboard != null,
          child: const Text('Paste attributes'),
        ),
        PopupMenuItem(
            value: _TimelineClipAction.split,
            enabled: editable,
            child: const Text('Split at playhead          Ctrl+K')),
        PopupMenuItem(
            value: _TimelineClipAction.delete,
            enabled: editable,
            child: const Text('Delete                         Delete')),
        if (result.track.type == TrackType.video) ...[
          const PopupMenuDivider(),
          PopupMenuItem(
            value: _TimelineClipAction.effects,
            enabled: editable,
            child: const Text('Clip effects'),
          ),
          PopupMenuItem(
              value: _TimelineClipAction.transitions,
              enabled: editable,
              child: const Text('Add transition')),
          const PopupMenuItem(
              value: _TimelineClipAction.captions,
              child: Text('Generate captions')),
          PopupMenuItem(
              value: _TimelineClipAction.extractAudio,
              enabled: editable,
              child: const Text('Extract audio')),
        ],
        const PopupMenuDivider(),
        PopupMenuItem(
          value: _TimelineClipAction.deactivate,
          enabled: editable,
          child:
              Text(result.clip.isMuted ? 'Activate clip' : 'Deactivate clip'),
        ),
        const PopupMenuItem(
            value: _TimelineClipAction.details,
            child: Text('Show in Inspector')),
      ],
    );
    if (choice == null || !mounted) return;
    switch (choice) {
      case _TimelineClipAction.copy:
        _copySelectedTimelineClip();
      case _TimelineClipAction.cut:
        _cutSelectedTimelineClip();
      case _TimelineClipAction.paste:
        _pasteTimelineClip();
      case _TimelineClipAction.duplicate:
        _duplicateSelectedTimelineClip();
      case _TimelineClipAction.copyAttributes:
        _copySelectedClipAttributes();
      case _TimelineClipAction.pasteAttributes:
        _pasteSelectedClipAttributes();
      case _TimelineClipAction.split:
        _splitClipAtPlayhead();
      case _TimelineClipAction.delete:
        _deleteClipPartAtPlayhead();
      case _TimelineClipAction.captions:
        _openLeftWorkspaceTab(LeftWorkspaceTab.captions);
      case _TimelineClipAction.extractAudio:
        _extractSelectedClipAudio();
      case _TimelineClipAction.effects:
        _openEffectsWorkspace(_EffectsWorkspaceCategory.effects);
      case _TimelineClipAction.transitions:
        _openEffectsWorkspace(_EffectsWorkspaceCategory.transitions);
      case _TimelineClipAction.deactivate:
        _toggleSelectedTimelineClipActive();
      case _TimelineClipAction.details:
        unawaited(_selectMultiTrackClip(clipId));
    }
  }

  void _addTimelineMarker() {
    final value = _currentProgramSeconds();
    if (_timelineMarkers.any((marker) => (marker - value).abs() < 0.03)) {
      _showMessage('A marker already exists at this position.');
      return;
    }
    _recordEditorHistory('marker-add');
    setState(() {
      _timelineMarkers.add(value);
      _timelineMarkers.sort();
      _status = 'Marker added at ${_formatDuration(value)}';
    });
    unawaited(_autosaveProject());
  }

