  double _timelinePlayheadOffset() {
    if (_hasAuthoritativeProgramTimeline) {
      return (_currentProgramSeconds() * _timelinePixelsPerSecond())
          .clamp(0.0, _timelineContentWidth())
          .toDouble();
    }
    var offset = 0.0;
    for (final item in _visibleTimelineVideos()) {
      final index = item.index;
      final video = item.video;
      final parts = _clipTimelineEditFor(video.path).timelineParts(
        video.durationSeconds,
      );
      if (index < _selectedVideoIndex) {
        offset += parts.fold<double>(
          0,
          (sum, part) => sum + _timelinePartWidth(part),
        );
        continue;
      }
      if (index == _selectedVideoIndex) {
        final position = _currentPlayheadSeconds();
        if (parts.isEmpty) return offset;
        for (var partIndex = 0; partIndex < parts.length; partIndex++) {
          final part = parts[partIndex];
          final width = _timelinePartWidth(part);
          if (position < part.start - 0.001 || position > part.end + 0.001) {
            offset += width;
            continue;
          }
          final duration = (part.end - part.start).abs() <= 0.001
              ? 1.0
              : part.end - part.start;
          final localProgress =
              ((position - part.start) / duration).clamp(0.0, 1.0).toDouble();
          return offset + width * localProgress;
        }
        return offset.clamp(0.0, _timelineContentWidth());
      }
    }
    return offset;
  }

  double _timelineSequenceDuration() {
    if (_multiTrackTimeline.duration > 0.001) {
      return _multiTrackTimeline.duration;
    }
    return _visibleTimelineVideos().fold<double>(0, (sum, item) {
      final video = item.video;
      final parts = _clipTimelineEditFor(video.path).timelineParts(
        video.durationSeconds,
      );
      return sum +
          parts.fold<double>(
            0,
            (partSum, part) => partSum + (part.end - part.start).abs(),
          );
    });
  }

  Future<void> _seekTimelineAt(double timelineX) async {
    if (_videos.isEmpty) return;
    if (_hasAuthoritativeProgramTimeline) {
      final timelineSeconds = timelineX.clamp(0.0, double.infinity).toDouble() /
          _timelinePixelsPerSecond();
      _requestMultiTrackTimelineSeek(timelineSeconds);
      return;
    }
    final target = _timelinePositionForOffset(timelineX);
    if (target == null) return;
    final wasPlaying = _previewController?.value.isPlaying == true;
    if (target.videoIndex != _selectedVideoIndex) {
      await _selectVideo(target.videoIndex);
    }
    final controller = _previewController;
    if (controller != null && controller.value.isInitialized) {
      await controller.seekTo(
        Duration(milliseconds: (target.seconds * 1000).round()),
      );
      if (wasPlaying) {
        await controller.play();
      }
    }
    if (mounted) setState(() {});
  }

  ({int videoIndex, double seconds})? _timelinePositionForOffset(double x) {
    var remaining = x.clamp(0.0, double.infinity).toDouble();
    final visibleVideos = _visibleTimelineVideos();
    for (final item in visibleVideos) {
      final index = item.index;
      final video = item.video;
      final parts = _clipTimelineEditFor(video.path).timelineParts(
        video.durationSeconds,
      );
      for (final part in parts) {
        final width = _timelinePartWidth(part);
        if (remaining <= width) {
          final duration = (part.end - part.start).abs() <= 0.001
              ? 1.0
              : part.end - part.start;
          final progress = (remaining / width).clamp(0.0, 1.0).toDouble();
          return (videoIndex: index, seconds: part.start + duration * progress);
        }
        remaining -= width;
      }
    }
    final lastIndex =
        visibleVideos.isEmpty ? _videos.length - 1 : visibleVideos.last.index;
    return (
      videoIndex: lastIndex,
      seconds: _videos[lastIndex].durationSeconds ?? 0,
    );
  }

  ({int videoIndex, double seconds})? _timelinePositionForSequenceSeconds(
    double seconds,
  ) {
    if (_videos.isEmpty) return null;
    var remaining = seconds.clamp(0.0, double.infinity).toDouble();
    final visibleVideos = _visibleTimelineVideos();
    for (final item in visibleVideos) {
      final index = item.index;
      final video = item.video;
      final parts = _clipTimelineEditFor(video.path).timelineParts(
        video.durationSeconds,
      );
      for (final part in parts) {
        final duration = (part.end - part.start).abs();
        if (remaining <= duration) {
          return (
            videoIndex: index,
            seconds: part.start + remaining.clamp(0.0, duration),
          );
        }
        remaining -= duration;
      }
    }
    for (final item in visibleVideos.reversed) {
      final index = item.index;
      final video = item.video;
      final parts = _clipTimelineEditFor(video.path).timelineParts(
        video.durationSeconds,
      );
      if (parts.isNotEmpty) {
        return (videoIndex: index, seconds: parts.last.end);
      }
    }
    final lastIndex =
        visibleVideos.isEmpty ? _videos.length - 1 : visibleVideos.last.index;
    return (
      videoIndex: lastIndex,
      seconds: _videos[lastIndex].durationSeconds ?? 0,
    );
  }

  ({
    int videoIndex,
    double? sourceSeconds,
    String? clipId,
    double timelineSeconds,
    bool isGap,
  })? _programTargetForTimelineSeconds(double seconds) {
    if (_videos.isEmpty) return null;
    final playhead = seconds.clamp(0.0, double.infinity).toDouble();
    if (_hasAuthoritativeProgramTimeline) {
      final resolved = ProgramTimelineMapper.resolve(
        _multiTrackTimeline,
        playhead,
      );
      final clip = resolved.clip;
      if (clip == null) {
        return (
          videoIndex: _selectedVideoIndex.clamp(0, _videos.length - 1).toInt(),
          sourceSeconds: null,
          clipId: null,
          timelineSeconds: resolved.timelineSeconds,
          isGap: true,
        );
      }
      final videoIndex =
          _videos.indexWhere((video) => video.path == clip.mediaPath);
      if (videoIndex >= 0) {
        return (
          videoIndex: videoIndex,
          sourceSeconds: resolved.sourceSeconds,
          clipId: clip.id,
          timelineSeconds: resolved.timelineSeconds,
          isGap: false,
        );
      }
      return (
        videoIndex: _selectedVideoIndex.clamp(0, _videos.length - 1).toInt(),
        sourceSeconds: null,
        clipId: null,
        timelineSeconds: resolved.timelineSeconds,
        isGap: true,
      );
    }

    final legacy = _timelinePositionForSequenceSeconds(playhead);
    if (legacy == null) return null;
    return (
      videoIndex: legacy.videoIndex,
      sourceSeconds: legacy.seconds,
      clipId: null,
      timelineSeconds: playhead,
      isGap: false,
    );
  }

  double _currentPlayheadSeconds() {
    final controller = _previewController;
    if (controller == null || !controller.value.isInitialized) {
      return 0;
    }
    return controller.value.position.inMilliseconds / 1000;
  }

  Future<void> _nudgePlayhead(double deltaSeconds) async {
    if (_videos.isEmpty) return;
    final duration = _programPlaybackDurationSeconds();
    final target = (_currentProgramSeconds() + deltaSeconds)
        .clamp(0.0, math.max(0.0, duration))
        .toDouble();
    _requestMultiTrackTimelineSeek(target);
  }

  ({TrackModel track, ClipModel clip})? _editableClipAtProgramPlayhead(
    double playhead,
  ) {
    bool contains(ClipModel clip) =>
        playhead > clip.timelineStart + 0.04 &&
        playhead < clip.timelineEnd - 0.04;

    final selectedId = _selectedTimelineClipId;
    if (selectedId != null) {
      final selected = _multiTrackTimeline.clipById(selectedId);
      if (selected != null &&
          selected.track.type != TrackType.text &&
          !selected.track.isLocked &&
          contains(selected.clip)) {
        return selected;
      }
    }

    // When selection is stale or empty, edit the visible unlocked video under
    // the blue program playhead. Higher video layers win, matching preview.
    for (final track in _multiTrackTimeline.videoTracks.reversed) {
      if (track.isLocked) continue;
      for (final clip in track.clips.reversed) {
        if (contains(clip)) return (track: track, clip: clip);
      }
    }
    for (final track in _multiTrackTimeline.audioTracks.reversed) {
      if (track.isLocked) continue;
      for (final clip in track.clips.reversed) {
        if (!clip.isLinkedAudio && contains(clip)) {
          return (track: track, clip: clip);
        }
      }
    }
    return null;
  }

  void _cutClipStartAtPlayhead() {
    if (_videos.isEmpty) return;
    final playhead = _currentProgramSeconds();
    final selected = _editableClipAtProgramPlayhead(playhead);
    if (selected != null) {
      final keptId = '${selected.clip.id}-b-${(playhead * 1000).round()}';
      _recordEditorHistory('timeline-trim-start');
      setState(() {
        final next = _timelineEditor.keepClipAfterPlayhead(
          _multiTrackTimeline,
          clipId: selected.clip.id,
          playhead: playhead,
        );
        _applyTimelineModelUpdate(next);
        _selectedTimelineClipId = next.clipById(keptId) == null ? null : keptId;
        _selectedTimelineClipIds
          ..clear()
          ..addAll(_selectedTimelineClipId == null
              ? const <String>[]
              : [_selectedTimelineClipId!]);
        if (selected.track.type == TrackType.video) {
          _programTimelineClipId = _selectedTimelineClipId;
        }
        _status =
            'Removed ${_formatDuration(playhead - selected.clip.timelineStart)} before the playhead';
      });
      unawaited(_autosaveProject());
      return;
    }
    if (_hasAuthoritativeProgramTimeline) {
      _showMessage('Move the blue playhead inside an unlocked video clip.');
      return;
    }
    if (!_ensureTimelineClipUnlocked(
      _selectedTimelineClipId,
      action: 'trimming this clip',
    )) {
      return;
    }
    final seconds = _currentPlayheadSeconds();
    final video = _videos[_selectedVideoIndex];
    final current = _clipTimelineEditFor(video.path);
    final duration = video.durationSeconds ?? 0;
    final end = current.trimEndSeconds > current.trimStartSeconds
        ? current.trimEndSeconds
        : duration;
    if (end > 0 && seconds >= end - 0.05) {
      _showMessage('Move the playhead before the current clip end.');
      return;
    }
    _setSelectedClipTimelineEdit(
      current.copyWith(trimStartSeconds: seconds),
    );
    setState(() => _status = 'Trimmed start to ${_formatDuration(seconds)}');
  }

  void _cutClipEndAtPlayhead() {
    if (_videos.isEmpty) return;
    final playhead = _currentProgramSeconds();
    final selected = _editableClipAtProgramPlayhead(playhead);
    if (selected != null) {
      final keptId = '${selected.clip.id}-a-${(playhead * 1000).round()}';
      _recordEditorHistory('timeline-trim-end');
      setState(() {
        final next = _timelineEditor.keepClipBeforePlayhead(
          _multiTrackTimeline,
          clipId: selected.clip.id,
          playhead: playhead,
        );
        _applyTimelineModelUpdate(next);
        _selectedTimelineClipId = next.clipById(keptId) == null ? null : keptId;
        _selectedTimelineClipIds
          ..clear()
          ..addAll(_selectedTimelineClipId == null
              ? const <String>[]
              : [_selectedTimelineClipId!]);
        if (selected.track.type == TrackType.video) {
          _programTimelineClipId = _selectedTimelineClipId;
        }
        _status =
            'Removed ${_formatDuration(selected.clip.timelineEnd - playhead)} after the playhead';
      });
      unawaited(_autosaveProject());
      return;
    }
    if (_hasAuthoritativeProgramTimeline) {
      _showMessage('Move the blue playhead inside an unlocked video clip.');
      return;
    }
    if (!_ensureTimelineClipUnlocked(
      _selectedTimelineClipId,
      action: 'trimming this clip',
    )) {
      return;
    }
    final seconds = _currentPlayheadSeconds();
    final current = _clipTimelineEditFor(_videos[_selectedVideoIndex].path);
    if (seconds <= current.trimStartSeconds + 0.05) {
      _showMessage('Move the playhead after the current clip start.');
      return;
    }
    _setSelectedClipTimelineEdit(
      current.copyWith(trimEndSeconds: seconds),
    );
    setState(() => _status = 'Trimmed end to ${_formatDuration(seconds)}');
  }

  void _splitClipAtPlayhead() {
    if (_videos.isEmpty) return;
    final selectedIds = _effectiveSelectedTimelineClipIds;
    if (selectedIds.length > 1) {
      final playhead = _currentProgramSeconds();
      var next = _multiTrackTimeline;
      final nextSelected = <String>{};
      var splitCount = 0;
      for (final id in selectedIds) {
        final result = next.clipById(id);
        if (result == null ||
            result.track.type == TrackType.text ||
            result.track.isLocked ||
            playhead <= result.clip.timelineStart + 0.04 ||
            playhead >= result.clip.timelineEnd - 0.04) {
          nextSelected.add(id);
          continue;
        }
        next = _timelineEditor.splitClip(
          next,
          clipId: id,
          playhead: playhead,
        );
        nextSelected.add('$id-a-${(playhead * 1000).round()}');
        splitCount++;
      }
      if (splitCount == 0) {
        _showMessage('Move the playhead inside the selected unlocked clips.');
        return;
      }
      _recordEditorHistory('timeline-multi-split');
      setState(() {
        _multiTrackTimeline = next;
        _selectedTimelineClipIds
          ..clear()
          ..addAll(nextSelected.where(
            (id) => next.clipById(id) != null,
          ));
        _selectedTimelineClipId = _selectedTimelineClipIds.isEmpty
            ? null
            : _selectedTimelineClipIds.last;
        _status = '$splitCount clips split at ${_formatDuration(playhead)}';
      });
      unawaited(_autosaveProject());
      return;
    }
    final playhead = _currentProgramSeconds();
    final selectedTimelineClip = _editableClipAtProgramPlayhead(playhead);
    if (selectedTimelineClip?.track.type == TrackType.text) {
      _showMessage(
          'Resize text timing with the handles on its timeline block.');
      return;
    }
    if (selectedTimelineClip != null) {
      if (!_ensureTimelineClipUnlocked(
        selectedTimelineClip.clip.id,
        action: 'splitting this clip',
      )) {
        return;
      }
      final next = _timelineEditor.splitClip(
        _multiTrackTimeline,
        clipId: selectedTimelineClip.clip.id,
        playhead: playhead,
      );
      if (identical(next, _multiTrackTimeline)) {
        _showMessage('Move the playhead inside the selected timeline clip.');
        return;
      }
      _recordEditorHistory('timeline-split');
      setState(() {
        _multiTrackTimeline = next;
        _selectedTimelineClipId =
            '${selectedTimelineClip.clip.id}-a-${(playhead * 1000).round()}';
        if (selectedTimelineClip.track.type == TrackType.video) {
          _programTimelineClipId = _selectedTimelineClipId;
        }
        _status = 'Clip split at ${_formatDuration(playhead)}';
      });
      unawaited(_autosaveProject());
      return;
    }
    if (_hasAuthoritativeProgramTimeline) {
      _showMessage('Move the blue playhead inside an unlocked video clip.');
      return;
    }
    final seconds = _currentPlayheadSeconds();
    if (seconds <= 0.05) return;
    final video = _videos[_selectedVideoIndex];
    final duration = video.durationSeconds ?? 0;
    if (duration > 0 && seconds >= duration - 0.05) return;
    final current = _clipTimelineEditFor(video.path);
    if (current.timelinePartAt(seconds, video.durationSeconds) == null) {
      _showMessage('Move the playhead onto a visible clip before splitting.');
      return;
    }
    if (current.splitPoints.any((point) => (point - seconds).abs() < 0.03)) {
      _showMessage('A split already exists at this position.');
      return;
    }
    final points = {...current.splitPoints, seconds}.toList()..sort();
    _setSelectedClipTimelineEdit(current.copyWith(splitPoints: points));
    setState(() => _status = 'Split at ${_formatDuration(seconds)}');
  }

  bool _deleteSelectedTimelineItems() {
    final captionIds = _effectiveSelectedCaptionIds;
    if (_editorSelection.kind == EditorSelectionKind.captionCue &&
        captionIds.isNotEmpty) {
      if (_captionTrackLocked) {
        _showMessage('Unlock T1 before deleting captions.');
        return true;
      }
      _recordEditorHistory('caption-multi-delete');
      final removals = <String, List<int>>{};
      for (final id in captionIds) {
        if (!id.startsWith('caption:')) continue;
        final separator = id.lastIndexOf(':');
        if (separator <= 'caption:'.length) continue;
        final path = Uri.decodeComponent(
          id.substring('caption:'.length, separator),
        );
        final index = int.tryParse(id.substring(separator + 1));
        if (index != null) removals.putIfAbsent(path, () => []).add(index);
      }
      setState(() {
        var removed = 0;
        for (final entry in removals.entries) {
          final cues = [...?_captionCuesByVideo[entry.key]];
          final indexes = entry.value.toSet().toList()
            ..sort((a, b) => b.compareTo(a));
          for (final index in indexes) {
            if (index >= 0 && index < cues.length) {
              cues.removeAt(index);
              removed++;
            }
          }
          _captionCuesByVideo[entry.key] = cues;
        }
        _selectedCaptionIds.clear();
        _selectedCaptionCueIndex = 0;
        _editorSelection = const EditorSelection.none();
        _status = '$removed caption clip${removed == 1 ? '' : 's'} deleted';
      });
      unawaited(_autosaveProject());
      return true;
    }

    final selectedIds = _effectiveSelectedTimelineClipIds;
    if (selectedIds.length <= 1) {
      if (_musicTimelineSelected) {
        unawaited(_deleteMusicTimelineTrack());
        return true;
      }
      return false;
    }
    final deletable = <String>[];
    final textIds = <String>{};
    for (final id in selectedIds) {
      final result = _multiTrackTimeline.clipById(id);
      if (result == null || result.track.isLocked) continue;
      deletable.add(id);
      if (result.track.type == TrackType.text) {
        textIds.addAll([result.clip.id, result.clip.mediaPath]);
      }
    }
    if (deletable.isEmpty) {
      _showMessage('Unlock the selected tracks before deleting clips.');
      return true;
    }
    _recordEditorHistory('timeline-multi-delete');
    var next = _multiTrackTimeline;
    for (final id in deletable) {
      next = _timelineEditor.deleteClip(next, id);
    }
    setState(() {
      _multiTrackTimeline = next.normalized();
      if (textIds.isNotEmpty) {
        _textOverlays.removeWhere(
          (overlay) => textIds.contains(overlay.id),
        );
        if (_textOverlays.isEmpty) {
          _textOverlays.add(const _TextOverlayDraft());
        }
      }
      _selectedTimelineClipIds.clear();
      _selectedTimelineClipId = null;
      _programTimelineClipId = null;
      _editorSelection = const EditorSelection.none();
      _status = '${deletable.length} timeline clips deleted';
    });
    unawaited(_autosaveProject());
    return true;
  }

  void _deleteClipPartAtPlayhead() {
    if (_deleteSelectedTimelineItems()) return;
    if (_videos.isEmpty) return;
    final selectedTimelineClip = _selectedTimelineClipId == null
        ? null
        : _multiTrackTimeline.clipById(_selectedTimelineClipId!);
    if (selectedTimelineClip?.track.type == TrackType.text) {
      if (!_ensureTimelineClipUnlocked(
        selectedTimelineClip!.clip.id,
        action: 'deleting this text',
      )) {
        return;
      }
      final index = _textOverlays.indexWhere(
        (overlay) => overlay.id == selectedTimelineClip.clip.id,
      );
      if (index >= 0) _deleteTextOverlayAt(index);
      return;
    }
    if (selectedTimelineClip != null) {
      if (!_ensureTimelineClipUnlocked(
        selectedTimelineClip.clip.id,
        action: 'deleting this clip',
      )) {
        return;
      }
      _recordEditorHistory('timeline-delete');
      setState(() {
        _multiTrackTimeline = _timelineEditor.deleteClip(
          _multiTrackTimeline,
          selectedTimelineClip.clip.id,
        );
        _selectedTimelineClipIds.clear();
        _selectedTimelineClipId = null;
        if (_programTimelineClipId == selectedTimelineClip.clip.id) {
          _programTimelineClipId = null;
        }
        _status = 'Clip deleted';
      });
      unawaited(_autosaveProject());
      return;
    }
    final video = _videos[_selectedVideoIndex];
    final current = _clipTimelineEditFor(video.path);
    final part = current.timelinePartAt(
      _currentPlayheadSeconds(),
      video.durationSeconds,
    );
    if (part == null) return;
    _setSelectedClipTimelineEdit(
      current.copyWith(
        deletedRanges: [
          ...current.deletedRanges,
          (start: part.start, end: part.end),
        ],
      ),
    );
    setState(() {
      _status = 'Deleted ${_formatDuration(part.end - part.start)} section';
    });
  }

  void _beginTimelineTrim() {
    if (_videos.isEmpty || _activeTimelineTrimOriginal != null) return;
    if (!_ensureTimelineClipUnlocked(
      _selectedTimelineClipId,
      action: 'trimming this clip',
    )) {
      return;
    }
    final path = _videos[_selectedVideoIndex].path;
    _activeTimelineTrimPath = path;
    _activeTimelineTrimOriginal = _clipTimelineEditFor(path);
  }

  void _updateTimelineTrim({
    required bool startEdge,
    required double deltaPixels,
  }) {
    final path = _activeTimelineTrimPath;
    if (path == null || _videos.isEmpty) return;
    final index = _videos.indexWhere((video) => video.path == path);
    if (index < 0) return;
    final video = _videos[index];
    final duration = video.durationSeconds ?? 0;
    if (duration <= 0) return;
    final edit = _clipTimelineEditFor(path);
    final deltaSeconds = deltaPixels / _timelinePixelsPerSecond();
    final start = edit.trimStartSeconds.clamp(0.0, duration).toDouble();
    final end = edit.trimEndSeconds > start
        ? edit.trimEndSeconds.clamp(start, duration).toDouble()
        : duration;
    final minimumDuration = math.min(0.05, duration);
    final maximumStart = math.max(0.0, end - minimumDuration);
    final minimumEnd = math.min(duration, start + minimumDuration);
    final next = startEdge
        ? edit.copyWith(
            trimStartSeconds:
                (start + deltaSeconds).clamp(0.0, maximumStart).toDouble(),
          )
        : edit.copyWith(
            trimEndSeconds:
                (end + deltaSeconds).clamp(minimumEnd, duration).toDouble(),
          );
    setState(() => _setClipTimelineEditWithoutHistory(path, next));
    final previewSeconds = startEdge
        ? next.trimStartSeconds
        : next.trimEndSeconds > 0
            ? next.trimEndSeconds
            : duration;
    final controller = _previewController;
    if (controller != null && controller.value.isInitialized) {
      unawaited(controller.seekTo(
        Duration(milliseconds: (previewSeconds * 1000).round()),
      ));
    }
  }

  void _endTimelineTrim() {
    final path = _activeTimelineTrimPath;
    final original = _activeTimelineTrimOriginal;
    _activeTimelineTrimPath = null;
    _activeTimelineTrimOriginal = null;
    if (path == null || original == null) return;
    final current = _clipTimelineEditFor(path);
    if (current.sameAs(original)) return;
    setState(() {
      _clipTimelineUndoStacks.putIfAbsent(path, () => []).add(original);
      _clipTimelineRedoStacks[path]?.clear();
      _status = 'Clip edge trimmed — Ctrl+Z to undo';
    });
  }

  void _moveSelectedClipPart({
    required int fromVisualIndex,
    required int toVisualIndex,
  }) {
    if (_videos.isEmpty || fromVisualIndex == toVisualIndex) return;
    final video = _videos[_selectedVideoIndex];
    final current = _clipTimelineEditFor(video.path);
    final parts = current.timelineParts(video.durationSeconds);
    if (fromVisualIndex < 0 ||
        fromVisualIndex >= parts.length ||
        toVisualIndex < 0 ||
        toVisualIndex >= parts.length) {
      return;
    }
    final keys = parts.map(_timelinePartKey).toList();
    final moved = keys.removeAt(fromVisualIndex);
    keys.insert(toVisualIndex, moved);
    _setSelectedClipTimelineEdit(current.copyWith(partOrder: keys));
  }

  double _timelinePartKey(({double start, double end}) part) {
    return double.parse(part.start.toStringAsFixed(3));
  }

  void _setSelectedClipTimelineEdit(_ClipTimelineEdit edit) {
    if (_videos.isEmpty) return;
    final selectedId = _selectedTimelineClipId;
    final selected =
        selectedId == null ? null : _multiTrackTimeline.clipById(selectedId);
    if (selected?.track.isLocked == true) {
      _showMessage('Unlock ${selected!.track.label} before editing.');
      return;
    }
    final path = _videos[_selectedVideoIndex].path;
    final current = _clipTimelineEditFor(path);
    if (current.sameAs(edit)) return;
    _recordEditorHistory('clip-edit');
    setState(() {
      _clipTimelineUndoStacks.putIfAbsent(path, () => []).add(current);
      _clipTimelineRedoStacks[path]?.clear();
      _setClipTimelineEditWithoutHistory(path, edit);
    });
    unawaited(_seekPreviewToPlayablePosition(preferNext: true));
  }

  void _setClipTimelineEditWithoutHistory(String path, _ClipTimelineEdit edit) {
    _clipTimelineEdits[path] = edit;
    if (_videos.isNotEmpty && _videos[_selectedVideoIndex].path == path) {
      _applyClipTimelineEdit(edit);
    }
    if (edit.hasStructuralTimelineEdit) {
      _syncMultiTrackFromLegacy(preferredMediaPath: path);
      return;
    }
    final selectedId = _selectedTimelineClipId;
    final selected =
        selectedId == null ? null : _multiTrackTimeline.clipById(selectedId);
    if (selected != null &&
        selected.track.type == TrackType.video &&
        selected.clip.mediaPath == path) {
      final sourceStart = math.max(0, edit.trimStartSeconds).toDouble();
      final requestedEnd = edit.trimEndSeconds > sourceStart
          ? edit.trimEndSeconds
          : selected.clip.sourceEnd;
      final duration = math.max(0.001, requestedEnd - sourceStart).toDouble();
      final transform = selected.clip.transform.copyWith(
        scaleX: edit.scaleX * edit.zoom,
        scaleY: edit.scaleY * edit.zoom,
        positionX: (0.5 + edit.panX * 0.5).clamp(0, 1).toDouble(),
        positionY: (0.5 + edit.panY * 0.5).clamp(0, 1).toDouble(),
      );
      final linkedAudioId =
          _multiTrackTimeline.linkedAudioForVideo(selected.clip.id)?.id;
      _multiTrackTimeline = _multiTrackTimeline.copyWith(
        tracks: [
          for (final track in _multiTrackTimeline.tracks)
            track.copyWith(
              clips: [
                for (final clip in track.clips)
                  if (clip.id == selected.clip.id ||
                      (linkedAudioId != null && clip.id == linkedAudioId))
                    clip.copyWith(
                      sourceStart: sourceStart,
                      duration: duration,
                      transform: clip.id == selected.clip.id
                          ? transform
                          : clip.transform,
                    )
                  else
                    clip,
              ],
            ),
        ],
      ).normalized();
      return;
    }
    // Legacy projects without a selected timeline block still use the older
    // per-file edit conversion for backward compatibility.
    _syncMultiTrackFromLegacy();
  }

  Widget _timelineCaptionClips() {
    return _timelineClipStrip(
      children: [
        for (final entry in _visibleTimelineVideos())
          ..._timelineCaptionParts(entry.video),
      ],
    );
  }

  List<Widget> _timelineCaptionParts(PickedVideo video) {
    final parts = _clipTimelineEditFor(video.path).timelineParts(
      video.durationSeconds,
    );
    final cues = _captionCuesByVideo[video.path] ?? const <_CaptionCue>[];
    return [
      for (final part in parts)
        Builder(
          builder: (context) {
            final width = _timelinePartWidth(part);
            final duration = math.max(0.001, part.end - part.start);
            final visibleCues = cues
                .where((cue) => cue.end > part.start && cue.start < part.end)
                .toList();
            return SizedBox(
              width: width,
              child: Stack(
                clipBehavior: Clip.hardEdge,
                children: [
                  if (visibleCues.isEmpty && _isGeneratingCaptions)
                    const Positioned.fill(
                      child: Center(
                        child: SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        ),
                      ),
                    ),
                  for (final cue in visibleCues)
                    Positioned(
                      left: ((math.max(cue.start, part.start) - part.start) /
                              duration *
                              width)
                          .clamp(0.0, width)
                          .toDouble(),
                      width: (((math.min(cue.end, part.end) -
                                      math.max(cue.start, part.start)) /
                                  duration *
                                  width)
                              .clamp(8.0, width))
                          .toDouble(),
                      top: 3,
                      bottom: 5,
                      child: GestureDetector(
                        onTap: () => unawaited(_focusCaptionCue(video, cue)),
                        onDoubleTap: () => unawaited(
                          _focusCaptionCue(video, cue, edit: true),
                        ),
                        child: Container(
                          padding: const EdgeInsets.symmetric(horizontal: 4),
                          decoration: BoxDecoration(
                            color: const Color(0xffc2410c),
                            borderRadius: BorderRadius.circular(3),
                            border: Border.all(
                              color: video.path ==
                                          _videos[_selectedVideoIndex].path &&
                                      cues.indexOf(cue) ==
                                          _selectedCaptionCueIndex
                                  ? Colors.white
                                  : const Color(0xfffb923c),
                              width: 1.5,
                            ),
                          ),
                          alignment: Alignment.centerLeft,
                          child: KText(
                            cue.text,
                            maxLines: 1,
                            overflow: TextOverflow.clip,
                            style: const TextStyle(
                              color: Colors.white,
                              fontSize: 9,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ),
                      ),
                    ),
                ],
              ),
            );
          },
        ),
    ];
  }

  Future<void> _focusCaptionCue(
    PickedVideo video,
    _CaptionCue cue, {
    bool edit = false,
  }) async {
    final videoIndex = _videos.indexWhere((item) => item.path == video.path);
    if (videoIndex < 0) return;
    if (_selectedVideoIndex != videoIndex) {
      await _selectVideo(videoIndex);
      if (!mounted) return;
    }
    final cues = _captionCuesByVideo[video.path] ?? const <_CaptionCue>[];
    final cueIndex = cues.indexOf(cue);
    if (cueIndex < 0) return;
    setState(() {
      _selectedCaptionCueIndex = cueIndex;
      _editorSelection = EditorSelection.caption(
        _captionTimelineId(video.path, cueIndex),
        label: cue.text,
      );
      _visibleWorkspacePanels.add('inspector');
    });
    if (edit) await _showCaptionCueEditor(index: cueIndex);
  }

  Widget _timelineVideoClips() {
    return Opacity(
      opacity: _videoTrackHidden ? 0.35 : 1,
      child: _timelineClipStrip(
        children: [
          for (final entry in _visibleTimelineVideos())
            ..._timelineClipParts(
              entry.video,
              entry.index,
              color: entry.index == _selectedVideoIndex
                  ? const Color(0xff60a5fa)
                  : const Color(0xff93c5fd),
            ),
        ],
      ),
    );
  }

  Widget _timelineAudioClips({bool extracted = false}) {
    return _timelineClipStrip(
      children: [
        for (final entry in _visibleTimelineVideos())
          ..._timelineClipParts(
            entry.video,
            entry.index,
            color:
                extracted ? const Color(0xffa78bfa) : const Color(0xff38bdf8),
            audio: true,
            extractedAudio: extracted,
          ),
      ],
    );
  }

  Widget _timelineClipStrip({required List<Widget> children}) {
    return LayoutBuilder(
      builder: (context, constraints) {
        return SizedBox(
          width: constraints.maxWidth,
          child: ClipRect(
            child: SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              physics: const NeverScrollableScrollPhysics(),
              clipBehavior: Clip.hardEdge,
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: children,
              ),
            ),
          ),
        );
      },
    );
  }

  List<Widget> _timelineClipParts(
    PickedVideo video,
    int index, {
    required Color color,
    bool audio = false,
    bool extractedAudio = false,
  }) {
    final edit = _clipTimelineEditFor(video.path);
    final parts = edit.timelineParts(video.durationSeconds);
    final hasEdit = edit.hasEdit(video.durationSeconds);
    return [
      for (var partIndex = 0; partIndex < parts.length; partIndex++)
        _timelineClipPartDropTarget(
          video: video,
          visualPartIndex: partIndex,
          enabled: _clipEditMode && !audio && index == _selectedVideoIndex,
          child: _timelineClip(
            video,
            index,
            color: color,
            audio: audio,
            partIndex: parts.length > 1 ? partIndex + 1 : null,
            edited: hasEdit,
            trimOnly: hasEdit && parts.length == 1,
            width: _timelinePartWidth(parts[partIndex]),
            extractedAudio: extractedAudio,
            draggable: _clipEditMode &&
                !audio &&
                index == _selectedVideoIndex &&
                parts.length > 1,
            timelinePart: parts[partIndex],
            visualPartIndex: partIndex,
            showStartTrimHandle: _clipEditMode &&
                !audio &&
                index == _selectedVideoIndex &&
                partIndex == 0,
            showEndTrimHandle: _clipEditMode &&
                !audio &&
                index == _selectedVideoIndex &&
                partIndex == parts.length - 1,
          ),
        ),
    ];
  }

  Widget _timelineClipPartDropTarget({
    required PickedVideo video,
    required int visualPartIndex,
    required bool enabled,
    required Widget child,
  }) {
    if (!enabled) return child;
    return DragTarget<_TimelinePartDrag>(
      onWillAcceptWithDetails: (details) =>
          details.data.videoPath == video.path &&
          details.data.visualPartIndex != visualPartIndex,
      onAcceptWithDetails: (details) {
        _moveSelectedClipPart(
          fromVisualIndex: details.data.visualPartIndex,
          toVisualIndex: visualPartIndex,
        );
      },
      builder: (context, candidateData, rejectedData) {
        final active = candidateData.isNotEmpty;
        return AnimatedContainer(
          duration: const Duration(milliseconds: 120),
          decoration: BoxDecoration(
            border: active
                ? Border.all(color: const Color(0xfffacc15), width: 2)
                : null,
          ),
          child: child,
        );
      },
    );
  }

  Widget _timelineClip(
    PickedVideo video,
    int index, {
    required Color color,
    bool audio = false,
    bool extractedAudio = false,
    int? partIndex,
    bool edited = false,
    bool trimOnly = false,
    double width = 124,
    bool draggable = false,
    ({double start, double end})? timelinePart,
    int? visualPartIndex,
    bool showStartTrimHandle = false,
    bool showEndTrimHandle = false,
  }) {
    final compactClip = width < 52;
    final hasFilmstrip = !audio &&
        (video.timelineThumbnailPaths.isNotEmpty ||
            video.thumbnailPath != null);
    final showText = width >= 72;
    final showContent = width >= 30;
    final showEditIcon = edited && !audio && width >= 44;
    final clip = InkWell(
      onTap: () => _selectVideo(index),
      child: Container(
        width: width,
        margin: const EdgeInsets.symmetric(vertical: 5),
        padding: EdgeInsets.zero,
        decoration: BoxDecoration(
          color: color.withOpacity(audio ? 0.45 : 0.68),
          borderRadius: BorderRadius.circular(3),
          border: Border.all(
            color: index == _selectedVideoIndex
                ? Colors.white
                : color.withOpacity(0.7),
          ),
        ),
        child: Stack(
          children: [
            if (hasFilmstrip)
              Positioned.fill(
                child: _timelineFilmstrip(
                  video,
                  width: width,
                  timelinePart: timelinePart,
                ),
              ),
            if (hasFilmstrip)
              const Positioned.fill(
                child: ColoredBox(color: Color(0x26000000)),
              ),
            if (audio)
              Positioned.fill(
                child: IgnorePointer(
                  child: CustomPaint(
                    painter: _TimelineWaveformPainter(
                      color: const Color(0xff0f172a).withOpacity(0.28),
                    ),
                  ),
                ),
              ),
            if (trimOnly && !audio) ...[
              const Positioned(
                left: 0,
                top: 0,
                bottom: 0,
                child: ColoredBox(
                  color: Color(0xfffacc15),
                  child: SizedBox(width: 4),
                ),
              ),
              const Positioned(
                right: 0,
                top: 0,
                bottom: 0,
                child: ColoredBox(
                  color: Color(0xfffacc15),
                  child: SizedBox(width: 4),
                ),
              ),
            ],
            if (showContent)
              Padding(
                padding: EdgeInsets.symmetric(
                  horizontal: showStartTrimHandle || showEndTrimHandle ? 13 : 6,
                ),
                child: Row(
                  children: [
                    if (!hasFilmstrip)
                      Icon(
                        extractedAudio
                            ? Icons.library_music
                            : audio
                                ? Icons.graphic_eq
                                : Icons.movie_outlined,
                        size: 16,
                        color: const Color(0xff0f172a),
                      ),
                    if (showText) ...[
                      const SizedBox(width: 5),
                      Expanded(
                        child: Align(
                          alignment: Alignment.centerLeft,
                          child: DecoratedBox(
                            decoration: BoxDecoration(
                              color: hasFilmstrip
                                  ? const Color(0x99000000)
                                  : Colors.transparent,
                              borderRadius: BorderRadius.circular(3),
                            ),
                            child: Padding(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 4,
                                vertical: 2,
                              ),
                              child: KText(
                                audio
                                    ? extractedAudio
                                        ? 'Extracted ${_formatDuration(video.durationSeconds)}'
                                        : _formatDuration(video.durationSeconds)
                                    : partIndex == null
                                        ? video.name
                                        : '${video.name}-$partIndex',
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: TextStyle(
                                  color: hasFilmstrip
                                      ? Colors.white
                                      : const Color(0xff0f172a),
                                  fontWeight: FontWeight.w800,
                                  fontSize: 11,
                                  shadows: hasFilmstrip
                                      ? const [
                                          Shadow(
                                            color: Colors.black,
                                            blurRadius: 2,
                                          ),
                                        ]
                                      : null,
                                ),
                              ),
                            ),
                          ),
                        ),
                      ),
                    ] else if (compactClip)
                      const Spacer(),
                    if (showEditIcon)
                      const Icon(
                        Icons.content_cut,
                        size: 13,
                        color: Color(0xff111827),
                      ),
                  ],
                ),
              ),
            if (showStartTrimHandle)
              Positioned(
                left: 0,
                top: 0,
                bottom: 0,
                child: _timelineTrimHandle(startEdge: true),
              ),
            if (showEndTrimHandle)
              Positioned(
                right: 0,
                top: 0,
                bottom: 0,
                child: _timelineTrimHandle(startEdge: false),
              ),
          ],
        ),
      ),
    );
    if (!draggable || timelinePart == null || visualPartIndex == null) {
      return clip;
    }
    return Draggable<_TimelinePartDrag>(
      data: _TimelinePartDrag(
        videoPath: video.path,
        visualPartIndex: visualPartIndex,
      ),
      feedback: Material(
        color: Colors.transparent,
        child: SizedBox(
          width: width.clamp(72.0, 260.0).toDouble(),
          height: 38,
          child: Opacity(opacity: 0.85, child: clip),
        ),
      ),
      childWhenDragging: Opacity(opacity: 0.35, child: clip),
      child: clip,
    );
  }

  Widget _timelineFilmstrip(
    PickedVideo video, {
    required double width,
    ({double start, double end})? timelinePart,
  }) {
    final frames = video.timelineThumbnailPaths.isNotEmpty
        ? video.timelineThumbnailPaths
        : [if (video.thumbnailPath != null) video.thumbnailPath!];
    if (frames.isEmpty) return const SizedBox.shrink();
    final tileCount = math.max(1, (width / 58).ceil());
    final tileWidth = width / tileCount;
    final duration = math.max(0.001, video.durationSeconds ?? 0.001);
    final partStart = timelinePart?.start ?? 0.0;
    final partEnd = timelinePart?.end ?? duration;
    return ClipRect(
      child: Row(
        children: [
          for (var tile = 0; tile < tileCount; tile++)
            SizedBox(
              width: tileWidth,
              child: Image.file(
                File(
                  frames[((partStart +
                              (partEnd - partStart) *
                                  ((tile + 0.5) / tileCount)) /
                          duration *
                          frames.length)
                      .floor()
                      .clamp(0, frames.length - 1)],
                ),
                height: double.infinity,
                fit: BoxFit.cover,
                filterQuality: FilterQuality.low,
                gaplessPlayback: true,
                errorBuilder: (_, __, ___) => ColoredBox(
                  color: const Color(0xff334155),
                  child: Icon(
                    Icons.movie_outlined,
                    size: 14,
                    color: Colors.white.withOpacity(0.6),
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }

  Widget _timelineTrimHandle({required bool startEdge}) {
    return MouseRegion(
      cursor: SystemMouseCursors.resizeLeftRight,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onHorizontalDragStart: (_) => _beginTimelineTrim(),
        onHorizontalDragUpdate: (details) => _updateTimelineTrim(
          startEdge: startEdge,
          deltaPixels: details.delta.dx,
        ),
        onHorizontalDragEnd: (_) => _endTimelineTrim(),
        onHorizontalDragCancel: _endTimelineTrim,
        child: Tooltip(
          message:
              startEdge ? 'Drag to trim clip start' : 'Drag to trim clip end',
          child: Container(
            width: 11,
            decoration: BoxDecoration(
              color: const Color(0xfffacc15),
              borderRadius: BorderRadius.horizontal(
                left: Radius.circular(startEdge ? 3 : 0),
                right: Radius.circular(startEdge ? 0 : 3),
              ),
              boxShadow: const [
                BoxShadow(color: Color(0x66000000), blurRadius: 3),
              ],
            ),
            child: Center(
              child: Container(
                width: 2,
                height: 14,
                color: const Color(0xff713f12),
              ),
            ),
          ),
        ),
      ),
    );
  }

