  // Retained temporarily for project-file compatibility testing; no UI action
  // opens this legacy blocking workflow.
  // ignore: unused_element
  Future<void> _showLegacyCaptionSettingsDialog() async {
    var enabled = _automaticCaptions;
    var model = _captionModel;
    var language = _captionLanguage;
    var device = _captionDevice;
    var style = _captionStyle;
    var font = _captionFont;
    var fontSize = _captionFontSize;
    var wordsPerLine = _captionWordsPerLine;
    var bold = _captionBold;
    var underline = _captionUnderline;
    var italic = _captionItalic;
    var letterCase = _captionCase;
    var color = _captionColor;
    var characterSpacing = _captionCharacterSpacing;
    var wordSpacing = _captionWordSpacing;
    var lineSpacing = _captionLineSpacing;
    var strokeEnabled = _captionStrokeEnabled;
    var strokeColor = _captionStrokeColor;
    var strokeWidth = _captionStrokeWidth;
    var backgroundEnabled = _captionBackgroundEnabled;
    var backgroundColor = _captionBackgroundColor;
    var backgroundOpacity = _captionBackgroundOpacity;
    var glowEnabled = _captionGlowEnabled;
    var glowColor = _captionGlowColor;
    var glowStrength = _captionGlowStrength;
    var shadowEnabled = _captionShadowEnabled;
    var shadowColor = _captionShadowColor;
    var shadowStrength = _captionShadowStrength;
    var curve = _captionCurve;
    var generateNow = false;

    final applied = await showDialog<bool>(
      context: context,
      builder: (context) => StatefulBuilder(
        builder: (context, setDialogState) {
          Widget dropdown(
            String label,
            String value,
            List<String> values,
            ValueChanged<String> onChanged,
          ) {
            return Padding(
              padding: const EdgeInsets.only(bottom: 12),
              child: DropdownButtonFormField<String>(
                value: value,
                isExpanded: true,
                decoration: InputDecoration(
                  labelText: label,
                  border: const OutlineInputBorder(),
                ),
                items: [
                  for (final item in values)
                    DropdownMenuItem(value: item, child: KText(item)),
                ],
                onChanged: (next) {
                  if (next != null) onChanged(next);
                },
              ),
            );
          }

          return AlertDialog(
            title: const Row(
              children: [
                Icon(Icons.subtitles_outlined),
                SizedBox(width: 10),
                KText('AI Caption Generator'),
              ],
            ),
            content: SizedBox(
              width: 540,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    SwitchListTile(
                      contentPadding: EdgeInsets.zero,
                      value: enabled,
                      onChanged: (value) =>
                          setDialogState(() => enabled = value),
                      title: const KText(
                        'Generate captions on export',
                        style: TextStyle(fontWeight: FontWeight.w800),
                      ),
                      subtitle: const KText(
                        'Faster-Whisper creates word timing, then FFmpeg burns the ASS captions into the exported video.',
                      ),
                    ),
                    const SizedBox(height: 8),
                    dropdown(
                      'Whisper model',
                      model,
                      const [
                        'tiny.en',
                        'base.en',
                        'small.en',
                        'tiny',
                        'base',
                        'small',
                        'medium',
                      ],
                      (value) => setDialogState(() {
                        model = value;
                        if (value.endsWith('.en')) language = 'en';
                      }),
                    ),
                    Row(
                      children: [
                        Expanded(
                          child: dropdown(
                            'Language',
                            language,
                            const ['en', 'auto', 'km'],
                            (value) => setDialogState(() {
                              language = value;
                              if (value != 'en' && model.endsWith('.en')) {
                                model = model.substring(0, model.length - 3);
                              }
                            }),
                          ),
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: dropdown(
                            'Device',
                            device,
                            const ['auto', 'cuda', 'cpu'],
                            (value) => setDialogState(() => device = value),
                          ),
                        ),
                      ],
                    ),
                    _captionPresetPicker(
                      selected: style,
                      onChanged: (value) {
                        final preset = _captionPreset(value);
                        setDialogState(() {
                          style = value;
                          color = preset.accentColor;
                          bold = preset.bold;
                          italic = preset.italic;
                          letterCase = preset.uppercase ? 'upper' : 'original';
                          strokeEnabled = preset.outline > 0;
                          strokeColor = preset.outlineColor;
                          strokeWidth = preset.outline;
                          backgroundEnabled =
                              preset.backgroundColor != Colors.transparent ||
                                  preset.activeBoxColor != Colors.transparent;
                          final presetBackground =
                              preset.activeBoxColor != Colors.transparent
                                  ? preset.activeBoxColor
                                  : preset.backgroundColor;
                          backgroundColor = presetBackground.withAlpha(255);
                          backgroundOpacity = presetBackground.opacity;
                          glowEnabled = preset.motion == 'glow';
                          glowColor = preset.accentColor;
                          glowStrength = math.max(6, preset.shadow);
                          shadowEnabled = preset.shadow > 0;
                          shadowColor = preset.outlineColor;
                          shadowStrength = preset.shadow;
                          curve = 0;
                        });
                      },
                    ),
                    _captionTypographyControls(
                      bold: bold,
                      underline: underline,
                      italic: italic,
                      letterCase: letterCase,
                      color: color,
                      characterSpacing: characterSpacing,
                      wordSpacing: wordSpacing,
                      lineSpacing: lineSpacing,
                      onBold: (value) => setDialogState(() => bold = value),
                      onUnderline: (value) =>
                          setDialogState(() => underline = value),
                      onItalic: (value) => setDialogState(() => italic = value),
                      onCase: (value) =>
                          setDialogState(() => letterCase = value),
                      onColor: (value) => setDialogState(() => color = value),
                      onCharacterSpacing: (value) =>
                          setDialogState(() => characterSpacing = value),
                      onWordSpacing: (value) =>
                          setDialogState(() => wordSpacing = value),
                      onLineSpacing: (value) =>
                          setDialogState(() => lineSpacing = value),
                    ),
                    const SizedBox(height: 12),
                    _fontDropdown(
                      'Font',
                      font,
                      (value) => setDialogState(() => font = value),
                    ),
                    KText('Font size: ${fontSize.round()}'),
                    Slider(
                      value: fontSize,
                      min: 6,
                      max: 36,
                      divisions: 30,
                      label: '${fontSize.round()}',
                      onChanged: (value) =>
                          setDialogState(() => fontSize = value),
                    ),
                    KText('Words per line: $wordsPerLine'),
                    Slider(
                      value: wordsPerLine.toDouble(),
                      min: 1,
                      max: 8,
                      divisions: 7,
                      label: '$wordsPerLine',
                      onChanged: (value) => setDialogState(
                        () => wordsPerLine = value.round(),
                      ),
                    ),
                    const Card(
                      child: Padding(
                        padding: EdgeInsets.all(12),
                        child: KText(
                          'Captions appear in the final export. The first use downloads the model; later exports reuse the transcript cache.',
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(context).pop(false),
                child: const KText('Cancel'),
              ),
              OutlinedButton.icon(
                onPressed: _videos.isEmpty
                    ? null
                    : () {
                        enabled = true;
                        generateNow = true;
                        Navigator.of(context).pop(true);
                      },
                icon: const Icon(Icons.auto_awesome),
                label: const KText('Generate now'),
              ),
              FilledButton.icon(
                onPressed: () => Navigator.of(context).pop(true),
                icon: const Icon(Icons.check),
                label: KText(enabled ? 'Apply & Enable' : 'Apply'),
              ),
            ],
          );
        },
      ),
    );
    if (applied != true || !mounted) return;
    setState(() {
      _automaticCaptions = enabled;
      _captionModel = model;
      _captionLanguage = language;
      _captionDevice = device;
      _captionStyle = style;
      _captionFont = font;
      _captionFontSize = fontSize;
      _captionWordsPerLine = wordsPerLine;
      _captionBold = bold;
      _captionUnderline = underline;
      _captionItalic = italic;
      _captionCase = letterCase;
      _captionColor = color;
      _captionCharacterSpacing = characterSpacing;
      _captionWordSpacing = wordSpacing;
      _captionLineSpacing = lineSpacing;
      _captionStrokeEnabled = strokeEnabled;
      _captionStrokeColor = strokeColor;
      _captionStrokeWidth = strokeWidth;
      _captionBackgroundEnabled = backgroundEnabled;
      _captionBackgroundColor = backgroundColor;
      _captionBackgroundOpacity = backgroundOpacity;
      _captionGlowEnabled = glowEnabled;
      _captionGlowColor = glowColor;
      _captionGlowStrength = glowStrength;
      _captionShadowEnabled = shadowEnabled;
      _captionShadowColor = shadowColor;
      _captionShadowStrength = shadowStrength;
      _captionCurve = curve;
      _status = enabled
          ? 'AI captions enabled — captions generate during export'
          : 'AI captions disabled';
    });
    if (generateNow) await _generateSelectedCaptionPreview();
  }

  Future<void> _generateSelectedCaptionPreview() async {
    if (_videos.isEmpty || _isGeneratingCaptions) return;
    if (_captionTrackLocked) {
      _showMessage('Unlock T1 before generating captions.');
      return;
    }
    _saveSelectedClipTimelineEdit();
    _storeActiveCompositionTimeline();
    final targetIndexes = _captionGenerateAllVideos
        ? _parseVideoTargetExpression(_captionVideoTargetsController.text)
        : (indexes: <int>[_selectedVideoIndex], error: null);
    if (targetIndexes.error != null || targetIndexes.indexes.isEmpty) {
      _showMessage(targetIndexes.error ?? 'Choose at least one video.');
      return;
    }
    final targets = [
      for (final index in targetIndexes.indexes) _videos[index],
    ];
    await _pausePlaybackForExport();
    if (!mounted) return;
    final video = targets.first;
    final cancelToken = ExportCancelToken();
    _captionCancelToken = cancelToken;
    final progress = ValueNotifier<_CaptionGenerationView>(
      _CaptionGenerationView(
        videoName: video.name,
        currentVideo: 1,
        totalVideos: targets.length,
      ),
    );
    var dialogOpen = true;
    setState(() {
      _isGeneratingCaptions = true;
      _automaticCaptions = true;
      _status = 'Starting Faster-Whisper for ${video.name}...';
    });
    final dialogClosed = showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) => _CaptionGenerationDialog(
        progress: progress,
        onCancel: () {
          cancelToken.cancel();
          progress.value = progress.value.copyWith(
            status: 'Cancelling caption generation...',
            cancelling: true,
          );
        },
      ),
    ).whenComplete(() => dialogOpen = false);
    ExportResult result = const ExportResult(
      success: true,
      message: 'Captions generated.',
    );
    final generatedByPath = <String, List<_CaptionCue>>{};
    final temporaryCaptionInputs = <File>[];
    _recordEditorHistory('caption-generate');
    try {
      final tempDirectory = await getTemporaryDirectory();
      for (var targetIndex = 0;
          targetIndex < targets.length && !cancelToken.isCanceled;
          targetIndex++) {
        final target = targets[targetIndex];
        if (mounted) {
          setState(() {
            // Regeneration replaces this video's old captions immediately.
            // Completed earlier videos remain saved if a later one is canceled.
            _captionCuesByVideo.remove(target.path);
            _status =
                'Generating captions for video ${targetIndex + 1} of ${targets.length}: ${target.name}';
          });
        }
        if (dialogOpen) {
          progress.value = _CaptionGenerationView(
            videoName: target.name,
            currentVideo: targetIndex + 1,
            totalVideos: targets.length,
            status: 'Preparing edited cuts...',
          );
        }
        final timeline = _selectedCompositionPath == target.path
            ? _multiTrackTimeline
            : _timelinesByComposition[target.path];
        var clips = <ClipModel>[
          for (final track in timeline?.videoTracks ?? const <TrackModel>[])
            if (!track.isMuted)
              for (final clip in track.clips)
                if (!clip.isMuted &&
                    clip.mediaPath == target.path &&
                    clip.duration > 0.001)
                  clip,
        ]..sort(
            (left, right) => left.timelineStart.compareTo(right.timelineStart));
        if (clips.isEmpty) {
          clips = [
            for (final part in _clipTimelineEditFor(target.path)
                .timelineParts(target.durationSeconds))
              ClipModel(
                id: 'caption-${target.path.hashCode}-${part.start}',
                mediaPath: target.path,
                timelineStart: part.start,
                duration: math.max(0.001, part.end - part.start).toDouble(),
                sourceStart: part.start,
                zIndex: 0,
              ),
          ];
        }
        if (clips.isEmpty) {
          generatedByPath[target.path] = const [];
          if (mounted) {
            setState(() => _captionCuesByVideo[target.path] = const []);
            await _autosaveProject();
          }
          continue;
        }

        final stamp = DateTime.now().microsecondsSinceEpoch;
        final editedInput = File(
          '${tempDirectory.path}${Platform.pathSeparator}'
          'klipio_caption_${targetIndex}_$stamp.wav',
        );
        temporaryCaptionInputs.add(editedInput);
        final segments = <({
          double outputStart,
          double outputEnd,
          double speed,
          ClipModel clip,
        })>[];
        final audioSegments = <CaptionAudioSegment>[];
        var outputCursor = 0.0;
        for (final clip in clips) {
          final edit = _clipTimelineEditFor(clip.mediaPath);
          final speed = edit.speed.clamp(_minVideoSpeed, _maxVideoSpeed);
          final outputDuration = clip.duration / speed;
          segments.add((
            outputStart: outputCursor,
            outputEnd: outputCursor + outputDuration,
            speed: speed,
            clip: clip,
          ));
          outputCursor += outputDuration;
          audioSegments.add(
            CaptionAudioSegment(
              inputPath: clip.mediaPath,
              sourceStart: clip.sourceStart,
              duration: clip.duration,
              speed: speed,
            ),
          );
        }
        final render = await exportCaptionAudioSequence(
          segments: audioSegments,
          outputPath: editedInput.path,
          cancelToken: cancelToken,
          onProgress: (value, status) {
            if (!dialogOpen) return;
            progress.value = _CaptionGenerationView(
              videoName: target.name,
              currentVideo: targetIndex + 1,
              totalVideos: targets.length,
              progress: value.clamp(0, 1) * 0.18,
              status: 'Preparing speech audio: $status',
              cancelling: cancelToken.isCanceled,
            );
          },
        );
        if (!render.success || cancelToken.isCanceled) {
          result = render;
          if (await editedInput.exists()) await editedInput.delete();
          break;
        }
        final captionResult = await generateCaptionPreview(
          ExportJob(
            inputPath: editedInput.path,
            outputPath: editedInput.path,
            settings: _settings.copyWith(
              automaticCaptions: true,
              speed: 1,
              trimStartSeconds: 0,
              trimEndSeconds: 0,
            ),
            cancelToken: cancelToken,
            onProgress: (value, status) {
              if (!dialogOpen) return;
              progress.value = _CaptionGenerationView(
                videoName: target.name,
                currentVideo: targetIndex + 1,
                totalVideos: targets.length,
                progress: 0.18 + value.clamp(0, 1) * 0.82,
                status: status,
                cancelling: cancelToken.isCanceled,
              );
            },
          ),
        );
        if (!captionResult.success || captionResult.outputPath == null) {
          result = captionResult;
          if (await editedInput.exists()) await editedInput.delete();
          break;
        }
        final localCues = await _captionCuesFromAss(captionResult.outputPath!);
        final mapped = <_CaptionCue>[];
        for (final cue in localCues) {
          for (final segment in segments) {
            final visibleStart = math.max(cue.start, segment.outputStart);
            final visibleEnd = math.min(cue.end, segment.outputEnd);
            if (visibleEnd <= visibleStart) continue;
            double sourceTime(double localTime) =>
                segment.clip.sourceStart +
                (localTime - segment.outputStart) * segment.speed;
            mapped.add(
              cue.copyWith(
                start: sourceTime(visibleStart),
                end: sourceTime(visibleEnd),
                words: [
                  for (final word in cue.words)
                    if (word.end > visibleStart && word.start < visibleEnd)
                      _CaptionWord(
                        start: sourceTime(math.max(word.start, visibleStart)),
                        end: sourceTime(math.min(word.end, visibleEnd)),
                        text: word.text,
                      ),
                ],
              ),
            );
          }
        }
        mapped.sort((left, right) => left.start.compareTo(right.start));
        generatedByPath[target.path] = mapped;
        if (mounted) {
          setState(() {
            _captionCuesByVideo[target.path] = mapped;
            _status =
                'Captions completed for video ${targetIndex + 1} of ${targets.length}';
          });
          await _autosaveProject();
        }
        if (await editedInput.exists()) await editedInput.delete();
      }
    } catch (error) {
      result = ExportResult(success: false, message: '$error');
    } finally {
      for (final temporaryInput in temporaryCaptionInputs) {
        try {
          if (await temporaryInput.exists()) await temporaryInput.delete();
        } catch (_) {
          // The OS may still be releasing a canceled FFmpeg worker handle.
        }
      }
      if (dialogOpen && mounted) {
        Navigator.of(context, rootNavigator: true).pop();
      }
      await dialogClosed;
      progress.dispose();
      if (identical(_captionCancelToken, cancelToken)) {
        _captionCancelToken = null;
      }
      MediaJobManager.instance.resumeBackgroundWork();
    }
    if (!mounted) return;
    if (!result.success || cancelToken.isCanceled) {
      setState(() {
        _isGeneratingCaptions = false;
        _status = cancelToken.isCanceled
            ? 'Caption generation canceled after ${generatedByPath.length} of ${targets.length} videos'
            : 'Caption generation failed';
      });
      unawaited(_autosaveProject());
      if (!cancelToken.isCanceled) _showMessage(result.message);
      return;
    }
    setState(() {
      final cues = generatedByPath[video.path] ?? const <_CaptionCue>[];
      if (cues.isNotEmpty) {
        _selectedCaptionCueIndex = 0;
        _selectedTimelineClipId = null;
        _editorSelection = EditorSelection.caption(
          _captionTimelineId(video.path, 0),
          label: cues.first.text,
        );
        _visibleWorkspacePanels.add('inspector');
      }
      _isGeneratingCaptions = false;
      _status = cues.isEmpty
          ? 'No speech was detected in ${video.name}'
          : _captionGenerateAllVideos
              ? 'Captions ready for ${generatedByPath.length} videos'
              : '${cues.length} caption blocks ready on T1';
    });
    unawaited(_autosaveProject());
  }

  Future<List<_CaptionCue>> _captionCuesFromAss(
    String path, {
    bool capCutStyleOnly = true,
  }) async {
    final file = File(path);
    if (!await file.exists()) return const [];
    final pattern = RegExp(
      r'^Dialogue:\s*[^,]*,([^,]+),([^,]+),([^,]*),[^,]*,[^,]*,[^,]*,[^,]*,[^,]*,(.*)$',
    );
    final cues = <_CaptionCue>[];
    for (final line in await file.readAsLines()) {
      final match = pattern.firstMatch(line);
      if (match == null) continue;
      if (capCutStyleOnly && (match.group(3) ?? '').trim() != 'CapCutPro') {
        continue;
      }
      final start = _parseAssSeconds(match.group(1) ?? '');
      final end = _parseAssSeconds(match.group(2) ?? '');
      final rawText = match.group(4) ?? '';
      final text = normalizeAssDisplayText(rawText);
      if (start != null && end != null && end > start && text.isNotEmpty) {
        final words = <_CaptionWord>[];
        var cursor = start;
        final karaoke = RegExp(
          r'\{[^}]*\\(?:kf|ko|k)(\d+)[^}]*\}([^\{]*)',
          caseSensitive: false,
        );
        for (final wordMatch in karaoke.allMatches(rawText)) {
          final duration = (int.tryParse(wordMatch.group(1) ?? '') ?? 0) / 100;
          final word = normalizeAssDisplayText(wordMatch.group(2) ?? '');
          if (word.isNotEmpty) {
            words.add(
              _CaptionWord(
                start: cursor,
                end: math.min(end, cursor + math.max(0.01, duration)),
                text: word,
              ),
            );
          }
          cursor += duration;
        }
        cues.add(
          _CaptionCue(start: start, end: end, text: text, words: words),
        );
      }
    }
    return cues;
  }

  double? _parseAssSeconds(String raw) {
    final parts = raw.trim().split(':');
    if (parts.length != 3) return null;
    final hours = double.tryParse(parts[0]);
    final minutes = double.tryParse(parts[1]);
    final seconds = double.tryParse(parts[2]);
    if (hours == null || minutes == null || seconds == null) return null;
    return hours * 3600 + minutes * 60 + seconds;
  }

  List<_CaptionCue> get _selectedCaptionCues {
    if (_videos.isEmpty) return const [];
    return _captionCuesByVideo[_videos[_selectedVideoIndex].path] ?? const [];
  }

  Future<void> _showCaptionCueEditor({int? index}) async {
    if (_videos.isEmpty) return;
    if (_captionTrackLocked) {
      _showMessage('Unlock T1 before editing captions.');
      return;
    }
    final path = _videos[_selectedVideoIndex].path;
    final cues = _captionCuesByVideo[path] ?? const <_CaptionCue>[];
    final existing =
        index != null && index >= 0 && index < cues.length ? cues[index] : null;
    final start = existing?.start ?? _currentPlayheadSeconds();
    final videoEnd = _videos[_selectedVideoIndex].durationSeconds;
    final end = existing?.end ??
        (videoEnd == null
            ? start + 2
            : math.min(videoEnd, math.max(start + 0.5, start + 2)));
    final textController = TextEditingController(text: existing?.text ?? '');
    final startController =
        TextEditingController(text: start.toStringAsFixed(3));
    final endController = TextEditingController(text: end.toStringAsFixed(3));
    final applied = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: KText(existing == null ? 'Add caption' : 'Edit caption'),
        content: SizedBox(
          width: 560,
          child: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Row(
                  children: [
                    Expanded(
                      child: TextField(
                        controller: startController,
                        decoration: const InputDecoration(
                          labelText: 'Start (seconds or timecode)',
                          hintText: '12.5 or 00:12.500',
                        ),
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: TextField(
                        controller: endController,
                        decoration: const InputDecoration(
                          labelText: 'End (seconds or timecode)',
                          hintText: '15.0 or 00:15.000',
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: textController,
                  autofocus: true,
                  minLines: 3,
                  maxLines: 8,
                  decoration: const InputDecoration(
                    labelText: 'Caption text',
                    hintText: 'Correct the transcript here',
                  ),
                ),
                const SizedBox(height: 10),
                KText(
                  'Editing text clears the original word-level alignment for this cue. The cue remains fully editable and exportable.',
                  style: TextStyle(fontSize: 12, color: _mutedTextColor),
                ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(false),
            child: const KText('Cancel'),
          ),
          FilledButton.icon(
            onPressed: () => Navigator.of(context).pop(true),
            icon: const Icon(Icons.check),
            label: const KText('Save caption'),
          ),
        ],
      ),
    );
    if (applied != true || !mounted) {
      textController.dispose();
      startController.dispose();
      endController.dispose();
      return;
    }
    final nextStart = _parseCaptionEditorTime(startController.text);
    final nextEnd = _parseCaptionEditorTime(endController.text);
    final nextText = textController.text.trim();
    textController.dispose();
    startController.dispose();
    endController.dispose();
    if (nextStart == null || nextEnd == null || nextEnd <= nextStart) {
      _showMessage('Caption end time must be after its start time.');
      return;
    }
    if (nextText.isEmpty) {
      _showMessage('Caption text cannot be empty.');
      return;
    }
    final next = existing?.copyWith(
          start: math.max(0, nextStart),
          end: math.max(0, nextEnd),
          text: nextText,
          words: const [],
        ) ??
        _CaptionCue(
          start: math.max(0, nextStart),
          end: math.max(0, nextEnd),
          text: nextText,
        );
    _recordEditorHistory(
      existing == null ? 'caption-add' : 'caption-edit',
    );
    setState(() {
      final updated = [...cues];
      if (existing == null) {
        updated.add(next);
      } else {
        updated[index!] = next;
      }
      updated.sort((a, b) => a.start.compareTo(b.start));
      _captionCuesByVideo[path] = updated;
      _selectedCaptionCueIndex = updated.indexOf(next);
      _automaticCaptions = true;
      _status = existing == null ? 'Caption added to T1' : 'Caption updated';
    });
    unawaited(_autosaveProject());
  }

  double? _parseCaptionEditorTime(String input) {
    final raw = input.trim();
    if (raw.isEmpty) return null;
    final normalized = raw.replaceAll(',', '.');
    if (!normalized.contains(':')) return double.tryParse(normalized);
    final parts = normalized.split(':');
    if (parts.length == 2) {
      final minutes = double.tryParse(parts[0]);
      final seconds = double.tryParse(parts[1]);
      return minutes == null || seconds == null ? null : minutes * 60 + seconds;
    }
    if (parts.length == 3) {
      final hours = double.tryParse(parts[0]);
      final minutes = double.tryParse(parts[1]);
      final seconds = double.tryParse(parts[2]);
      return hours == null || minutes == null || seconds == null
          ? null
          : hours * 3600 + minutes * 60 + seconds;
    }
    return null;
  }

  void _deleteSelectedCaptionCue() {
    if (_videos.isEmpty || _selectedCaptionCues.isEmpty) return;
    if (_captionTrackLocked) {
      _showMessage('Unlock T1 before deleting captions.');
      return;
    }
    _recordEditorHistory('caption-delete');
    final path = _videos[_selectedVideoIndex].path;
    final updated = [..._selectedCaptionCues];
    final index = _selectedCaptionCueIndex.clamp(0, updated.length - 1);
    updated.removeAt(index);
    setState(() {
      _captionCuesByVideo[path] = updated;
      _selectedCaptionCueIndex =
          updated.isEmpty ? 0 : index.clamp(0, updated.length - 1);
      _status = 'Caption deleted';
    });
    unawaited(_autosaveProject());
  }

  void _splitSelectedCaptionCue() {
    if (_videos.isEmpty || _selectedCaptionCues.isEmpty) return;
    if (_captionTrackLocked) {
      _showMessage('Unlock T1 before splitting captions.');
      return;
    }
    final path = _videos[_selectedVideoIndex].path;
    final updated = [..._selectedCaptionCues];
    final index = _selectedCaptionCueIndex.clamp(0, updated.length - 1);
    final cue = updated[index];
    var split = _currentPlayheadSeconds();
    if (split <= cue.start + 0.05 || split >= cue.end - 0.05) {
      split = (cue.start + cue.end) / 2;
    }
    final words = cue.text.trim().split(RegExp(r'\s+'));
    final cut = math.max(1, (words.length / 2).ceil());
    final firstText = words.take(cut).join(' ');
    final secondText = words.skip(cut).join(' ');
    if (secondText.isEmpty) {
      _showMessage('Add more words before splitting this caption.');
      return;
    }
    _recordEditorHistory('caption-split');
    updated
      ..removeAt(index)
      ..insertAll(index, [
        cue.copyWith(end: split, text: firstText, words: const []),
        cue.copyWith(start: split, text: secondText, words: const []),
      ]);
    setState(() {
      _captionCuesByVideo[path] = updated;
      _selectedCaptionCueIndex = index;
      _status = 'Caption split at ${_formatDuration(split)}';
    });
    unawaited(_autosaveProject());
  }

  void _mergeSelectedCaptionCue() {
    if (_videos.isEmpty || _selectedCaptionCues.length < 2) return;
    if (_captionTrackLocked) {
      _showMessage('Unlock T1 before merging captions.');
      return;
    }
    _recordEditorHistory('caption-merge');
    final path = _videos[_selectedVideoIndex].path;
    final updated = [..._selectedCaptionCues];
    final index = _selectedCaptionCueIndex.clamp(0, updated.length - 1);
    final otherIndex = index < updated.length - 1 ? index + 1 : index - 1;
    final firstIndex = math.min(index, otherIndex);
    final first = updated[firstIndex];
    final second = updated[firstIndex + 1];
    final merged = _CaptionCue(
      start: math.min(first.start, second.start),
      end: math.max(first.end, second.end),
      text: '${first.text.trim()} ${second.text.trim()}'.trim(),
      x: first.x,
      y: first.y,
    );
    updated
      ..removeRange(firstIndex, firstIndex + 2)
      ..insert(firstIndex, merged);
    setState(() {
      _captionCuesByVideo[path] = updated;
      _selectedCaptionCueIndex = firstIndex;
      _status = 'Captions merged';
    });
    unawaited(_autosaveProject());
  }

  Future<void> _importSubtitleFile() async {
    if (_videos.isEmpty) return;
    if (_captionTrackLocked) {
      _showMessage('Unlock T1 before importing captions.');
      return;
    }
    final result = await FilePicker.platform.pickFiles(
      type: FileType.custom,
      allowedExtensions: const ['srt', 'vtt', 'ass'],
    );
    final path = result?.files.single.path;
    if (path == null) return;
    final extension = path.toLowerCase().split('.').last;
    List<_CaptionCue> cues;
    if (extension == 'ass') {
      cues = await _captionCuesFromAss(path, capCutStyleOnly: false);
    } else {
      cues = _captionCuesFromSrtOrVtt(await File(path).readAsString());
    }
    if (!mounted) return;
    if (cues.isEmpty) {
      _showMessage('No valid subtitle cues were found in this file.');
      return;
    }
    _recordEditorHistory('caption-import');
    setState(() {
      _captionCuesByVideo[_videos[_selectedVideoIndex].path] = cues;
      _selectedCaptionCueIndex = 0;
      _automaticCaptions = true;
      _status =
          'Imported ${cues.length} captions from ${platform.basename(path)}';
    });
    unawaited(_autosaveProject());
  }

  List<_CaptionCue> _captionCuesFromSrtOrVtt(String input) {
    final normalized = input
        .replaceFirst('\ufeff', '')
        .replaceAll('\r\n', '\n')
        .replaceAll('\r', '\n');
    final blocks = normalized.split(RegExp(r'\n\s*\n'));
    final cues = <_CaptionCue>[];
    final timing = RegExp(
      r'((?:\d+:)?\d{1,2}:\d{2}[\.,]\d{3})\s*-->\s*((?:\d+:)?\d{1,2}:\d{2}[\.,]\d{3})',
    );
    for (final block in blocks) {
      final lines =
          block.split('\n').where((line) => line.trim().isNotEmpty).toList();
      final timingIndex = lines.indexWhere((line) => timing.hasMatch(line));
      if (timingIndex < 0) continue;
      final match = timing.firstMatch(lines[timingIndex])!;
      final start = _parseCaptionEditorTime(match.group(1) ?? '');
      final end = _parseCaptionEditorTime(match.group(2) ?? '');
      final text = lines
          .skip(timingIndex + 1)
          .join('\n')
          .replaceAll(RegExp(r'<[^>]+>'), '')
          .trim();
      if (start != null && end != null && end > start && text.isNotEmpty) {
        cues.add(_CaptionCue(start: start, end: end, text: text));
      }
    }
    cues.sort((a, b) => a.start.compareTo(b.start));
    return cues;
  }

  Future<void> _exportSubtitleFile() async {
    if (_videos.isEmpty || _selectedCaptionCues.isEmpty) {
      _showMessage('Generate or import captions before exporting subtitles.');
      return;
    }
    final format = await showDialog<String>(
      context: context,
      builder: (context) => SimpleDialog(
        title: const KText('Export subtitle file'),
        children: [
          for (final item in const ['srt', 'vtt', 'ass'])
            SimpleDialogOption(
              onPressed: () => Navigator.of(context).pop(item),
              child: KText(item.toUpperCase()),
            ),
        ],
      ),
    );
    if (format == null || !mounted) return;
    final videoName = _withoutExtension(_videos[_selectedVideoIndex].name);
    final path = await FilePicker.platform.saveFile(
      dialogTitle: 'Export ${format.toUpperCase()} subtitles',
      fileName: '${_safeName(videoName)}.$format',
      type: FileType.custom,
      allowedExtensions: [format],
    );
    if (path == null) return;
    final target =
        path.toLowerCase().endsWith('.$format') ? path : '$path.$format';
    await File(target).writeAsString(
      _subtitleFileContents(format, _selectedCaptionCues),
      flush: true,
    );
    if (mounted) {
      setState(() =>
          _status = 'Subtitle file exported: ${platform.basename(target)}');
    }
  }

  String _subtitleFileContents(String format, List<_CaptionCue> cues) {
    if (format == 'ass') {
      final events = [
        for (final cue in cues)
          'Dialogue: 0,${_assExportTime(cue.start)},${_assExportTime(cue.end)},Default,,0,0,0,,${_subtitleAssText(cue.text)}',
      ];
      return '[Script Info]\nScriptType: v4.00+\nPlayResX: 1920\nPlayResY: 1080\n\n'
          '[V4+ Styles]\nFormat: Name,Fontname,Fontsize,PrimaryColour,SecondaryColour,OutlineColour,BackColour,Bold,Italic,Underline,StrikeOut,ScaleX,ScaleY,Spacing,Angle,BorderStyle,Outline,Shadow,Alignment,MarginL,MarginR,MarginV,Encoding\n'
          'Style: Default,${_safeCaptionFont(_captionFont).replaceAll(',', ' ')},${_captionAssFontSize(_captionFontSize).round()},&H00FFFFFF,&H0000FFFF,&H00000000,&H80000000,${_captionBold ? -1 : 0},${_captionItalic ? -1 : 0},${_captionUnderline ? -1 : 0},0,100,100,${_captionCharacterSpacing.toStringAsFixed(1)},0,1,4,2,2,30,30,70,1\n\n'
          '[Events]\nFormat: Layer,Start,End,Style,Name,MarginL,MarginR,MarginV,Effect,Text\n${events.join('\n')}\n';
    }
    final buffer = StringBuffer();
    if (format == 'vtt') buffer.writeln('WEBVTT\n');
    for (var index = 0; index < cues.length; index++) {
      final cue = cues[index];
      if (format == 'srt') buffer.writeln(index + 1);
      buffer.writeln(
        '${_subtitleTime(cue.start, comma: format == 'srt')} --> '
        '${_subtitleTime(cue.end, comma: format == 'srt')}',
      );
      buffer.writeln(cue.text);
      buffer.writeln();
    }
    return buffer.toString();
  }

  String _subtitleTime(double seconds, {required bool comma}) {
    final safe = math.max(0.0, seconds);
    final milliseconds = (safe * 1000).round();
    final hours = milliseconds ~/ 3600000;
    final minutes = (milliseconds ~/ 60000) % 60;
    final secs = (milliseconds ~/ 1000) % 60;
    final millis = milliseconds % 1000;
    final separator = comma ? ',' : '.';
    return '${hours.toString().padLeft(2, '0')}:'
        '${minutes.toString().padLeft(2, '0')}:'
        '${secs.toString().padLeft(2, '0')}$separator'
        '${millis.toString().padLeft(3, '0')}';
  }

  String _assExportTime(double seconds) {
    final safe = math.max(0.0, seconds);
    final hours = safe ~/ 3600;
    final minutes = (safe ~/ 60) % 60;
    final secs = safe - hours * 3600 - minutes * 60;
    return '$hours:${minutes.toString().padLeft(2, '0')}:'
        '${secs.toStringAsFixed(2).padLeft(5, '0')}';
  }

  String _subtitleAssText(String text) => text
      .replaceAll(r'\', r'\\')
      .replaceAll('{', r'\{')
      .replaceAll('}', r'\}')
      .replaceAll('\r\n', r'\N')
      .replaceAll('\n', r'\N');

