  _CaptionCue? _activeCaptionCue() {
    if (_videos.isEmpty || _captionTrackHidden) return null;
    // The preview controller position is source-media time. Program clips can
    // start hundreds of seconds into that source while appearing near the
    // beginning of the edited timeline, so it must never be used to choose an
    // active timeline clip. Resolve the program playhead first, then map that
    // active clip back to source time for its source-based caption cues.
    final timelineSeconds = _currentProgramSeconds();
    for (final track in _multiTrackTimeline.videoTracks) {
      if (track.isMuted) continue;
      for (final clip in track.clips.reversed) {
        if (clip.isMuted ||
            timelineSeconds < clip.timelineStart ||
            timelineSeconds >= clip.timelineEnd) {
          continue;
        }
        final sourceSeconds =
            clip.sourceStart + timelineSeconds - clip.timelineStart;
        for (final cue
            in _captionCuesByVideo[clip.mediaPath] ?? const <_CaptionCue>[]) {
          if (sourceSeconds >= cue.start && sourceSeconds < cue.end) return cue;
        }
      }
    }
    return null;
  }

  Widget _ratioSelector() {
    const ratios = ['original', '16:9', '9:16', '4:5', '1:1', '3:4', '4:3'];
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const KText('Output ratio'),
        const SizedBox(height: 8),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: ratios.map((ratio) {
            final selected = ratio == _outputRatio;
            return ChoiceChip(
              selected: selected,
              label: KText(ratio == 'original' ? 'Original' : ratio),
              onSelected: (_) {
                _recordEditorHistory('output-ratio');
                setState(() => _outputRatio = ratio);
              },
              selectedColor: const Color(0xff1f6bff),
              labelStyle: TextStyle(
                color: selected ? Colors.white : const Color(0xffd1d5db),
                fontWeight: FontWeight.w700,
              ),
            );
          }).toList(),
        ),
      ],
    );
  }

  Widget _programTransportBar(VideoPlayerController? controller) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 6),
      decoration: BoxDecoration(
        color: _monitorChromeColor,
        border: Border(top: BorderSide(color: _monitorChromeBorderColor)),
      ),
      child: ValueListenableBuilder<VideoPlayerValue>(
        valueListenable: controller ?? _emptyVideoValueListenable,
        builder: (context, value, child) {
          final initialized = controller != null && value.isInitialized;
          final duration =
              initialized ? _programPlaybackDurationSeconds() : 0.0;
          final position = initialized ? _currentProgramSeconds() : 0.0;
          return LayoutBuilder(builder: (context, constraints) {
            final roomy = constraints.maxWidth >= 470;
            return Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                // Program scrub slider — shows the FULL timeline duration
                SizedBox(
                  height: 20,
                  child: SliderTheme(
                    data: const SliderThemeData(
                      trackHeight: 2,
                      thumbShape: RoundSliderThumbShape(enabledThumbRadius: 5),
                    ),
                    child: Slider(
                      value: duration <= 0 ? 0 : position.clamp(0.0, duration),
                      min: 0,
                      max: duration <= 0 ? 1 : duration,
                      onChanged: initialized
                          ? (value) => _requestMultiTrackTimelineSeek(value)
                          : null,
                    ),
                  ),
                ),
                SizedBox(
                  height: 32,
                  child: Stack(
                    alignment: Alignment.center,
                    children: [
                      Align(
                        alignment: Alignment.centerLeft,
                        child: Text.rich(
                          TextSpan(children: [
                            TextSpan(
                              text: initialized
                                  ? _formatTimecode(position)
                                  : '00:00:00:00',
                              style: const TextStyle(color: Color(0xff22d3ee)),
                            ),
                            const TextSpan(
                              text: '  /  ',
                              style: TextStyle(color: Color(0xff64748b)),
                            ),
                            TextSpan(
                              text: initialized
                                  ? _formatTimecode(duration)
                                  : '00:00:00:00',
                              style: TextStyle(color: _monitorChromeTextColor),
                            ),
                          ]),
                          style: TextStyle(fontSize: roomy ? 10.5 : 9),
                          maxLines: 1,
                        ),
                      ),
                      _monitorIconButton(
                        onPressed: initialized ? _togglePreview : null,
                        icon: Icon(
                          value.isPlaying ? Icons.pause : Icons.play_arrow,
                          size: 21,
                          color: _monitorChromeTextColor,
                        ),
                        tooltip: 'Play / pause',
                      ),
                      Align(
                        alignment: Alignment.centerRight,
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            if (roomy)
                              _monitorIconButton(
                                onPressed: _videos.length < 2
                                    ? null
                                    : _selectPreviousVideo,
                                icon: const Icon(Icons.skip_previous, size: 18),
                                tooltip: 'Previous clip',
                              ),
                            if (roomy)
                              _monitorIconButton(
                                onPressed: _videos.length < 2
                                    ? null
                                    : _selectNextVideo,
                                icon: const Icon(Icons.skip_next, size: 18),
                                tooltip: 'Next clip',
                              ),
                            if (roomy)
                              _monitorIconButton(
                                onPressed: initialized
                                    ? () => _showMonitorVolumeDialog(
                                          title: 'Program volume',
                                          value: _originalVolume,
                                          onChanged: _setOriginalVolume,
                                        )
                                    : null,
                                icon: Icon(
                                  _effectiveOriginalVolume <= 0
                                      ? Icons.volume_off_outlined
                                      : Icons.volume_up_outlined,
                                  size: 18,
                                ),
                                tooltip: 'Program volume',
                              ),
                            if (roomy)
                              _monitorLabelButton(
                                  'Full',
                                  initialized
                                      ? () =>
                                          _showMonitorFullscreen(source: false)
                                      : null),
                            _monitorIconButton(
                              onPressed: initialized
                                  ? () => setState(() =>
                                      _programTransformOverlayVisible =
                                          !_programTransformOverlayVisible)
                                  : null,
                              icon: Icon(
                                _programTransformOverlayVisible
                                    ? Icons.center_focus_strong
                                    : Icons.center_focus_weak,
                                size: 20,
                                color: _programTransformOverlayVisible
                                    ? const Color(0xff22d3ee)
                                    : _monitorChromeTextColor,
                              ),
                              tooltip: _programTransformOverlayVisible
                                  ? 'Hide transform handles'
                                  : 'Show transform handles',
                            ),
                            PopupMenuButton<String>(
                              tooltip: 'Canvas ratio',
                              enabled: initialized,
                              onSelected: (ratio) {
                                _recordEditorHistory('output-ratio');
                                setState(() => _outputRatio = ratio);
                              },
                              itemBuilder: (context) => [
                                for (final ratio in const [
                                  'original',
                                  '16:9',
                                  '9:16',
                                  '4:5',
                                  '1:1',
                                  '3:4',
                                  '4:3'
                                ])
                                  PopupMenuItem(
                                    value: ratio,
                                    child: Row(children: [
                                      Icon(
                                          ratio == _outputRatio
                                              ? Icons.check
                                              : Icons.crop_free,
                                          size: 18),
                                      const SizedBox(width: 10),
                                      KText(ratio == 'original'
                                          ? 'Original'
                                          : ratio),
                                    ]),
                                  ),
                              ],
                              child: Padding(
                                padding: const EdgeInsets.symmetric(
                                    horizontal: 4, vertical: 8),
                                child: KText(roomy ? 'Ratio' : _outputRatio,
                                    style: TextStyle(
                                        color: _monitorChromeTextColor,
                                        fontSize: 10,
                                        decoration: TextDecoration.underline)),
                              ),
                            ),
                            _monitorIconButton(
                              onPressed: initialized
                                  ? () => _showMonitorFullscreen(source: false)
                                  : null,
                              icon: const Icon(Icons.fullscreen, size: 21),
                              tooltip: 'Fullscreen program',
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            );
          });
        },
      ),
    );
  }

  Widget _monitorLabelButton(String label, VoidCallback? onPressed) {
    return TextButton(
      onPressed: onPressed,
      style: TextButton.styleFrom(
        minimumSize: const Size(34, 30),
        padding: const EdgeInsets.symmetric(horizontal: 4),
        tapTargetSize: MaterialTapTargetSize.shrinkWrap,
      ),
      child: KText(label,
          style: TextStyle(
              color: _monitorChromeTextColor,
              fontSize: 10,
              decoration: TextDecoration.underline)),
    );
  }

  Widget _monitorIconButton({
    required Widget icon,
    required String tooltip,
    required VoidCallback? onPressed,
  }) {
    return IconButton(
      visualDensity: VisualDensity.compact,
      padding: EdgeInsets.zero,
      constraints: const BoxConstraints.tightFor(width: 30, height: 30),
      onPressed: onPressed,
      color: _monitorChromeTextColor,
      disabledColor: const Color(0xff6b7280),
      icon: icon,
      tooltip: tooltip,
    );
  }

  Future<void> _showMonitorFullscreen({required bool source}) async {
    final controller = source ? _sourceController : _previewController;
    if (controller == null || !controller.value.isInitialized) return;
    await showDialog<void>(
      context: context,
      barrierColor: _monitorCanvasColor,
      builder: (context) {
        return Dialog.fullscreen(
          backgroundColor: _monitorCanvasColor,
          child: Stack(
            children: [
              Positioned.fill(
                child: source
                    ? _liveSourceVideo(controller)
                    : _livePreviewVideo(controller),
              ),
              Positioned(
                left: 16,
                top: 12,
                right: 16,
                child: Row(
                  children: [
                    KText(
                      source ? 'SOURCE MONITOR' : 'PROGRAM MONITOR',
                      style: TextStyle(
                        color: _monitorChromeTextColor,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    const Spacer(),
                    IconButton.filledTonal(
                      onPressed: () => Navigator.of(context).pop(),
                      icon: const Icon(Icons.close),
                      tooltip: 'Close fullscreen',
                    ),
                  ],
                ),
              ),
              Positioned(
                left: 24,
                right: 24,
                bottom: 24,
                child: _fullscreenTransportBar(
                  source: source,
                  controller: controller,
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  Future<void> _showMonitorVolumeDialog({
    required String title,
    required double value,
    required ValueChanged<double> onChanged,
  }) async {
    var draft = value;
    await showDialog<void>(
      context: context,
      builder: (context) {
        return StatefulBuilder(
          builder: (context, setDialogState) {
            return Dialog(
              backgroundColor: _panelColor,
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(6),
                side: BorderSide(color: _panelBorderColor),
              ),
              child: Padding(
                padding: const EdgeInsets.fromLTRB(14, 10, 14, 12),
                child: SizedBox(
                  width: 300,
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Row(
                        children: [
                          Icon(
                            draft <= 0
                                ? Icons.volume_off_outlined
                                : Icons.volume_up_outlined,
                            color: _monitorChromeTextColor,
                          ),
                          const SizedBox(width: 10),
                          Expanded(
                            child: Slider(
                              value: draft.clamp(0.0, _maxAudioBoost),
                              min: 0,
                              max: _maxAudioBoost,
                              divisions: 60,
                              label: _volumeDbText(draft),
                              onChanged: (next) {
                                setDialogState(() => draft = next);
                                onChanged(next);
                              },
                            ),
                          ),
                        ],
                      ),
                      KText(
                        title,
                        style: TextStyle(
                          color: _mutedTextColor,
                          fontSize: 12,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        );
      },
    );
  }

  Widget _fullscreenTransportBar({
    required bool source,
    required VideoPlayerController controller,
  }) {
    return ValueListenableBuilder<VideoPlayerValue>(
      valueListenable: controller,
      builder: (context, value, child) {
        final initialized = value.isInitialized;
        final duration = initialized
            ? source
                ? value.duration.inMilliseconds / 1000
                : _programPlaybackDurationSeconds()
            : 0.0;
        final position = initialized
            ? source
                ? value.position.inMilliseconds / 1000
                : _currentProgramSeconds()
            : 0.0;
        return DecoratedBox(
          decoration: BoxDecoration(
            color: _monitorChromeColor.withOpacity(0.94),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: _monitorChromeBorderColor),
          ),
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
            child: Row(
              children: [
                SizedBox(
                  width: 48,
                  child: KText(
                    initialized ? _formatDuration(position) : '00:00',
                    style: const TextStyle(
                      color: Color(0xff60a5fa),
                      fontSize: 12,
                    ),
                  ),
                ),
                Expanded(
                  child: Slider(
                    value: duration <= 0 ? 0 : position.clamp(0.0, duration),
                    min: 0,
                    max: duration <= 0 ? 1 : duration,
                    onChanged: initialized
                        ? (next) => unawaited(
                              source
                                  ? _seekSourcePreview(next)
                                  : _seekProgramPreview(next),
                            )
                        : null,
                  ),
                ),
                _monitorIconButton(
                  onPressed: _videos.length < 2 ? null : _selectPreviousVideo,
                  icon: const Icon(Icons.skip_previous, size: 18),
                  tooltip: 'Previous clip',
                ),
                _monitorIconButton(
                  onPressed: initialized
                      ? (source ? _toggleSourcePreview : _togglePreview)
                      : null,
                  icon: Icon(
                    value.isPlaying ? Icons.pause : Icons.play_arrow,
                    size: 18,
                  ),
                  tooltip: 'Play',
                ),
                _monitorIconButton(
                  onPressed: _videos.length < 2 ? null : _selectNextVideo,
                  icon: const Icon(Icons.skip_next, size: 18),
                  tooltip: 'Next clip',
                ),
                _monitorIconButton(
                  onPressed: () => _showMonitorVolumeDialog(
                    title: source ? 'Source volume' : 'Program volume',
                    value: source ? _sourceVolume : _originalVolume,
                    onChanged: source ? _setSourceVolume : _setOriginalVolume,
                  ),
                  icon: Icon(
                    (source ? _sourceVolume : _effectiveOriginalVolume) <= 0
                        ? Icons.volume_off_outlined
                        : Icons.volume_up_outlined,
                    size: 18,
                  ),
                  tooltip: source ? 'Source volume' : 'Program volume',
                ),
                _monitorIconButton(
                  onPressed: () => Navigator.of(context).pop(),
                  icon: const Icon(Icons.fullscreen_exit, size: 20),
                  tooltip: 'Back to small screen',
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  Widget _liveSourceVideo(VideoPlayerController controller) {
    final size = controller.value.size;
    final videoWidth = size.width <= 0 ? 16.0 : size.width;
    final videoHeight = size.height <= 0 ? 9.0 : size.height;
    return SizedBox.expand(
      child: Center(
        child: FittedBox(
          fit: BoxFit.contain,
          child: SizedBox(
            width: videoWidth,
            height: videoHeight,
            child: VideoPlayer(controller),
          ),
        ),
      ),
    );
  }

  Widget _livePreviewVideo(VideoPlayerController controller) {
    final size = controller.value.size;
    final videoWidth = size.width <= 0 ? 16.0 : size.width;
    final videoHeight = size.height <= 0 ? 9.0 : size.height;
    final hFlip = _flip == 'left' || _flip == 'right' || _flip == 'up';
    final vFlip = _flip == 'up' || _flip == 'down';
    final xScale = _scaleX * _zoom * (hFlip ? -1 : 1);
    final yScale = _scaleY * _zoom * (vFlip ? -1 : 1);
    final textOverlays = _previewTextOverlays();
    final previewSeconds = _currentProgramSeconds();
    final professionalClip = _activeBaseVideoClip(previewSeconds);
    final canvasTransform = professionalClip?.transformAt(
      previewSeconds - professionalClip.timelineStart,
    );
    final hasLayeredVideo = _multiTrackTimeline.hasLayeredVideo;
    final activeVideoLayers = hasLayeredVideo
        ? MultiTrackPreview.activeVideoLayers(
            model: _multiTrackTimeline,
            playheadSeconds: previewSeconds,
            includeBaseTrack: true,
          )
        : const <({TrackModel track, ClipModel clip})>[];
    final directTextureLayer = hasLayeredVideo
        ? MultiTrackPreview.directTextureLayer(
            model: _multiTrackTimeline,
            playheadSeconds: previewSeconds,
            preferredMediaPath: _videos[_selectedVideoIndex].path,
          )
        : null;
    final useTrueMultiTrackPreview = hasLayeredVideo &&
        activeVideoLayers.isNotEmpty &&
        directTextureLayer == null;
    final hideLegacyTexture =
        hasLayeredVideo ? directTextureLayer == null : _videoTrackHidden;
    // video_player_win textures can turn into a gray surface when wrapped in
    // ColorFiltered/ImageFiltered. Keep the decoded texture direct on Windows;
    // the complete effect stack is still rendered by FFmpeg during export.
    final showPreviewEffects = !Platform.isWindows &&
        !_projectProxyEnabled &&
        widget.settings.previewQuality != PreviewQuality.low;
    final showTextOverlays =
        widget.settings.previewQuality != PreviewQuality.low;
    final animateTextOverlays = !_projectProxyEnabled &&
        widget.settings.previewQuality == PreviewQuality.full;

    return SizedBox.expand(
      child: Center(
        child: Padding(
          padding: const EdgeInsets.all(10),
          child: AspectRatio(
            aspectRatio: _previewAspectRatio(controller),
            child: DecoratedBox(
              decoration: BoxDecoration(
                color: _monitorCanvasColor,
                border: Border.all(color: const Color(0xff6b7280)),
                boxShadow: const [
                  BoxShadow(
                    color: Color(0xaa000000),
                    blurRadius: 12,
                    offset: Offset(0, 4),
                  ),
                ],
              ),
              child: Stack(
                clipBehavior: Clip.none,
                fit: StackFit.expand,
                children: [
                  Positioned.fill(
                    child: ClipRect(
                      child: _canvasPreviewBackground(
                        controller: controller,
                        videoSize: Size(videoWidth, videoHeight),
                        transform: canvasTransform,
                      ),
                    ),
                  ),
                  if (hideLegacyTexture)
                    const SizedBox.shrink()
                  else
                    Positioned.fill(
                      child: ClipRect(
                        child: LayoutBuilder(
                          builder: (context, constraints) {
                            final rect = _videoTransformRect(
                              canvasSize: constraints.biggest,
                              videoSize: Size(videoWidth, videoHeight),
                              xScale: xScale.abs(),
                              yScale: yScale.abs(),
                            );
                            return Stack(
                              clipBehavior: Clip.none,
                              children: [
                                Positioned(
                                  left: rect.left,
                                  top: rect.top,
                                  width: rect.width,
                                  height: rect.height,
                                  child: GestureDetector(
                                    behavior: HitTestBehavior.opaque,
                                    onTap: () => setState(() =>
                                        _programTransformOverlayVisible = true),
                                    child: Transform(
                                      alignment: Alignment.center,
                                      transform: Matrix4.diagonal3Values(
                                        hFlip ? -1 : 1,
                                        vFlip ? -1 : 1,
                                        1,
                                      ),
                                      child: Builder(
                                        builder: (context) {
                                          Widget video = showPreviewEffects
                                              ? ColorFiltered(
                                                  colorFilter:
                                                      ColorFilter.matrix(
                                                    _previewColorMatrix(),
                                                  ),
                                                  child:
                                                      VideoPlayer(controller),
                                                )
                                              : VideoPlayer(controller);
                                          if (professionalClip != null &&
                                              showPreviewEffects) {
                                            video = ProfessionalClipPreview(
                                              clip: professionalClip,
                                              playheadSeconds: previewSeconds,
                                              child: video,
                                            );
                                          }
                                          return video;
                                        },
                                      ),
                                    ),
                                  ),
                                ),
                              ],
                            );
                          },
                        ),
                      ),
                    ),
                  if (useTrueMultiTrackPreview)
                    Positioned.fill(
                      child: Builder(
                        builder: (context) {
                          Widget preview = MultiTrackPreview(
                            model: _multiTrackTimeline,
                            playheadSeconds: previewSeconds,
                            isPlaying: controller.value.isPlaying,
                            includeBaseTrack: true,
                            preferredController: controller,
                            preferredMediaPath:
                                _videos[_selectedVideoIndex].path,
                            previewMediaPaths: {
                              for (final video in _videos)
                                if (video.proxyPath != null &&
                                    File(video.proxyPath!).existsSync())
                                  video.path: video.proxyPath!,
                            },
                            playbackSpeedsByMediaPath: {
                              for (final video in _videos)
                                video.path:
                                    _clipTimelineEditFor(video.path).speed,
                            },
                            selectedClipId: _selectedTimelineClipId,
                            enableTextureEffects: !Platform.isWindows,
                            onClipSelected: (clipId) =>
                                unawaited(_selectMultiTrackClip(clipId)),
                          );
                          final hasColorAdjustment =
                              _brightness.abs() > 0.0001 ||
                                  (_contrast - 1).abs() > 0.0001 ||
                                  (_saturation - 1).abs() > 0.0001;
                          if (showPreviewEffects && hasColorAdjustment) {
                            preview = ColorFiltered(
                              colorFilter: ColorFilter.matrix(
                                _previewColorMatrix(),
                              ),
                              child: preview,
                            );
                          }
                          return preview;
                        },
                      ),
                    ),
                  if (_programTransformOverlayVisible &&
                      !useTrueMultiTrackPreview)
                    Positioned.fill(
                      child: LayoutBuilder(
                        builder: (context, constraints) {
                          return Stack(
                            clipBehavior: Clip.none,
                            children: [
                              _outputFrameDragOverlay(
                                canvasSize: constraints.biggest,
                                videoSize: Size(videoWidth, videoHeight),
                                xScale: xScale.abs(),
                                yScale: yScale.abs(),
                              ),
                            ],
                          );
                        },
                      ),
                    ),
                  for (final entry in textOverlays.indexed)
                    if (showTextOverlays &&
                        entry.$2.isVisible &&
                        entry.$2.text.trim().isNotEmpty &&
                        (entry.$2.duration <= 0 ||
                            (previewSeconds >= entry.$2.timelineStart &&
                                previewSeconds <
                                    entry.$2.timelineStart +
                                        entry.$2.duration)))
                      LayoutBuilder(
                        builder: (context, constraints) {
                          final overlay = entry.$2;
                          final selected =
                              entry.$1 == _selectedTextOverlayIndex;
                          final child = GestureDetector(
                            behavior: HitTestBehavior.translucent,
                            onTap: () => _selectTextOverlay(entry.$1),
                            onPanStart: selected && !overlay.isLocked
                                ? (_) => _recordEditorHistory('text-position')
                                : null,
                            onPanUpdate: selected && !overlay.isLocked
                                ? (details) {
                                    final width = constraints.maxWidth <= 0
                                        ? 260.0
                                        : constraints.maxWidth;
                                    final height = constraints.maxHeight <= 0
                                        ? 260.0
                                        : constraints.maxHeight;
                                    setState(() {
                                      _overlayTextX = (_overlayTextX +
                                              details.delta.dx / width)
                                          .clamp(0.0, 1.0)
                                          .toDouble();
                                      _overlayTextY = (_overlayTextY +
                                              details.delta.dy / height)
                                          .clamp(0.0, 1.0)
                                          .toDouble();
                                      final next = _currentTextOverlayDraft();
                                      _textOverlays[_selectedTextOverlayIndex] =
                                          next;
                                      _insertTextTimelineClip(next);
                                    });
                                  }
                                : null,
                            child: _styledOverlayText(overlay),
                          );
                          if (!animateTextOverlays) {
                            return Align(
                              alignment: Alignment(
                                overlay.x * 2 - 1,
                                overlay.y * 2 - 1,
                              ),
                              child: child,
                            );
                          }
                          return AnimatedBuilder(
                            animation: _textAnimationController,
                            builder: (context, child) {
                              final position = _previewTextPosition(
                                _textAnimationPhase(overlay),
                                overlay,
                              );
                              return Align(
                                alignment: Alignment(
                                  position.dx * 2 - 1,
                                  position.dy * 2 - 1,
                                ),
                                child: child,
                              );
                            },
                            child: child,
                          );
                        },
                      ),
                  if (_watermarkPath != null)
                    LayoutBuilder(
                      builder: (context, constraints) {
                        final previewHeight = constraints.maxHeight <= 0
                            ? videoHeight
                            : constraints.maxHeight;
                        return Align(
                          alignment: Alignment(
                            _watermarkX * 2 - 1,
                            _watermarkY * 2 - 1,
                          ),
                          child: GestureDetector(
                            behavior: HitTestBehavior.translucent,
                            onPanStart: (_) =>
                                _recordEditorHistory('watermark-position'),
                            onPanUpdate: (details) {
                              final width = constraints.maxWidth <= 0
                                  ? 260.0
                                  : constraints.maxWidth;
                              final height = constraints.maxHeight <= 0
                                  ? 260.0
                                  : constraints.maxHeight;
                              setState(() {
                                _watermarkX =
                                    (_watermarkX + details.delta.dx / width)
                                        .clamp(0.0, 1.0)
                                        .toDouble();
                                _watermarkY =
                                    (_watermarkY + details.delta.dy / height)
                                        .clamp(0.0, 1.0)
                                        .toDouble();
                              });
                            },
                            child: ClipRect(
                              child: Image.file(
                                File(_watermarkPath!),
                                height: (previewHeight * _watermarkSize)
                                    .clamp(24, 220),
                              ),
                            ),
                          ),
                        );
                      },
                    ),
                  _captionPreviewLayer(
                    controller: controller,
                    videoHeight: videoHeight,
                  ),
                  if (_outputRatio != 'original' &&
                      _programTransformOverlayVisible)
                    const Positioned(
                      right: 10,
                      top: 10,
                      child: DecoratedBox(
                        decoration: BoxDecoration(
                          color: Color(0xaa000000),
                          borderRadius: BorderRadius.all(Radius.circular(6)),
                        ),
                        child: Padding(
                          padding:
                              EdgeInsets.symmetric(horizontal: 8, vertical: 5),
                          child: KText(
                            'Drag to reframe',
                            style: TextStyle(color: Colors.white, fontSize: 12),
                          ),
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }

  ClipModel? _activeBaseVideoClip(double playhead) {
    if (_multiTrackTimeline.videoTracks.isEmpty) return null;
    final track = _multiTrackTimeline.videoTracks.first;
    if (track.isMuted) return null;
    for (final clip in track.clips) {
      if (!clip.isMuted &&
          playhead >= clip.timelineStart &&
          playhead < clip.timelineEnd) {
        return clip;
      }
    }
    return null;
  }

  Widget _canvasPreviewBackground({
    required VideoPlayerController controller,
    required Size videoSize,
    ClipTransform? transform,
  }) {
    final mode = transform?.canvasMode ?? _canvasMode;
    final color = _parseHexColor(transform?.canvasColor ?? '') ?? _canvasColor;
    final pattern = transform?.canvasPattern ?? _canvasPattern;
    final blur = transform?.canvasBlur ?? _canvasBlur;
    switch (mode) {
      case 'blur':
        return Stack(
          fit: StackFit.expand,
          children: [
            ImageFiltered(
              imageFilter: ui.ImageFilter.blur(
                sigmaX: blur.clamp(4, 80).toDouble(),
                sigmaY: blur.clamp(4, 80).toDouble(),
                tileMode: TileMode.mirror,
              ),
              child: Transform.scale(
                scale: 1.12,
                child: FittedBox(
                  fit: BoxFit.cover,
                  clipBehavior: Clip.hardEdge,
                  child: SizedBox(
                    width: videoSize.width,
                    height: videoSize.height,
                    child: VideoPlayer(controller),
                  ),
                ),
              ),
            ),
            const ColoredBox(color: Color(0x18000000)),
          ],
        );
      case 'color':
        return ColoredBox(color: color);
      case 'pattern':
        return CustomPaint(
          painter: _CanvasPatternPainter(
            pattern: pattern,
            color: color,
          ),
        );
      default:
        return ColoredBox(color: _monitorCanvasColor);
    }
  }

  Widget _captionPreviewLayer({
    required VideoPlayerController controller,
    required double videoHeight,
  }) {
    return Positioned.fill(
      child: ValueListenableBuilder<VideoPlayerValue>(
        valueListenable: controller,
        builder: (context, value, child) {
          final cue = _activeCaptionCue();
          if (cue == null) return const SizedBox.shrink();
          return LayoutBuilder(
            builder: (context, constraints) {
              final previewHeight = constraints.maxHeight <= 0
                  ? videoHeight
                  : constraints.maxHeight;
              final scale = previewHeight / videoHeight;
              final fontSize = _captionPreviewFontSize(
                scale: scale,
                previewHeight: previewHeight,
              );
              final preset = _captionPreset(_captionStyle);
              final style = _resolvedCaptionStyle;
              final currentSeconds = value.position.inMilliseconds / 1000;
              final captionBackground = style.backgroundColor.withOpacity(
                style.backgroundOpacity,
              );
              final caption = _captionWordFlow(
                cue: cue,
                currentSeconds: currentSeconds,
                preset: preset,
                fontSize: fontSize,
                scale: scale,
              );
              return Align(
                alignment: Alignment(
                  cue.x.clamp(0.0, 1.0) * 2 - 1,
                  cue.y.clamp(0.0, 1.0) * 2 - 1,
                ),
                child: GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onPanStart: (_) => _recordEditorHistory('caption-position'),
                  onPanUpdate: (details) => _dragSelectedCaptions(
                    cue,
                    Offset(
                      details.delta.dx / math.max(1, constraints.maxWidth),
                      details.delta.dy / math.max(1, previewHeight),
                    ),
                  ),
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      color: captionBackground,
                      borderRadius: BorderRadius.circular(
                        (style.borderRadius * scale)
                            .clamp(0.0, 24.0)
                            .toDouble(),
                      ),
                    ),
                    child: Padding(
                      padding: captionBackground == Colors.transparent
                          ? EdgeInsets.zero
                          : EdgeInsets.symmetric(
                              horizontal: (style.padding * scale)
                                  .clamp(2.0, 50.0)
                                  .toDouble(),
                              vertical: (style.padding * 0.5 * scale)
                                  .clamp(1.0, 30.0)
                                  .toDouble(),
                            ),
                      child: caption,
                    ),
                  ),
                ),
              );
            },
          );
        },
      ),
    );
  }

  Widget _captionWordFlow({
    required _CaptionCue cue,
    required double currentSeconds,
    required _CaptionPreset preset,
    required double fontSize,
    required double scale,
  }) {
    final resolved = _resolvedCaptionStyle;
    TextStyle style(Color color, {bool active = false}) {
      return TextStyle(
        color: color.withOpacity(resolved.opacity),
        fontFamily: resolved.fontFamily,
        fontSize: fontSize,
        fontWeight: resolved.bold ? FontWeight.w900 : FontWeight.w400,
        fontStyle: resolved.italic ? FontStyle.italic : FontStyle.normal,
        decoration:
            resolved.underline ? TextDecoration.underline : TextDecoration.none,
        decorationColor: color,
        letterSpacing: resolved.letterSpacing * scale,
        height: (1.05 + resolved.lineSpacing / math.max(5, resolved.fontSize))
            .clamp(0.65, 3.0)
            .toDouble(),
        shadows: _captionTextShadows(
          preset,
          preset.motion == 'glow' && active ? scale * 1.6 : scale,
          custom: true,
        ),
      );
    }

    String display(String text) {
      return switch (_captionCase) {
        'upper' => text.toUpperCase(),
        'lower' => text.toLowerCase(),
        'title' => text
            .split(RegExp(r'\s+'))
            .map((word) => word.isEmpty
                ? word
                : '${word[0].toUpperCase()}${word.substring(1).toLowerCase()}')
            .join(' '),
        _ => text,
      };
    }

    if (cue.words.isEmpty) {
      return KText(
        display(cue.text),
        maxLines: 3,
        overflow: TextOverflow.visible,
        textAlign: TextAlign.center,
        style: style(resolved.color, active: true),
      );
    }

    return Wrap(
      alignment: WrapAlignment.center,
      runAlignment: WrapAlignment.center,
      crossAxisAlignment: WrapCrossAlignment.center,
      spacing: (fontSize * 0.22 + resolved.wordSpacing * scale)
          .clamp(2.0, 120.0)
          .toDouble(),
      runSpacing: (fontSize * 0.08).clamp(1.0, 12.0).toDouble(),
      children: [
        for (final entry in cue.words.indexed)
          Builder(
            builder: (context) {
              final word = entry.$2;
              final active =
                  currentSeconds >= word.start && currentSeconds < word.end;
              final activeBox = preset.motion == 'box' && active
                  ? preset.activeBoxColor
                  : Colors.transparent;
              final wordWidget = AnimatedContainer(
                duration: const Duration(milliseconds: 90),
                curve: Curves.easeOutBack,
                padding: preset.motion != 'box'
                    ? EdgeInsets.zero
                    : EdgeInsets.symmetric(
                        horizontal: (7 * scale).clamp(3.0, 12.0).toDouble(),
                        vertical: (3 * scale).clamp(1.5, 7.0).toDouble(),
                      ),
                decoration: BoxDecoration(
                  color: activeBox,
                  borderRadius: BorderRadius.circular(
                    (5 * scale).clamp(2.0, 9.0).toDouble(),
                  ),
                ),
                child: KText(
                  display(word.text),
                  style: style(
                    active ? resolved.color : preset.inactiveColor,
                    active: active,
                  ),
                ),
              );
              final scaleValue = !active
                  ? 1.0
                  : preset.motion == 'big_word'
                      ? 1.48
                      : (preset.motion == 'pop' || preset.motion == 'bounce')
                          ? 1.18
                          : 1.0;
              final animated = AnimatedScale(
                scale: scaleValue,
                duration: const Duration(milliseconds: 110),
                curve: Curves.easeOutBack,
                child: wordWidget,
              );
              final center = (cue.words.length - 1) / 2;
              final normalized =
                  center <= 0 ? 0.0 : (entry.$1 - center) / center;
              final curveOffset =
                  _captionCurve / 100 * fontSize * normalized * normalized;
              final bounceOffset = !active
                  ? 0.0
                  : preset.motion == 'big_word'
                      ? -fontSize * 0.18
                      : preset.motion == 'bounce'
                          ? -fontSize * 0.12
                          : 0.0;
              return Transform.translate(
                offset: Offset(0, curveOffset + bounceOffset),
                child: Transform.rotate(
                  angle: -_captionCurve / 100 * normalized * 0.22,
                  child: animated,
                ),
              );
            },
          ),
      ],
    );
  }

  Widget _outputFrameDragOverlay({
    required Size canvasSize,
    required Size videoSize,
    required double xScale,
    required double yScale,
  }) {
    if (_videoTrackHidden ||
        canvasSize.width <= 0 ||
        canvasSize.height <= 0 ||
        videoSize.width <= 0 ||
        videoSize.height <= 0) {
      return const SizedBox.shrink();
    }

    final rect = _videoTransformRect(
      canvasSize: canvasSize,
      videoSize: videoSize,
      xScale: xScale,
      yScale: yScale,
    );
    final travel = _videoTransformTravel(
      canvasSize: canvasSize,
      visualSize: rect.size,
    );

    void moveFrame(DragUpdateDetails details) {
      final nextPanX = travel.dx > 0.5
          ? (_panX + details.delta.dx / travel.dx).clamp(-1.0, 1.0).toDouble()
          : _panX;
      final nextPanY = travel.dy > 0.5
          ? (_panY + details.delta.dy / travel.dy).clamp(-1.0, 1.0).toDouble()
          : _panY;
      _setSelectedTransformEdit(
        (edit) => edit.copyWith(
          panX: nextPanX,
          panY: nextPanY,
        ),
      );
    }

    return Positioned(
      left: rect.left,
      top: rect.top,
      width: rect.width,
      height: rect.height,
      child: Stack(
        clipBehavior: Clip.none,
        children: [
          Positioned.fill(
            child: MouseRegion(
              cursor: SystemMouseCursors.move,
              child: GestureDetector(
                behavior: HitTestBehavior.translucent,
                onPanUpdate: moveFrame,
                child: DecoratedBox(
                  decoration: BoxDecoration(
                    border: Border.all(color: Colors.white, width: 1.4),
                  ),
                ),
              ),
            ),
          ),
          _resizeCornerHandle(Alignment.topLeft),
          _resizeCornerHandle(Alignment.topRight),
          _resizeCornerHandle(Alignment.bottomLeft),
          _resizeCornerHandle(Alignment.bottomRight),
        ],
      ),
    );
  }

  Widget _resizeCornerHandle(Alignment alignment) {
    final left = alignment.x < 0 ? -7.0 : null;
    final right = alignment.x > 0 ? -7.0 : null;
    final top = alignment.y < 0 ? -7.0 : null;
    final bottom = alignment.y > 0 ? -7.0 : null;
    final cornerKey = '${alignment.x}:${alignment.y}';
    final active = _activeResizeCornerKey == cornerKey;
    return Positioned(
      left: left,
      right: right,
      top: top,
      bottom: bottom,
      child: MouseRegion(
        cursor: alignment.x * alignment.y > 0
            ? SystemMouseCursors.resizeUpLeftDownRight
            : SystemMouseCursors.resizeUpRightDownLeft,
        onEnter: (_) => setState(() => _activeResizeCornerKey = cornerKey),
        onExit: (_) {
          if (_activeResizeCornerKey == cornerKey) {
            setState(() => _activeResizeCornerKey = null);
          }
        },
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onPanStart: (_) => setState(() => _activeResizeCornerKey = cornerKey),
          onPanUpdate: (details) {
            final horizontalDelta =
                alignment.x < 0 ? -details.delta.dx : details.delta.dx;
            final verticalDelta =
                alignment.y < 0 ? -details.delta.dy : details.delta.dy;
            final delta = (horizontalDelta + verticalDelta) / 220;
            final factor = (1 + delta).clamp(0.2, 5.0).toDouble();
            final nextScaleX = (_scaleX * factor).clamp(0.1, 3.0).toDouble();
            final nextScaleY = (_scaleY * factor).clamp(0.1, 3.0).toDouble();
            _setSelectedTransformEdit(
              (edit) => edit.copyWith(
                scaleX: nextScaleX,
                scaleY: nextScaleY,
              ),
            );
          },
          onPanEnd: (_) {
            if (_activeResizeCornerKey == cornerKey) {
              setState(() => _activeResizeCornerKey = null);
            }
          },
          onPanCancel: () {
            if (_activeResizeCornerKey == cornerKey) {
              setState(() => _activeResizeCornerKey = null);
            }
          },
          child: SizedBox(
            width: 30,
            height: 30,
            child: Stack(
              clipBehavior: Clip.none,
              alignment: Alignment.center,
              children: [
                if (active)
                  Transform.rotate(
                    angle: alignment.x * alignment.y > 0 ? 0 : math.pi / 2,
                    child: const Icon(
                      Icons.open_in_full,
                      color: Colors.white,
                      size: 20,
                      shadows: [
                        Shadow(color: Colors.black, blurRadius: 4),
                      ],
                    ),
                  ),
                const DecoratedBox(
                  decoration: BoxDecoration(
                    color: Colors.white,
                    shape: BoxShape.circle,
                    boxShadow: [
                      BoxShadow(color: Color(0xaa000000), blurRadius: 3),
                    ],
                  ),
                  child: SizedBox(width: 11, height: 11),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Rect _videoTransformRect({
    required Size canvasSize,
    required Size videoSize,
    required double xScale,
    required double yScale,
  }) {
    final baseSize = _videoTransformBaseSize(
      canvasSize: canvasSize,
      videoSize: videoSize,
    );
    final baseWidth = baseSize.width;
    final baseHeight = baseSize.height;
    final visualSize = Size(baseWidth * xScale, baseHeight * yScale);
    final travel = _videoTransformTravel(
      canvasSize: canvasSize,
      visualSize: visualSize,
    );
    final left = (canvasSize.width - visualSize.width) / 2 +
        _panX.clamp(-1.0, 1.0) * travel.dx;
    final top = (canvasSize.height - visualSize.height) / 2 +
        _panY.clamp(-1.0, 1.0) * travel.dy;
    return Rect.fromLTWH(left, top, visualSize.width, visualSize.height);
  }

  Size _videoTransformBaseSize({
    required Size canvasSize,
    required Size videoSize,
  }) {
    final sourceRatio = videoSize.width / videoSize.height;
    final canvasRatio = canvasSize.width / canvasSize.height;

    var baseWidth = canvasSize.width;
    var baseHeight = baseWidth / sourceRatio;
    if (baseHeight > canvasSize.height || sourceRatio < canvasRatio) {
      baseHeight = canvasSize.height;
      baseWidth = baseHeight * sourceRatio;
    }
    return Size(baseWidth, baseHeight);
  }

  Offset _videoTransformTravel({
    required Size canvasSize,
    required Size visualSize,
  }) {
    return Offset(
      ((canvasSize.width - visualSize.width).abs() / 2).toDouble(),
      ((canvasSize.height - visualSize.height).abs() / 2).toDouble(),
    );
  }

  Widget _styledOverlayText(_TextOverlayDraft overlay) {
    return AnimatedBuilder(
      animation: _textAnimationController,
      builder: (context, child) {
        final phase = _textAnimationPhase(overlay);
        final effect = _previewTextEffect(phase, overlay);
        final text = effect.text;
        if (text.isEmpty) {
          return const SizedBox.shrink();
        }

        final fontSize = overlay.size.clamp(16, 96).toDouble();
        final baseStyle = TextStyle(
          fontFamily: overlay.font,
          fontSize: fontSize,
          fontWeight: FontWeight.w800,
          letterSpacing: overlay.tracking,
          height: 1,
          shadows: overlay.shadowOpacity <= 0
              ? null
              : [
                  Shadow(
                    blurRadius: 7,
                    color:
                        overlay.shadowColor.withOpacity(overlay.shadowOpacity),
                    offset: const Offset(3, 3),
                  ),
                ],
        );

        final textStack = Stack(
          clipBehavior: Clip.none,
          alignment: Alignment.center,
          children: [
            if (effect.showLine)
              Positioned(
                left: 0,
                right: 0,
                bottom: -8,
                child: FractionallySizedBox(
                  widthFactor: effect.lineWidth,
                  child: Container(
                    height: 4,
                    decoration: BoxDecoration(
                      color: overlay.strokeColor.withOpacity(
                        overlay.strokeOpacity * effect.opacity,
                      ),
                      borderRadius: BorderRadius.circular(999),
                    ),
                  ),
                ),
              ),
            if (overlay.stroke > 0 && overlay.strokeOpacity > 0)
              KText(
                text,
                textAlign: TextAlign.center,
                style: baseStyle.copyWith(
                  foreground: ui.Paint()
                    ..style = ui.PaintingStyle.stroke
                    ..strokeWidth = overlay.stroke * effect.scale
                    ..strokeJoin = ui.StrokeJoin.round
                    ..color = overlay.strokeColor.withOpacity(
                      overlay.strokeOpacity * effect.opacity,
                    ),
                ),
              ),
            KText(
              text,
              textAlign: TextAlign.center,
              style: baseStyle.copyWith(
                color: overlay.color.withOpacity(
                  overlay.opacity * effect.opacity,
                ),
              ),
            ),
          ],
        );

        return Opacity(
          opacity: effect.opacity.clamp(0.0, 1.0),
          child: Transform.rotate(
            angle: overlay.curve / 100 * 0.12,
            child: Transform.scale(scale: effect.scale, child: textStack),
          ),
        );
      },
    );
  }

  _TextPreviewEffect _previewTextEffect(
    double phase,
    _TextOverlayDraft overlay,
  ) {
    final animation = overlay.animation.replaceAll('-', ' ');
    final eased = Curves.easeOutCubic.transform(phase.clamp(0, 1));
    final text = overlay.text;
    return switch (animation) {
      'fade in' => _TextPreviewEffect(
          text: text,
          opacity: phase.clamp(0, 1).toDouble(),
        ),
      'fade out' => _TextPreviewEffect(
          text: text,
          opacity: (1 - phase).clamp(0, 1).toDouble(),
        ),
      'text typing' => _TextPreviewEffect(
          text: String.fromCharCodes(
            text.runes.take(
              (text.runes.length * phase.clamp(0, 1)).ceil(),
            ),
          ),
        ),
      'flow up' => _TextPreviewEffect(
          text: text,
          opacity: eased,
        ),
      'flow down' => _TextPreviewEffect(
          text: text,
          opacity: eased,
        ),
      'flow left' => _TextPreviewEffect(
          text: text,
          opacity: eased,
        ),
      'flow right' => _TextPreviewEffect(
          text: text,
          opacity: eased,
        ),
      'pop up line' => _TextPreviewEffect(
          text: text,
          opacity: eased,
          scale: 0.7 + 0.3 * eased,
          showLine: true,
          lineWidth: eased,
        ),
      'pulse' => _TextPreviewEffect(
          text: text,
          opacity: 0.72 + 0.28 * (phase < 0.5 ? phase * 2 : (1 - phase) * 2),
          scale: 0.96 + 0.04 * (phase < 0.5 ? phase * 2 : (1 - phase) * 2),
        ),
      _ => _TextPreviewEffect(text: text),
    };
  }

  double _textAnimationPhase(_TextOverlayDraft overlay) {
    final durationMs =
        (overlay.animationDuration * 1000).clamp(200, 5000).round();
    final elapsed =
        DateTime.now().difference(_textAnimationStartedAt).inMilliseconds;
    return (elapsed % durationMs) / durationMs;
  }

  Offset _previewTextPosition(double phase, _TextOverlayDraft overlay) {
    final animation = overlay.animation.replaceAll('-', ' ');
    if (!animation.startsWith('flow')) {
      return Offset(overlay.x, overlay.y);
    }
    final eased = Curves.easeOutCubic.transform(phase.clamp(0, 1));
    return Offset(
      overlay.startX + (overlay.x - overlay.startX) * eased,
      overlay.startY + (overlay.y - overlay.startY) * eased,
    );
  }

  double _previewAspectRatio(VideoPlayerController controller) {
    return switch (_outputRatio) {
      '16:9' => 16 / 9,
      '9:16' => 9 / 16,
      '4:5' => 4 / 5,
      '1:1' => 1,
      '3:4' => 3 / 4,
      '4:3' => 4 / 3,
      _ => controller.value.aspectRatio == 0
          ? 16 / 9
          : controller.value.aspectRatio,
    };
  }

  List<double> _previewColorMatrix() {
    final saturation = _saturation.clamp(0.0, 3.0).toDouble();
    final contrast = _contrast.clamp(0.0, 3.0).toDouble();
    final brightness = (_brightness.clamp(-1.0, 1.0) * 255).toDouble();
    const r = 0.2126;
    const g = 0.7152;
    const b = 0.0722;
    final sr = (1 - saturation) * r;
    final sg = (1 - saturation) * g;
    final sb = (1 - saturation) * b;
    final offset = 128 * (1 - contrast) + brightness;
    return [
      (sr + saturation) * contrast,
      sg * contrast,
      sb * contrast,
      0,
      offset,
      sr * contrast,
      (sg + saturation) * contrast,
      sb * contrast,
      0,
      offset,
      sr * contrast,
      sg * contrast,
      (sb + saturation) * contrast,
      0,
      offset,
      0,
      0,
      0,
      1,
      0,
    ];
  }

  Future<void> _setPreviewSpeed(double value) async {
    final speed = value.clamp(_minVideoSpeed, _maxVideoSpeed).toDouble();
    _setSelectedTransformEdit((edit) => edit.copyWith(speed: speed));
    final controller = _previewController;
    if (controller != null && controller.value.isInitialized) {
      try {
        await controller.setPlaybackSpeed(speed);
      } catch (_) {
        if (!mounted) return;
        setState(() {
          _status = 'Speed will apply on export. Preview player limited it.';
        });
      }
    }
  }

  void _setSourceVolume(double value) {
    setState(() => _sourceVolume = value);
    final controller = _sourceController;
    if (controller != null && controller.value.isInitialized) {
      unawaited(controller.setVolume(_previewAudioVolume(value)));
    }
  }

  void _setOriginalVolume(double value) {
    if (_videos.isEmpty) return;
    _recordEditorHistory('audio-original-volume');
    final path = _videos[_selectedVideoIndex].path;
    setState(() {
      _originalVolume = value;
      _clipTimelineEdits[path] =
          _clipTimelineEditFor(path).copyWith(originalVolume: value);
      _multiTrackTimeline = _multiTrackTimeline.copyWith(
        tracks: [
          for (final track in _multiTrackTimeline.tracks)
            track.type == TrackType.audio
                ? track.copyWith(
                    clips: [
                      for (final clip in track.clips)
                        clip.mediaPath == path
                            ? clip.copyWith(volume: value)
                            : clip,
                    ],
                  )
                : track,
        ],
      );
      _storeActiveCompositionTimeline();
    });
    final controller = _previewController;
    if (controller != null && controller.value.isInitialized) {
      unawaited(
          controller.setVolume(_previewAudioVolume(_effectiveOriginalVolume)));
    }
    unawaited(_autosaveProject());
  }

  void _setMusicVolume(double value) {
    _recordEditorHistory('audio-music-volume');
    setState(() => _musicVolume = value);
    unawaited(_musicPreviewPlayer
        .setVolume(_previewAudioVolume(_effectiveMusicVolume)));
  }

  bool get _activeTimelineSourceAudioMuted {
    final videoId = _programTimelineClipId ?? _selectedTimelineClipId;
    if (videoId == null) return false;
    final linked = _multiTrackTimeline.linkedAudioForVideo(videoId);
    if (linked == null) return false;
    final result = _multiTrackTimeline.clipById(linked.id);
    return linked.isMuted || result?.track.isMuted == true;
  }

  double get _effectiveOriginalVolume =>
      _originalAudioMuted || _activeTimelineSourceAudioMuted
          ? 0
          : _originalVolume;

  double get _effectiveMusicVolume => _musicTrackMuted ? 0 : _musicVolume;

  double _previewAudioVolume(double value) => value.clamp(0.0, 1.0).toDouble();

  void _setTextAnimation(String value) {
    _updateTextControl('text-animation', () {
      _overlayTextAnimation = value;
      switch (value) {
        case 'flow up':
          _overlayTextStartX = _overlayTextX;
          _overlayTextStartY = 1;
          break;
        case 'flow down':
          _overlayTextStartX = _overlayTextX;
          _overlayTextStartY = 0;
          break;
        case 'flow left':
          _overlayTextStartX = 0;
          _overlayTextStartY = _overlayTextY;
          break;
        case 'flow right':
          _overlayTextStartX = 1;
          _overlayTextStartY = _overlayTextY;
          break;
      }
    });
  }

  String _layerTitle(_TextOverlayDraft overlay, int index) {
    final text = overlay.text.trim();
    return text.isEmpty ? 'Text ${index + 1}' : text;
  }

  _TextOverlayDraft _currentTextOverlayDraft() {
    final current = _selectedTextOverlayIndex >= 0 &&
            _selectedTextOverlayIndex < _textOverlays.length
        ? _textOverlays[_selectedTextOverlayIndex]
        : const _TextOverlayDraft();
    return _TextOverlayDraft(
      id: current.id,
      text: _overlayTextController.text,
      font: _overlayFont,
      size: _overlayTextSize,
      color: _overlayTextColor,
      opacity: _overlayTextOpacity,
      stroke: _overlayTextStroke,
      strokeColor: _overlayTextStrokeColor,
      strokeOpacity: _overlayTextStrokeOpacity,
      shadowColor: _overlayTextShadowColor,
      shadowOpacity: _overlayTextShadowOpacity,
      animation: _overlayTextAnimation,
      animationDuration: _overlayTextAnimationDuration,
      x: _overlayTextX,
      y: _overlayTextY,
      startX: _overlayTextStartX,
      startY: _overlayTextStartY,
      timelineStart: current.timelineStart,
      duration: current.duration,
      trackIndex: current.trackIndex,
      isVisible: current.isVisible,
      isLocked: current.isLocked,
      tracking: _overlayTextTracking,
      curve: _overlayTextCurve,
    );
  }

  void _saveSelectedTextOverlay() {
    if (_selectedTextOverlayIndex < 0 ||
        _selectedTextOverlayIndex >= _textOverlays.length) {
      return;
    }
    final current = _currentTextOverlayDraft();
    _textOverlays[_selectedTextOverlayIndex] = current;
    final selectedTextIds = _effectiveSelectedTimelineClipIds.where((id) {
      final result = _multiTrackTimeline.clipById(id);
      return result?.track.type == TrackType.text &&
          result?.track.isLocked != true;
    }).toSet();
    if (selectedTextIds.length <= 1) return;
    for (var index = 0; index < _textOverlays.length; index++) {
      final overlay = _textOverlays[index];
      if (overlay.id == current.id ||
          !selectedTextIds.contains(overlay.id) ||
          overlay.isLocked) {
        continue;
      }
      _textOverlays[index] = overlay.copyWith(
        font: current.font,
        size: current.size,
        color: current.color,
        opacity: current.opacity,
        stroke: current.stroke,
        strokeColor: current.strokeColor,
        strokeOpacity: current.strokeOpacity,
        shadowColor: current.shadowColor,
        shadowOpacity: current.shadowOpacity,
        animation: current.animation,
        animationDuration: current.animationDuration,
        x: current.x,
        y: current.y,
        startX: current.startX,
        startY: current.startY,
        tracking: current.tracking,
        curve: current.curve,
      );
    }
  }

  void _loadTextOverlay(_TextOverlayDraft overlay) {
    _overlayTextController.text = overlay.text;
    _overlayFont = overlay.font;
    _overlayTextSize = overlay.size;
    _overlayTextColor = overlay.color;
    _overlayTextOpacity = overlay.opacity;
    _overlayTextStroke = overlay.stroke;
    _overlayTextStrokeColor = overlay.strokeColor;
    _overlayTextStrokeOpacity = overlay.strokeOpacity;
    _overlayTextShadowColor = overlay.shadowColor;
    _overlayTextShadowOpacity = overlay.shadowOpacity;
    _overlayTextAnimation = overlay.animation;
    _overlayTextAnimationDuration = overlay.animationDuration;
    _overlayTextX = overlay.x;
    _overlayTextY = overlay.y;
    _overlayTextStartX = overlay.startX;
    _overlayTextStartY = overlay.startY;
    _overlayTextTracking = overlay.tracking;
    _overlayTextCurve = overlay.curve;
  }

  void _selectTextOverlay(int index) {
    if (index < 0 || index >= _textOverlays.length) return;
    setState(() {
      _saveSelectedTextOverlay();
      _selectedTextOverlayIndex = index;
      _loadTextOverlay(_textOverlays[index]);
      _selectedTimelineClipId = _textOverlays[index].id;
      _editorSelection = EditorSelection.text(
        _textOverlays[index].id,
        label: _layerTitle(_textOverlays[index], index),
      );
      _visibleWorkspacePanels.add('inspector');
    });
  }

  int _nextTextTrackIndex() {
    final indexes = <int>{
      for (final track in _multiTrackTimeline.textTracks) track.index,
      for (final overlay in _textOverlays)
        if (overlay.text.trim().isNotEmpty) overlay.trackIndex,
    };
    return indexes.isEmpty ? 1 : indexes.reduce(math.max) + 1;
  }

  void _insertTextTimelineClip(_TextOverlayDraft overlay) {
    if (overlay.id.isEmpty || overlay.text.trim().isEmpty) return;
    var tracks = [..._multiTrackTimeline.tracks];
    var trackIndex = tracks.indexWhere(
      (track) =>
          track.type == TrackType.text && track.index == overlay.trackIndex,
    );
    if (trackIndex < 0) {
      tracks.add(
        TrackModel(
          id: 'text-${overlay.trackIndex}',
          type: TrackType.text,
          index: overlay.trackIndex,
          isMuted: !overlay.isVisible,
          isLocked: overlay.isLocked,
        ),
      );
      trackIndex = tracks.length - 1;
    }
    final track = tracks[trackIndex];
    final clip = ClipModel(
      id: overlay.id,
      mediaPath: overlay.id,
      timelineStart: overlay.timelineStart,
      duration: overlay.duration <= 0
          ? math.max(0.5, _multiTrackTimeline.duration)
          : overlay.duration,
      sourceStart: 0,
      zIndex: overlay.trackIndex - 1,
    );
    tracks[trackIndex] = track.copyWith(
      isMuted: !overlay.isVisible,
      isLocked: overlay.isLocked,
      clips: [
        ...track.clips.where((item) => item.id != overlay.id),
        clip,
      ],
    );
    _multiTrackTimeline = TimelineModel(
      tracks: tracks,
      duration: TimelineModel.calculateDuration(tracks),
    ).normalized();
  }

  void _ensureTextTimelineTracks() {
    for (var index = 0; index < _textOverlays.length; index++) {
      var overlay = _textOverlays[index];
      if (overlay.text.trim().isEmpty) continue;
      if (overlay.id.isEmpty) {
        final migratedStart =
            overlay.timelineStart > 0 ? overlay.timelineStart : index * 5.0;
        final available = _multiTrackTimeline.duration - migratedStart;
        overlay = overlay.copyWith(
          id: 'text-legacy-${index + 1}',
          trackIndex: index + 1,
          timelineStart: migratedStart,
          duration: overlay.duration <= 0
              ? math.max(0.5, math.min(5.0, math.max(0.5, available)))
              : overlay.duration,
        );
        _textOverlays[index] = overlay;
      }
      if (_multiTrackTimeline.clipById(overlay.id) == null) {
        _insertTextTimelineClip(overlay);
      }
    }
  }

  void _applyTimelineModelUpdate(TimelineModel model) {
    _multiTrackTimeline = model;
    final primaryAudio = model.trackById('audio-1');
    if (primaryAudio != null) {
      _originalAudioMuted = primaryAudio.isMuted;
    }
    for (final track in model.textTracks) {
      for (final clip in track.clips) {
        final index = _textOverlays.indexWhere(
          (overlay) => overlay.id == clip.id || overlay.id == clip.mediaPath,
        );
        if (index < 0) continue;
        _textOverlays[index] = _textOverlays[index].copyWith(
          timelineStart: clip.timelineStart,
          duration: clip.duration,
          trackIndex: track.index,
          isVisible: !track.isMuted,
          isLocked: track.isLocked,
        );
      }
    }
  }

  void _toggleTextOverlayVisibility(int index) {
    if (index < 0 || index >= _textOverlays.length) return;
    _recordEditorHistory('text-visibility');
    setState(() {
      final next = _textOverlays[index].copyWith(
        isVisible: !_textOverlays[index].isVisible,
      );
      _textOverlays[index] = next;
      _insertTextTimelineClip(next);
    });
  }

  void _toggleTextOverlayLock(int index) {
    if (index < 0 || index >= _textOverlays.length) return;
    _recordEditorHistory('text-lock');
    setState(() {
      final next = _textOverlays[index].copyWith(
        isLocked: !_textOverlays[index].isLocked,
      );
      _textOverlays[index] = next;
      _insertTextTimelineClip(next);
    });
  }

  void _addTextOverlay({String template = 'default'}) {
    _recordEditorHistory('text-add');
    setState(() {
      _saveSelectedTextOverlay();
      if (_textOverlays.length == 1 &&
          _textOverlays.first.text.trim().isEmpty) {
        _textOverlays.clear();
        _selectedTextOverlayIndex = 0;
      }
      final index = _textOverlays.length;
      final id = 'text-${DateTime.now().microsecondsSinceEpoch}';
      final trackIndex = _nextTextTrackIndex();
      final playhead = _currentProgramSeconds();
      final sequenceEnd = _multiTrackTimeline.duration > 0
          ? _multiTrackTimeline.duration
          : playhead + 5;
      final duration = math.max(0.5, math.min(5.0, sequenceEnd - playhead));
      final next = _TextOverlayDraft(
        id: id,
        text: template == 'lower_third' ? 'Lower Third' : 'Text ${index + 1}',
        font: template == 'trending' ? 'Impact' : 'Arial',
        size: template == '3d' ? 64 : 44,
        color: template == 'trending' ? const Color(0xffffe500) : Colors.white,
        stroke: template == '3d' ? 7 : 3,
        shadowOpacity: template == '3d' ? 0.9 : 0.65,
        animation: template == 'lower_third' ? 'flow right' : 'none',
        x: template == 'lower_third' ? 0.28 : 0.5,
        y: (0.25 + index * 0.12).clamp(0.0, 0.9).toDouble(),
        timelineStart: playhead,
        duration: duration,
        trackIndex: trackIndex,
      );
      _textOverlays.add(next);
      _selectedTextOverlayIndex = _textOverlays.length - 1;
      _loadTextOverlay(next);
      _insertTextTimelineClip(next);
      _selectedTimelineClipId = id;
      _editorSelection = EditorSelection.text(id, label: next.text);
      _status = 'Added ${next.text} on T$trackIndex at the playhead';
    });
    unawaited(_autosaveProject());
  }

  void _duplicateTextOverlay() {
    _recordEditorHistory('text-duplicate');
    setState(() {
      _saveSelectedTextOverlay();
      final copy = _textOverlays[_selectedTextOverlayIndex].copyWith(
        id: 'text-${DateTime.now().microsecondsSinceEpoch}',
        y: (_overlayTextY + 0.08).clamp(0.0, 1.0).toDouble(),
        trackIndex: _nextTextTrackIndex(),
      );
      _textOverlays.add(copy);
      _selectedTextOverlayIndex = _textOverlays.length - 1;
      _loadTextOverlay(copy);
      _insertTextTimelineClip(copy);
      _selectedTimelineClipId = copy.id;
      _editorSelection = EditorSelection.text(copy.id, label: copy.text);
    });
    unawaited(_autosaveProject());
  }

  void _deleteTextOverlay() {
    _deleteTextOverlayAt(_selectedTextOverlayIndex);
  }

  void _deleteTextOverlayAt(int index) {
    if (index < 0 || index >= _textOverlays.length) return;
    if (_textOverlays[index].isLocked) {
      _showMessage(
        'Unlock T${_textOverlays[index].trackIndex} before deleting text.',
      );
      return;
    }
    _recordEditorHistory('text-delete');
    setState(() {
      final removed = _textOverlays.removeAt(index);
      _multiTrackTimeline =
          _timelineEditor.deleteClip(_multiTrackTimeline, removed.id);
      if (_textOverlays.isEmpty) {
        _textOverlays.add(const _TextOverlayDraft());
      }
      _selectedTextOverlayIndex = index.clamp(0, _textOverlays.length - 1);
      _loadTextOverlay(_textOverlays[_selectedTextOverlayIndex]);
      _selectedTimelineClipIds.remove(removed.id);
      _selectedTimelineClipId = null;
      _editorSelection = _videos.isEmpty
          ? const EditorSelection.none()
          : EditorSelection.video(_videos[_selectedVideoIndex].path);
    });
    unawaited(_autosaveProject());
  }

  List<_TextOverlayDraft> _previewTextOverlays() {
    final overlays = List<_TextOverlayDraft>.of(_textOverlays);
    if (_selectedTextOverlayIndex >= 0 &&
        _selectedTextOverlayIndex < overlays.length) {
      overlays[_selectedTextOverlayIndex] = _currentTextOverlayDraft();
    }
    return overlays;
  }

  List<TextOverlaySettings> _exportManualTextOverlays() =>
      _previewTextOverlays()
          .where(
              (overlay) => overlay.text.trim().isNotEmpty && overlay.isVisible)
          .map((overlay) => overlay.toSettings(_colorToHex))
          .toList();

  List<CaptionCueSettings> _exportTimelineCaptionCues([
    TimelineModel? requestedTimeline,
  ]) {
    if (!_automaticCaptions ||
        _captionTrackHidden ||
        _captionCuesByVideo.isEmpty) {
      return const [];
    }
    final result = <CaptionCueSettings>[];
    final timeline = requestedTimeline ?? _multiTrackTimeline;
    final timelineEnd = _actualMultiTrackExportDuration(timeline);
    for (final track in timeline.videoTracks) {
      if (track.isMuted) continue;
      for (final clip in track.clips) {
        if (clip.isMuted) continue;
        final cues =
            _captionCuesByVideo[clip.mediaPath] ?? const <_CaptionCue>[];
        for (final cue in cues) {
          final sourceStart = math.max(cue.start, clip.sourceStart);
          final sourceEnd = math.min(cue.end, clip.sourceEnd);
          if (sourceEnd - sourceStart <= 0.01) continue;
          final start = clip.timelineStart + sourceStart - clip.sourceStart;
          final end = clip.timelineStart + sourceEnd - clip.sourceStart;
          if (start >= timelineEnd || end <= 0) continue;
          final text = normalizeAssDisplayText(cue.text).trim();
          if (text.isEmpty) continue;
          result.add(
            CaptionCueSettings(
              start: start.clamp(0.0, timelineEnd).toDouble(),
              end: end.clamp(0.0, timelineEnd).toDouble(),
              text: text,
              x: cue.x,
              y: cue.y,
              words: [
                for (final word in cue.words)
                  if (word.end > sourceStart && word.start < sourceEnd)
                    CaptionWordSettings(
                      start: (clip.timelineStart +
                              math.max(word.start, sourceStart) -
                              clip.sourceStart)
                          .clamp(0.0, timelineEnd)
                          .toDouble(),
                      end: (clip.timelineStart +
                              math.min(word.end, sourceEnd) -
                              clip.sourceStart)
                          .clamp(0.0, timelineEnd)
                          .toDouble(),
                      text: normalizeAssDisplayText(word.text),
                    ),
              ],
            ),
          );
        }
      }
    }
    result.sort((left, right) => left.start.compareTo(right.start));
    return result;
  }

