  String _formatDuration(double? seconds) {
    if (seconds == null || seconds <= 0) {
      return '--:--';
    }
    final whole = seconds.round();
    final h = whole ~/ 3600;
    final m = (whole % 3600) ~/ 60;
    final s = whole % 60;
    if (h > 0) {
      return '$h:${m.toString().padLeft(2, '0')}:${s.toString().padLeft(2, '0')}';
    }
    return '$m:${s.toString().padLeft(2, '0')}';
  }

