class _CaptionStyleAnimationPreviewState
    extends State<_CaptionStyleAnimationPreview>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 2800),
    )..repeat();
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  List<Shadow> _shadows(bool active) {
    final preset = widget.preset;
    final outline = preset.outline.clamp(0.0, 9.0).toDouble();
    final shadows = <Shadow>[];
    if (outline > 0) {
      for (final offset in const [
        Offset(-1, -1),
        Offset(1, -1),
        Offset(-1, 1),
        Offset(1, 1),
      ]) {
        shadows.add(
          Shadow(
            color: preset.outlineColor,
            blurRadius: 1,
            offset: Offset(offset.dx * outline, offset.dy * outline),
          ),
        );
      }
    }
    if (preset.shadow > 0) {
      shadows.add(
        Shadow(
          color: preset.motion == 'glow' && active
              ? preset.accentColor
              : preset.outlineColor,
          blurRadius: preset.motion == 'glow' && active
              ? preset.shadow * 2.5
              : preset.shadow,
          offset: preset.motion == 'glow'
              ? Offset.zero
              : Offset(preset.shadow * 0.7, preset.shadow),
        ),
      );
    }
    return shadows;
  }

  @override
  Widget build(BuildContext context) {
    const sample = ['THE', 'QUICK', 'BROWN', 'FOX'];
    final preset = widget.preset;
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, child) {
        final activeIndex = (_controller.value * sample.length)
            .floor()
            .clamp(0, sample.length - 1);
        return DecoratedBox(
          decoration: const BoxDecoration(
            gradient: LinearGradient(
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
              colors: [Color(0xff172033), Color(0xff05070b)],
            ),
          ),
          child: Stack(
            children: [
              const Positioned(
                right: 28,
                top: 24,
                child: Icon(
                  Icons.videocam_outlined,
                  color: Color(0x337c8ba8),
                  size: 100,
                ),
              ),
              Center(
                child: DecoratedBox(
                  decoration: BoxDecoration(
                    color: preset.backgroundColor,
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: Padding(
                    padding: preset.backgroundColor == Colors.transparent
                        ? EdgeInsets.zero
                        : const EdgeInsets.symmetric(
                            horizontal: 14,
                            vertical: 8,
                          ),
                    child: Wrap(
                      alignment: WrapAlignment.center,
                      crossAxisAlignment: WrapCrossAlignment.center,
                      spacing: 12,
                      runSpacing: 10,
                      children: [
                        for (final entry in sample.indexed)
                          Builder(
                            builder: (context) {
                              final active = entry.$1 == activeIndex;
                              final activeBox = preset.motion == 'box' && active
                                  ? preset.activeBoxColor
                                  : Colors.transparent;
                              final text = KText(
                                preset.uppercase
                                    ? entry.$2
                                    : entry.$2.toLowerCase(),
                                style: TextStyle(
                                  color: active
                                      ? preset.accentColor
                                      : preset.inactiveColor,
                                  fontFamily: widget.fontFamily,
                                  fontSize: 42,
                                  fontWeight: preset.bold
                                      ? FontWeight.w900
                                      : FontWeight.w500,
                                  fontStyle: preset.italic
                                      ? FontStyle.italic
                                      : FontStyle.normal,
                                  shadows: _shadows(active),
                                ),
                              );
                              final animated = AnimatedContainer(
                                duration: const Duration(milliseconds: 120),
                                padding: activeBox == Colors.transparent
                                    ? EdgeInsets.zero
                                    : const EdgeInsets.symmetric(
                                        horizontal: 9,
                                        vertical: 4,
                                      ),
                                decoration: BoxDecoration(
                                  color: activeBox,
                                  borderRadius: BorderRadius.circular(6),
                                ),
                                child: text,
                              );
                              return AnimatedScale(
                                scale: active &&
                                        (preset.motion == 'pop' ||
                                            preset.motion == 'bounce')
                                    ? 1.2
                                    : 1,
                                duration: const Duration(milliseconds: 130),
                                curve: Curves.easeOutBack,
                                child: Transform.translate(
                                  offset: active && preset.motion == 'bounce'
                                      ? const Offset(0, -8)
                                      : Offset.zero,
                                  child: animated,
                                ),
                              );
                            },
                          ),
                      ],
                    ),
                  ),
                ),
              ),
              Positioned(
                left: 16,
                bottom: 14,
                child: DecoratedBox(
                  decoration: BoxDecoration(
                    color: const Color(0xaa000000),
                    borderRadius: BorderRadius.circular(99),
                  ),
                  child: Padding(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                    child: KText(
                      'AUTO PLAY • ${preset.motion.toUpperCase()}',
                      style: TextStyle(
                        color: preset.accentColor,
                        fontSize: 11,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

