class _EditableSlider extends StatefulWidget {
  const _EditableSlider({
    required this.label,
    required this.value,
    required this.min,
    required this.max,
    required this.divisions,
    required this.onChanged,
    this.valueFormatter,
    this.valueParser,
  });

  final String label;
  final double value;
  final double min;
  final double max;
  final int divisions;
  final ValueChanged<double> onChanged;
  final String Function(double value)? valueFormatter;
  final double? Function(String text)? valueParser;

  @override
  State<_EditableSlider> createState() => _EditableSliderState();
}

class _EditableSliderState extends State<_EditableSlider> {
  late final TextEditingController _controller;
  late final FocusNode _focusNode;

  @override
  void initState() {
    super.initState();
    _controller = TextEditingController(text: _valueText(widget.value));
    _focusNode = FocusNode()..addListener(_handleFocusChange);
  }

  @override
  void didUpdateWidget(covariant _EditableSlider oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!_focusNode.hasFocus && oldWidget.value != widget.value) {
      _setText(widget.value);
    }
  }

  @override
  void dispose() {
    _focusNode
      ..removeListener(_handleFocusChange)
      ..dispose();
    _controller.dispose();
    super.dispose();
  }

  void _handleFocusChange() {
    if (!_focusNode.hasFocus) _commit();
  }

  void _setText(double value) {
    _controller.value = TextEditingValue(
      text: _valueText(value),
      selection: TextSelection.collapsed(offset: _valueText(value).length),
    );
  }

  void _commit() {
    final parsed = widget.valueParser?.call(_controller.text) ??
        double.tryParse(_controller.text.trim().replaceAll(',', '.'));
    if (parsed == null) {
      _setText(widget.value);
      return;
    }
    final value = parsed.clamp(widget.min, widget.max).toDouble();
    _setText(value);
    if (value != widget.value) widget.onChanged(value);
  }

  String _valueText(double value) {
    final formatter = widget.valueFormatter;
    if (formatter != null) return formatter(value);
    final normalized = value.abs() < 0.0005 ? 0.0 : value;
    if (normalized.abs() >= 10) return normalized.toStringAsFixed(0);
    return normalized.toStringAsFixed(2).replaceFirst(RegExp(r'0$'), '');
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            Expanded(child: KText(widget.label)),
            SizedBox(
              width: 68,
              height: 30,
              child: TextField(
                controller: _controller,
                focusNode: _focusNode,
                textAlign: TextAlign.right,
                keyboardType: TextInputType.numberWithOptions(
                  decimal: true,
                  signed: widget.min < 0,
                ),
                onTap: () => _controller.selection = TextSelection(
                  baseOffset: 0,
                  extentOffset: _controller.text.length,
                ),
                onSubmitted: (_) {
                  _commit();
                  _focusNode.unfocus();
                },
                decoration: const InputDecoration(
                  isDense: true,
                  contentPadding:
                      EdgeInsets.symmetric(horizontal: 7, vertical: 6),
                  border: OutlineInputBorder(),
                ),
              ),
            ),
          ],
        ),
        Slider(
          value: widget.value.clamp(widget.min, widget.max).toDouble(),
          min: widget.min,
          max: widget.max,
          divisions: widget.divisions,
          onChanged: widget.onChanged,
        ),
      ],
    );
  }
}

// Helper functions from platform support
String basename(String path) => platform.basename(path);

Future<List<String>> videoFilesInFolder(String folder) async {
  final dir = Directory(folder);
  if (!await dir.exists()) return const [];
  final files = <String>[];
  await for (final entity in dir.list()) {
    if (entity is File) {
      final lower = entity.path.toLowerCase();
      if (lower.endsWith('.mp4') ||
          lower.endsWith('.mov') ||
          lower.endsWith('.avi') ||
          lower.endsWith('.mkv') ||
          lower.endsWith('.webm') ||
          lower.endsWith('.m4v')) {
        files.add(entity.path);
      }
    }
  }
  return files;
}

